		{"8-Bit Blip", "rbxassetid://16480580213"}, {"8-Bit Beep", "rbxassetid://16480578737"},
		{"Wheel Tick", "rbxassetid://9120658649"}, {"Ping", "rbxasset://sounds/electronicpingshort.wav"},
		{"Bubble", "rbxassetid://9112872239"}},
	reveal = {{"Sparkle Ding", "rbxassetid://9126073001"}, {"Magic Chime", "rbxassetid://9116394545"},
		{"Magic Glow", "rbxassetid://9116395089"}, {"Choir", "rbxassetid://9114792002", 3.5},
		{"Desk Bell", "rbxassetid://9125485591", 2.5}, {"Big Bell", "rbxassetid://1034263055", 3},
		{"Stinger", "rbxassetid://15675043410"}, {"Notify", "rbxassetid://17208361335"},
