function GameEffects.Kill.effectContext(state, character, killer)
	local root = character:FindFirstChild("HumanoidRootPart") or character:FindFirstChild("UpperTorso") or character:FindFirstChild("Torso")
	if not root then return nil end

	local chest = character:FindFirstChild("UpperTorso") or character:FindFirstChild("Torso") or root
	local head = character:FindFirstChild("Head") or root
	return {char = character, root = root.Position, chest = chest.Position, head = head.Position, killer = killer,
		ignore = {a = character, b = state.context.player.Character, c = state.context.workspace.CurrentCamera}}
end

function GameEffects.Kill.play(state, name, options, character, killer)
	if name == "Random" or not state.effects[name] then name = options[math.random(1, #options)] end
	local effect = state.effects[name]
	local context = character and GameEffects.Kill.effectContext(state, character, killer)
	if not effect or not context then return end

	context.orig = state.originals[character]
	context.ignore.d = context.orig
	context.ghostTakes = GameEffects.Kill.ghostEffects[name] or false
	if context.orig then state.contexts[character] = context end

	local ok, message = pcall(effect, context)
	if not ok then state.lastError = tostring(message) end
end

function GameEffects.Kill.evidence(state, victim, character, position)
	local now = state.context.environment.os.clock()

	for index = #state.shots, 1, -1 do
		local shot = state.shots[index]
		if now - shot.time > 0.9 then break end
		if shot.shooter == character then continue end

		if shot.hit and shot.hit:IsDescendantOf(character) then return "gun", shot.shooter end
		if position and shot.position and (shot.position - position).Magnitude < 4.5 then return "gun", shot.shooter end
	end

	if not position then return nil end

	for _, player in state.context.players:GetPlayers() do
		local other = player ~= victim and player.Character
		local root = other and other:FindFirstChild("Knife") and other:FindFirstChild("HumanoidRootPart")
		if root and (root.Position - position).Magnitude < 12 then return "knife", other end
	end

	for index = #state.blades, 1, -1 do
		local blade = state.blades[index]
		if now - blade.time > 0.6 then break end
		if (blade.position - position).Magnitude < 7 then return "knife", nil end
	end

	return nil
end

function GameEffects.Kill.isMine(state, weapon, roles)
	local player = state.context.player
	local data = roles[player.Name]
	local role = data and data.Role
	if weapon == "knife" then return role == "Murderer" end

	local character = player.Character
	local backpack = player:FindFirstChild("Backpack")
	return character and character:FindFirstChild("Gun") ~= nil or backpack and backpack:FindFirstChild("Gun") ~= nil or role == "Sheriff"
end

function GameEffects.Kill.killer(state, victim, roles, weapon)
	local victimRoot = victim.Character and victim.Character:FindFirstChild("HumanoidRootPart")
	local nearest, distance

	for _, player in state.context.players:GetPlayers() do
		local character = player ~= victim and player.Character
		if not character then continue end

		local data = roles[player.Name]
		local matches = weapon == "knife" and data and data.Role == "Murderer" or weapon ~= "knife" and character:FindFirstChild("Gun") ~= nil
		if not matches then continue end

		local part = character:FindFirstChild("UpperTorso") or character:FindFirstChild("Torso") or character:FindFirstChild("HumanoidRootPart")
		if not part then continue end

		local current = victimRoot and (part.Position - victimRoot.Position).Magnitude or 0
		if not distance or current < distance then nearest, distance = part, current end
	end

	return nearest
end

function GameEffects.Kill.recordShot(state, shooter, position, hit)
	local environment = state.context.environment
	if environment.typeof(shooter) ~= "Instance" then shooter = nil end

	while shooter and not (shooter:IsA("Model") and shooter:FindFirstChildOfClass("Humanoid")) do
		shooter = shooter.Parent
	end

	table.insert(state.shots, {time = environment.os.clock(), shooter = shooter,
		position = environment.typeof(position) == "Vector3" and position or nil,
		hit = environment.typeof(hit) == "Instance" and hit or nil})
	if #state.shots > 16 then table.remove(state.shots, 1) end
end

function GameEffects.Kill.recordBlade(state, position)
	table.insert(state.blades, {time = state.context.environment.os.clock(), position = position})
	if #state.blades > 300 then table.remove(state.blades, 1) end
end

function GameEffects.Kill.waitEvidence(state, victim, character, position)
	local environment = state.context.environment
	local started = environment.os.clock()

	while state.alive do
		local weapon, shooter = GameEffects.Kill.evidence(state, victim, character, position)
		if weapon then return weapon, shooter end
		if environment.os.clock() - started > 0.35 then return nil end
		environment.task.wait()
	end

	return nil
end

function GameEffects.Kill.appearance(character)
	local ok, value = pcall(function()
		local torso = character:FindFirstChild("UpperTorso")
		local shirt = character:FindFirstChildOfClass("Shirt")
		local pants = character:FindFirstChildOfClass("Pants")
		return table.concat({torso and torso:IsA("MeshPart") and torso.MeshId or "", shirt and shirt.ShirtTemplate or "", pants and pants.PantsTemplate or ""}, "|")
	end)

	return ok and value or "||"
end

function GameEffects.Kill.recordRagdoll(state, model)
	if model.Name ~= "Raggy" or not model:IsA("Model") then return end

	local now, recent = state.context.environment.os.clock(), {}
	for _, ragdoll in state.ragdolls do
		if now - ragdoll.time < 6 and ragdoll.model.Parent then table.insert(recent, ragdoll) end
	end

	table.insert(recent, {model = model, time = now})
	state.ragdolls = recent
end

function GameEffects.Kill.findRagdoll(state, position, appearance, deathTime, timeout)
	local environment = state.context.environment
	local deadline = environment.os.clock() + (timeout or 0.8)

	repeat
		local nearest, distance
		for _, ragdoll in state.ragdolls do
			local model = ragdoll.model
			if not model.Parent or state.originals[model] or ragdoll.time < deathTime - 0.6 then continue end

			local root = model:FindFirstChild("LowerTorso") or model:FindFirstChild("HumanoidRootPart")
			if not root then continue end

			local current = (root.Position - position).Magnitude
			if current >= 14 or appearance ~= "||" and GameEffects.Kill.appearance(model) ~= appearance then continue end
			if not distance or current < distance then nearest, distance = model, current end
		end

		if nearest then return nearest end
		environment.task.wait()
	until environment.os.clock() > deadline

	return nil
end

function GameEffects.Kill.hide(character)
	for _, object in character:GetDescendants() do
		if object:IsA("BasePart") then
			pcall(function() object.LocalTransparencyModifier = 1 end)
			pcall(function() object.CollisionGroup = "Characters" end)
			continue
		end

		if object:IsA("Decal") then pcall(function() object.LocalTransparencyModifier = 1 end) end
	end
end

function GameEffects.Kill.onDeath(state, victim, character)
	if not state.alive or not state.on then return end

	local environment = state.context.environment
	local torso = character:FindFirstChild("LowerTorso") or character:FindFirstChild("HumanoidRootPart")
	local root = character:FindFirstChild("HumanoidRootPart") or torso
	local position = root and root.Position
	local torsoPosition = torso and torso.Position
	local appearance = torso and GameEffects.Kill.appearance(character)
	local deathTime = environment.os.clock()
	local weapon, shooter = GameEffects.Kill.waitEvidence(state, victim, character, position)
	if not weapon or not state.alive or not state.on then return end

	local roles = state.context.roles and state.context.roles() or {}
	if state.mine then
		if shooter and shooter ~= state.context.player.Character then return end
		if not shooter and not GameEffects.Kill.isMine(state, weapon, roles) then return end
	end

	local killer = shooter and (shooter:FindFirstChild("UpperTorso") or shooter:FindFirstChild("Torso") or shooter:FindFirstChild("HumanoidRootPart"))
		or GameEffects.Kill.killer(state, victim, roles, weapon)
	local target = character

	if torso then
		for _, tracked in {state.originals, state.taken, state.contexts} do
			for model in tracked do if not model.Parent then tracked[model] = nil end end
		end

		local ragdoll = GameEffects.Kill.findRagdoll(state, torsoPosition, appearance, deathTime)
		if ragdoll then
			state.originals[ragdoll] = character
			GameEffects.Kill.hide(character)
			target = ragdoll
		else
			environment.task.spawn(function()
				local delayed = GameEffects.Kill.findRagdoll(state, torsoPosition, appearance, deathTime, 4)
				if not delayed or not state.alive then return end
				state.originals[delayed], state.taken[delayed] = character, true
				GameEffects.Kill.hide(delayed)
			end)
		end
	end

	if not state.alive then return end

	local now = environment.os.clock()
	local slot = math.max(now, state.slotAt or 0)
	state.slotAt = slot + 0.03
	if slot > now then environment.task.wait(slot - now) end
	if not state.alive then return end

	state.play(weapon == "gun" and state.gun or state.knife, weapon, target, killer)
end

function GameEffects.Kill.folder(state)
	local context, environment = state.context, state.context.environment
	local camera = context.workspace.CurrentCamera
	if state.folder and state.folder.Parent == camera then return state.folder end

	local folder = environment.Instance.new("Folder")
	folder.Name, folder.Parent = "PulseKillFX", camera
	state.folder = folder
	return folder
end

function GameEffects.Kill.anchor(state, frame, size)
	local environment = state.context.environment
	local part = environment.Instance.new("Part")
	part.Anchored, part.CanCollide, part.CanQuery, part.CanTouch, part.CastShadow = true, false, false, false, false
	part.Transparency, part.Size = 1, size or environment.Vector3.new(1, 1, 1)
	part.CFrame, part.Parent = frame, GameEffects.Kill.folder(state)
	return part
end

function GameEffects.Kill.delay(state, duration, callback)
	return state.context.environment.task.delay(duration / state.speed, callback)
end

function GameEffects.Kill.destroyLater(state, object, duration)
	GameEffects.Kill.delay(state, duration, function() pcall(function() object:Destroy() end) end)
end

function GameEffects.Kill.tween(state, object, duration, properties, style, direction)
	local context, environment = state.context, state.context.environment
	local info = environment.TweenInfo.new(duration / state.speed, style or environment.Enum.EasingStyle.Quint,
		direction or environment.Enum.EasingDirection.Out)
	local tween = context.tweenService:Create(object, info, properties)
	tween:Play()
	return tween
end

function GameEffects.Kill.numberSequence(state, ...)
	local environment = state.context.environment
	local values, points = {...}, {}
	for index = 1, #values, 2 do
		table.insert(points, environment.NumberSequenceKeypoint.new(values[index], values[index + 1]))
	end
	return environment.NumberSequence.new(points)
end

function GameEffects.Kill.animate(state, duration, update, finish)
	local context, environment = state.context, state.context.environment
	local started = environment.os.clock()
	local connection

	connection = context.runService.RenderStepped:Connect(function()
		local progress = math.clamp((environment.os.clock() - started) * state.speed / duration, 0, 1)
		local ok, message = pcall(update, progress)
		if not ok then state.driveError = tostring(message) end
		if progress < 1 and ok and state.alive then return end

		connection:Disconnect()
		if not finish then return end
		local finished, failure = pcall(finish)
		if not finished then state.driveError = tostring(failure) end
	end)
	return connection
end

function GameEffects.Kill.particle(state, parent, properties, count, delay)
	local environment = state.context.environment
	local emitter = environment.Instance.new("ParticleEmitter")
	emitter.Enabled, emitter.LightEmission, emitter.LightInfluence, emitter.Brightness = false, 1, 0, 2
	emitter.Speed = environment.NumberRange.new(0)
	for key, value in properties do emitter[key] = value end
	if state.brightTextures and state.brightTextures[emitter.Texture] then emitter.LightEmission = math.max(emitter.LightEmission, 1) end
	emitter.TimeScale, emitter.Parent = state.speed, parent

	GameEffects.Kill.delay(state, delay or 0, function()
		if emitter.Parent then emitter:Emit(count) end
	end)
	return emitter
end

function GameEffects.Kill.light(state, parent, color, brightness, range, duration)
	local light = state.context.environment.Instance.new("PointLight")
	light.Color, light.Brightness, light.Range, light.Shadows, light.Parent = color, brightness, range, false, parent
	GameEffects.Kill.tween(state, light, duration, {Brightness = 0}, state.context.environment.Enum.EasingStyle.Quad)
	return light
end

function GameEffects.Kill.sound(state, id, volume, speed, parent, fade)
	if not state.sound then return nil end

	local sound
	pcall(function()
		local environment = state.context.environment
		sound = environment.Instance.new("Sound")
		sound.SoundId, sound.Volume, sound.PlaybackSpeed = id, math.clamp(state.volume / 100, 0, 1) * (volume or 1), speed or 1
		sound.RollOffMaxDistance, sound.Parent = 200, parent or GameEffects.Kill.folder(state)
		sound:Play()
		if not fade then GameEffects.Kill.destroyLater(state, sound, 5); return end

		GameEffects.Kill.delay(state, fade, function()
			if sound.Parent then GameEffects.Kill.tween(state, sound, 0.4, {Volume = 0}) end
		end)
		GameEffects.Kill.destroyLater(state, sound, fade + 0.5)
	end)
	return sound
end

function GameEffects.Kill.scatter(state, position, count, color, material, distance, duration)
	local environment = state.context.environment
	for _ = 1, count do
		local part = environment.Instance.new("WedgePart")
		part.Anchored, part.CanCollide, part.CanQuery, part.CanTouch, part.CastShadow = true, false, false, false, false
		part.Material, part.Color, part.Transparency, part.Reflectance = material, color, 0.15, 0.25

		local size = math.random() * 0.6 + 0.25
		part.Size = environment.Vector3.new(size * 0.4, size, size * 0.8)
		local offset = environment.Vector3.new(math.random() - 0.5, math.random() * 1.4 - 0.7, math.random() - 0.5) * environment.Vector3.new(2, 4, 1.2)
		part.CFrame = environment.CFrame.new(position + offset) * environment.CFrame.Angles(math.random() * 6.3, math.random() * 6.3, math.random() * 6.3)
		part.Parent = GameEffects.Kill.folder(state)

		local direction = (offset.Magnitude > 0.05 and offset.Unit or environment.Vector3.new(0, 1, 0)) * (distance * (0.6 + math.random() * 0.6))
		local target = environment.CFrame.new(position + offset + direction + environment.Vector3.new(0, -2.5 - math.random() * 2, 0))
			* environment.CFrame.Angles(math.random() * 9, math.random() * 9, math.random() * 9)
		GameEffects.Kill.tween(state, part, duration, {CFrame = target}, environment.Enum.EasingStyle.Quad, environment.Enum.EasingDirection.Out)
		GameEffects.Kill.tween(state, part, duration, {Transparency = 1}, environment.Enum.EasingStyle.Quint, environment.Enum.EasingDirection.In)
		GameEffects.Kill.destroyLater(state, part, duration + 0.1)
	end
end

function GameEffects.Kill.line(state, start, finish, width, up, color, material, transparency)
	local environment = state.context.environment
	local length = (finish - start).Magnitude
	if length < 0.01 then return nil end

	local part = environment.Instance.new("Part")
	part.Anchored, part.CanCollide, part.CanQuery, part.CanTouch, part.CastShadow = true, false, false, false, false
	part.Material, part.Color, part.Transparency = material or environment.Enum.Material.Neon, color, transparency or 0
	part.Size = environment.Vector3.new(width, 0.04, length + 0.03)
	part.CFrame = environment.CFrame.lookAt((start + finish) / 2, finish, up)
	part.Parent = GameEffects.Kill.folder(state)
	return part
end

function GameEffects.Kill.arcSegment(state, start, finish, normal, outward, width, color, hold, white)
	if not state.alive then return end

	local environment = state.context.environment
	local inner = GameEffects.Kill.line(state, start + outward * width * 0.3, finish + outward * width * 0.3,
		math.max(0.04, width * 0.55), normal, white or environment.Color3.new(1, 1, 1))
	local outer = GameEffects.Kill.line(state, start, finish, math.max(0.1, width * 1.6), normal, color, environment.Enum.Material.Neon, 0.45)

	for _, part in {inner, outer} do
		GameEffects.Kill.delay(state, hold, function()
			if not part.Parent then return end
			GameEffects.Kill.tween(state, part, 0.22, {Transparency = 1, Size = environment.Vector3.new(0.02, part.Size.Y, part.Size.Z),
				CFrame = part.CFrame + outward * 0.7}, environment.Enum.EasingStyle.Quad)
		end)
		GameEffects.Kill.destroyLater(state, part, hold + 0.3)
	end
end

function GameEffects.Kill.arc(state, position, roll, radius, halfAngle, color, width, drawTime, hold, yaw, white, reverse)
	local environment = state.context.environment
	local camera = state.context.workspace.CurrentCamera
	local frame = camera and camera.CFrame or environment.CFrame.new()
	local yawAngle, rollAngle = math.rad(yaw or 0), math.rad(roll)
	local view = (frame.LookVector * math.cos(yawAngle) + frame.RightVector * math.sin(yawAngle)).Unit
	local direction = frame.RightVector * math.cos(rollAngle) + frame.UpVector * math.sin(rollAngle)
	direction = (direction - view * direction:Dot(view)).Unit
	if reverse then direction = -direction end

	local normal = view:Cross(direction).Unit
	local center = position - normal * radius * math.cos(halfAngle)
	GameEffects.Kill.arcFrom(state, center, normal, direction, radius, -halfAngle, halfAngle, color, width, drawTime, hold, white)
end

function GameEffects.Kill.arcFrom(state, center, normal, direction, radius, startAngle, endAngle, color, width, drawTime, hold, white)
	local points = {}
	for index = 0, 14 do
		local angle = startAngle + (endAngle - startAngle) * index / 14
		points[index] = center + (normal * math.cos(angle) + direction * math.sin(angle)) * radius
	end

	for index = 1, 14 do
		local weight = math.sin(math.pi * (index - 0.5) / 14) ^ 0.7
		local start, finish = points[index - 1], points[index]
		local outward = ((start + finish) / 2 - center).Unit
		GameEffects.Kill.delay(state, drawTime * (index - 1) / 14, function()
			if not state.alive then return end
			GameEffects.Kill.arcSegment(state, start, finish, normal:Cross(direction).Unit, outward, width * weight, color, hold, white)
		end)
	end
end

function GameEffects.Kill.beam(state, start, finish, width, color, material, transparency)
	local environment = state.context.environment
	local length = (finish - start).Magnitude
	if length < 0.01 then finish, length = start + environment.Vector3.new(0, 0.01, 0), 0.01 end

	local direction = (finish - start).Unit
	local up = math.abs(direction.Y) > 0.98 and environment.Vector3.new(1, 0, 0) or environment.Vector3.new(0, 1, 0)
	local part = environment.Instance.new("Part")
	part.Anchored, part.CanCollide, part.CanQuery, part.CanTouch, part.CastShadow = true, false, false, false, false
	part.Material, part.Color, part.Transparency = material or environment.Enum.Material.Neon, color, transparency or 0
	part.Size = environment.Vector3.new(width, width, length)
	part.CFrame, part.Parent = environment.CFrame.lookAt((start + finish) / 2, finish, up), GameEffects.Kill.folder(state)
	return part
end

function GameEffects.Kill.disc(state, frame, size, color, material, transparency)
	local environment = state.context.environment
	local part = environment.Instance.new("Part")
	part.Shape = environment.Enum.PartType.Cylinder
	part.Anchored, part.CanCollide, part.CanQuery, part.CanTouch, part.CastShadow = true, false, false, false, false
	part.Material, part.Color, part.Transparency = material or environment.Enum.Material.SmoothPlastic, color, transparency or 0
	part.Size = environment.Vector3.new(0.04, size, size)
	part.CFrame, part.Parent = frame * environment.CFrame.Angles(0, 0, math.pi / 2), GameEffects.Kill.folder(state)
	return part
end

function GameEffects.Kill.ground(state, position, ignore, distance)
	local context, environment = state.context, state.context.environment
	local params = environment.RaycastParams.new()
	params.FilterType, params.RespectCanCollide = environment.Enum.RaycastFilterType.Exclude, true

	local excluded = {}
	for _, object in ignore or {} do
		if environment.typeof(object) == "Instance" then table.insert(excluded, object) end
	end
	local bodies = context.workspace:FindFirstChild("PulseKillBodies")
	if bodies then table.insert(excluded, bodies) end
	if context.workspace.CurrentCamera then table.insert(excluded, context.workspace.CurrentCamera) end
	params.FilterDescendantsInstances = excluded

	local origin = position + environment.Vector3.new(0, 1.5, 0)
	for _ = 1, 8 do
		local result = context.workspace:Raycast(origin, environment.Vector3.new(0, -(distance or 60), 0), params)
		if not result then return nil end

		local part = result.Instance
		local model = part:FindFirstAncestorOfClass("Model")
		local humanoid = model and model:FindFirstChildOfClass("Humanoid")
		if part.Transparency < 0.9 and not humanoid then return result.Position, result.Normal end

		table.insert(excluded, humanoid and model or part)
		params.FilterDescendantsInstances = excluded
	end
	return nil
end

function GameEffects.Kill.groundRing(state, parent, texture, color, startSize, endSize, duration, brightness)
	local environment = state.context.environment
	return GameEffects.Kill.particle(state, parent, {Texture = texture, Color = environment.ColorSequence.new(color, color),
		Size = GameEffects.Kill.numberSequence(state, 0, startSize, 1, endSize),
		Transparency = GameEffects.Kill.numberSequence(state, 0, 0, 0.7, 0.4, 1, 1), Lifetime = environment.NumberRange.new(duration),
		Speed = environment.NumberRange.new(0.01), EmissionDirection = environment.Enum.NormalId.Top,
		Orientation = environment.Enum.ParticleOrientation.VelocityPerpendicular, Brightness = brightness or 3}, 1)
end

function GameEffects.Kill.groundDecal(state, position, normal, size, color, lifetime, growth, texture, count)
	local environment = state.context.environment
	local reference = math.abs(normal.Z) < 0.9 and environment.Vector3.new(0, 0, 1) or environment.Vector3.new(1, 0, 0)
	local frame = environment.CFrame.fromMatrix(position, normal:Cross(reference).Unit, normal)

	for index = 1, count or 3 do
		local width = size * (1 - (index - 1) * 0.3)
		local offset = index == 1 and environment.Vector3.new(0, 0, 0)
			or environment.Vector3.new((math.random() - 0.5) * size * 0.35, 0, (math.random() - 0.5) * size * 0.35)
		local part = GameEffects.Kill.anchor(state,
			frame * environment.CFrame.new(offset + environment.Vector3.new(0, 0.02 + index * 0.012, 0))
				* environment.CFrame.Angles(0, math.random() * 6.28, 0), environment.Vector3.new(0.2, 0.05, 0.2))
		local decal = environment.Instance.new("Decal")
		decal.Texture = texture and not state.brightTextures[texture] and texture or state.textures.splat
		decal.Face = environment.Enum.NormalId.Top
		decal.Color3 = color:Lerp(environment.Color3.new(0, 0, 0), (index - 1) * 0.15)
		decal.Transparency, decal.Parent = 0.02 + (index - 1) * 0.1, part

		GameEffects.Kill.delay(state, (index - 1) * 0.07, function()
			if part.Parent then GameEffects.Kill.tween(state, part, growth or 0.9, {Size = environment.Vector3.new(width, 0.05, width)}) end
		end)
		GameEffects.Kill.delay(state, lifetime, function()
			if decal.Parent then GameEffects.Kill.tween(state, decal, 1.4, {Transparency = 1}, environment.Enum.EasingStyle.Quad) end
		end)
		GameEffects.Kill.destroyLater(state, part, lifetime + 1.5)
	end
end

function GameEffects.Kill.splat(state, position, size, color, lifetime, ignore, growth, texture, count)
	local ground, normal = GameEffects.Kill.ground(state, position, ignore)
	if ground then GameEffects.Kill.groundDecal(state, ground, normal, size, color, lifetime, growth, texture, count) end
end

function GameEffects.Kill.resetShake(state)
	local context = state.context
	pcall(function() context.runService:UnbindFromRenderStep("PulseKillShakeA") end)
	pcall(function() context.runService:UnbindFromRenderStep("PulseKillShakeB") end)

	if state.shakeRestore then
		local camera = context.workspace.CurrentCamera
		if camera then pcall(function() camera.CFrame = state.shakeRestore end) end
		state.shakeRestore = nil
	end

	table.clear(state.shakes)
	state.shakeBound = false
end

function GameEffects.Kill.shakeCamera(state, position, amplitude, duration)
	if not state.shake or not state.alive then return end

	local context, environment = state.context, state.context.environment
	local camera = context.workspace.CurrentCamera
	if not camera then return end

	local strength = amplitude * math.clamp(1.2 - (camera.CFrame.Position - position).Magnitude / 75, 0, 1)
	if strength < 0.05 then return end

	table.insert(state.shakes, {time = environment.os.clock(), amplitude = strength, duration = duration, seed = math.random() * 50})
	if state.shakeBound then return end
	state.shakeBound = true

	context.runService:BindToRenderStep("PulseKillShakeA", environment.Enum.RenderPriority.First.Value, function()
		if state.shakeRestore then
			local current = context.workspace.CurrentCamera
			if current then current.CFrame = state.shakeRestore end
			state.shakeRestore = nil
		end
		if #state.shakes == 0 then GameEffects.Kill.resetShake(state) end
	end)

	context.runService:BindToRenderStep("PulseKillShakeB", environment.Enum.RenderPriority.Camera.Value + 2, function()
		local current = context.workspace.CurrentCamera
		if not current then return end

		local now, pitch, yaw, roll = environment.os.clock(), 0, 0, 0
		for index = #state.shakes, 1, -1 do
			local shake = state.shakes[index]
			local progress = (now - shake.time) * state.speed / shake.duration
			if progress >= 1 then table.remove(state.shakes, index); continue end

			local strength = shake.amplitude * (1 - progress) ^ 2
			local time = (now - shake.time) * 24
			pitch += math.noise(time, shake.seed) * strength * 2.2
			yaw += math.noise(shake.seed, time) * strength * 2.2
			roll += math.noise(time, shake.seed + 9.3) * strength
		end

		if pitch ~= 0 or yaw ~= 0 or roll ~= 0 then
			state.shakeRestore = current.CFrame
			current.CFrame = current.CFrame * environment.CFrame.Angles(math.rad(pitch), math.rad(yaw), math.rad(roll))
		end
	end)
end

GameEffects.Kill.bodyExcluded = {"LuaSourceContainer", "Tool", "ForceField", "BillboardGui", "SurfaceGui", "Sound", "ParticleEmitter",
	"Trail", "Beam", "Highlight", "Light", "Fire", "Smoke", "Sparkles", "BodyMover", "SelectionBox", "ProximityPrompt", "ClickDetector", "Animator"}

function GameEffects.Kill.canTake(state, character, ghost)
	if not state.originals[character] or state.taken[character] or not character.Parent then return false end
	if ghost and not (state.contexts[character] and state.contexts[character].ghostTakes) then return false end

	local root = character:FindFirstChild("LowerTorso") or character:FindFirstChild("UpperTorso") or character:FindFirstChild("HumanoidRootPart")
	if not root then return false end
	if state.forceTake or root.Anchored then return true end

	local ok, owned = pcall(state.context.environment.isnetworkowner, root)
	if ok and type(owned) == "boolean" then return owned end
	return true
end

function GameEffects.Kill.cleanBody(state, body, taken)
	for _, object in body:GetDescendants() do
		local exclude = false
		for _, class in GameEffects.Kill.bodyExcluded do
			if object:IsA(class) then exclude = true; break end
		end

		if exclude then pcall(function() object:Destroy() end) end
	end

	if taken then
		for _, object in body:GetDescendants() do
			if object:IsA("BasePart") or object:IsA("Decal") then pcall(function() object.LocalTransparencyModifier = 0 end) end
		end
	end

	local humanoid = body:FindFirstChildOfClass("Humanoid")
	if humanoid then
		pcall(function()
			humanoid.RequiresNeck = false
			humanoid.BreakJointsOnDeath = false
			humanoid.EvaluateStateMachine = false
			humanoid.DisplayDistanceType = state.context.environment.Enum.HumanoidDisplayDistanceType.None
			humanoid.HealthDisplayType = state.context.environment.Enum.HumanoidHealthDisplayType.AlwaysOff
			if not taken then humanoid.MaxHealth, humanoid.Health = 100, 100 end
		end)
	end

	body.Name = "PulseKillBody"
	return body
end

function GameEffects.Kill.cloneBody(state, character)
	if GameEffects.Kill.canTake(state, character) then
		state.taken[character] = true
		return GameEffects.Kill.cleanBody(state, character, true)
	end

	local archivable = character.Archivable
	character.Archivable = true
	local ok, body = pcall(function() return character:Clone() end)
	pcall(function() character.Archivable = archivable end)
	if not ok or not body then return nil end

	return GameEffects.Kill.cleanBody(state, body, false)
end

function GameEffects.Kill.link(state, first, second, attachment0, attachment1)
	local environment = state.context.environment
	local joint = environment.Instance.new("BallSocketConstraint")
	joint.Attachment0, joint.Attachment1 = attachment0, attachment1
	joint.LimitsEnabled, joint.UpperAngle = true, 60
	joint.TwistLimitsEnabled, joint.TwistLowerAngle, joint.TwistUpperAngle = true, -45, 45
	joint.Parent = first
	if first and second and first:IsA("BasePart") and second:IsA("BasePart") then
		local collision = environment.Instance.new("NoCollisionConstraint")
		collision.Part0, collision.Part1, collision.Parent = first, second, first
	end

	return joint
end

function GameEffects.Kill.joints(state, body, root)
	local environment = state.context.environment
	local joints, linked = {}, {}
	for _, class in {"BallSocketConstraint", "Motor6D", "AnimationConstraint"} do
		for _, object in body:GetDescendants() do if object.ClassName == class then table.insert(joints, object) end end
	end

	local function seen(first, second)
		return linked[first] and linked[first][second] or linked[second] and linked[second][first]
	end

	local function remember(first, second)
		linked[first] = linked[first] or {}
		linked[first][second] = true
	end

	for _, joint in joints do
		local class = joint.ClassName
		if class == "BallSocketConstraint" then
			if not joint.Attachment0 or not joint.Attachment1 then continue end
			local first, second = joint.Attachment0.Parent, joint.Attachment1.Parent
			if first and second and seen(first, second) then joint:Destroy(); continue end

			if first and second then remember(first, second) end
			joint.Enabled, joint.LimitsEnabled, joint.UpperAngle = true, true, 60
			joint.TwistLimitsEnabled, joint.TwistLowerAngle, joint.TwistUpperAngle = true, -45, 45
			pcall(function() joint.MaxFrictionTorque = 0 end)
			pcall(function() joint.Restitution = 0 end)
			if first and second and first:IsA("BasePart") and second:IsA("BasePart") then
				local collision = environment.Instance.new("NoCollisionConstraint")
				collision.Part0, collision.Part1, collision.Parent = first, second, first
			end
			continue
		end

		local first, second, attachment0, attachment1
		if class == "Motor6D" then
			first, second = joint.Part0, joint.Part1
			if first and second and first ~= root and second ~= root and not seen(first, second) then
				attachment0, attachment1 = environment.Instance.new("Attachment"), environment.Instance.new("Attachment")
				attachment0.CFrame, attachment0.Parent = joint.C0, first
				attachment1.CFrame, attachment1.Parent = joint.C1, second
			end
		end
		if class == "AnimationConstraint" then
			attachment0, attachment1 = joint.Attachment0, joint.Attachment1
			first, second = attachment0 and attachment0.Parent, attachment1 and attachment1.Parent
			if first and second and (not first:IsA("BasePart") or not second:IsA("BasePart") or first == root or second == root or seen(first, second)) then
				attachment0, attachment1 = nil, nil
			end
		end

		if first and second and attachment0 and attachment1 then
			remember(first, second)
			GameEffects.Kill.link(state, first, second, attachment0, attachment1)
		end
		joint:Destroy()
	end
end

function GameEffects.Kill.ghostCandidate(part)
	if not part:IsA("BasePart") or part.Name == "HumanoidRootPart" or part.Transparency >= 0.95 then return false end
	if part:FindFirstChildWhichIsA("WrapLayer") then return false end

	local accessory = part:FindFirstAncestorWhichIsA("Accessory")
	return not accessory or not accessory:FindFirstChildWhichIsA("WrapLayer", true)
end

function GameEffects.Kill.prepareGhost(part, options)
	for _, child in part:GetChildren() do
		if child:IsA("SpecialMesh") then
			if not options.textured then pcall(function() child.TextureId = "" end) end
			continue
		end
		if options.textured and (child:IsA("Decal") or child:IsA("SurfaceAppearance")) then continue end
		pcall(function() child:Destroy() end)
	end

	if part:IsA("MeshPart") and not options.textured then pcall(function() part.TextureID = "" end) end
	part.Anchored, part.CanCollide, part.CanQuery, part.CanTouch, part.CastShadow = true, false, false, false, false
	if options.material then part.Material = options.material end
	if options.color then part.Color = options.color end
	if options.transparency ~= nil then part.Transparency = options.transparency end
	if not options.textured then part.Reflectance = 0 end
	part.Name = "G"
end

function GameEffects.Kill.ghost(state, character, options)
	local taken = GameEffects.Kill.canTake(state, character, true)
	local parts = {}
	if taken then state.taken[character] = true end

	for _, source in character:GetDescendants() do
		if not GameEffects.Kill.ghostCandidate(source) then continue end

		local part = source
		if not taken then
			local ok, clone = pcall(function()
				local archivable = source.Archivable
				source.Archivable = true
				local result = source:Clone()
				source.Archivable = archivable
				return result
			end)
			if not ok or not clone then continue end
			part = clone
		end

		GameEffects.Kill.prepareGhost(part, options)
		if taken then pcall(function() part.LocalTransparencyModifier = 0 end) end
		if not taken then part.Parent = GameEffects.Kill.folder(state) end
		table.insert(parts, part)
	end

	if taken then
		for _, part in parts do part.Parent = GameEffects.Kill.folder(state) end
		GameEffects.Kill.hide(character)
	end
	return parts
end

function GameEffects.Kill.fadeGhost(state, parts, duration, properties)
	local environment = state.context.environment
	for _, part in parts do
		local target = {Transparency = 1}
		if properties then for key, value in properties(part) do target[key] = value end end

		GameEffects.Kill.tween(state, part, duration, target, environment.Enum.EasingStyle.Quad, environment.Enum.EasingDirection.In)
		for _, child in part:GetChildren() do
			if child:IsA("Decal") then GameEffects.Kill.tween(state, child, duration, {Transparency = 1}, environment.Enum.EasingStyle.Quad, environment.Enum.EasingDirection.In) end
		end
		GameEffects.Kill.destroyLater(state, part, duration + 0.1)
	end
end

function GameEffects.Kill.staticBody(state, effect)
	local model = GameEffects.Kill.cloneBody(state, effect.char)
	if not model then return GameEffects.Kill.ghost(state, effect.char, {textured = true}), nil end

	for _, object in model:GetDescendants() do
		if object:IsA("JointInstance") or object:IsA("WeldConstraint") or object:IsA("Constraint") then
			pcall(function() object.Enabled = false end)
		end
	end

	local parts = {}
	for _, part in model:GetDescendants() do
		if not part:IsA("BasePart") then continue end
		part.Anchored, part.CanCollide, part.CanQuery, part.CanTouch, part.CastShadow = true, false, false, false, false
		if part.Name == "HumanoidRootPart" or part.Transparency >= 0.95 then
			part.Transparency = 1
			continue
		end
		table.insert(parts, part)
	end

	model.Parent = GameEffects.Kill.folder(state)
	GameEffects.Kill.destroyLater(state, model, 9)
	return parts, model
end

function GameEffects.Kill.bodyParts(model)
	local parts, body = {}, {}

	for _, part in model:GetDescendants() do
		if not part:IsA("BasePart") then continue end

		local accessory = part:FindFirstAncestorWhichIsA("Accessory")
		part.Anchored, part.CanQuery, part.CanTouch = false, false, false
		part.CanCollide, part.Massless = not accessory, accessory and true or false
		pcall(function() part.CollisionGroup = "Ragdolls" end)

		table.insert(parts, part)
		if not accessory then table.insert(body, part) end
	end

	return parts, body
end

function GameEffects.Kill.launch(state, result, velocity, spin, callback)
	local function applyVelocity()
		for _, part in result.body do pcall(function() part.CanCollide, part.AssemblyLinearVelocity = true, velocity end) end
		if spin and result.torso then pcall(function() result.torso.AssemblyAngularVelocity = spin end) end
		if callback then pcall(callback, result) end
	end

	applyVelocity()
	local steps, connection = 0, nil
	connection = state.context.runService.Stepped:Connect(function()
		steps += 1
		if result.model.Parent then applyVelocity() end
		if steps >= 2 then connection:Disconnect() end
	end)
end

function GameEffects.Kill.fadeBody(state, result, lifetime)
	local context, environment = state.context, state.context.environment
	local duration = lifetime or 2.8

	environment.task.delay(duration / state.speed, function()
		for _, part in result.parts do
			if not part.Parent then continue end

			context.tweenService:Create(part, environment.TweenInfo.new(0.5 / state.speed, environment.Enum.EasingStyle.Quad), {Transparency = 1}):Play()
			for _, child in part:GetChildren() do
				if child:IsA("Decal") then context.tweenService:Create(child, environment.TweenInfo.new(0.5 / state.speed), {Transparency = 1}):Play() end
			end
		end
	end)

	environment.task.delay((duration + 0.6) / state.speed, function() pcall(function() result.model:Destroy() end) end)
end

function GameEffects.Kill.bodiesFolder(state)
	local context = state.context
	if state.bodies and state.bodies.Parent == context.workspace then return state.bodies end

	state.bodies = context.environment.Instance.new("Folder")
	state.bodies.Name, state.bodies.Parent = "PulseKillBodies", context.workspace
	return state.bodies
end

function GameEffects.Kill.body(state, effect, velocity, spin, lifetime, callback, held)
	local context, environment = state.context, state.context.environment
	local model = GameEffects.Kill.cloneBody(state, effect.char)
	if not model then return nil end

	local root = model:FindFirstChild("HumanoidRootPart")
	GameEffects.Kill.joints(state, model, root)
	if root then root:Destroy() end

	local parts, body = GameEffects.Kill.bodyParts(model)
	local original = model ~= effect.char and effect.char or effect.orig
	for _, part in original and original.Parent and original:GetDescendants() or {} do
		if part:IsA("BasePart") then pcall(function() part.CanCollide, part.CollisionGroup = false, "Characters" end) end
	end

	model.Parent = GameEffects.Kill.bodiesFolder(state)
	for _, part in body do part.CanCollide = true end

	local result = {model = model, parts = parts, body = body,
		torso = model:FindFirstChild("UpperTorso") or model:FindFirstChild("Torso") or body[1], head = model:FindFirstChild("Head")}
	local humanoid = model:FindFirstChildOfClass("Humanoid")
	if humanoid then pcall(function() humanoid.PlatformStand = true; humanoid:ChangeState(environment.Enum.HumanoidStateType.Physics) end) end

	result.release = function() end
	if held then
		for _, part in parts do part.Anchored = true end
		result.release = function(nextVelocity, nextCallback)
			if result.released or not model.Parent then return end

			result.released = true
			for _, part in parts do part.Anchored = false end
			GameEffects.Kill.launch(state, result, nextVelocity or velocity, spin, nextCallback or callback)
		end
	end
	if not held then GameEffects.Kill.launch(state, result, velocity, spin, callback) end

	GameEffects.Kill.fadeBody(state, result, lifetime)
	return result
end

function GameEffects.Kill.direction(state, effect)
	local environment = state.context.environment
	local camera = state.context.workspace.CurrentCamera
	local origin = effect.killer and effect.killer.Parent and effect.killer.Position
		or camera and camera.CFrame.Position or effect.root + environment.Vector3.new(0, 0, 5)
	local direction = effect.root - origin
	direction = environment.Vector3.new(direction.X, 0, direction.Z)
	if direction.Magnitude > 0.05 then return direction.Unit, origin end
	return environment.Vector3.new(0, 0, -1), origin
end

function GameEffects.Kill.hideEffectBody(state, character)
	local original = state.originals[character]
	if original and original.Parent then GameEffects.Kill.hide(original) end
	if not state.taken[character] then GameEffects.Kill.hide(character) end
end

function GameEffects.Kill.randomVector(state, magnitude)
	return state.context.environment.Vector3.new(math.random() - 0.5, math.random() - 0.5, math.random() - 0.5) * 2 * magnitude
end

function GameEffects.Kill.slash(state, effect)
	local environment = state.context.environment
	local color = environment.Color3.fromRGB(255, 36, 64)
	local white = environment.Color3.new(1, 1, 1)
	local direction = GameEffects.Kill.direction(state, effect)
	local body = GameEffects.Kill.body(state, effect, direction * 20 + environment.Vector3.new(0, 12, 0),
		GameEffects.Kill.randomVector(state, 3), 2.8, nil, true)
	GameEffects.Kill.hideEffectBody(state, effect.char)

	local angle, reverse = math.random(25, 40), math.random() < 0.5
	GameEffects.Kill.arc(state, effect.chest, angle, 3.4, 1.05, color, 0.75, 0.07, 0.08, -12, nil, reverse)
	GameEffects.Kill.delay(state, 0.1, function()
		GameEffects.Kill.arc(state, effect.chest, 180 - angle, 3.4, 1.05, color, 0.75, 0.07, 0.08, 12, nil, not reverse)
	end)

	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.chest), environment.Vector3.new(2, 2, 2))
	local attachment = environment.Instance.new("Attachment")
	attachment.Parent = anchor
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end

	for index = 0, 1 do
		GameEffects.Kill.delay(state, 0.05 + index * 0.1, function()
			GameEffects.Kill.particle(state, attachment, {Texture = state.textures.sparkBright, Color = colors(white), Size = sequence(0, 4, 1, 0),
				Lifetime = environment.NumberRange.new(0.12), Brightness = 6, ZOffset = 2}, 1)
			GameEffects.Kill.particle(state, attachment, {Texture = state.textures.spark, Color = colors(white, color), Size = sequence(0, 1.2, 1, 0),
				Lifetime = environment.NumberRange.new(0.2, 0.4), Speed = environment.NumberRange.new(20, 34), SpreadAngle = environment.Vector2.new(180, 180),
				Drag = 6, Orientation = environment.Enum.ParticleOrientation.VelocityParallel, Brightness = 4}, 16)
			GameEffects.Kill.particle(state, attachment, {Texture = state.textures.splat, Color = colors(environment.Color3.fromRGB(150, 0, 16), environment.Color3.fromRGB(90, 0, 10)),
				Size = sequence(0, 0.55, 1, 0.25), Lifetime = environment.NumberRange.new(0.6, 1), Speed = environment.NumberRange.new(8, 16),
				SpreadAngle = environment.Vector2.new(75, 75), Acceleration = environment.Vector3.new(0, -60, 0), Rotation = environment.NumberRange.new(0, 360),
				LightEmission = 0, Brightness = 1}, 20)
			GameEffects.Kill.sound(state, index == 0 and GameEffects.Kill.soundIds.whooshQuick or GameEffects.Kill.soundIds.fleshSlash, 1, 1 + index * 0.2, anchor)
		end)
	end

	GameEffects.Kill.delay(state, 0.17, function()
		GameEffects.Kill.particle(state, attachment, {Texture = state.textures.ring, Color = colors(color), Size = sequence(0, 1, 1, 10),
			Transparency = sequence(0, 0, 1, 1), Lifetime = environment.NumberRange.new(0.42), Brightness = 4}, 1)
		if body then body.release() end
		GameEffects.Kill.shakeCamera(state, effect.chest, 0.5, 0.22)
		GameEffects.Kill.delay(state, 0.8, function()
			local position = body and body.torso and body.torso.Parent and body.torso.Position or effect.root
			GameEffects.Kill.splat(state, position, 3.2, environment.Color3.fromRGB(125, 0, 12), 2.6, effect.ignore, 0.9)
		end)
	end)
	GameEffects.Kill.light(state, anchor, color, 7, 16, 0.6)
	GameEffects.Kill.destroyLater(state, anchor, 2.5)
end

function GameEffects.Kill.blood(state, effect)
	local environment = state.context.environment
	local color = environment.Color3.fromRGB(120, 0, 12)
	local direction = GameEffects.Kill.direction(state, effect)
	local body = GameEffects.Kill.body(state, effect, direction * 5 + environment.Vector3.new(0, 3, 0),
		GameEffects.Kill.randomVector(state, 1.5), 3.4)
	GameEffects.Kill.hideEffectBody(state, effect.char)

	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.chest), environment.Vector3.new(2, 2, 2))
	local attachment = environment.Instance.new("Attachment")
	attachment.Parent = anchor
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end

	GameEffects.Kill.particle(state, attachment, {Texture = state.textures.splat,
		Color = colors(environment.Color3.fromRGB(190, 10, 30), color), Size = sequence(0, 0.9, 1, 0.3),
		Lifetime = environment.NumberRange.new(0.7, 1.2), Speed = environment.NumberRange.new(10, 24), SpreadAngle = environment.Vector2.new(180, 180),
		Acceleration = environment.Vector3.new(0, -70, 0), Drag = 1, Rotation = environment.NumberRange.new(0, 360),
		RotSpeed = environment.NumberRange.new(-200, 200), LightEmission = 0, Brightness = 1.2}, 46)
	GameEffects.Kill.particle(state, attachment, {Texture = state.textures.soft, Color = colors(environment.Color3.fromRGB(160, 0, 20)),
		Size = sequence(0, 2, 1, 6), Transparency = sequence(0, 0.35, 1, 1), Lifetime = environment.NumberRange.new(0.7, 1.1),
		Speed = environment.NumberRange.new(2, 5), SpreadAngle = environment.Vector2.new(180, 180), LightEmission = 0.3, Brightness = 1}, 10)
	GameEffects.Kill.particle(state, attachment, {Texture = state.textures.burst, Color = colors(environment.Color3.fromRGB(255, 60, 70), color),
		Size = sequence(0, 2, 1, 7), Transparency = sequence(0, 0, 1, 1), Lifetime = environment.NumberRange.new(0.25), Brightness = 3}, 1)

	GameEffects.Kill.delay(state, 0.55, function()
		local position = body and body.torso and body.torso.Parent and body.torso.Position or effect.root
		GameEffects.Kill.splat(state, position, 6, environment.Color3.fromRGB(125, 0, 12), 3.6, effect.ignore, 1.4)
	end)
	GameEffects.Kill.light(state, anchor, environment.Color3.fromRGB(255, 30, 40), 4, 12, 0.5)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.stab2, 0.9, 0.8, anchor)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.guts, 0.9, 0.8, anchor)
	GameEffects.Kill.destroyLater(state, anchor, 2.5)
end

function GameEffects.Kill.detachHead(body, direction, spin, vector)
	if not body.head then return end

	for _, joint in body.model:GetDescendants() do
		if not joint:IsA("BallSocketConstraint") then continue end
		if joint.Attachment0 and joint.Attachment0.Parent == body.head or joint.Attachment1 and joint.Attachment1.Parent == body.head then
			joint:Destroy()
		end
	end

	body.head.AssemblyLinearVelocity = direction * 36 + vector.new(0, 44, 0)
	body.head.AssemblyAngularVelocity = spin
end

function GameEffects.Kill.headshotTorso(state, effect, body)
	if not body or not body.torso then return end

	local environment = state.context.environment
	local anchor = GameEffects.Kill.anchor(state, body.torso.CFrame, environment.Vector3.new(0.4, 0.4, 0.4))
	local attachment = environment.Instance.new("Attachment")
	attachment.Parent = anchor

	local emitter = GameEffects.Kill.particle(state, attachment, {Texture = state.textures.splat,
		Color = environment.ColorSequence.new(environment.Color3.fromRGB(190, 0, 25), environment.Color3.fromRGB(100, 0, 10)),
		Size = GameEffects.Kill.numberSequence(state, 0, 0.38, 1, 0.15), Lifetime = environment.NumberRange.new(0.5, 0.8),
		Speed = environment.NumberRange.new(9, 15), SpreadAngle = environment.Vector2.new(18, 18),
		Acceleration = environment.Vector3.new(0, -55, 0), Rotation = environment.NumberRange.new(0, 360), LightEmission = 0, Brightness = 1}, 12)
	emitter.Rate, emitter.Enabled = 70, true

	GameEffects.Kill.animate(state, 1.2, function(progress)
		if body.torso.Parent then anchor.CFrame = body.torso.CFrame * environment.CFrame.new(0, body.torso.Size.Y / 2, 0) end
		emitter.Rate = 70 * (1 - progress)
	end, function() emitter.Enabled = false end)
	GameEffects.Kill.delay(state, 0.7, function()
		local position = body.torso.Parent and body.torso.Position or effect.root
		GameEffects.Kill.splat(state, position, 4, environment.Color3.fromRGB(125, 0, 12), 2.8, effect.ignore, 1.2)
	end)
	GameEffects.Kill.destroyLater(state, anchor, 2.2)
end

function GameEffects.Kill.headshotHead(state, body)
	if not body or not body.head then return end

	local environment = state.context.environment
	local anchor = GameEffects.Kill.anchor(state, body.head.CFrame, environment.Vector3.new(0.6, 0.6, 0.6))
	local color = environment.Color3.fromRGB(170, 0, 20)
	local emitter = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.splat,
		Color = environment.ColorSequence.new(color, color), Size = GameEffects.Kill.numberSequence(state, 0, 0.3, 1, 0.1),
		Lifetime = environment.NumberRange.new(0.4, 0.7), Speed = environment.NumberRange.new(0, 2),
		SpreadAngle = environment.Vector2.new(180, 180), Acceleration = environment.Vector3.new(0, -40, 0),
		Rotation = environment.NumberRange.new(0, 360), Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0, Brightness = 1}, 0)
	emitter.Rate, emitter.Enabled = 45, true

	GameEffects.Kill.animate(state, 0.9, function()
		if body.head.Parent then anchor.CFrame = body.head.CFrame end
	end, function() emitter.Enabled = false end)
	GameEffects.Kill.destroyLater(state, anchor, 1.8)
end

function GameEffects.Kill.headshotLabel(state, anchor, color, white)
	local environment = state.context.environment
	local billboard = environment.Instance.new("BillboardGui")
	billboard.Size, billboard.AlwaysOnTop, billboard.LightInfluence = environment.UDim2.fromOffset(260, 60), true, 0
	billboard.StudsOffsetWorldSpace, billboard.Adornee, billboard.Parent = environment.Vector3.new(0, 1.8, 0), anchor, anchor
	pcall(function() environment.getgenv().__pulseBBMirror.add(billboard) end)

	local label = environment.Instance.new("TextLabel")
	label.BackgroundTransparency, label.Size, label.Text = 1, environment.UDim2.fromScale(1, 1), "HEADSHOT"
	label.FontFace = environment.Font.new("rbxasset://fonts/families/GothamSSm.json", environment.Enum.FontWeight.Heavy, environment.Enum.FontStyle.Italic)
	label.TextScaled, label.TextColor3, label.Parent = true, white, billboard

	local stroke = environment.Instance.new("UIStroke")
	stroke.Color, stroke.Thickness, stroke.Parent = environment.Color3.fromRGB(200, 30, 40), 3, label
	local gradient = environment.Instance.new("UIGradient")
	gradient.Color, gradient.Rotation, gradient.Parent = environment.ColorSequence.new(white, color), 90, label
	local scale = environment.Instance.new("UIScale")
	scale.Scale, scale.Parent = 0.3, label

	GameEffects.Kill.tween(state, scale, 0.18, {Scale = 1.15}, environment.Enum.EasingStyle.Back)
	GameEffects.Kill.delay(state, 0.18, function()
		if scale.Parent then GameEffects.Kill.tween(state, scale, 0.2, {Scale = 1}) end
	end)
	GameEffects.Kill.tween(state, billboard, 1.2, {StudsOffsetWorldSpace = environment.Vector3.new(0, 3.2, 0)}, environment.Enum.EasingStyle.Quad)
	GameEffects.Kill.delay(state, 0.8, function()
		if not label.Parent then return end
		GameEffects.Kill.tween(state, label, 0.4, {TextTransparency = 1})
		GameEffects.Kill.tween(state, stroke, 0.4, {Transparency = 1})
	end)
end

function GameEffects.Kill.headshot(state, effect)
	local environment = state.context.environment
	local color, white = environment.Color3.fromRGB(255, 205, 80), environment.Color3.new(1, 1, 1)
	local direction = GameEffects.Kill.direction(state, effect)
	local headSpin = GameEffects.Kill.randomVector(state, 14)
	local body = GameEffects.Kill.body(state, effect, direction * 9 + environment.Vector3.new(0, 3, 0),
		GameEffects.Kill.randomVector(state, 1.5), 3, function(result)
			GameEffects.Kill.detachHead(result, direction, headSpin, environment.Vector3)
		end)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	GameEffects.Kill.headshotTorso(state, effect, body)
	GameEffects.Kill.headshotHead(state, body)

	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.head), environment.Vector3.new(1, 1, 1))
	local attachment = environment.Instance.new("Attachment")
	attachment.Parent = anchor
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end

	GameEffects.Kill.particle(state, attachment, {Texture = state.textures.sparkBright, Color = colors(white), Size = sequence(0, 7, 1, 0),
		Lifetime = environment.NumberRange.new(0.16), Brightness = 6, ZOffset = 2}, 1)
	GameEffects.Kill.particle(state, attachment, {Texture = state.textures.needles, Color = colors(white, color), Size = sequence(0, 2, 1, 9),
		Transparency = sequence(0, 0, 1, 1), Lifetime = environment.NumberRange.new(0.3), Brightness = 5}, 1)
	GameEffects.Kill.particle(state, attachment, {Texture = state.textures.ring, Color = colors(color), Size = sequence(0, 1, 1, 9),
		Transparency = sequence(0, 0, 1, 1), Lifetime = environment.NumberRange.new(0.4), Brightness = 4}, 1)
	GameEffects.Kill.particle(state, attachment, {Texture = state.textures.splat,
		Color = colors(environment.Color3.fromRGB(170, 0, 18), environment.Color3.fromRGB(90, 0, 10)), Size = sequence(0, 0.5, 1, 0.2),
		Lifetime = environment.NumberRange.new(0.5, 0.9), Speed = environment.NumberRange.new(10, 18), SpreadAngle = environment.Vector2.new(180, 180),
		Acceleration = environment.Vector3.new(0, -60, 0), Rotation = environment.NumberRange.new(0, 360), LightEmission = 0, Brightness = 1}, 26)

	GameEffects.Kill.headshotLabel(state, anchor, color, white)
	GameEffects.Kill.light(state, anchor, color, 6, 14, 0.4)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.sniper, 0.9, 1, anchor)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.bone1, 0.8, 0.9, anchor)
	GameEffects.Kill.shakeCamera(state, effect.head, 0.6, 0.22)
	GameEffects.Kill.destroyLater(state, anchor, 2)
end

function GameEffects.Kill.impactDust(state, position, speed)
	local environment = state.context.environment
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(position), environment.Vector3.new(2, 2, 2))
	local attachment = environment.Instance.new("Attachment")
	attachment.Parent = anchor
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end

	GameEffects.Kill.particle(state, anchor, {Texture = state.textures.soft,
		Color = colors(environment.Color3.fromRGB(150, 145, 140), environment.Color3.fromRGB(90, 88, 85)),
		Size = sequence(0, 1.5, 1, 4.5), Transparency = sequence(0, 0.35, 1, 1), Lifetime = environment.NumberRange.new(0.6, 1),
		Speed = environment.NumberRange.new(3, 7), SpreadAngle = environment.Vector2.new(180, 180), Drag = 3,
		Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0, LightInfluence = 1, Brightness = 1}, 12)
	GameEffects.Kill.particle(state, anchor, {Texture = state.textures.rock, Color = colors(environment.Color3.fromRGB(80, 76, 72)),
		Size = sequence(0, 0.4, 1, 0.25), Lifetime = environment.NumberRange.new(0.5, 0.8), Speed = environment.NumberRange.new(8, 16),
		SpreadAngle = environment.Vector2.new(180, 180), Acceleration = environment.Vector3.new(0, -60, 0), Rotation = environment.NumberRange.new(0, 360),
		RotSpeed = environment.NumberRange.new(-300, 300), Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0, LightInfluence = 1, Brightness = 1}, 10)
	GameEffects.Kill.particle(state, attachment, {Texture = state.textures.ring, Color = colors(environment.Color3.new(1, 1, 1)),
		Size = sequence(0, 1, 1, 7), Transparency = sequence(0, 0.3, 1, 1), Lifetime = environment.NumberRange.new(0.3), Brightness = 3}, 1)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.bodyFall, 0.35, 2.3, anchor)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.punch2, 0.6, 0.7, anchor)
	GameEffects.Kill.shakeCamera(state, position, math.clamp(speed / 75, 0.3, 1) * 0.8, 0.2)
	GameEffects.Kill.destroyLater(state, anchor, 1.5)
end

function GameEffects.Kill.impactTrack(state, body)
	if not body or not body.torso then return end

	local velocity, count, last = body.torso.AssemblyLinearVelocity, 0, -1
	GameEffects.Kill.animate(state, 1.8, function(progress)
		local torso = body.torso
		if not torso.Parent then return end

		local current = torso.AssemblyLinearVelocity
		if velocity.Magnitude > 28 and (current - velocity).Magnitude > velocity.Magnitude * 0.55 and count < 3 and progress - last > 0.08 then
			count, last = count + 1, progress
			GameEffects.Kill.impactDust(state, torso.Position, velocity.Magnitude)
		end
		velocity = current
	end)
end

function GameEffects.Kill.impact(state, effect)
	local environment = state.context.environment
	local color, white = environment.Color3.fromRGB(255, 200, 110), environment.Color3.new(1, 1, 1)
	local direction, fallback = GameEffects.Kill.direction(state, effect)
	local source = effect.killer and effect.killer.Parent and effect.killer.Position + environment.Vector3.new(0, 0.6, 0) or fallback
	local delta = effect.chest - source
	local shot = delta.Magnitude > 0.1 and delta.Unit or direction
	local up = math.abs(shot.Y) < 0.95 and environment.Vector3.new(0, 1, 0) or environment.Vector3.new(1, 0, 0)
	local frame = environment.CFrame.fromMatrix(effect.chest, shot:Cross(up).Unit, shot)

	if delta.Magnitude > 1 and delta.Magnitude < 250 then
		local core = GameEffects.Kill.beam(state, source, effect.chest, 0.1, environment.Color3.fromRGB(255, 245, 220))
		local glow = GameEffects.Kill.beam(state, source, effect.chest, 0.4, color, environment.Enum.Material.Neon, 0.6)
		for _, part in {core, glow} do
			GameEffects.Kill.tween(state, part, 0.2, {Transparency = 1, Size = environment.Vector3.new(0.02, 0.02, part.Size.Z)}, environment.Enum.EasingStyle.Quad)
			GameEffects.Kill.destroyLater(state, part, 0.25)
		end
	end

	for index = 1, 2 do
		GameEffects.Kill.delay(state, (index - 1) * 0.05, function()
			local disc = GameEffects.Kill.disc(state, frame + shot * (index - 1) * 1.4, 0.4, white, environment.Enum.Material.Neon, 0.25)
			GameEffects.Kill.tween(state, disc, 0.3, {Size = environment.Vector3.new(0.04, 7 - index, 7 - index), Transparency = 1}, environment.Enum.EasingStyle.Quad)
			GameEffects.Kill.destroyLater(state, disc, 0.35)
		end)
	end

	local anchor = GameEffects.Kill.anchor(state, frame, environment.Vector3.new(0.5, 0.5, 0.5))
	local attachment = environment.Instance.new("Attachment")
	attachment.Parent = anchor
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
	GameEffects.Kill.particle(state, attachment, {Texture = state.textures.sparkBright, Color = colors(white), Size = sequence(0, 5, 1, 0),
		Lifetime = environment.NumberRange.new(0.12), Brightness = 6, ZOffset = 2}, 1)
	GameEffects.Kill.particle(state, attachment, {Texture = state.textures.fsparks, Color = colors(white, color), Size = sequence(0, 0.5, 1, 0),
		Lifetime = environment.NumberRange.new(0.3, 0.6), Speed = environment.NumberRange.new(30, 55), SpreadAngle = environment.Vector2.new(25, 25),
		Drag = 3, Orientation = environment.Enum.ParticleOrientation.VelocityParallel, Brightness = 5}, 30)
	GameEffects.Kill.particle(state, attachment, {Texture = state.textures.splat,
		Color = colors(environment.Color3.fromRGB(170, 0, 20), environment.Color3.fromRGB(90, 0, 10)), Size = sequence(0, 0.5, 1, 0.2),
		Lifetime = environment.NumberRange.new(0.5, 0.8), Speed = environment.NumberRange.new(14, 26), SpreadAngle = environment.Vector2.new(30, 30),
		Acceleration = environment.Vector3.new(0, -60, 0), Rotation = environment.NumberRange.new(0, 360), LightEmission = 0, Brightness = 1}, 22)

	local horizontal = environment.Vector3.new(shot.X, 0, shot.Z)
	local body = GameEffects.Kill.body(state, effect, (horizontal.Magnitude > 0.05 and horizontal.Unit or direction) * 75 + environment.Vector3.new(0, 16, 0),
		GameEffects.Kill.randomVector(state, 4), 3)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	GameEffects.Kill.impactTrack(state, body)
	GameEffects.Kill.light(state, anchor, color, 6, 14, 0.35)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.sniper, 0.9, 0.85, anchor)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.punch2, 0.7, 1.3, anchor)
	GameEffects.Kill.shakeCamera(state, effect.chest, 0.8, 0.25)
	GameEffects.Kill.destroyLater(state, anchor, 2)
end

function GameEffects.Kill.electricSmoke(state, position)
	local environment = state.context.environment
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(position), environment.Vector3.new(2, 1, 2))
	GameEffects.Kill.particle(state, anchor, {Texture = state.textures.fsmoke,
		Color = environment.ColorSequence.new(environment.Color3.fromRGB(70, 72, 80), environment.Color3.fromRGB(30, 30, 34)),
		Size = GameEffects.Kill.numberSequence(state, 0, 1.5, 1, 4), Transparency = GameEffects.Kill.numberSequence(state, 0, 0.4, 1, 1),
		Lifetime = environment.NumberRange.new(1, 1.5), Speed = environment.NumberRange.new(1, 3), Acceleration = environment.Vector3.new(0, 3, 0),
		Rotation = environment.NumberRange.new(0, 360), Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0, LightInfluence = 1, Brightness = 1}, 8)
	GameEffects.Kill.destroyLater(state, anchor, 2)
end

function GameEffects.Kill.electricBody(state, body, anchor, color, white)
	if not body then return end

	local environment = state.context.environment
	local highlight = environment.Instance.new("Highlight")
	highlight.FillColor, highlight.OutlineColor = color, white
	highlight.FillTransparency, highlight.OutlineTransparency = 0.3, 0
	highlight.DepthMode, highlight.Adornee, highlight.Parent = environment.Enum.HighlightDepthMode.Occluded, body.model, body.model

	GameEffects.Kill.animate(state, 0.9, function()
		if body.torso and body.torso.Parent then anchor.CFrame = body.torso.CFrame end
	end)
	environment.task.spawn(function()
		for index = 1, 12 do
			if not body.model.Parent or not state.alive then return end

			highlight.FillTransparency = index % 2 == 0 and 0.1 or 0.7
			for _, part in body.body do
				pcall(function()
					local jitter = environment.Vector3.new(math.random() - 0.5, math.random() * 0.7, math.random() - 0.5) * 16
					part.AssemblyLinearVelocity += jitter
				end)
			end
			environment.task.wait(0.06 / state.speed)
		end

		if highlight.Parent then
			GameEffects.Kill.tween(state, highlight, 0.4, {FillColor = environment.Color3.fromRGB(18, 18, 22), FillTransparency = 0.1, OutlineTransparency = 1})
		end
		if body.torso and body.torso.Parent then GameEffects.Kill.electricSmoke(state, body.torso.Position) end
	end)
end

function GameEffects.Kill.electric(state, effect)
	local environment = state.context.environment
	local color, white = environment.Color3.fromRGB(90, 200, 255), environment.Color3.new(1, 1, 1)
	local direction = GameEffects.Kill.direction(state, effect)
	local body = GameEffects.Kill.body(state, effect, direction * 4 + environment.Vector3.new(0, 2, 0), nil, 2.8)
	GameEffects.Kill.hideEffectBody(state, effect.char)

	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.chest), environment.Vector3.new(2.5, 5, 2.5))
	GameEffects.Kill.electricBody(state, body, anchor, color, white)
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end

	local bolt = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.bolt, Color = colors(white, color),
		Size = sequence(0, 2.2, 1, 1.4), Transparency = sequence(0, 0, 0.8, 0.3, 1, 1), Lifetime = environment.NumberRange.new(0.12, 0.2),
		Rotation = environment.NumberRange.new(0, 360), Shape = environment.Enum.ParticleEmitterShape.Box, Brightness = 6, ZOffset = 1}, 10)
	for index = 1, 6 do
		GameEffects.Kill.delay(state, index * 0.12, function() if bolt.Parent then bolt:Emit(8) end end)
	end

	local attachment = environment.Instance.new("Attachment")
	attachment.Parent = anchor
	GameEffects.Kill.particle(state, attachment, {Texture = state.textures.shards, Color = colors(white, color), Size = sequence(0, 1.2, 1, 0.2),
		Lifetime = environment.NumberRange.new(0.3, 0.5), Speed = environment.NumberRange.new(10, 20), SpreadAngle = environment.Vector2.new(180, 180),
		Drag = 5, Rotation = environment.NumberRange.new(0, 360), Brightness = 5}, 22)
	GameEffects.Kill.particle(state, attachment, {Texture = state.textures.soft, Color = colors(color), Size = sequence(0, 3, 1, 7),
		Transparency = sequence(0, 0.3, 1, 1), Lifetime = environment.NumberRange.new(0.5), Brightness = 3}, 1)
	GameEffects.Kill.light(state, anchor, color, 8, 16, 0.9)

	for index = 1, 16 do
		GameEffects.Kill.delay(state, math.random() * 0.9, function()
			local sound = index % 3 == 0 and GameEffects.Kill.soundIds.zap2 or GameEffects.Kill.soundIds.zap1
			GameEffects.Kill.sound(state, sound, 0.6, 1.6 + math.random() * 1.8, anchor)
		end)
	end
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.flash, 0.8, 1.7, anchor)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.zap3, 0.3, 2.4, anchor)
	GameEffects.Kill.destroyLater(state, anchor, 2.2)
end

function GameEffects.Kill.disintegrate(state, effect)
	local environment = state.context.environment
	local color = environment.Color3.fromRGB(255, 170, 60)
	local parts = GameEffects.Kill.ghost(state, effect.char, {material = environment.Enum.Material.Neon, color = color, transparency = 0.15})
	GameEffects.Kill.hideEffectBody(state, effect.char)
	GameEffects.Kill.fadeGhost(state, parts, 1.3, function(part)
		return {Color = environment.Color3.fromRGB(40, 20, 10), CFrame = part.CFrame + environment.Vector3.new(0.6, 0.8, 0)}
	end)

	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.chest), environment.Vector3.new(2.2, 4.6, 1.4))
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
	local emitter = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.square,
		Color = colors(environment.Color3.fromRGB(255, 220, 140), environment.Color3.fromRGB(60, 30, 10)),
		Size = sequence(0, 0.22, 1, 0), Lifetime = environment.NumberRange.new(1, 1.8), Speed = environment.NumberRange.new(0.5, 2),
		SpreadAngle = environment.Vector2.new(40, 40), Acceleration = environment.Vector3.new(3, 4, 0), Drag = 0.6,
		Rotation = environment.NumberRange.new(0, 360), RotSpeed = environment.NumberRange.new(-180, 180),
		Shape = environment.Enum.ParticleEmitterShape.Box, ShapeStyle = environment.Enum.ParticleEmitterShapeStyle.Volume, Brightness = 3}, 80)
	emitter.Rate, emitter.Enabled = 120, true
	GameEffects.Kill.delay(state, 1.1, function() if emitter.Parent then emitter.Enabled = false end end)
	GameEffects.Kill.particle(state, anchor, {Texture = state.textures.fsparks, Color = colors(environment.Color3.new(1, 1, 1), color),
		Size = sequence(0, 0.3, 1, 0), Lifetime = environment.NumberRange.new(0.6, 1.2), Speed = environment.NumberRange.new(2, 5),
		Acceleration = environment.Vector3.new(2, 6, 0), Shape = environment.Enum.ParticleEmitterShape.Box, Brightness = 4}, 30)
	GameEffects.Kill.light(state, anchor, color, 5, 14, 1.3)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.sear, 0.8, 0.6, anchor)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.fuse, 0.4, 1.4, anchor)
	GameEffects.Kill.destroyLater(state, anchor, 3.5)
end

function GameEffects.Kill.void(state, effect)
	local environment = state.context.environment
	local color = environment.Color3.fromRGB(150, 60, 255)
	local white = environment.Color3.new(1, 1, 1)
	local parts = GameEffects.Kill.ghost(state, effect.char, {material = environment.Enum.Material.ForceField,
		color = environment.Color3.fromRGB(60, 10, 110), transparency = 0})
	GameEffects.Kill.hideEffectBody(state, effect.char)
	GameEffects.Kill.fadeGhost(state, parts, 0.7, function(part)
		return {CFrame = environment.CFrame.new(effect.chest) * (part.CFrame - part.CFrame.Position), Size = part.Size * 0.2}
	end)

	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.chest), environment.Vector3.new(12, 12, 12))
	local attachment = environment.Instance.new("Attachment")
	attachment.Parent = anchor
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
	GameEffects.Kill.particle(state, anchor, {Texture = state.textures.soft, Color = colors(color, environment.Color3.fromRGB(40, 0, 80)),
		Size = sequence(0, 0.6, 1, 0.1), Lifetime = environment.NumberRange.new(0.5, 0.7), Speed = environment.NumberRange.new(9, 14),
		Shape = environment.Enum.ParticleEmitterShape.Sphere, ShapeStyle = environment.Enum.ParticleEmitterShapeStyle.Surface,
		ShapeInOut = environment.Enum.ParticleEmitterShapeInOut.Inward, Brightness = 3}, 60)
	GameEffects.Kill.particle(state, attachment, {Texture = state.textures.darkBall, Color = colors(environment.Color3.fromRGB(80, 30, 160)),
		Size = sequence(0, 1, 0.6, 5, 1, 0), Transparency = sequence(0, 0, 1, 0.2), Lifetime = environment.NumberRange.new(0.75),
		LightEmission = 0.2, Brightness = 1.5, ZOffset = 1}, 1)
	GameEffects.Kill.particle(state, attachment, {Texture = state.textures.implode, Color = colors(color), Size = sequence(0, 8, 1, 1),
		Transparency = sequence(0, 0.2, 1, 1), Lifetime = environment.NumberRange.new(0.6), Brightness = 3}, 1)
	GameEffects.Kill.particle(state, attachment, {Texture = state.textures.needles, Color = colors(white, color), Size = sequence(0, 2, 1, 11),
		Transparency = sequence(0, 0, 1, 1), Lifetime = environment.NumberRange.new(0.4), Brightness = 5}, 1, 0.7)
	GameEffects.Kill.particle(state, attachment, {Texture = state.textures.ring, Color = colors(color), Size = sequence(0, 1, 1, 13),
		Transparency = sequence(0, 0, 1, 1), Lifetime = environment.NumberRange.new(0.5), Brightness = 4}, 1, 0.7)
	GameEffects.Kill.delay(state, 0.7, function()
		if anchor.Parent then GameEffects.Kill.light(state, anchor, color, 8, 18, 0.6) end
	end)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.void, 1, 1, anchor)
	GameEffects.Kill.destroyLater(state, anchor, 2.5)
end

function GameEffects.Kill.soul(state, effect)
	local environment = state.context.environment
	local color, white = environment.Color3.fromRGB(170, 225, 255), environment.Color3.new(1, 1, 1)
	local glow = GameEffects.Kill.ghost(state, effect.char, {material = environment.Enum.Material.Neon, color = color, transparency = 0.6})
	local shell = GameEffects.Kill.ghost(state, effect.char, {material = environment.Enum.Material.ForceField, color = color, transparency = 0})
	local direction = GameEffects.Kill.direction(state, effect)
	GameEffects.Kill.body(state, effect, direction * 3 + environment.Vector3.new(0, 2, 0), GameEffects.Kill.randomVector(state, 1), 3.2)
	GameEffects.Kill.hideEffectBody(state, effect.char)

	local parts, frames, transparency = {}, {}, {}
	for _, part in glow do table.insert(parts, part) end
	for _, part in shell do table.insert(parts, part) end
	for index, part in parts do frames[index], transparency[index] = part.CFrame, part.Transparency end

	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.chest), environment.Vector3.new(2, 4, 1.4))
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
	local mist = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.soft, Color = colors(color, white),
		Size = sequence(0, 1, 1, 0), Transparency = sequence(0, 0.45, 1, 1), Lifetime = environment.NumberRange.new(0.6, 1),
		Speed = environment.NumberRange.new(0.5, 1.5), SpreadAngle = environment.Vector2.new(180, 180),
		Shape = environment.Enum.ParticleEmitterShape.Box, Brightness = 2.5}, 0)
	mist.Rate, mist.Enabled = 45, true
	local stars = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.star, Color = colors(white, color),
		Size = sequence(0, 0.35, 1, 0), Lifetime = environment.NumberRange.new(0.5, 0.9), Speed = environment.NumberRange.new(1, 2),
		SpreadAngle = environment.Vector2.new(180, 180), Rotation = environment.NumberRange.new(0, 360), RotSpeed = environment.NumberRange.new(-120, 120),
		Shape = environment.Enum.ParticleEmitterShape.Box, Brightness = 4}, 0)
	stars.Rate, stars.Enabled = 14, true
	local attachment = environment.Instance.new("Attachment")
	attachment.Parent = anchor
	GameEffects.Kill.particle(state, attachment, {Texture = state.textures.soft, Color = colors(white, color), Size = sequence(0, 2, 1, 6),
		Transparency = sequence(0, 0.3, 1, 1), Lifetime = environment.NumberRange.new(0.5), Brightness = 3}, 1)

	GameEffects.Kill.animate(state, 2, function(progress)
		local height = progress * progress * 10 + progress * 1.2
		local offset = environment.Vector3.new(math.sin(progress * 7) * 0.35 * (1 - progress), height, math.cos(progress * 5) * 0.25 * (1 - progress))
		for index, part in parts do
			part.CFrame = frames[index] + offset
			part.Transparency = transparency[index] + (1 - transparency[index]) * progress ^ 2.2
		end
		anchor.CFrame = environment.CFrame.new(effect.chest + offset)
	end, function()
		mist.Enabled, stars.Enabled = false, false
		for _, part in parts do pcall(function() part:Destroy() end) end
		GameEffects.Kill.particle(state, attachment, {Texture = state.textures.star, Color = colors(white, color), Size = sequence(0, 0.6, 1, 0),
			Lifetime = environment.NumberRange.new(0.5, 0.9), Speed = environment.NumberRange.new(4, 9), SpreadAngle = environment.Vector2.new(180, 180),
			Drag = 3, Brightness = 5}, 18)
		GameEffects.Kill.particle(state, attachment, {Texture = state.textures.soft, Color = colors(color), Size = sequence(0, 3, 1, 7),
			Transparency = sequence(0, 0.3, 1, 1), Lifetime = environment.NumberRange.new(0.6), Brightness = 3}, 1)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.chimes, 0.3, 1.8, anchor, 2)
	end)
	GameEffects.Kill.light(state, anchor, color, 4, 14, 2.2)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.ghost, 0.8, 1.05, anchor)
	GameEffects.Kill.destroyLater(state, anchor, 3.8)
end

function GameEffects.Kill.shatter(state, effect)
	local environment = state.context.environment
	local color, white = environment.Color3.fromRGB(215, 235, 255), environment.Color3.new(1, 1, 1)
	local parts = GameEffects.Kill.ghost(state, effect.char, {material = environment.Enum.Material.Glass, color = color, transparency = 0.15})
	GameEffects.Kill.hideEffectBody(state, effect.char)
	GameEffects.Kill.delay(state, 0.12, function()
		for _, part in parts do pcall(function() part:Destroy() end) end
		GameEffects.Kill.scatter(state, effect.chest, 34, color, environment.Enum.Material.Glass, 7, 1.1)
	end)

	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.chest), environment.Vector3.new(2, 2, 2))
	local attachment = environment.Instance.new("Attachment")
	attachment.Parent = anchor
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
	GameEffects.Kill.particle(state, attachment, {Texture = state.textures.cracks, Color = colors(white), Size = sequence(0, 5, 1, 7),
		Transparency = sequence(0, 0, 0.6, 0.3, 1, 1), Lifetime = environment.NumberRange.new(0.3), Brightness = 4, ZOffset = 2}, 1)
	GameEffects.Kill.particle(state, attachment, {Texture = state.textures.sparkBright, Color = colors(white, color), Size = sequence(0, 0.8, 1, 0),
		Lifetime = environment.NumberRange.new(0.3, 0.6), Speed = environment.NumberRange.new(12, 22), SpreadAngle = environment.Vector2.new(180, 180),
		Drag = 4, Brightness = 5}, 20, 0.1)
	GameEffects.Kill.light(state, anchor, color, 5, 14, 0.6)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.glass, 1, 1, anchor)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.ice, 0.4, 1.4, anchor)
	GameEffects.Kill.destroyLater(state, anchor, 2.5)
end

function GameEffects.Kill.freeze(state, effect)
	local environment = state.context.environment
	local color, white = environment.Color3.fromRGB(150, 220, 255), environment.Color3.new(1, 1, 1)
	local parts = GameEffects.Kill.ghost(state, effect.char, {material = environment.Enum.Material.Glass, color = color, transparency = 0.25})
	for _, part in parts do part.Reflectance = 0.35 end
	GameEffects.Kill.hideEffectBody(state, effect.char)

	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.chest), environment.Vector3.new(2.6, 5, 2.6))
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	GameEffects.Kill.particle(state, anchor, {Texture = state.textures.crystal, Color = environment.ColorSequence.new(white, color),
		Size = sequence(0, 0.2, 0.3, 1.1, 1, 0.9), Transparency = sequence(0, 0, 0.8, 0, 1, 1), Lifetime = environment.NumberRange.new(0.9),
		Rotation = environment.NumberRange.new(-30, 30), Shape = environment.Enum.ParticleEmitterShape.Box, Brightness = 3, ZOffset = 1}, 30)

	local ground = GameEffects.Kill.ground(state, effect.root, effect.ignore)
	local height = ground and ground.Y or effect.root.Y - 3
	local ring = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.root.X, height + 0.1, effect.root.Z), environment.Vector3.new(1, 0.2, 1))
	GameEffects.Kill.groundRing(state, ring, state.textures.ring, color, 1, 10, 1, 2)
	GameEffects.Kill.light(state, anchor, color, 5, 14, 1.2)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.ice, 1, 1, anchor)

	GameEffects.Kill.delay(state, 0.85, function()
		for _, part in parts do pcall(function() part:Destroy() end) end
		GameEffects.Kill.scatter(state, effect.chest, 30, color, environment.Enum.Material.Glass, 6, 1)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.glass, 1, 1.1, anchor)
		local attachment = environment.Instance.new("Attachment")
		attachment.Parent = anchor
		GameEffects.Kill.particle(state, attachment, {Texture = state.textures.sparkBright, Color = environment.ColorSequence.new(white, color),
			Size = sequence(0, 0.8, 1, 0), Lifetime = environment.NumberRange.new(0.3, 0.6), Speed = environment.NumberRange.new(10, 20),
			SpreadAngle = environment.Vector2.new(180, 180), Drag = 4, Brightness = 5}, 18)
	end)
	GameEffects.Kill.destroyLater(state, ring, 2)
	GameEffects.Kill.destroyLater(state, anchor, 3)
end

function GameEffects.Kill.cameraClicks(state, anchor, count)
	local environment = state.context.environment
	for index = 0, (count or 7) - 1 do
		GameEffects.Kill.delay(state, index * 0.055, function()
			local id = index % 2 == 0 and GameEffects.Kill.soundIds.click or GameEffects.Kill.soundIds.switch
			GameEffects.Kill.sound(state, id, 0.8, 0.6 + math.random() * 1.6, anchor)
		end)
	end
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.flash, 0.6, 0.7, anchor)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.shutter, 0.5, 0.8, anchor)
end

function GameEffects.Kill.glitchLayers(state, layers, right)
	local environment = state.context.environment
	local frames = {}
	for index, layer in layers do
		frames[index] = {}
		for partIndex, part in layer do frames[index][partIndex] = part.CFrame end
	end

	environment.task.spawn(function()
		for index = 1, 12 do
			for layerIndex, layer in layers do
				local jitter = (math.random() - 0.5) * 0.9
				local offset = layerIndex == 1 and -0.25 or (layerIndex == 2 and 0.25 or 0)
				local shift = jitter + offset
				local vertical = math.random() < 0.3 and (math.random() - 0.5) * 0.6 or 0
				for partIndex, part in layer do
					if not part.Parent then continue end
					part.CFrame = frames[layerIndex][partIndex] + right * shift + environment.Vector3.new(0, vertical, 0)
					part.Transparency = math.clamp(0.3 + index * 0.05 + math.random() * 0.3, 0, 1)
				end
			end
			environment.task.wait(0.05 / state.speed)
		end
		for _, layer in layers do GameEffects.Kill.fadeGhost(state, layer, 0.2) end
	end)
end

function GameEffects.Kill.glitch(state, effect)
	local environment = state.context.environment
	local white = environment.Color3.new(1, 1, 1)
	local layers = {
		GameEffects.Kill.ghost(state, effect.char, {material = environment.Enum.Material.Neon, color = environment.Color3.fromRGB(255, 40, 80), transparency = 0.35}),
		GameEffects.Kill.ghost(state, effect.char, {material = environment.Enum.Material.Neon, color = environment.Color3.fromRGB(40, 220, 255), transparency = 0.35}),
		GameEffects.Kill.ghost(state, effect.char, {material = environment.Enum.Material.Neon, color = white, transparency = 0.55}),
	}
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local camera = state.context.workspace.CurrentCamera
	local right = camera and camera.CFrame.RightVector or environment.Vector3.new(1, 0, 0)
	GameEffects.Kill.glitchLayers(state, layers, right)

	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.chest), environment.Vector3.new(2.6, 5, 2.6))
	GameEffects.Kill.particle(state, anchor, {Texture = state.textures.glitch, Color = environment.ColorSequence.new(white, white),
		Size = GameEffects.Kill.numberSequence(state, 0, 1.6, 1, 0.8), Transparency = GameEffects.Kill.numberSequence(state, 0, 0, 1, 0.6),
		Lifetime = environment.NumberRange.new(0.08, 0.16), Shape = environment.Enum.ParticleEmitterShape.Box, Brightness = 4, ZOffset = 1}, 14)
	for index = 1, 5 do
		GameEffects.Kill.delay(state, index * 0.1, function()
			if anchor.Parent then anchor:FindFirstChildWhichIsA("ParticleEmitter"):Emit(6) end
		end)
	end
	GameEffects.Kill.light(state, anchor, environment.Color3.fromRGB(200, 80, 255), 5, 14, 0.7)
	GameEffects.Kill.cameraClicks(state, anchor)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.scratch, 0.7, 1.2, anchor)
	GameEffects.Kill.destroyLater(state, anchor, 2)
end

function GameEffects.Kill.poisonHighlight(state, body, anchor, color)
	if not body then return end

	local environment = state.context.environment
	local highlight = environment.Instance.new("Highlight")
	highlight.FillColor, highlight.OutlineColor = color, environment.Color3.fromRGB(40, 120, 20)
	highlight.FillTransparency, highlight.OutlineTransparency = 0.6, 0.3
	highlight.DepthMode, highlight.Adornee, highlight.Parent = environment.Enum.HighlightDepthMode.Occluded, body.model, body.model
	GameEffects.Kill.animate(state, 2.4, function(progress)
		highlight.FillTransparency = 0.4 + 0.2 * math.sin(progress * 22)
		if body.torso and body.torso.Parent then anchor.CFrame = body.torso.CFrame end
	end, function()
		if highlight.Parent then
			GameEffects.Kill.tween(state, highlight, 0.5, {FillColor = environment.Color3.fromRGB(30, 60, 20), FillTransparency = 0.15, OutlineTransparency = 1})
		end
	end)
end

function GameEffects.Kill.poison(state, effect)
	local environment = state.context.environment
	local color = environment.Color3.fromRGB(120, 255, 60)
	local ground = GameEffects.Kill.ground(state, effect.root, effect.ignore)
	local height = ground and ground.Y or effect.root.Y - 3
	local direction = GameEffects.Kill.direction(state, effect)
	local body = GameEffects.Kill.body(state, effect, direction * 2 + environment.Vector3.new(0, 1, 0), GameEffects.Kill.randomVector(state, 0.8), 3.2)
	GameEffects.Kill.hideEffectBody(state, effect.char)

	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.chest), environment.Vector3.new(2.2, 4, 1.4))
	GameEffects.Kill.poisonHighlight(state, body, anchor, color)
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
	local bubbles = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.bubbles, Color = colors(color, environment.Color3.fromRGB(60, 160, 30)),
		Size = sequence(0, 0.3, 1, 0.7), Transparency = sequence(0, 0.2, 0.8, 0.3, 1, 1), Lifetime = environment.NumberRange.new(0.8, 1.3),
		Speed = environment.NumberRange.new(1, 3), Acceleration = environment.Vector3.new(0, 4, 0), Rotation = environment.NumberRange.new(0, 360),
		Shape = environment.Enum.ParticleEmitterShape.Box, Brightness = 2}, 6)
	bubbles.Rate, bubbles.Enabled = 26, true
	GameEffects.Kill.delay(state, 2, function() if bubbles.Parent then bubbles.Enabled = false end end)
	local drops = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.soft, Color = colors(color), Size = sequence(0, 0.25, 1, 0.1),
		Lifetime = environment.NumberRange.new(0.4, 0.7), Speed = environment.NumberRange.new(0, 1), Acceleration = environment.Vector3.new(0, -30, 0),
		Shape = environment.Enum.ParticleEmitterShape.Box, Brightness = 2}, 0)
	drops.Rate, drops.Enabled = 20, true
	GameEffects.Kill.delay(state, 1.8, function() if drops.Parent then drops.Enabled = false end end)

	local floor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.root.X, height + 0.3, effect.root.Z), environment.Vector3.new(4, 0.4, 4))
	local attachment = environment.Instance.new("Attachment")
	attachment.Parent = floor
	GameEffects.Kill.particle(state, floor, {Texture = state.textures.smokeFB,
		FlipbookLayout = environment.Enum.ParticleFlipbookLayout.Grid4x4, FlipbookMode = environment.Enum.ParticleFlipbookMode.OneShot,
		Color = colors(environment.Color3.fromRGB(110, 220, 60), environment.Color3.fromRGB(40, 90, 20)), Size = sequence(0, 2.5, 1, 7),
		Transparency = sequence(0, 0.35, 0.7, 0.5, 1, 1), Lifetime = environment.NumberRange.new(1.4, 2), Speed = environment.NumberRange.new(1, 3),
		SpreadAngle = environment.Vector2.new(70, 70), Rotation = environment.NumberRange.new(0, 360),
		Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0.3, Brightness = 1.3}, 12, 0.1)
	GameEffects.Kill.groundRing(state, attachment, state.textures.ringEdge, color, 2, 9, 0.9, 2.5)
	for index = 1, 9 do
		GameEffects.Kill.delay(state, 0.15 + index * 0.16 + math.random() * 0.1, function()
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.bubblesDeep, 0.5, 0.8 + math.random() * 0.8, anchor)
		end)
	end
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.acid, 0.3, 1.3, anchor)
	GameEffects.Kill.light(state, anchor, color, 3, 12, 2)
	GameEffects.Kill.destroyLater(state, anchor, 3.4)
	GameEffects.Kill.destroyLater(state, floor, 3)
end

function GameEffects.Kill.balloon(state, effect)
	local environment = state.context.environment
	local colors = {environment.Color3.fromRGB(255, 70, 90), environment.Color3.fromRGB(255, 200, 60),
		environment.Color3.fromRGB(80, 220, 255), environment.Color3.fromRGB(190, 90, 255), environment.Color3.fromRGB(110, 255, 120)}
	local parts = GameEffects.Kill.staticBody(state, effect)
	GameEffects.Kill.hideEffectBody(state, effect.char)

	local original = {}
	for index, part in parts do original[index] = {frame = part.CFrame, size = part.Size} end
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.whistle, 0.6, 0.8)
	GameEffects.Kill.animate(state, 0.8, function(progress)
		local squared = progress * progress
		local scale = 1 + 0.55 * squared + math.sin(progress * 32) * 0.05 * progress
		local rise = environment.Vector3.new(0, 1.4 * squared, 0)
		for index, part in parts do
			if not part.Parent then continue end
			local base = original[index]
			part.CFrame = environment.CFrame.new(effect.chest + (base.frame.Position - effect.chest) * (1 + 0.4 * squared) + rise) * base.frame.Rotation
			part.Size = base.size * scale
		end
	end, function()
		local position = effect.chest + environment.Vector3.new(0, 1.4, 0)
		for _, part in parts do pcall(function() part:Destroy() end) end

		local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(position), environment.Vector3.new(2, 3, 2))
		local attachment = environment.Instance.new("Attachment")
		attachment.Parent = anchor
		local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
		local white = environment.Color3.new(1, 1, 1)
		for _, color in colors do
			GameEffects.Kill.particle(state, anchor, {Texture = state.textures.square, Color = environment.ColorSequence.new(color, color),
				Size = sequence(0, 0.24, 1, 0.18), Lifetime = environment.NumberRange.new(1.3, 2.1), Speed = environment.NumberRange.new(10, 22),
				SpreadAngle = environment.Vector2.new(180, 180), Drag = 2.5, Acceleration = environment.Vector3.new(0, -14, 0),
				Rotation = environment.NumberRange.new(0, 360), RotSpeed = environment.NumberRange.new(-400, 400),
				Squash = sequence(0, 0, 0.2, 1.5, 0.4, -1.5, 0.6, 1.5, 0.8, -1.5, 1, 0),
				Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0.2, LightInfluence = 0.6, Brightness = 1.6}, 14)
		end
		GameEffects.Kill.particle(state, attachment, {Texture = state.textures.ring, Color = environment.ColorSequence.new(white, white),
			Size = sequence(0, 1, 1, 9), Transparency = sequence(0, 0, 1, 1), Lifetime = environment.NumberRange.new(0.3), Brightness = 4}, 1)
		GameEffects.Kill.particle(state, attachment, {Texture = state.textures.soft, Color = environment.ColorSequence.new(white, white),
			Size = sequence(0, 3, 1, 7), Transparency = sequence(0, 0.3, 1, 1), Lifetime = environment.NumberRange.new(0.25), Brightness = 3}, 1)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.balloonPop, 1, 1.8, anchor)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.partyHorn, 0.8, 1.3, anchor)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.whistle, 0.5, 1.4, anchor)
		GameEffects.Kill.shakeCamera(state, position, 0.5, 0.2)
		GameEffects.Kill.destroyLater(state, anchor, 2.6)
	end)
end

function GameEffects.Kill.scatterBody(state, body, center, minimum, variation, lift, spin)
	local environment = state.context.environment
	GameEffects.Kill.removeSockets(body)
	for _, part in body.body do
		local direction = part.Position - center
		direction = direction.Magnitude > 0.05 and direction.Unit or environment.Vector3.new(0, 1, 0)
		part.AssemblyLinearVelocity = direction * (minimum + math.random() * variation) + environment.Vector3.new(0, lift, 0)
		part.AssemblyAngularVelocity = GameEffects.Kill.randomVector(state, spin)
	end
end

function GameEffects.Kill.removeSockets(body)
	for _, joint in body.model:GetDescendants() do
		if joint:IsA("BallSocketConstraint") then joint:Destroy() end
	end
end

function GameEffects.Kill.shred(state, effect)
	local environment = state.context.environment
	local color, white = environment.Color3.fromRGB(255, 40, 60), environment.Color3.new(1, 1, 1)
	local body = GameEffects.Kill.body(state, effect, environment.Vector3.new(0, 0, 0), nil, 3.2, nil, true)
	GameEffects.Kill.hideEffectBody(state, effect.char)

	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.chest), environment.Vector3.new(2.2, 4.4, 1.4))
	local attachment = environment.Instance.new("Attachment")
	attachment.Parent = anchor
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
	local angles = {30, 150, 80, -20}
	for index = 1, 4 do
		GameEffects.Kill.delay(state, (index - 1) * 0.075, function()
			GameEffects.Kill.arc(state, effect.chest + environment.Vector3.new(0, (index - 2.5) * 0.35, 0), angles[index] + math.random(-12, 12),
				3 + math.random() * 0.6, 1.1, color, 0.6, 0.05, 0.07, math.random(-25, 25), nil, index % 2 == 0)
			GameEffects.Kill.particle(state, attachment, {Texture = state.textures.spark, Color = colors(white, color), Size = sequence(0, 1, 1, 0),
				Lifetime = environment.NumberRange.new(0.15, 0.3), Speed = environment.NumberRange.new(16, 28), SpreadAngle = environment.Vector2.new(180, 180),
				Drag = 6, Orientation = environment.Enum.ParticleOrientation.VelocityParallel, Brightness = 5}, 10)
			GameEffects.Kill.sound(state, index % 2 == 0 and GameEffects.Kill.soundIds.whooshAiry or GameEffects.Kill.soundIds.stab1, 0.8, 0.95 + index * 0.12, anchor)
		end)
	end

	GameEffects.Kill.delay(state, 0.45, function()
		if body then body.release(environment.Vector3.new(0, 0, 0), function(result) GameEffects.Kill.scatterBody(state, result, effect.chest, 7, 6, 9, 8) end) end
		GameEffects.Kill.particle(state, anchor, {Texture = state.textures.splat,
			Color = colors(environment.Color3.fromRGB(190, 10, 30), environment.Color3.fromRGB(100, 0, 12)), Size = sequence(0, 0.7, 1, 0.25),
			Lifetime = environment.NumberRange.new(0.6, 1.1), Speed = environment.NumberRange.new(8, 20), SpreadAngle = environment.Vector2.new(180, 180),
			Acceleration = environment.Vector3.new(0, -65, 0), Rotation = environment.NumberRange.new(0, 360), RotSpeed = environment.NumberRange.new(-200, 200),
			Shape = environment.Enum.ParticleEmitterShape.Box, ShapeStyle = environment.Enum.ParticleEmitterShapeStyle.Volume, LightEmission = 0, Brightness = 1.1}, 60)
		GameEffects.Kill.particle(state, attachment, {Texture = state.textures.burst,
			Color = colors(environment.Color3.fromRGB(255, 60, 70), environment.Color3.fromRGB(120, 0, 12)), Size = sequence(0, 2, 1, 8),
			Transparency = sequence(0, 0, 1, 1), Lifetime = environment.NumberRange.new(0.3), Brightness = 3}, 1)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.rip, 0.9, 0.7, anchor)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.guts2, 0.9, 0.9, anchor)
		GameEffects.Kill.shakeCamera(state, effect.chest, 0.7, 0.25)
		GameEffects.Kill.delay(state, 0.25, function()
			GameEffects.Kill.splat(state, effect.root, 6.5, environment.Color3.fromRGB(125, 0, 12), 3.2, effect.ignore, 1.1)
		end)
	end)
	GameEffects.Kill.light(state, anchor, color, 6, 14, 0.8)
	GameEffects.Kill.destroyLater(state, anchor, 2.5)
end

function GameEffects.Kill.upForce(state, body, strength)
	if not body or not body.torso then return nil end

	local context, environment = state.context, state.context.environment
	local mass = 0
	for _, part in body.body do mass += part:GetMass() end
	local attachment = environment.Instance.new("Attachment")
	attachment.Parent = body.torso
	local force = environment.Instance.new("VectorForce")
	force.Attachment0, force.RelativeTo, force.ApplyAtCenterOfMass = attachment, environment.Enum.ActuatorRelativeTo.World, true
	force.Force, force.Parent = environment.Vector3.new(0, mass * context.workspace.Gravity * strength, 0), body.torso
	return force
end

function GameEffects.Kill.effectAttachment(state, position, lifetime)
	local environment = state.context.environment
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(position), environment.Vector3.new(0.4, 0.4, 0.4))
	local attachment = environment.Instance.new("Attachment")
	attachment.Parent = anchor
	GameEffects.Kill.destroyLater(state, anchor, lifetime or 4)
	return anchor, attachment
end

function GameEffects.Kill.bubble(state, effect)
	local environment = state.context.environment
	local body = GameEffects.Kill.body(state, effect, environment.Vector3.new(0, 2, 0), GameEffects.Kill.randomVector(state, 1), 4.2)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	if not body or not body.torso then return end

	local force = GameEffects.Kill.upForce(state, body, 1.02)
	local shell = environment.Instance.new("Part")
	shell.Shape = environment.Enum.PartType.Ball
	shell.Anchored, shell.CanCollide, shell.CanQuery, shell.CanTouch, shell.CastShadow = true, false, false, false, false
	shell.Material, shell.Color = environment.Enum.Material.Glass, environment.Color3.fromRGB(200, 240, 255)
	shell.Transparency, shell.Reflectance = 0.7, 0.4
	shell.Size, shell.CFrame, shell.Parent = environment.Vector3.new(0.5, 0.5, 0.5), environment.CFrame.new(body.torso.Position), GameEffects.Kill.folder(state)
	local shine = shell:Clone()
	shine.Material, shine.Color = environment.Enum.Material.ForceField, environment.Color3.fromRGB(190, 130, 255)
	shine.Transparency, shine.Reflectance, shine.Parent = 0, 0, GameEffects.Kill.folder(state)

	GameEffects.Kill.animate(state, 2, function(progress)
		if not body.torso.Parent then return end
		local time = progress * 2
		local diameter = math.min(1, time / 0.3) * 6.5 + math.sin(time * 6) * 0.2
		shell.Size = environment.Vector3.new(diameter, diameter * (1 + math.sin(time * 5) * 0.03), diameter)
		shine.Size = shell.Size * 1.01
		shell.CFrame, shine.CFrame = environment.CFrame.new(body.torso.Position), environment.CFrame.new(body.torso.Position)
	end, function()
		local position = shell.Position
		for _, part in {shell, shine} do pcall(function() part:Destroy() end) end
		if force then pcall(function() force:Destroy() end) end

		local _, attachment = GameEffects.Kill.effectAttachment(state, position)
		local white = environment.Color3.new(1, 1, 1)
		local blue = environment.Color3.fromRGB(210, 240, 255)
		GameEffects.Kill.particle(state, attachment, {Texture = state.textures.soft, Color = environment.ColorSequence.new(blue, blue),
			Size = GameEffects.Kill.numberSequence(state, 0, 0.35, 1, 0.1), Lifetime = environment.NumberRange.new(0.5, 0.9),
			Speed = environment.NumberRange.new(8, 16), SpreadAngle = environment.Vector2.new(180, 180),
			Acceleration = environment.Vector3.new(0, -30, 0), LightEmission = 0.3, Brightness = 2}, 40)
		GameEffects.Kill.particle(state, attachment, {Texture = state.textures.ring, Color = environment.ColorSequence.new(white, white),
			Size = GameEffects.Kill.numberSequence(state, 0, 3, 1, 9), Transparency = GameEffects.Kill.numberSequence(state, 0, 0.2, 1, 1),
			Lifetime = environment.NumberRange.new(0.3), Brightness = 3}, 1)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.balloonPop, 1, 1.2)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.waterSplash, 0.7, 1.3)
	end)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.bubblesDeep, 0.6, 1, nil, 1.8)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.fairy, 0.4, 1.4, nil, 1.5)
end

function GameEffects.Kill.paintRays(state, effect, direction, first, second)
	local context, environment = state.context, state.context.environment
	local params = environment.RaycastParams.new()
	params.FilterType, params.RespectCanCollide = environment.Enum.RaycastFilterType.Exclude, true
	params.FilterDescendantsInstances = {effect.char, context.workspace.CurrentCamera, GameEffects.Kill.bodiesFolder(state), context.player.Character}

	for index = 1, 10 do
		local offset = environment.Vector3.new(math.random() - 0.5, math.random() * 0.9 - 0.6, math.random() - 0.5) * 1.4
		local result = context.workspace:Raycast(effect.chest, (direction + offset).Unit * 16, params)
		if not result or result.Instance.Transparency >= 0.9 then continue end

		local model = result.Instance:FindFirstAncestorOfClass("Model")
		if model and model:FindFirstChildOfClass("Humanoid") then continue end
		GameEffects.Kill.delay(state, result.Distance / 45, function()
			GameEffects.Kill.groundDecal(state, result.Position, result.Normal, 1.2 + math.random() * 1.8,
				index % 2 == 0 and first or second, 3.2, 0.1, state.textures.splat, 2)
		end)
	end
end

function GameEffects.Kill.paint(state, effect)
	local environment = state.context.environment
	local palette = {environment.Color3.fromRGB(255, 60, 120), environment.Color3.fromRGB(60, 200, 255),
		environment.Color3.fromRGB(255, 210, 40), environment.Color3.fromRGB(120, 255, 90),
		environment.Color3.fromRGB(170, 90, 255), environment.Color3.fromRGB(255, 120, 40)}
	local index = math.random(1, #palette)
	local other = (index % #palette + math.random(1, #palette - 1) - 1) % #palette + 1
	local first, second = palette[index], palette[other]
	local direction = GameEffects.Kill.direction(state, effect)
	local body = GameEffects.Kill.body(state, effect, direction * 18 + environment.Vector3.new(0, 8, 0), GameEffects.Kill.randomVector(state, 3), 3)
	GameEffects.Kill.hideEffectBody(state, effect.char)

	if body then
		local highlight = environment.Instance.new("Highlight")
		highlight.FillColor, highlight.OutlineColor, highlight.FillTransparency, highlight.OutlineTransparency = first, second, 0.3, 0.4
		highlight.DepthMode, highlight.Adornee, highlight.Parent = environment.Enum.HighlightDepthMode.Occluded, body.model, body.model
	end

	local up = math.abs(direction.Y) < 0.95 and environment.Vector3.new(0, 1, 0) or environment.Vector3.new(1, 0, 0)
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.fromMatrix(effect.chest, direction:Cross(up).Unit, direction), environment.Vector3.new(0.5, 0.5, 0.5))
	local attachment = environment.Instance.new("Attachment")
	attachment.Parent = anchor
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(a, b) return environment.ColorSequence.new(a, b or a) end
	for colorIndex, color in {first, second} do
		GameEffects.Kill.particle(state, attachment, {Texture = state.textures.splat, Color = colors(color), Size = sequence(0, 0.7, 1, 0.3),
			Lifetime = environment.NumberRange.new(0.5, 0.9), Speed = environment.NumberRange.new(12, 26), SpreadAngle = environment.Vector2.new(65, 65),
			Acceleration = environment.Vector3.new(0, -50, 0), Rotation = environment.NumberRange.new(0, 360), RotSpeed = environment.NumberRange.new(-200, 200),
			LightEmission = 0.1, LightInfluence = 0.4, Brightness = 1.5}, colorIndex == 1 and 30 or 20)
	end
	GameEffects.Kill.particle(state, attachment, {Texture = state.textures.burst, Color = colors(first, second), Size = sequence(0, 2, 1, 6),
		Transparency = sequence(0, 0, 1, 1), Lifetime = environment.NumberRange.new(0.25), Brightness = 2.5}, 1)
	GameEffects.Kill.paintRays(state, effect, direction, first, second)
	GameEffects.Kill.delay(state, 0.6, function()
		local position = body and body.torso and body.torso.Parent and body.torso.Position or effect.root
		GameEffects.Kill.splat(state, position, 3.2, first, 3, effect.ignore, 0.3, state.textures.splat, 2)
	end)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.mud, 1, 1.1, anchor)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.bounce, 0.6, 1.4, anchor)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.punch, 0.5, 1.4, anchor)
	GameEffects.Kill.shakeCamera(state, effect.chest, 0.4, 0.2)
	GameEffects.Kill.destroyLater(state, anchor, 2)
end

function GameEffects.Kill.reaper(state, effect)
	local environment = state.context.environment
	local color = environment.Color3.fromRGB(110, 255, 160)
	local ground = GameEffects.Kill.ground(state, effect.root, effect.ignore)
	local height = ground and ground.Y or effect.root.Y - 3
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.chest), environment.Vector3.new(2.2, 4, 1.6))
	local attachment = environment.Instance.new("Attachment")
	attachment.Parent = anchor
	GameEffects.Kill.arc(state, effect.chest + environment.Vector3.new(0, 0.4, 0), -15, 4.4, 1.35, color, 1.2, 0.13, 0.12, 25,
		environment.Color3.fromRGB(215, 255, 230), math.random() < 0.5)
	local shadow = GameEffects.Kill.ghost(state, effect.char, {material = environment.Enum.Material.SmoothPlastic,
		color = environment.Color3.fromRGB(12, 10, 16), transparency = 0})
	local soul = GameEffects.Kill.ghost(state, effect.char, {material = environment.Enum.Material.ForceField, color = color, transparency = 0})
	GameEffects.Kill.hideEffectBody(state, effect.char)

	GameEffects.Kill.delay(state, 0.2, function()
		for _, part in shadow do
			if not part.Parent then continue end
			GameEffects.Kill.tween(state, part, 1, {CFrame = part.CFrame - environment.Vector3.new(0, 5.5, 0), Transparency = 0.6},
				environment.Enum.EasingStyle.Quad, environment.Enum.EasingDirection.In)
			GameEffects.Kill.destroyLater(state, part, 1.05)
		end
	end)
	local frames = {}
	for index, part in soul do frames[index] = part.CFrame end
	local angle = math.random() * 6.28
	GameEffects.Kill.delay(state, 0.15, function()
		GameEffects.Kill.animate(state, 1.5, function(progress)
			local eased = 1 - (1 - progress) ^ 2
			local rotation = angle + eased * 7
			local offset = environment.Vector3.new(math.cos(rotation) * 1.4 * eased, eased * 7, math.sin(rotation) * 1.4 * eased)
			for index, part in soul do part.CFrame, part.Transparency = frames[index] + offset, progress ^ 1.6 end
		end, function() for _, part in soul do pcall(function() part:Destroy() end) end end)
	end)

	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
	GameEffects.Kill.particle(state, anchor, {Texture = state.textures.soft, Color = colors(color, environment.Color3.fromRGB(20, 80, 50)),
		Size = sequence(0, 0.6, 1, 0), Lifetime = environment.NumberRange.new(0.8, 1.4), Speed = environment.NumberRange.new(1, 3),
		Acceleration = environment.Vector3.new(0, 7, 0), SpreadAngle = environment.Vector2.new(40, 40), Shape = environment.Enum.ParticleEmitterShape.Box,
		Brightness = 3}, 30, 0.1)
	local floor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.root.X, height + 0.15, effect.root.Z), environment.Vector3.new(4, 0.2, 4))
	local floorAttachment = environment.Instance.new("Attachment")
	floorAttachment.Parent = floor
	GameEffects.Kill.particle(state, floor, {Texture = state.textures.smokeFB,
		FlipbookLayout = environment.Enum.ParticleFlipbookLayout.Grid4x4, FlipbookMode = environment.Enum.ParticleFlipbookMode.OneShot,
		Color = colors(environment.Color3.fromRGB(22, 18, 28)), Size = sequence(0, 2.5, 1, 5), Transparency = sequence(0, 0.2, 0.7, 0.4, 1, 1),
		Lifetime = environment.NumberRange.new(0.9, 1.3), Speed = environment.NumberRange.new(1, 3), SpreadAngle = environment.Vector2.new(60, 60),
		Rotation = environment.NumberRange.new(0, 360), Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0, Brightness = 1}, 12)
	local ring = GameEffects.Kill.groundRing(state, floorAttachment, state.textures.vortex, color, 2, 9, 1.1, 3)
	ring.RotSpeed = environment.NumberRange.new(-220)
	GameEffects.Kill.light(state, anchor, color, 4, 14, 1.2)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.magicGrowl, 1, 0.55, anchor)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.whisper, 0.6, 0.8, anchor)
	GameEffects.Kill.destroyLater(state, anchor, 3)
	GameEffects.Kill.destroyLater(state, floor, 3)
end

function GameEffects.Kill.blade(state, color, material, length, width, transparency)
	local environment = state.context.environment
	local parts = {}
	local specs = {
		{"WedgePart", environment.Vector3.new(0.06, length, width / 2), color, material},
		{"WedgePart", environment.Vector3.new(0.06, length, width / 2), color, material},
		{"Part", environment.Vector3.new(0.14, 0.1, width + 0.3), environment.Color3.fromRGB(40, 36, 34), environment.Enum.Material.Metal},
		{"Part", environment.Vector3.new(0.14, 0.7, 0.17), environment.Color3.fromRGB(60, 34, 20), environment.Enum.Material.Wood},
	}
	for _, spec in specs do
		local part = environment.Instance.new(spec[1])
		part.Anchored, part.CanCollide, part.CanQuery, part.CanTouch, part.CastShadow = true, false, false, false, false
		part.Size, part.Color, part.Material, part.Transparency = spec[2], spec[3], spec[4], transparency or 0
		part.Reflectance, part.Parent = spec[4] == environment.Enum.Material.Metal and 0.35 or 0, GameEffects.Kill.folder(state)
		table.insert(parts, part)
	end
	return parts, {environment.CFrame.new(0, length / 2, -width / 4),
		environment.CFrame.Angles(0, math.pi, 0) * environment.CFrame.new(0, length / 2, -width / 4),
		environment.CFrame.new(0, -0.05, 0), environment.CFrame.new(0, -0.45, 0)}
end

function GameEffects.Kill.bladeFrame(state, position, direction)
	local environment = state.context.environment
	local reference = math.abs(direction.Z) < 0.9 and environment.Vector3.new(0, 0, 1) or environment.Vector3.new(1, 0, 0)
	return environment.CFrame.fromMatrix(position, direction:Cross(reference).Unit, direction)
end

function GameEffects.Kill.positionBlade(parts, offsets, frame)
	for index, part in parts do if part.Parent then part.CFrame = frame * offsets[index] end end
end

function GameEffects.Kill.butterflies(state, effect)
	local environment = state.context.environment
	local palette = {
		{environment.Color3.fromRGB(255, 140, 210), environment.Color3.fromRGB(190, 80, 255)},
		{environment.Color3.fromRGB(120, 215, 255), environment.Color3.fromRGB(60, 110, 255)},
		{environment.Color3.fromRGB(255, 225, 120), environment.Color3.fromRGB(255, 130, 60)},
		{environment.Color3.fromRGB(150, 255, 205), environment.Color3.fromRGB(50, 195, 170)},
		{environment.Color3.fromRGB(215, 175, 255), environment.Color3.fromRGB(255, 110, 190)},
	}
	local white = environment.Color3.new(1, 1, 1)
	local body, model = GameEffects.Kill.staticBody(state, effect)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local highlight = model and GameEffects.Kill.highlight(state, model, palette[1][1], white, 1, 0.35)
	if highlight then GameEffects.Kill.tween(state, highlight, 0.35, {FillTransparency = 0.45}) end
	local sorted = table.clone(body)
	table.sort(sorted, function(first, second) return first.Position.Y < second.Position.Y end)
	local rotation = environment.CFrame.Angles(0, 0, math.pi / 2)
	local butterflies, created = {}, {}
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local function wing(size, color, transparency)
		local part = environment.Instance.new("Part")
		part.Shape, part.Anchored = environment.Enum.PartType.Cylinder, true
		part.CanCollide, part.CanQuery, part.CanTouch, part.CastShadow = false, false, false, false
		part.Material, part.Color, part.Transparency = environment.Enum.Material.Neon, color, transparency
		part.Size, part.Parent = environment.Vector3.new(0.02, size, size), GameEffects.Kill.folder(state)
		table.insert(created, part)
		return part
	end
	local function spawn(position)
		if #butterflies >= 20 then return end
		local colors, scale = palette[math.random(1, #palette)], 0.8 + math.random() * 0.5
		local part = environment.Instance.new("Part")
		part.Anchored = true
		part.CanCollide, part.CanQuery, part.CanTouch, part.CastShadow = false, false, false, false
		part.Material, part.Color = environment.Enum.Material.SmoothPlastic, environment.Color3.fromRGB(40, 30, 50)
		part.Size = environment.Vector3.new(0.07 * scale, 0.07 * scale, 0.38 * scale)
		part.CFrame, part.Parent = environment.CFrame.new(position), GameEffects.Kill.folder(state)
		table.insert(created, part)
		local emitter = GameEffects.Kill.particle(state, part, {Texture = state.textures.star4, Color = environment.ColorSequence.new(white, colors[1]),
			Size = sequence(0, 0.2, 1, 0), Lifetime = environment.NumberRange.new(0.4, 0.7), Speed = environment.NumberRange.new(0.1),
			Rotation = environment.NumberRange.new(0, 90), Brightness = 4}, 0)
		emitter.Rate, emitter.Enabled = 9, true
		local butterfly = {position = position, phase = math.random() * 6.28, wobble = math.random() * 6.28,
			velocity = environment.Vector3.new((math.random() - 0.5) * 3, 2 + math.random() * 2, (math.random() - 0.5) * 3), body = part}
		butterfly.wings = {
			{part = wing(0.62 * scale, colors[1], 0.1), side = -1, z = -0.1 * scale, radius = 0.3 * scale},
			{part = wing(0.62 * scale, colors[1], 0.1), side = 1, z = -0.1 * scale, radius = 0.3 * scale},
			{part = wing(0.44 * scale, colors[2], 0.12), side = -1, z = 0.15 * scale, radius = 0.22 * scale},
			{part = wing(0.44 * scale, colors[2], 0.12), side = 1, z = 0.15 * scale, radius = 0.22 * scale},
		}
		table.insert(butterflies, butterfly)
	end
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.chest), environment.Vector3.new(0.3, 0.3, 0.3))
	local previous, nextPart = 0, 1
	GameEffects.Kill.animate(state, 3.2, function(progress)
		local elapsed = progress * 3.2
		local delta = elapsed - previous
		previous = elapsed
		while nextPart <= #sorted and elapsed >= 0.3 + nextPart / #sorted * 0.9 do
			local part = sorted[nextPart]
			nextPart += 1
			if part.Parent then
				GameEffects.Kill.tween(state, part, 0.25, {Transparency = 1})
				for _, child in part:GetChildren() do if child:IsA("Decal") then GameEffects.Kill.tween(state, child, 0.25, {Transparency = 1}) end end
				anchor.CFrame, anchor.Size = part.CFrame, part.Size
				spawn(part.Position)
			end
		end
		local parts, frames = {}, {}
		for _, butterfly in butterflies do
			local velocity = butterfly.velocity
			butterfly.velocity = (velocity + environment.Vector3.new(math.sin(elapsed * 2.2 + butterfly.wobble) * 4,
				1.3 + math.sin(elapsed * 3 + butterfly.phase) * 1.6, math.cos(elapsed * 1.9 + butterfly.wobble) * 4) * delta) * (1 - 0.35 * delta)
			butterfly.position += butterfly.velocity * delta
			local horizontal = environment.Vector3.new(butterfly.velocity.X, 0, butterfly.velocity.Z)
			local frame = environment.CFrame.lookAt(butterfly.position, butterfly.position + (horizontal.Magnitude > 0.1 and horizontal or environment.Vector3.new(0, 0, -1)))
				* environment.CFrame.Angles(-math.pi / 10, 0, 0)
			local flap = (math.sin((elapsed + butterfly.phase) * 24) * 0.5 + 0.5) * 1.35
			table.insert(parts, butterfly.body)
			table.insert(frames, frame)
			local fade = math.clamp((elapsed - 2.5) / 0.7, 0, 1)
			for _, item in butterfly.wings do
				table.insert(parts, item.part)
				table.insert(frames, frame * environment.CFrame.new(item.side * 0.03, 0, item.z) * environment.CFrame.Angles(0, 0, item.side * flap)
					* environment.CFrame.new(item.side * item.radius, 0, 0) * rotation)
				if fade > 0 then item.part.Transparency = 0.1 + 0.9 * fade end
			end
			if fade > 0 then butterfly.body.Transparency = fade end
		end
		GameEffects.Kill.moveParts(state, parts, frames)
	end, function()
		for _, part in created do pcall(function() part:Destroy() end) end
		for _, part in body do pcall(function() part:Destroy() end) end
	end)
	local emitter = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.star4, Color = environment.ColorSequence.new(white, palette[5][1]),
		Size = sequence(0, 0, 0.3, 0.5, 1, 0), Lifetime = environment.NumberRange.new(0.4, 0.8), Speed = environment.NumberRange.new(1, 3),
		SpreadAngle = environment.Vector2.new(180, 180), Rotation = environment.NumberRange.new(0, 90), Shape = environment.Enum.ParticleEmitterShape.Box, Brightness = 5}, 0)
	emitter.Rate, emitter.Enabled = 30, true
	GameEffects.Kill.delay(state, 1.3, function() if emitter.Parent then emitter.Enabled = false end end)
	GameEffects.Kill.destroyLater(state, anchor, 2.5)
	GameEffects.Kill.light(state, anchor, palette[1][1], 3, 12, 1.6)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.fairy, 0.8, 1, nil, 2.5)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.shimmer, 0.5, 1.2)
	GameEffects.Kill.delay(state, 0.4, function() GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.pigeonWings, 0.35, 1.5, nil, 1.6) end)
	GameEffects.Kill.delay(state, 1.4, function() GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.chimes, 0.4, 1.2, nil, 2) end)
end

function GameEffects.Kill.knifeRain(state, effect)
	local environment = state.context.environment
	local white = environment.Color3.new(1, 1, 1)
	local body = GameEffects.Kill.body(state, effect, environment.Vector3.new(0, -2, 0), GameEffects.Kill.randomVector(state, 1), 3.4, nil, true)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local targets = {}
	if body then
		for _, name in {"UpperTorso", "LowerTorso", "LeftUpperLeg", "RightUpperArm"} do
			local part = body.model:FindFirstChild(name)
			if part then table.insert(targets, part) end
		end
	end
	local hits = 0
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
	for index = 1, 11 do
		GameEffects.Kill.delay(state, (index - 1) * 0.07, function()
			if not state.alive then return end
			local target = index % 2 == 1 and targets[(index + 1) / 2]
			local position
			if target then
				position = target.Position + environment.Vector3.new((math.random() - 0.5) * 0.5, 0.3, (math.random() - 0.5) * 0.3)
			else
				local angle, radius = math.random() * 6.28, 1.4 + math.random() * 2.4
				local offset = environment.Vector3.new(math.cos(angle) * radius, 0, math.sin(angle) * radius)
				local ground = GameEffects.Kill.ground(state, effect.root + offset, effect.ignore)
				position = ground and ground - environment.Vector3.new(0, 0.35, 0) or effect.root + offset - environment.Vector3.new(0, 3, 0)
			end
			local direction = environment.Vector3.new((math.random() - 0.5) * 0.5, -1, (math.random() - 0.5) * 0.5).Unit
			local parts, offsets = GameEffects.Kill.blade(state, environment.Color3.fromRGB(210, 214, 224), environment.Enum.Material.Metal, 1.7, 0.36)
			local finish = GameEffects.Kill.bladeFrame(state, position - direction * (1.7 - 0.45), direction)
			local start = finish - direction * 16
			GameEffects.Kill.positionBlade(parts, offsets, start)
			GameEffects.Kill.animate(state, 0.2, function(progress)
				GameEffects.Kill.positionBlade(parts, offsets, start:Lerp(finish, progress * progress))
			end, function()
				local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(position), environment.Vector3.new(0.5, 0.5, 0.5))
				GameEffects.Kill.particle(state, anchor, {Texture = state.textures.spark, Color = colors(white, environment.Color3.fromRGB(255, 220, 160)),
					Size = sequence(0, 0.5, 1, 0), Lifetime = environment.NumberRange.new(0.15, 0.3), Speed = environment.NumberRange.new(8, 16),
					SpreadAngle = environment.Vector2.new(180, 180), Drag = 5, Orientation = environment.Enum.ParticleOrientation.VelocityParallel, Brightness = 4}, 8)
				if target and target.Parent then
					for _, part in parts do
						part.Anchored, part.Massless, part.Parent = false, true, body.model
						local weld = environment.Instance.new("WeldConstraint")
						weld.Part0, weld.Part1, weld.Parent = target, part, part
					end
					GameEffects.Kill.particle(state, anchor, {Texture = state.textures.splat, Color = colors(environment.Color3.fromRGB(170, 0, 20), environment.Color3.fromRGB(90, 0, 10)),
						Size = sequence(0, 0.4, 1, 0.15), Lifetime = environment.NumberRange.new(0.4, 0.7), Speed = environment.NumberRange.new(6, 12),
						SpreadAngle = environment.Vector2.new(180, 180), Acceleration = environment.Vector3.new(0, -55, 0), Rotation = environment.NumberRange.new(0, 360), LightEmission = 0, Brightness = 1}, 14)
					GameEffects.Kill.delay(state, 2.7, function() for _, part in parts do if part.Parent then GameEffects.Kill.tween(state, part, 0.4, {Transparency = 1}) end end end)
					hits += 1
					if hits == 2 then body.release() end
					GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.stab1, 0.7, 1.3 + math.random() * 0.3, anchor)
				else
					local gray = environment.Color3.fromRGB(140, 135, 130)
					GameEffects.Kill.particle(state, anchor, {Texture = state.textures.soft, Color = colors(gray), Size = sequence(0, 0.8, 1, 2),
						Transparency = sequence(0, 0.4, 1, 1), Lifetime = environment.NumberRange.new(0.4, 0.7), Speed = environment.NumberRange.new(2, 5),
						SpreadAngle = environment.Vector2.new(70, 70), LightEmission = 0, LightInfluence = 1, Brightness = 1}, 5)
					GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.arrow2, 0.6, 0.6 + math.random() * 0.3, anchor)
					GameEffects.Kill.delay(state, 2.2, function() for _, part in parts do if part.Parent then GameEffects.Kill.tween(state, part, 0.4, {Transparency = 1}) end end end)
					for _, part in parts do GameEffects.Kill.destroyLater(state, part, 2.7) end
				end
				GameEffects.Kill.destroyLater(state, anchor, 1)
			end)
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.arrow, 0.35, 1.6 + math.random() * 0.4)
		end)
	end
	GameEffects.Kill.delay(state, 1, function() if body and not body.released then body.release() end end)
	GameEffects.Kill.delay(state, 0.9, function()
		local position = body and body.torso and body.torso.Parent and body.torso.Position or effect.root
		GameEffects.Kill.splat(state, position, 4, environment.Color3.fromRGB(125, 0, 12), 2.6, effect.ignore, 1)
	end)
end

function GameEffects.Kill.judgment(state, effect)
	local environment = state.context.environment
	local color, white = environment.Color3.fromRGB(255, 225, 140), environment.Color3.new(1, 1, 1)
	local body, model = GameEffects.Kill.staticBody(state, effect)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	if model then GameEffects.Kill.highlight(state, model, color, environment.Color3.fromRGB(255, 250, 220), 0.55, 0) end
	local ground = GameEffects.Kill.ground(state, effect.root, effect.ignore)
	local height = ground and ground.Y or effect.root.Y - 3
	local beam = environment.Instance.new("Part")
	beam.Shape, beam.Anchored, beam.CanCollide, beam.CanQuery, beam.CanTouch, beam.CastShadow = environment.Enum.PartType.Cylinder, true, false, false, false, false
	beam.Material, beam.Color, beam.Transparency = environment.Enum.Material.Neon, color, 0.55
	beam.Size = environment.Vector3.new(160, 0.2, 0.2)
	beam.CFrame = environment.CFrame.new(effect.root.X, height + 80, effect.root.Z) * environment.CFrame.Angles(0, 0, math.pi / 2)
	beam.Parent = GameEffects.Kill.folder(state)
	GameEffects.Kill.tween(state, beam, 0.3, {Size = environment.Vector3.new(160, 5.5, 5.5)}, environment.Enum.EasingStyle.Quad)
	GameEffects.Kill.delay(state, 2, function()
		if beam.Parent then GameEffects.Kill.tween(state, beam, 0.5, {Size = environment.Vector3.new(160, 0.1, 0.1), Transparency = 1}) end
	end)
	GameEffects.Kill.destroyLater(state, beam, 2.6)
	local adornments = {}
	for index = 0, 15 do
		local first, second = index / 16 * 6.283, (index + 1) / 16 * 6.283
		local start = effect.head + environment.Vector3.new(math.cos(first) * 0.8, 1.1, math.sin(first) * 0.8)
		local finish = effect.head + environment.Vector3.new(math.cos(second) * 0.8, 1.1, math.sin(second) * 0.8)
		table.insert(adornments, GameEffects.Kill.beam(state, start, finish, 0.12, environment.Color3.fromRGB(255, 230, 120), environment.Enum.Material.Neon, 0))
	end
	local direction = GameEffects.Kill.cameraDirection(state)
	local wingCenter = effect.chest + direction * 0.6 + environment.Vector3.new(0, 0.4, 0)
	local wings = {}
	for side = -1, 1, 2 do
		for index = 1, 4 do
			local part = environment.Instance.new("WedgePart")
			part.Anchored, part.CanCollide, part.CanQuery, part.CanTouch, part.CastShadow = true, false, false, false, false
			part.Size, part.Material, part.Color, part.Transparency = environment.Vector3.new(0.08, 2.4 + index * 0.5, 0.7), environment.Enum.Material.Neon, environment.Color3.fromRGB(255, 252, 240), 0.15
			part.Parent = GameEffects.Kill.folder(state)
			table.insert(wings, {part = part, side = side, index = index})
			table.insert(adornments, part)
		end
	end
	local bodyFrames, haloFrames = {}, {}
	for index, part in body do bodyFrames[index] = part.CFrame end
	local function wingFrame(wing, spread)
		local angle = math.rad(20 + wing.index * 22) * spread
		return environment.CFrame.lookAt(wingCenter, wingCenter - direction) * environment.CFrame.new(wing.side * 0.3, 0, 0)
			* environment.CFrame.Angles(0, 0, -wing.side * (angle + 0.15)) * environment.CFrame.new(0, (2.4 + wing.index * 0.5) / 2, 0)
			* environment.CFrame.Angles(0, math.pi / 2, 0)
	end
	for _, wing in wings do wing.part.CFrame = wingFrame(wing, 0) end
	for index, part in adornments do haloFrames[index] = part.CFrame end
	GameEffects.Kill.animate(state, 2, function(progress)
		local elapsed = progress * 2
		local spread = math.clamp(elapsed / 0.4, 0, 1)
		local rise = elapsed < 0.5 and 0 or ((elapsed - 0.5) / 1.5) ^ 2 * 14
		local offset, parts, frames = environment.Vector3.new(0, rise, 0), {}, {}
		for index, part in body do
			if not part.Parent then continue end
			table.insert(parts, part)
			table.insert(frames, bodyFrames[index] + offset)
		end
		for _, wing in wings do
			local flap = math.sin(elapsed * 9) * 0.12 * spread
			table.insert(parts, wing.part)
			table.insert(frames, wingFrame(wing, spread + flap) + offset)
		end
		for index = 1, 16 do table.insert(parts, adornments[index]); table.insert(frames, haloFrames[index] + offset) end
		GameEffects.Kill.moveParts(state, parts, frames)
	end, function()
		local position = effect.chest + environment.Vector3.new(0, 14, 0)
		GameEffects.Kill.flash(state, position, color, 14, 6)
		local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(position), environment.Vector3.new(2, 3, 2))
		GameEffects.Kill.particle(state, anchor, {Texture = state.textures.leaf, Color = environment.ColorSequence.new(white, white),
			Size = GameEffects.Kill.numberSequence(state, 0, 0.45, 1, 0.3), Lifetime = environment.NumberRange.new(1.5, 2.5), Speed = environment.NumberRange.new(3, 8),
			SpreadAngle = environment.Vector2.new(180, 180), Drag = 1.5, Acceleration = environment.Vector3.new(0, -3, 0), Rotation = environment.NumberRange.new(0, 360),
			RotSpeed = environment.NumberRange.new(-200, 200), Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0.4, LightInfluence = 0.5, Brightness = 2}, 40)
		GameEffects.Kill.destroyLater(state, anchor, 3)
		for _, group in {body, adornments} do for _, part in group do pcall(function() part:Destroy() end) end end
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.chimes, 0.7, 1.2, nil, 2)
	end)
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.chest), environment.Vector3.new(3, 5, 3))
	GameEffects.Kill.particle(state, anchor, {Texture = state.textures.needles, Color = environment.ColorSequence.new(color, white),
		Size = GameEffects.Kill.numberSequence(state, 0, 5, 0.5, 8, 1, 9), Transparency = GameEffects.Kill.numberSequence(state, 0, 0.3, 1, 1),
		Lifetime = environment.NumberRange.new(1.6), Brightness = 3, ZOffset = -1}, 1)
	local emitter = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.leaf, Color = environment.ColorSequence.new(white, white),
		Size = GameEffects.Kill.numberSequence(state, 0, 0.35, 1, 0.25), Lifetime = environment.NumberRange.new(1.5, 2.2), Speed = environment.NumberRange.new(0.5, 1.5),
		Acceleration = environment.Vector3.new(0, -2, 0), Rotation = environment.NumberRange.new(0, 360), RotSpeed = environment.NumberRange.new(-150, 150),
		Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0.3, LightInfluence = 0.5, Brightness = 2}, 0)
	emitter.Rate, emitter.Enabled = 16, true
	GameEffects.Kill.delay(state, 1.8, function() if emitter.Parent then emitter.Enabled = false end end)
	GameEffects.Kill.light(state, anchor, color, 6, 20, 2)
	GameEffects.Kill.destroyLater(state, anchor, 4)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.choir, 0.6, 1, nil, 2.4)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.fairy, 0.5, 1.5, nil, 2)
end

function GameEffects.Kill.vampire(state, effect)
	local environment = state.context.environment
	local body = GameEffects.Kill.staticBody(state, effect)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local pale = GameEffects.Kill.transmute(state, body, environment.Enum.Material.SmoothPlastic, environment.Color3.fromRGB(170, 165, 162), 0.9, false, true)
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.chest), environment.Vector3.new(2, 4, 1.4))
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
	local white = environment.Color3.new(1, 1, 1)
	GameEffects.Kill.particle(state, anchor, {Texture = state.textures.soft, Color = colors(environment.Color3.fromRGB(170, 0, 25)), Size = sequence(0, 1.5, 1, 4),
		Transparency = sequence(0, 0.45, 1, 1), Lifetime = environment.NumberRange.new(0.6, 0.9), Speed = environment.NumberRange.new(1, 3),
		SpreadAngle = environment.Vector2.new(180, 180), Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0.4, Brightness = 1.5}, 8)
	GameEffects.Kill.delay(state, 1, function()
		for _, part in body do pcall(function() part:Destroy() end) end
		for _, part in pale do
			if not part.Parent then continue end
			GameEffects.Kill.tween(state, part, 0.5, {Size = part.Size * 0.3, CFrame = part.CFrame - environment.Vector3.new(0, 1.5, 0), Transparency = 1},
				environment.Enum.EasingStyle.Quad, environment.Enum.EasingDirection.In)
			for _, child in part:GetChildren() do if child:IsA("Decal") then GameEffects.Kill.tween(state, child, 0.4, {Transparency = 1}) end end
			GameEffects.Kill.destroyLater(state, part, 0.55)
		end
		GameEffects.Kill.particle(state, anchor, {Texture = state.textures.square, Color = colors(environment.Color3.fromRGB(190, 185, 180), environment.Color3.fromRGB(90, 88, 86)),
			Size = sequence(0, 0.2, 1, 0.05), Lifetime = environment.NumberRange.new(0.8, 1.3), Speed = environment.NumberRange.new(0.5, 2.5),
			SpreadAngle = environment.Vector2.new(180, 180), Acceleration = environment.Vector3.new(0, -7, 0), Rotation = environment.NumberRange.new(0, 360),
			RotSpeed = environment.NumberRange.new(-200, 200), Shape = environment.Enum.ParticleEmitterShape.Box,
			ShapeStyle = environment.Enum.ParticleEmitterShapeStyle.Volume, LightEmission = 0, LightInfluence = 1, Brightness = 1}, 60)
	end)
	local function target()
		if effect.killer and effect.killer.Parent then return effect.killer.Position end
		return effect.chest + environment.Vector3.new(0, 7, 0)
	end
	for index = 1, 16 do
		GameEffects.Kill.delay(state, 0.08 + index * 0.035, function()
			if not state.alive then return end
			local orb = environment.Instance.new("Part")
			orb.Shape, orb.Anchored, orb.CanCollide, orb.CanQuery, orb.CanTouch, orb.CastShadow = environment.Enum.PartType.Ball, true, false, false, false, false
			orb.Material, orb.Color, orb.Size = environment.Enum.Material.Neon, environment.Color3.fromRGB(200, 0, 30), environment.Vector3.new(0.32, 0.32, 0.32)
			local first, second = environment.Instance.new("Attachment"), environment.Instance.new("Attachment")
			first.Position, first.Parent = environment.Vector3.new(0, 0.14, 0), orb
			second.Position, second.Parent = environment.Vector3.new(0, -0.14, 0), orb
			local trail = environment.Instance.new("Trail")
			trail.Attachment0, trail.Attachment1, trail.Lifetime = first, second, 0.22 / state.speed
			trail.Color = colors(environment.Color3.fromRGB(255, 60, 80), environment.Color3.fromRGB(120, 0, 20))
			trail.Transparency, trail.WidthScale = sequence(0, 0.1, 1, 1), sequence(0, 1, 1, 0.2)
			trail.LightEmission, trail.FaceCamera, trail.Parent = 1, true, orb
			local start = effect.chest + environment.Vector3.new((math.random() - 0.5) * 1.6, (math.random() - 0.5) * 2.4, (math.random() - 0.5) * 1.6)
			orb.CFrame, orb.Parent = environment.CFrame.new(start), GameEffects.Kill.folder(state)
			local drift = environment.Vector3.new(math.random() - 0.5, 0, math.random() - 0.5) * 6
			GameEffects.Kill.animate(state, 0.55 + math.random() * 0.3, function(progress)
				local finish = target()
				local control = (start + finish) / 2 + environment.Vector3.new(0, 3 + (finish - start).Magnitude * 0.15, 0) + drift
				orb.CFrame = environment.CFrame.new(GameEffects.Kill.bezier(start, control, finish, progress ^ 1.6))
			end, function() orb.Transparency = 1; GameEffects.Kill.destroyLater(state, orb, 0.3) end)
		end)
	end
	GameEffects.Kill.delay(state, 1.05, function()
		local burst = GameEffects.Kill.anchor(state, environment.CFrame.new(target()), environment.Vector3.new(1, 1, 1))
		local attachment = environment.Instance.new("Attachment")
		attachment.Parent = burst
		GameEffects.Kill.particle(state, attachment, {Texture = state.textures.ring, Color = colors(environment.Color3.fromRGB(255, 50, 70)), Size = sequence(0, 1, 1, 7),
			Transparency = sequence(0, 0, 1, 1), Lifetime = environment.NumberRange.new(0.4), Brightness = 4}, 1)
		GameEffects.Kill.particle(state, attachment, {Texture = state.textures.soft, Color = colors(environment.Color3.fromRGB(255, 40, 60)), Size = sequence(0, 2, 1, 5),
			Transparency = sequence(0, 0.3, 1, 1), Lifetime = environment.NumberRange.new(0.5), Brightness = 2}, 1)
		GameEffects.Kill.particle(state, attachment, {Texture = state.textures.star, Color = colors(white, environment.Color3.fromRGB(255, 60, 80)), Size = sequence(0, 0.5, 1, 0),
			Lifetime = environment.NumberRange.new(0.4, 0.7), Speed = environment.NumberRange.new(4, 8), SpreadAngle = environment.Vector2.new(180, 180), Drag = 3, Brightness = 4}, 12)
		GameEffects.Kill.light(state, burst, environment.Color3.fromRGB(255, 40, 60), 4, 10, 0.5)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.magicGlow, 0.35, 1.6, burst)
		GameEffects.Kill.destroyLater(state, burst, 1.5)
	end)
	GameEffects.Kill.light(state, anchor, environment.Color3.fromRGB(200, 0, 30), 3, 12, 1.2)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.stab2, 0.9, 0.8, anchor)
	for _, delay in {0.35, 0.7} do
		GameEffects.Kill.delay(state, delay, function() GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.punch2, 0.5, 0.45, anchor) end)
	end
	GameEffects.Kill.destroyLater(state, anchor, 3)
end

function GameEffects.Kill.iaido(state, effect)
	local environment = state.context.environment
	local white = environment.Color3.new(1, 1, 1)
	local body = GameEffects.Kill.body(state, effect, environment.Vector3.new(0, 0, 0), nil, 3.8, nil, true)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local forward, right = GameEffects.Kill.cameraDirection(state)
	local upper = body and body.model:FindFirstChild("UpperTorso")
	local lower = body and body.model:FindFirstChild("LowerTorso")
	local head = body and body.head
	local socket = GameEffects.Kill.findSocket(body, upper, lower)
	local center = socket and socket.Attachment0 and socket.Attachment0.WorldPosition or effect.chest - environment.Vector3.new(0, 0.7, 0)
	for index, position in {center, effect.head - environment.Vector3.new(0, 0.6, 0)} do
		GameEffects.Kill.delay(state, (index - 1) * 0.05, function()
			local direction = (right + environment.Vector3.new(0, (math.random() - 0.5) * 0.25, 0)).Unit
			local start, finish = position - direction * 24, position + direction * 24
			local beams = {GameEffects.Kill.beam(state, start, finish, 0.2, white),
				GameEffects.Kill.beam(state, start, finish, 0.7, environment.Color3.fromRGB(170, 215, 255), environment.Enum.Material.Neon, 0.55)}
			for _, beam in beams do
				GameEffects.Kill.tween(state, beam, 0.35, {Transparency = 1, Size = environment.Vector3.new(0.01, 0.01, beam.Size.Z)}, environment.Enum.EasingStyle.Quad)
				GameEffects.Kill.destroyLater(state, beam, 0.4)
			end
		end)
	end
	local _, attachment = GameEffects.Kill.effectAttachment(state, effect.chest)
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
	GameEffects.Kill.particle(state, attachment, {Texture = state.textures.speed, Color = colors(white), Size = sequence(0, 6, 1, 9),
		Transparency = sequence(0, 0.3, 1, 1), Lifetime = environment.NumberRange.new(0.3), Rotation = environment.NumberRange.new(0, 360), Brightness = 3, ZOffset = 2}, 2)
	GameEffects.Kill.particle(state, attachment, {Texture = state.textures.sparkBright, Color = colors(white), Size = sequence(0, 5, 1, 0),
		Lifetime = environment.NumberRange.new(0.15), Brightness = 6, ZOffset = 2}, 1)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.swordIn, 1, 1.9)
	GameEffects.Kill.delay(state, 0.58, function() GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.timerBell, 1, 0.7) end)
	GameEffects.Kill.delay(state, 0.66, function()
		if not body then return end
		body.release(environment.Vector3.new(0, 0, 0), function(result)
			GameEffects.Kill.cutSocket(result, upper, lower)
			GameEffects.Kill.cutSocket(result, head, upper)
			for _, part in result.body do
				if part == head then
					part.AssemblyLinearVelocity = environment.Vector3.new(0, 14, 0) + right * 4
					part.AssemblyAngularVelocity = GameEffects.Kill.randomVector(state, 8)
					continue
				end
				if environment.UPPER[part.Name] then
					part.AssemblyLinearVelocity = right * 5 + environment.Vector3.new(0, 2, 0)
					continue
				end
				local side = part.Name:find("Left") and -1 or 1
				part.AssemblyLinearVelocity = -right * 5 + forward * side * 3 + environment.Vector3.new(0, 3, 0)
			end
			if lower then lower.AssemblyAngularVelocity = forward * (math.random() < 0.5 and -9 or 9) end
		end)
		GameEffects.Kill.wound(state, upper, false, body.model)
		GameEffects.Kill.wound(state, lower, true, body.model)
		GameEffects.Kill.wound(state, upper, true, body.model)
		GameEffects.Kill.wound(state, head, false, body.model)
		local anchor, burst = GameEffects.Kill.effectAttachment(state, effect.chest)
		GameEffects.Kill.particle(state, burst, {Texture = state.textures.splat, Color = colors(environment.Color3.fromRGB(190, 10, 30), environment.Color3.fromRGB(100, 0, 12)),
			Size = sequence(0, 0.6, 1, 0.25), Lifetime = environment.NumberRange.new(0.6, 1), Speed = environment.NumberRange.new(10, 22),
			SpreadAngle = environment.Vector2.new(180, 180), Acceleration = environment.Vector3.new(0, -60, 0), Rotation = environment.NumberRange.new(0, 360), LightEmission = 0, Brightness = 1.1}, 50)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.bone2, 1, 0.8, anchor)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.spurt, 0.9, 1, anchor)
		GameEffects.Kill.shakeCamera(state, effect.chest, 0.7, 0.25)
		GameEffects.Kill.delay(state, 1, function()
			local position = body.torso and body.torso.Parent and body.torso.Position or effect.root
			GameEffects.Kill.splat(state, position, 5, environment.Color3.fromRGB(125, 0, 12), 2.8, effect.ignore, 1.1)
		end)
	end)
end

function GameEffects.Kill.sever(state, effect)
	local environment = state.context.environment
	local color, white = environment.Color3.fromRGB(255, 40, 60), environment.Color3.new(1, 1, 1)
	local body = GameEffects.Kill.body(state, effect, environment.Vector3.new(0, 0, 0), nil, 3.4, nil, true)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local upper = body and body.model:FindFirstChild("UpperTorso")
	local lower = body and body.model:FindFirstChild("LowerTorso")
	local socket = GameEffects.Kill.findSocket(body, upper, lower)
	local center = socket and socket.Attachment0 and socket.Attachment0.WorldPosition or effect.chest - environment.Vector3.new(0, 0.7, 0)
	local forward, right = GameEffects.Kill.cameraDirection(state)
	local side = math.random() < 0.5 and -1 or 1
	local normal, radius, halfAngle = -forward, 4.6, 0.95
	GameEffects.Kill.arcFrom(state, center - normal * radius * math.cos(halfAngle), normal, right * side, radius, -halfAngle, halfAngle, color, 0.95, 0.08, 0.12)
	local line = GameEffects.Kill.beam(state, center - right * 5, center + right * 5, 0.07, white)
	GameEffects.Kill.tween(state, line, 0.25, {Size = environment.Vector3.new(0.01, 0.01, 12), Transparency = 1}, environment.Enum.EasingStyle.Quad)
	GameEffects.Kill.destroyLater(state, line, 0.3)
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.lookAt(center, center + right), environment.Vector3.new(0.3, 0.3, 3))
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
	GameEffects.Kill.particle(state, anchor, {Texture = state.textures.spark, Color = colors(white, color), Size = sequence(0, 0.9, 1, 0),
		Lifetime = environment.NumberRange.new(0.15, 0.35), Speed = environment.NumberRange.new(10, 24), SpreadAngle = environment.Vector2.new(180, 180),
		Drag = 6, Shape = environment.Enum.ParticleEmitterShape.Box, Orientation = environment.Enum.ParticleOrientation.VelocityParallel, Brightness = 5}, 24, 0.04)
	GameEffects.Kill.particle(state, anchor, {Texture = state.textures.splat, Color = colors(environment.Color3.fromRGB(170, 0, 20), environment.Color3.fromRGB(90, 0, 10)),
		Size = sequence(0, 0.5, 1, 0.2), Lifetime = environment.NumberRange.new(0.6, 1), Speed = environment.NumberRange.new(6, 14),
		SpreadAngle = environment.Vector2.new(80, 80), Acceleration = environment.Vector3.new(0, -60, 0), Shape = environment.Enum.ParticleEmitterShape.Box,
		Rotation = environment.NumberRange.new(0, 360), LightEmission = 0, Brightness = 1}, 30, 0.1)
	GameEffects.Kill.delay(state, 0.1, function()
		if not body then return end
		body.release(environment.Vector3.new(0, 0, 0), function(result)
			GameEffects.Kill.cutSocket(result, upper, lower)
			for _, part in result.body do
				if environment.UPPER[part.Name] then
					part.AssemblyLinearVelocity = right * side * 9 + environment.Vector3.new(0, 4, 0)
					continue
				end
				local sign = part.Name:find("Left") and -1 or 1
				part.AssemblyLinearVelocity = -right * side * 5 + forward * sign * 3 + environment.Vector3.new(0, 3, 0)
			end
			if upper then upper.AssemblyAngularVelocity = forward * side * 3 end
			if lower then lower.AssemblyAngularVelocity = right * (math.random() < 0.5 and -9 or 9) end
		end)
		if upper and lower then
			GameEffects.Kill.wound(state, upper, false, body.model)
			GameEffects.Kill.wound(state, lower, true, body.model)
		end
		GameEffects.Kill.delay(state, 0.9, function()
			local position = body.torso and body.torso.Parent and body.torso.Position or effect.root
			GameEffects.Kill.splat(state, position, 4.5, environment.Color3.fromRGB(125, 0, 12), 2.8, effect.ignore, 1.1)
		end)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.bone1, 0.9, 0.8, anchor)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.guts, 0.8, 0.9, anchor)
	end)
	GameEffects.Kill.light(state, anchor, color, 6, 14, 0.5)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.swordWhip, 1, 1.1, anchor)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.swordIn, 0.8, 1.2, anchor)
	GameEffects.Kill.shakeCamera(state, center, 0.5, 0.2)
	GameEffects.Kill.destroyLater(state, anchor, 2.5)
end

function GameEffects.Kill.findSocket(body, first, second)
	if not body or not first or not second then return nil end
	for _, joint in body.model:GetDescendants() do
		if not joint:IsA("BallSocketConstraint") then continue end
		local left = joint.Attachment0 and joint.Attachment0.Parent
		local right = joint.Attachment1 and joint.Attachment1.Parent
		if left == first and right == second or left == second and right == first then return joint end
	end
	return nil
end

function GameEffects.Kill.cutSocket(body, first, second)
	if not body or not first or not second then return end
	for _, joint in body.model:GetDescendants() do
		if not joint:IsA("BallSocketConstraint") then continue end
		local left = joint.Attachment0 and joint.Attachment0.Parent
		local right = joint.Attachment1 and joint.Attachment1.Parent
		if left == first and right == second or left == second and right == first then joint:Destroy() end
	end
end

function GameEffects.Kill.wound(state, part, top, parent)
	if not part or not part.Parent then return nil end
	local environment = state.context.environment
	local wound = environment.Instance.new("Part")
	wound.Size = environment.Vector3.new(part.Size.X * 0.8, 0.05, part.Size.Z * 0.8)
	wound.Material, wound.Color = environment.Enum.Material.Neon, environment.Color3.fromRGB(160, 0, 14)
	wound.CanCollide, wound.CanQuery, wound.CanTouch, wound.Massless, wound.CastShadow = false, false, false, true, false
	wound.CFrame = part.CFrame * environment.CFrame.new(0, (top and 1 or -1) * (part.Size.Y / 2 - 0.02), 0)
	wound.Parent = parent or part.Parent
	local weld = environment.Instance.new("WeldConstraint")
	weld.Part0, weld.Part1, weld.Parent = part, wound, wound
	local emitter = GameEffects.Kill.particle(state, wound, {Texture = state.textures.splat,
		Color = environment.ColorSequence.new(environment.Color3.fromRGB(190, 0, 25), environment.Color3.fromRGB(100, 0, 10)),
		Size = GameEffects.Kill.numberSequence(state, 0, 0.35, 1, 0.14), Lifetime = environment.NumberRange.new(0.4, 0.7),
		Speed = environment.NumberRange.new(6, 11), SpreadAngle = environment.Vector2.new(25, 25), Acceleration = environment.Vector3.new(0, -55, 0),
		EmissionDirection = top and environment.Enum.NormalId.Top or environment.Enum.NormalId.Bottom, Rotation = environment.NumberRange.new(0, 360), LightEmission = 0, Brightness = 1}, 8)
	emitter.Rate, emitter.Enabled = 55, true
	GameEffects.Kill.delay(state, 0.9, function() if emitter.Parent then emitter.Enabled = false end end)
	GameEffects.Kill.delay(state, 1.1, function()
		if wound.Parent then GameEffects.Kill.tween(state, wound, 0.5, {Color = environment.Color3.fromRGB(60, 0, 5), Transparency = 1}) end
	end)
	return wound
end

function GameEffects.Kill.dragon(state, effect)
	local environment = state.context.environment
	local color, center = environment.Color3.fromRGB(255, 120, 30), effect.chest
	local body = GameEffects.Kill.body(state, effect, environment.Vector3.new(0, 0, 0), nil, 3.4, nil, true)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local segments, horns = {}, {}
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local flameColors = environment.ColorSequence.new(environment.Color3.fromRGB(255, 200, 90), environment.Color3.fromRGB(220, 50, 10))
	for index = 1, 18 do
		local part = environment.Instance.new("Part")
		part.Shape, part.Anchored, part.CanCollide, part.CanQuery, part.CanTouch, part.CastShadow = environment.Enum.PartType.Ball, true, false, false, false, false
		local size = index == 1 and 1.7 or 1.35 - index / 18 * 0.95
		part.Size, part.Material = environment.Vector3.new(size, size, size), environment.Enum.Material.Neon
		part.Color = environment.Color3.fromRGB(255, 210, 90):Lerp(environment.Color3.fromRGB(200, 30, 10), index / 18)
		part.CFrame, part.Parent = environment.CFrame.new(center + environment.Vector3.new(0, -500, 0)), GameEffects.Kill.folder(state)
		if index % 2 == 1 then
			local emitter = GameEffects.Kill.particle(state, part, {Texture = state.textures.flame, Color = flameColors, Size = sequence(0, size * 0.9, 1, 0.1),
				Transparency = sequence(0, 0.3, 1, 1), Lifetime = environment.NumberRange.new(0.25, 0.45), Speed = environment.NumberRange.new(0.5, 2),
				SpreadAngle = environment.Vector2.new(180, 180), Rotation = environment.NumberRange.new(0, 360), Brightness = 3}, 0)
			emitter.Rate, emitter.Enabled = 25, true
		end
		table.insert(segments, part)
	end
	for side = -1, 1, 2 do
		local part = environment.Instance.new("WedgePart")
		part.Anchored, part.CanCollide, part.CanQuery, part.CanTouch = true, false, false, false
		part.Size, part.Material, part.Color = environment.Vector3.new(0.25, 1.1, 0.5), environment.Enum.Material.Neon, environment.Color3.fromRGB(255, 240, 180)
		part.Parent = GameEffects.Kill.folder(state)
		table.insert(horns, {part = part, side = side})
	end
	local angle = math.random() * 6.28
	local function position(progress)
		if progress < 0.8 then
			local stage = progress / 0.8
			local phase, radius = angle + stage * 9.5, 8 * (1 - stage) + 0.2
			return center + environment.Vector3.new(math.cos(phase) * radius, 6 - stage * 6.2, math.sin(phase) * radius)
		end
		local stage = (progress - 0.8) / 0.2
		return center + environment.Vector3.new(math.cos(angle) * stage * 2, -0.2 + stage * 26, math.sin(angle) * stage * 2)
	end
	local struck = false
	GameEffects.Kill.animate(state, 1.6, function(progress)
		local parts, frames = {}, {}
		for index, part in segments do
			local stage = math.clamp(progress - (index - 1) * 0.022, 0, 1)
			local current, ahead = position(stage), position(math.min(1, stage + 0.01))
			local frame = (ahead - current).Magnitude > 0.001 and environment.CFrame.lookAt(current, ahead) or environment.CFrame.new(current)
			table.insert(parts, part)
			table.insert(frames, frame)
			if index == 1 then
				for _, horn in horns do
					table.insert(parts, horn.part)
					table.insert(frames, frame * environment.CFrame.new(horn.side * 0.45, 0.6, 0.3) * environment.CFrame.Angles(math.rad(-50), 0, horn.side * 0.3))
				end
			end
			if progress > 0.85 then part.Transparency = (progress - 0.85) / 0.15 end
		end
		GameEffects.Kill.moveParts(state, parts, frames)
		if struck or progress < 0.8 then return end
		struck = true
		GameEffects.Kill.flash(state, center, color, 16, 6)
		GameEffects.Kill.sparks(state, center, color, 40, 40)
		local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(center), environment.Vector3.new(2, 3, 2))
		GameEffects.Kill.particle(state, anchor, {Texture = state.textures.flame,
			Color = environment.ColorSequence.new(environment.Color3.fromRGB(255, 220, 120), environment.Color3.fromRGB(220, 40, 10)),
			Size = sequence(0, 1.5, 1, 0.3), Transparency = sequence(0, 0.2, 1, 1), Lifetime = environment.NumberRange.new(0.5, 0.9),
			Speed = environment.NumberRange.new(8, 20), SpreadAngle = environment.Vector2.new(180, 180), Drag = 2, Acceleration = environment.Vector3.new(0, 10, 0),
			Rotation = environment.NumberRange.new(0, 360), Shape = environment.Enum.ParticleEmitterShape.Box, Brightness = 3}, 40)
		GameEffects.Kill.destroyLater(state, anchor, 2)
		if body then
			body.release(environment.Vector3.new(0, 55, 0) + GameEffects.Kill.direction(state, effect) * 8, nil)
			pcall(function() body.torso.AssemblyAngularVelocity = GameEffects.Kill.randomVector(state, 8) end)
			local highlight = GameEffects.Kill.highlight(state, body.model, color, environment.Color3.fromRGB(255, 220, 120), 0.35, 0)
			GameEffects.Kill.delay(state, 0.6, function()
				if highlight.Parent then GameEffects.Kill.tween(state, highlight, 0.6, {FillColor = environment.Color3.fromRGB(25, 10, 5), FillTransparency = 0.1, OutlineTransparency = 1}) end
			end)
		end
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.fireball2, 0.9, 1, anchor)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.boomDeep, 0.6, 0.8, anchor)
		GameEffects.Kill.shakeCamera(state, center, 1.4, 0.4)
	end, function()
		for _, part in segments do pcall(function() part:Destroy() end) end
		for _, horn in horns do pcall(function() horn.part:Destroy() end) end
	end)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.fireWhoosh2, 0.7, 0.8)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.roar, 0.5, 0.45)
end

function GameEffects.Kill.impale(state, effect)
	local environment = state.context.environment
	local color = environment.Color3.fromRGB(255, 30, 50)
	local ground = GameEffects.Kill.ground(state, effect.root, effect.ignore)
	local height = ground and ground.Y or effect.root.Y - 3
	local body = GameEffects.Kill.staticBody(state, effect)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local rise = environment.Vector3.new(0, 1.3, 0)
	GameEffects.Kill.delay(state, 0.08, function()
		for _, part in body do if part.Parent then GameEffects.Kill.tween(state, part, 0.14, {CFrame = part.CFrame + rise}, environment.Enum.EasingStyle.Back) end end
	end)
	GameEffects.Kill.delay(state, 1.05, function()
		GameEffects.Kill.fadeGhost(state, body, 0.45, function() return {Color = environment.Color3.fromRGB(70, 0, 10)} end)
	end)
	for index = 1, 9 do
		local angle, radius = index / 9 * math.pi * 2 + math.random() * 0.4, 1.8 + math.random() * 1.6
		local start = environment.Vector3.new(effect.root.X + math.cos(angle) * radius, height - 0.2, effect.root.Z + math.sin(angle) * radius)
		local target = effect.chest + rise + environment.Vector3.new((math.random() - 0.5) * 0.8, (math.random() - 0.3) * 1.6, (math.random() - 0.5) * 0.8)
		local offset = target - start
		local finish = start + offset.Unit * (offset.Magnitude + 0.6 + math.random() * 1.2)
		local dark = index % 3 == 0
		local spikes, direction, length = GameEffects.Kill.spike(state, start, finish, 0.22, 0.34 + math.random() * 0.12,
			dark and environment.Color3.fromRGB(18, 6, 10) or environment.Color3.fromRGB(105, 0, 22), dark and environment.Enum.Material.SmoothPlastic or environment.Enum.Material.Neon)
		local delay = index * 0.02
		for _, part in spikes do
			local frame = part.CFrame
			local hidden = frame - direction * (length + 0.3)
			part.CFrame = hidden
			GameEffects.Kill.delay(state, delay, function() if part.Parent then GameEffects.Kill.tween(state, part, 0.13, {CFrame = frame}, environment.Enum.EasingStyle.Back) end end)
			GameEffects.Kill.delay(state, 1.15 + delay * 0.5, function()
				if part.Parent then GameEffects.Kill.tween(state, part, 0.3, {CFrame = hidden}, environment.Enum.EasingStyle.Quad, environment.Enum.EasingDirection.In) end
			end)
			GameEffects.Kill.destroyLater(state, part, 1.6 + delay)
		end
	end
	local floor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.root.X, height + 0.1, effect.root.Z), environment.Vector3.new(5, 0.2, 5))
	local attachment = environment.Instance.new("Attachment")
	attachment.Parent = floor
	GameEffects.Kill.groundRing(state, attachment, state.textures.cracks, color, 3, 9, 1.2, 2)
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
	GameEffects.Kill.particle(state, floor, {Texture = state.textures.rock, Color = colors(environment.Color3.fromRGB(70, 60, 60)), Size = sequence(0, 0.5, 1, 0.3),
		Lifetime = environment.NumberRange.new(0.5, 0.9), Speed = environment.NumberRange.new(10, 18), SpreadAngle = environment.Vector2.new(35, 35),
		Acceleration = environment.Vector3.new(0, -60, 0), Rotation = environment.NumberRange.new(0, 360), RotSpeed = environment.NumberRange.new(-300, 300),
		Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0, LightInfluence = 1, Brightness = 1}, 22)
	GameEffects.Kill.particle(state, floor, {Texture = state.textures.soft, Color = colors(environment.Color3.fromRGB(90, 40, 40)),
		Size = sequence(0, 2, 1, 4.5), Transparency = sequence(0, 0.4, 1, 1), Lifetime = environment.NumberRange.new(0.6, 1),
		Speed = environment.NumberRange.new(2, 5), SpreadAngle = environment.Vector2.new(70, 70), Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0, Brightness = 1}, 10)
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.chest + rise), environment.Vector3.new(1.5, 2.5, 1.5))
	GameEffects.Kill.particle(state, anchor, {Texture = state.textures.splat, Color = colors(environment.Color3.fromRGB(180, 0, 25), environment.Color3.fromRGB(90, 0, 10)),
		Size = sequence(0, 0.6, 1, 0.25), Lifetime = environment.NumberRange.new(0.6, 1), Speed = environment.NumberRange.new(8, 16),
		SpreadAngle = environment.Vector2.new(180, 180), Acceleration = environment.Vector3.new(0, -60, 0), Rotation = environment.NumberRange.new(0, 360),
		Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0, Brightness = 1}, 36, 0.14)
	GameEffects.Kill.light(state, anchor, color, 5, 14, 0.8)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.trap, 1, 0.8, floor)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.rockCrack, 0.5, 1.2, floor)
	GameEffects.Kill.delay(state, 0.12, function() GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.trap, 0.7, 1.1, anchor) end)
	GameEffects.Kill.shakeCamera(state, effect.chest, 1, 0.35)
	GameEffects.Kill.destroyLater(state, floor, 2.5)
	GameEffects.Kill.destroyLater(state, anchor, 2.5)
end

function GameEffects.Kill.drones(state, effect)
	local environment = state.context.environment
	local red, white, center = environment.Color3.fromRGB(255, 50, 60), environment.Color3.new(1, 1, 1), effect.chest
	local body = GameEffects.Kill.body(state, effect, environment.Vector3.new(0, 0, 0), nil, 3.6, nil, true)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local drones = {}
	for index = 1, 4 do
		local parts, offsets = {}, {}
		local function create(shape, size, color, material, offset)
			local part = environment.Instance.new("Part")
			part.Shape, part.Anchored, part.CanCollide, part.CanQuery, part.CanTouch, part.CastShadow = shape, true, false, false, false, true
			part.Size, part.Color, part.Material, part.Parent = size, color, material, GameEffects.Kill.folder(state)
			table.insert(parts, part)
			table.insert(offsets, offset)
			return part
		end
		create(environment.Enum.PartType.Block, environment.Vector3.new(1.3, 0.35, 1.3), environment.Color3.fromRGB(40, 42, 48), environment.Enum.Material.Metal, environment.CFrame.new())
		local eye = create(environment.Enum.PartType.Ball, environment.Vector3.new(0.35, 0.35, 0.35), red, environment.Enum.Material.Neon, environment.CFrame.new(0, -0.2, -0.5))
		for _, position in {environment.Vector3.new(0.8, 0.2, 0.8), environment.Vector3.new(-0.8, 0.2, 0.8),
			environment.Vector3.new(0.8, 0.2, -0.8), environment.Vector3.new(-0.8, 0.2, -0.8)} do
			create(environment.Enum.PartType.Cylinder, environment.Vector3.new(0.05, 0.8, 0.8), environment.Color3.fromRGB(120, 230, 255), environment.Enum.Material.Neon,
				environment.CFrame.new(position) * environment.CFrame.Angles(0, 0, math.pi / 2))
		end
		local angle = index / 4 * 6.283 + math.random() * 0.4
		table.insert(drones, {parts = parts, offsets = offsets, eye = eye,
			hover = center + environment.Vector3.new(math.cos(angle) * 5, 2.5 + index % 2 * 0.8, math.sin(angle) * 5),
			start = center + environment.Vector3.new(math.cos(angle) * 30, 12, math.sin(angle) * 30), phase = math.random() * 6})
	end
	local function place(drone, position, elapsed)
		local frame = environment.CFrame.lookAt(position, environment.Vector3.new(center.X, position.Y, center.Z))
			* environment.CFrame.new(0, math.sin(elapsed * 6 + drone.phase) * 0.15, 0)
		local frames = {}
		for index, offset in drone.offsets do frames[index] = frame * offset end
		GameEffects.Kill.moveParts(state, drone.parts, frames)
	end
	for _, drone in drones do place(drone, drone.start, 0) end
	local released = false
	GameEffects.Kill.animate(state, 0.5, function(progress)
		for _, drone in drones do place(drone, drone.start:Lerp(drone.hover, 1 - (1 - progress) ^ 3), progress) end
	end, function()
		for index = 0, 3 do GameEffects.Kill.delay(state, index * 0.08, function() GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.servo, 0.4, 2.2) end) end
		GameEffects.Kill.animate(state, 1, function(progress)
			for _, drone in drones do place(drone, drone.hover, 0.5 + progress) end
		end, function()
			for _, drone in drones do
				local finish = drone.hover + environment.Vector3.new(0, 25, 0) + (drone.hover - center) * 2
				GameEffects.Kill.animate(state, 0.5, function(progress) place(drone, drone.hover:Lerp(finish, progress * progress), 1.5 + progress) end,
					function() for _, part in drone.parts do pcall(function() part:Destroy() end) end end)
			end
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.engine, 0.5, 1.6, nil, 1.5)
		end)
		for index = 1, 10 do
			GameEffects.Kill.delay(state, 0.15 + index * 0.08, function()
				local drone = drones[(index - 1) % #drones + 1]
				if not drone.eye.Parent then return end
				local target = (body and body.torso and body.torso.Parent and body.torso.Position or center)
					+ environment.Vector3.new(math.random() - 0.5, math.random() - 0.5, math.random() - 0.5) * 1.2
				local beams = {GameEffects.Kill.beam(state, drone.eye.Position, target, 0.1, white),
					GameEffects.Kill.beam(state, drone.eye.Position, target, 0.35, red, environment.Enum.Material.Neon, 0.4)}
				for _, beam in beams do GameEffects.Kill.tween(state, beam, 0.12, {Transparency = 1}); GameEffects.Kill.destroyLater(state, beam, 0.15) end
				GameEffects.Kill.sparks(state, target, red, 6, 12, state.textures.spark)
				GameEffects.Kill.sound(state, index % 2 == 0 and GameEffects.Kill.soundIds.laser1 or GameEffects.Kill.soundIds.laser3, 0.5, 2.2 + math.random() * 0.4)
				if body and not released then
					released = true
					body.release(environment.Vector3.new(0, 4, 0), nil)
					return
				end
				if not body or not body.torso or not body.torso.Parent then return end
				for _, part in body.body do
					pcall(function() part.AssemblyLinearVelocity += environment.Vector3.new(math.random() - 0.5, 0.6, math.random() - 0.5) * 10 end)
				end
			end)
		end
	end)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.engine, 0.5, 1.8, nil, 1.5)
end

function GameEffects.Kill.ufo(state, effect)
	local context, environment = state.context, state.context.environment
	local color, white = environment.Color3.fromRGB(120, 255, 140), environment.Color3.new(1, 1, 1)
	local ground = GameEffects.Kill.ground(state, effect.root, effect.ignore)
	local height = ground and ground.Y or effect.root.Y - 3
	local base = environment.Vector3.new(effect.root.X, height, effect.root.Z)
	local params = environment.RaycastParams.new()
	params.FilterType, params.RespectCanCollide = environment.Enum.RaycastFilterType.Exclude, true
	params.FilterDescendantsInstances = {effect.char, context.workspace.CurrentCamera, GameEffects.Kill.bodiesFolder(state)}
	local ceiling = context.workspace:Raycast(base + environment.Vector3.new(0, 1, 0), environment.Vector3.new(0, 20, 0), params)
	local altitude = ceiling and math.clamp(ceiling.Distance - 2.5, 6, 14) or 14
	local center = base + environment.Vector3.new(0, altitude, 0)
	local _, right = GameEffects.Kill.cameraDirection(state)
	local start = center + right * 40 + environment.Vector3.new(0, 15, 0)
	local parts, offsets = {}, {}
	local function create(shape, size, partColor, material, transparency, offset)
		local part = environment.Instance.new("Part")
		part.Shape, part.Anchored, part.CanCollide, part.CanQuery, part.CanTouch, part.CastShadow = shape, true, false, false, false, true
		part.Size, part.Color, part.Material, part.Transparency = size, partColor, material, transparency or 0
		part.Reflectance, part.Parent = material == environment.Enum.Material.Metal and 0.3 or 0, GameEffects.Kill.folder(state)
		table.insert(parts, part)
		table.insert(offsets, offset)
		return part
	end
	local cylinder = environment.CFrame.Angles(0, 0, math.pi / 2)
	create(environment.Enum.PartType.Cylinder, environment.Vector3.new(0.8, 8, 8), environment.Color3.fromRGB(170, 175, 185), environment.Enum.Material.Metal, 0, cylinder)
	create(environment.Enum.PartType.Cylinder, environment.Vector3.new(0.35, 8.6, 8.6), color, environment.Enum.Material.Neon, 0.2, environment.CFrame.new(0, -0.1, 0) * cylinder)
	create(environment.Enum.PartType.Ball, environment.Vector3.new(3.4, 3.4, 3.4), environment.Color3.fromRGB(150, 230, 255), environment.Enum.Material.Glass, 0.35, environment.CFrame.new(0, 0.7, 0))
	local underside = create(environment.Enum.PartType.Cylinder, environment.Vector3.new(0.3, 3, 3), color, environment.Enum.Material.Neon, 0, environment.CFrame.new(0, -0.5, 0) * cylinder)
	local lamps = {}
	for index = 1, 8 do
		local angle = index / 8 * 6.283
		table.insert(lamps, create(environment.Enum.PartType.Ball, environment.Vector3.new(0.45, 0.45, 0.45), white, environment.Enum.Material.Neon, 0,
			environment.CFrame.new(math.cos(angle) * 3.9, 0, math.sin(angle) * 3.9)))
	end
	local colors = {environment.Color3.fromRGB(255, 80, 80), environment.Color3.fromRGB(255, 220, 80), environment.Color3.fromRGB(80, 255, 140), environment.Color3.fromRGB(80, 180, 255)}
	local function place(position, elapsed)
		local frame = environment.CFrame.new(position) * environment.CFrame.Angles(math.sin(elapsed * 3) * 0.06, elapsed * 2, math.cos(elapsed * 3) * 0.06)
		local frames = {}
		for index, offset in offsets do frames[index] = frame * offset end
		GameEffects.Kill.moveParts(state, parts, frames)
		for index, lamp in lamps do lamp.Color = colors[(index + math.floor(elapsed * 8)) % #colors + 1] end
	end
	place(start, 0)
	local body = GameEffects.Kill.body(state, effect, environment.Vector3.new(0, 2, 0), GameEffects.Kill.randomVector(state, 1.5), 4.5)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	GameEffects.Kill.animate(state, 0.7, function(progress) place(start:Lerp(center, 1 - (1 - progress) ^ 3), progress * 0.7) end, function()
		local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(base + environment.Vector3.new(0, 0.2, 0)), environment.Vector3.new(4, 0.3, 4))
		local first, second = environment.Instance.new("Attachment"), environment.Instance.new("Attachment")
		first.Parent, second.Parent = underside, anchor
		local beam = GameEffects.Kill.attachmentBeam(state, first, second, {Width0 = 2.6, Width1 = 5.5, Color = environment.ColorSequence.new(color, color),
			Transparency = GameEffects.Kill.numberSequence(state, 0, 0.55, 1, 0.75), Segments = 1})
		local emitter = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.soft, Color = environment.ColorSequence.new(color, white),
			Size = GameEffects.Kill.numberSequence(state, 0, 0.4, 1, 0), Lifetime = environment.NumberRange.new(altitude / 9), Speed = environment.NumberRange.new(8, 10),
			SpreadAngle = environment.Vector2.new(4, 4), Shape = environment.Enum.ParticleEmitterShape.Box, Brightness = 3}, 0)
		emitter.Rate, emitter.Enabled = 40, true
		GameEffects.Kill.light(state, anchor, color, 4, 12, 1.6)
		local force, captured = GameEffects.Kill.upForce(state, body, 1.3), false
		GameEffects.Kill.animate(state, 1.5, function(progress)
			place(center, 0.7 + progress * 1.5)
			if not body or not body.torso or not body.torso.Parent or captured then return end
			for _, part in body.body do
				local offset = part.Position - center
				local pull = environment.Vector3.new(-offset.X, 0, -offset.Z) * 2
				pcall(function() part.AssemblyLinearVelocity = pull + environment.Vector3.new(0, 5 + 7 * progress, 0) end)
			end
			if (body.torso.Position - center).Magnitude >= 2.2 then return end
			captured = true
			for _, part in body.parts do GameEffects.Kill.tween(state, part, 0.15, {Transparency = 1}) end
			GameEffects.Kill.delay(state, 0.2, function() pcall(function() body.model:Destroy() end) end)
		end, function()
			emitter.Enabled = false
			pcall(function() beam:Destroy() end)
			GameEffects.Kill.destroyLater(state, anchor, 0.6)
			if force then pcall(function() force:Destroy() end) end
			if body and not captured then pcall(function() body.model:Destroy() end) end
			local finish = center - right * 60 + environment.Vector3.new(0, 30, 0)
			GameEffects.Kill.animate(state, 0.45, function(progress) place(center:Lerp(finish, progress * progress), 2.2 + progress) end, function()
				local position = parts[1].Position
				for _, part in parts do pcall(function() part:Destroy() end) end
				local _, sparkle = GameEffects.Kill.effectAttachment(state, position)
				GameEffects.Kill.particle(state, sparkle, {Texture = state.textures.star4, Color = environment.ColorSequence.new(white, color),
					Size = GameEffects.Kill.numberSequence(state, 0, 0, 0.3, 8, 1, 0), Lifetime = environment.NumberRange.new(0.5),
					RotSpeed = environment.NumberRange.new(160), Brightness = 8}, 1)
			end)
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.sonic2, 0.6, 1.4, nil, 1.5)
		end)
		for index = 0, 2 do
			GameEffects.Kill.delay(state, index * 0.12, function() GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.sciSynth, 0.4, 2, nil, 0.8) end)
		end
	end)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.sonar, 0.7, 0.5)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.engine, 0.5, 0.6, nil, 3)
end

function GameEffects.Kill.execution(state, effect)
	local context, environment = state.context, state.context.environment
	local color = environment.Color3.fromRGB(255, 40, 60)
	local body = GameEffects.Kill.body(state, effect, environment.Vector3.new(0, 0, 0), nil, 3.2, nil, true)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local neck = effect.head - environment.Vector3.new(0, 0.55, 0)
	local camera = context.workspace.CurrentCamera
	local cameraRight = camera and camera.CFrame.RightVector or environment.Vector3.new(1, 0, 0)
	local horizontal = environment.Vector3.new(cameraRight.X, 0, cameraRight.Z)
	local right = horizontal.Magnitude > 0.05 and horizontal.Unit or environment.Vector3.new(1, 0, 0)
	local pivot, up = neck - right * 5.5, environment.Vector3.new(0, 1, 0)
	local bladeColor, handleColor = environment.Color3.fromRGB(190, 20, 40), environment.Color3.fromRGB(20, 16, 18)
	local pieces = {}
	for index = 1, 3 do
		local part = environment.Instance.new(index < 3 and "WedgePart" or "Part")
		part.Anchored, part.CanCollide, part.CanQuery, part.CanTouch, part.CastShadow = true, false, false, false, false
		part.Size = index < 3 and environment.Vector3.new(0.1, 6, 0.65) or environment.Vector3.new(0.25, 1.4, 0.3)
		part.Color, part.Material, part.Transparency = index < 3 and bladeColor or handleColor,
			index < 3 and environment.Enum.Material.Neon or environment.Enum.Material.Metal, index < 3 and 0.3 or 0
		part.Parent = GameEffects.Kill.folder(state)
		table.insert(pieces, part)
	end
	local start = environment.CFrame.fromAxisAngle(up, math.rad(-70)) * right
	GameEffects.Kill.arcFrom(state, pivot, start, up:Cross(start), 5.5, 0, math.rad(140), color, 0.9, 0.16, 0.1)
	GameEffects.Kill.animate(state, 0.16, function(progress)
		local direction = environment.CFrame.fromAxisAngle(up, math.rad(-70 + 140 * progress)) * right
		local frame = environment.CFrame.fromMatrix(pivot, up, direction)
		pieces[1].CFrame = frame * environment.CFrame.new(0, 4, -1.3 / 4)
		pieces[2].CFrame = frame * environment.CFrame.Angles(0, math.pi, 0) * environment.CFrame.new(0, 4, -1.3 / 4)
		pieces[3].CFrame = frame * environment.CFrame.new(0, 0.4, 0)
	end, function()
		for _, part in pieces do
			GameEffects.Kill.tween(state, part, 0.25, {Transparency = 1})
			GameEffects.Kill.destroyLater(state, part, 0.3)
		end
	end)
	GameEffects.Kill.delay(state, 0.08, function()
		local outward = up:Cross(right)
		if body then
			body.release(environment.Vector3.new(0, -2, 0), function(result)
				if not result.head then return end
				for _, joint in result.model:GetDescendants() do
					if not joint:IsA("BallSocketConstraint") then continue end
					if joint.Attachment0 and joint.Attachment0.Parent == result.head or joint.Attachment1 and joint.Attachment1.Parent == result.head then joint:Destroy() end
				end
				result.head.AssemblyLinearVelocity = outward * 14 + right * 10 + environment.Vector3.new(0, 30, 0)
				result.head.AssemblyAngularVelocity = GameEffects.Kill.randomVector(state, 12)
			end)
		end
		local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(neck), environment.Vector3.new(0.4, 0.4, 0.4))
		local emitter = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.splat,
			Color = environment.ColorSequence.new(environment.Color3.fromRGB(190, 0, 25), environment.Color3.fromRGB(100, 0, 10)),
			Size = GameEffects.Kill.numberSequence(state, 0, 0.38, 1, 0.15), Lifetime = environment.NumberRange.new(0.5, 0.8),
			Speed = environment.NumberRange.new(9, 15), SpreadAngle = environment.Vector2.new(20, 20), Acceleration = environment.Vector3.new(0, -55, 0),
			Rotation = environment.NumberRange.new(0, 360), LightEmission = 0, Brightness = 1}, 14)
		emitter.Rate, emitter.Enabled = 70, true
		GameEffects.Kill.animate(state, 1.2, function(progress)
			if body and body.torso and body.torso.Parent then anchor.CFrame = body.torso.CFrame * environment.CFrame.new(0, body.torso.Size.Y / 2, 0) end
			emitter.Rate = 70 * (1 - progress)
		end, function() emitter.Enabled = false end)
		GameEffects.Kill.destroyLater(state, anchor, 2.2)
		GameEffects.Kill.delay(state, 0.8, function()
			local position = body and body.torso and body.torso.Parent and body.torso.Position or effect.root
			GameEffects.Kill.splat(state, position, 4.5, environment.Color3.fromRGB(125, 0, 12), 2.8, effect.ignore, 1.2)
		end)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.bone2, 1, 0.7, anchor)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.spurt, 0.8, 0.8, anchor)
		GameEffects.Kill.shakeCamera(state, neck, 0.8, 0.25)
	end)
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(neck), environment.Vector3.new(1, 1, 1))
	GameEffects.Kill.light(state, anchor, color, 6, 14, 0.5)
	GameEffects.Kill.destroyLater(state, anchor, 1)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.whipSlow, 1, 0.55)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.swordIn, 0.8, 0.6)
end

function GameEffects.Kill.missiles(state, effect)
	local environment = state.context.environment
	local body = GameEffects.Kill.body(state, effect, environment.Vector3.new(0, 4, 0), GameEffects.Kill.randomVector(state, 1), 3.6)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local direction, origin = GameEffects.Kill.direction(state, effect)
	if effect.killer and effect.killer.Parent then origin = effect.killer.Position end
	local launch = origin + environment.Vector3.new(0, 25, 0) - direction * 10
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
	for index = 1, 6 do
		GameEffects.Kill.delay(state, (index - 1) * 0.13, function()
			if not state.alive then return end
			local target = body and body.torso and body.torso.Parent and body.torso.Position or effect.chest
			if index % 2 == 0 then target += environment.Vector3.new(math.random() * 4 - 2, -1.5, math.random() * 4 - 2) end
			local start = launch + environment.Vector3.new(math.random() * 8 - 4, math.random() * 4, math.random() * 8 - 4)
			local control = (start + target) / 2 + environment.Vector3.new(math.random() * 10 - 5, 12, math.random() * 10 - 5)
			local missile = environment.Instance.new("Part")
			missile.Anchored, missile.CanCollide, missile.CanQuery, missile.CanTouch, missile.CastShadow = true, false, false, false, false
			missile.Size, missile.Material, missile.Color, missile.Parent = environment.Vector3.new(0.35, 0.35, 1.3), environment.Enum.Material.Metal, environment.Color3.fromRGB(150, 155, 165), GameEffects.Kill.folder(state)
			local tip = environment.Instance.new("Part")
			tip.Shape, tip.Anchored, tip.CanCollide, tip.CanQuery, tip.CanTouch = environment.Enum.PartType.Ball, true, false, false, false
			tip.Size, tip.Material, tip.Color, tip.Parent = environment.Vector3.new(0.38, 0.38, 0.38), environment.Enum.Material.Neon, environment.Color3.fromRGB(255, 60, 50), GameEffects.Kill.folder(state)
			local trail = GameEffects.Kill.anchor(state, environment.CFrame.new(start), environment.Vector3.new(0.3, 0.3, 0.3))
			local smoke = GameEffects.Kill.particle(state, trail, {Texture = state.textures.soft,
				Color = colors(environment.Color3.fromRGB(235, 235, 235), environment.Color3.fromRGB(150, 150, 155)), Size = sequence(0, 0.5, 1, 1.8),
				Transparency = sequence(0, 0.2, 1, 1), Lifetime = environment.NumberRange.new(0.5, 0.8), Speed = environment.NumberRange.new(0.2, 1),
				SpreadAngle = environment.Vector2.new(180, 180), LightEmission = 0, LightInfluence = 0.8, Brightness = 1.2}, 0)
			smoke.Rate, smoke.Enabled = 70, true
			local flame = GameEffects.Kill.particle(state, trail, {Texture = state.textures.flame,
				Color = colors(environment.Color3.fromRGB(255, 220, 120), environment.Color3.fromRGB(255, 90, 20)), Size = sequence(0, 0.5, 1, 0.1),
				Lifetime = environment.NumberRange.new(0.08, 0.14), Speed = environment.NumberRange.new(0.1), Brightness = 4}, 0)
			flame.Rate, flame.Enabled = 60, true
			GameEffects.Kill.animate(state, 0.5, function(progress)
				local position = GameEffects.Kill.bezier(start, control, target, progress)
				local ahead = GameEffects.Kill.bezier(start, control, target, math.min(1, progress + 0.02))
				local frame = (ahead - position).Magnitude > 0.001 and environment.CFrame.lookAt(position, ahead) or environment.CFrame.new(position)
				missile.CFrame, tip.CFrame, trail.CFrame = frame, frame * environment.CFrame.new(0, 0, -0.7), frame * environment.CFrame.new(0, 0, 0.7)
			end, function()
				pcall(function() missile:Destroy() end)
				pcall(function() tip:Destroy() end)
				smoke.Enabled, flame.Enabled = false, false
				GameEffects.Kill.destroyLater(state, trail, 1)
				GameEffects.Kill.flash(state, target, environment.Color3.fromRGB(255, 140, 40), 8, 5)
				GameEffects.Kill.sparks(state, target, environment.Color3.fromRGB(255, 160, 60), 16, 25)
				GameEffects.Kill.smoke(state, target - environment.Vector3.new(0, 1, 0), environment.Color3.fromRGB(110, 100, 95), 5, 6, 1.6)
				GameEffects.Kill.splat(state, target, 2.8, environment.Color3.fromRGB(25, 20, 18), 2.4, effect.ignore, 0.1, state.textures.burn, 1)
				if body and body.torso and body.torso.Parent then
					local offset = body.torso.Position - target
					local impact = offset.Magnitude > 0.1 and offset.Unit or environment.Vector3.new(0, 1, 0)
					for _, part in body.body do pcall(function() part.AssemblyLinearVelocity += impact * 18 + environment.Vector3.new(0, 16, 0) end) end
				end
				GameEffects.Kill.sound(state, index % 2 == 0 and GameEffects.Kill.soundIds.explode or GameEffects.Kill.soundIds.boom, 0.6, 1 + math.random() * 0.3, trail)
				GameEffects.Kill.shakeCamera(state, target, 0.7, 0.2)
			end)
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.rocket, 0.35, 1.3 + math.random() * 0.3, trail)
		end)
	end
end

function GameEffects.Kill.bezier(start, control, finish, progress)
	return start * (1 - progress) ^ 2 + control * (2 * (1 - progress) * progress) + finish * progress ^ 2
end

function GameEffects.Kill.cannonball(state, effect)
	local context, environment = state.context, state.context.environment
	local fallback, origin = GameEffects.Kill.direction(state, effect)
	if effect.killer and effect.killer.Parent then origin = effect.killer.Position + environment.Vector3.new(0, 0.6, 0) end
	local target = effect.chest
	local offset = target - origin
	local direction = offset.Magnitude > 0.5 and offset.Unit or fallback
	local body = GameEffects.Kill.body(state, effect, environment.Vector3.new(0, 0, 0), nil, 3.4, nil, true)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local ball = environment.Instance.new("Part")
	ball.Shape, ball.Anchored, ball.CanCollide, ball.CanQuery, ball.CanTouch = environment.Enum.PartType.Ball, true, false, false, false
	ball.Size, ball.Material, ball.Color, ball.Reflectance = environment.Vector3.new(1.6, 1.6, 1.6), environment.Enum.Material.Metal, environment.Color3.fromRGB(30, 30, 34), 0.2
	local start = origin + direction * 2
	ball.CFrame, ball.Parent = environment.CFrame.new(start), GameEffects.Kill.folder(state)
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
	local emitter = GameEffects.Kill.particle(state, ball, {Texture = state.textures.soft, Color = colors(environment.Color3.fromRGB(220, 220, 220), environment.Color3.fromRGB(140, 140, 145)),
		Size = sequence(0, 0.8, 1, 2), Transparency = sequence(0, 0.3, 1, 1), Lifetime = environment.NumberRange.new(0.4, 0.7),
		Speed = environment.NumberRange.new(0.2, 1), SpreadAngle = environment.Vector2.new(180, 180), LightEmission = 0, LightInfluence = 0.8, Brightness = 1.2}, 0)
	emitter.Rate, emitter.Enabled = 60, true
	GameEffects.Kill.smoke(state, start, environment.Color3.fromRGB(200, 200, 200), 8, 6, 1.6)
	GameEffects.Kill.flash(state, start, environment.Color3.fromRGB(255, 180, 90), 6, 4)
	local control = (start + target) / 2 + environment.Vector3.new(0, offset.Magnitude * 0.12, 0)
	GameEffects.Kill.animate(state, 0.35, function(progress)
		ball.CFrame = environment.CFrame.new(GameEffects.Kill.bezier(start, control, target, progress))
	end, function()
		emitter.Enabled, ball.Anchored, ball.CanCollide = false, false, true
		pcall(function() ball.CollisionGroup = "Ragdolls" end)
		ball.Parent = GameEffects.Kill.bodiesFolder(state)
		local function launch() if ball.Parent then ball.AssemblyLinearVelocity = direction * 40 + environment.Vector3.new(0, 8, 0) end end
		launch()
		local connection
		connection = context.runService.Heartbeat:Connect(function() connection:Disconnect(); launch() end)
		GameEffects.Kill.delay(state, 2.4, function() if ball.Parent then GameEffects.Kill.tween(state, ball, 0.4, {Transparency = 1}) end end)
		GameEffects.Kill.destroyLater(state, ball, 2.9)
		if body then
			body.release(direction * 62 + environment.Vector3.new(0, 22, 0), nil)
			pcall(function() body.torso.AssemblyAngularVelocity = GameEffects.Kill.randomVector(state, 10) end)
		end
		GameEffects.Kill.smoke(state, target, environment.Color3.fromRGB(200, 195, 190), 10, 8, 2)
		GameEffects.Kill.sparks(state, target, environment.Color3.fromRGB(255, 200, 120), 16, 20)
		local _, attachment = GameEffects.Kill.effectAttachment(state, target)
		local white = environment.Color3.new(1, 1, 1)
		GameEffects.Kill.particle(state, attachment, {Texture = state.textures.ring, Color = colors(white), Size = sequence(0, 1, 1, 8),
			Transparency = sequence(0, 0.2, 1, 1), Lifetime = environment.NumberRange.new(0.3), Brightness = 3}, 1)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.metalHeavy, 1, 0.7)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.bodyHeavy, 0.6, 1.2)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.bounce, 0.7, 0.8)
		GameEffects.Kill.shakeCamera(state, target, 1.1, 0.3)
	end)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.cannon, 0.7, 1.3)
end

function GameEffects.Kill.updateChain(state, chain, progress)
	local environment = state.context.environment
	local offset = chain.part.Position - chain.origin
	local length = offset.Magnitude
	if length < 0.1 then return end
	local direction, count = offset / length, math.max(1, math.floor(length * progress / 0.42))
	for index = 1, math.max(count, #chain.links) do
		local link = chain.links[index]
		if not link and index <= count then
			link = environment.Instance.new("Part")
			link.Anchored, link.CanCollide, link.CanQuery, link.CanTouch, link.CastShadow = true, false, false, false, false
			link.Size, link.Material, link.Color, link.Reflectance = environment.Vector3.new(0.12, 0.3, 0.5), environment.Enum.Material.Metal, environment.Color3.fromRGB(80, 78, 90), 0.25
			link.Parent = GameEffects.Kill.folder(state)
			chain.links[index] = link
		end
		if not link then continue end
		if index > count then link.Transparency = 1; continue end
		local position = chain.origin + direction * (index - 0.5) * 0.42
		link.CFrame = environment.CFrame.lookAt(position, position + direction) * environment.CFrame.Angles(0, 0, index % 2 == 0 and math.pi / 2 or 0)
		link.Transparency = 0
	end
end

function GameEffects.Kill.chains(state, effect)
	local environment = state.context.environment
	local color = environment.Color3.fromRGB(160, 80, 255)
	local body, model = GameEffects.Kill.staticBody(state, effect)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	if model then GameEffects.Kill.highlight(state, model, color, color, 0.75, 0.3) end
	local ground = GameEffects.Kill.ground(state, effect.root, effect.ignore)
	local height = ground and ground.Y or effect.root.Y - 3
	local names, chains = {}, {}
	for _, part in body do names[part.Name] = part end
	for index, name in {"LeftHand", "RightHand", "LeftLowerLeg", "RightLowerLeg", "UpperTorso"} do
		local part = names[name]
		if not part then continue end
		local angle = index / 5 * 6.283 + math.random() * 0.5
		local origin = environment.Vector3.new(effect.root.X + math.cos(angle) * 4.5, height, effect.root.Z + math.sin(angle) * 4.5)
		GameEffects.Kill.splat(state, origin + environment.Vector3.new(0, 1, 0), 2.2, color, 1.8, effect.ignore, 0.2, state.textures.ring, 1)
		table.insert(chains, {origin = origin, part = part, links = {}})
	end
	GameEffects.Kill.animate(state, 0.28, function(progress)
		for _, chain in chains do GameEffects.Kill.updateChain(state, chain, progress) end
	end, function()
		for index = 1, #chains do
			GameEffects.Kill.delay(state, index * 0.03, function() GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.chainHit, 0.5, 1.2 + index * 0.1) end)
		end
	end)
	local frames = {}
	for index, part in body do frames[index] = part.CFrame end
	GameEffects.Kill.delay(state, 0.3, function()
		GameEffects.Kill.animate(state, 0.45, function()
			for index, part in body do
				if part.Parent then part.CFrame = frames[index] + environment.Vector3.new((math.random() - 0.5) * 0.25, 0, (math.random() - 0.5) * 0.25) end
			end
			for _, chain in chains do GameEffects.Kill.updateChain(state, chain, 1) end
		end, function()
			GameEffects.Kill.animate(state, 0.6, function(progress)
				local offset = environment.Vector3.new(0, -8 * progress * progress, 0)
				for index, part in body do if part.Parent then part.CFrame = frames[index] + offset end end
				for _, chain in chains do GameEffects.Kill.updateChain(state, chain, 1) end
			end, function()
				for _, chain in chains do for _, link in chain.links do pcall(function() link:Destroy() end) end end
				for _, part in body do pcall(function() part:Destroy() end) end
				GameEffects.Kill.ringAtGround(state, effect.root, color, 2, 12, 0.5, nil, effect.ignore)
				GameEffects.Kill.smoke(state, effect.root - environment.Vector3.new(0, 2.5, 0), environment.Color3.fromRGB(60, 40, 80), 8, 6, 2)
				GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.quakeDebris, 0.6, 0.8)
			end)
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.chainRattle, 0.8, 0.7)
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.growl, 0.6, 0.6)
		end)
	end)
	local anchor = GameEffects.Kill.effectAttachment(state, effect.chest)
	GameEffects.Kill.light(state, anchor, color, 5, 16, 1.6)
end

function GameEffects.Kill.demonHand(state, effect)
	local environment = state.context.environment
	local dark, red = environment.Color3.fromRGB(38, 6, 12), environment.Color3.fromRGB(255, 30, 40)
	local ground = GameEffects.Kill.ground(state, effect.root, effect.ignore)
	local height = ground and ground.Y or effect.root.Y - 3
	local body = GameEffects.Kill.staticBody(state, effect)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local direction, up = GameEffects.Kill.cameraDirection(state), environment.Vector3.new(0, 1, 0)
	local model = environment.Instance.new("Model")
	model.Name, model.Parent = "Hand", GameEffects.Kill.folder(state)
	GameEffects.Kill.highlight(state, model, red, red, 1, 0)
	local function create(size)
		local part = environment.Instance.new("Part")
		part.Anchored, part.CanCollide, part.CanQuery, part.CanTouch, part.CastShadow = true, false, false, false, true
		part.Size, part.Material, part.Color, part.Parent = size, environment.Enum.Material.SmoothPlastic, dark, model
		return part
	end
	local palm = create(environment.Vector3.new(6, 1.2, 5.2))
	local fingers = {}
	for _, x in {-2.2, -0.75, 0.75, 2.2} do
		local segments = {}
		for _ = 1, 3 do table.insert(segments, create(environment.Vector3.new(1.05, 1.05, 1.9))) end
		table.insert(fingers, {x = x, z = 2.6, segments = segments, length = 1.9, yaw = 0})
	end
	table.insert(fingers, {x = -3.3, z = 0.3, segments = {create(environment.Vector3.new(1.15, 1.15, 1.7)), create(environment.Vector3.new(1.05, 1.05, 1.6))}, length = 1.65, yaw = math.rad(-35)})
	local function place(frame, curl)
		palm.CFrame = frame
		for _, finger in fingers do
			local joint = frame * environment.CFrame.new(finger.x, 0.3, finger.z) * environment.CFrame.Angles(0, finger.yaw, 0)
			for _, segment in finger.segments do
				joint *= environment.CFrame.Angles(-curl, 0, 0)
				segment.CFrame = joint * environment.CFrame.new(0, 0, finger.length / 2)
				joint *= environment.CFrame.new(0, 0, finger.length)
			end
		end
	end
	local base = environment.Vector3.new(effect.root.X, height + 0.6, effect.root.Z) - direction * 1.2
	local function frame(position) return environment.CFrame.fromMatrix(position, up:Cross(direction), up) end
	place(frame(base - environment.Vector3.new(0, 8, 0)), 0.1)
	GameEffects.Kill.animate(state, 0.35, function(progress) place(frame(base - environment.Vector3.new(0, 8 * (1 - progress) ^ 2, 0)), 0.1) end, function()
		GameEffects.Kill.smoke(state, base, environment.Color3.fromRGB(80, 60, 55), 10, 8, 2.5)
		GameEffects.Kill.animate(state, 0.3, function(progress) place(frame(base), 0.1 + 0.85 * progress) end, function()
			GameEffects.Kill.animate(state, 0.15, function(progress) place(frame(base), 0.95 + 0.2 * progress) end, function()
				for _, part in body do pcall(function() part:Destroy() end) end
				local anchor, attachment = GameEffects.Kill.effectAttachment(state, effect.chest)
				GameEffects.Kill.particle(state, attachment, {Texture = state.textures.splat,
					Color = environment.ColorSequence.new(environment.Color3.fromRGB(190, 10, 30), environment.Color3.fromRGB(100, 0, 12)),
					Size = GameEffects.Kill.numberSequence(state, 0, 0.7, 1, 0.3), Lifetime = environment.NumberRange.new(0.6, 1), Speed = environment.NumberRange.new(14, 28),
					SpreadAngle = environment.Vector2.new(180, 180), Acceleration = environment.Vector3.new(0, -60, 0), Rotation = environment.NumberRange.new(0, 360), LightEmission = 0, Brightness = 1.1}, 60)
				GameEffects.Kill.flash(state, effect.chest, red, 10, 4)
				GameEffects.Kill.splatRays(state, effect.chest, 10, environment.Color3.fromRGB(125, 0, 12), 12, effect.ignore, 1, 2.6, 3)
				GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.boneSquish, 1, 0.7, anchor)
				GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.rocks, 0.7, 0.8, anchor)
				GameEffects.Kill.shakeCamera(state, effect.chest, 1.1, 0.3)
				GameEffects.Kill.delay(state, 0.35, function()
					GameEffects.Kill.animate(state, 0.6, function(progress) place(frame(base - environment.Vector3.new(0, 9 * progress * progress, 0)), 1.15) end,
						function() pcall(function() model:Destroy() end) end)
				end)
			end)
		end)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.rocks, 0.9, 0.6)
	end)
	GameEffects.Kill.splat(state, effect.root, 7, environment.Color3.fromRGB(30, 10, 10), 2.4, effect.ignore, 0.3, state.textures.cracks, 2)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.roarDeep, 0.8, 0.4, nil, 2.2)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.rise, 0.5, 0.4)
end

function GameEffects.Kill.anvil(state, effect)
	local environment = state.context.environment
	local color = environment.Color3.fromRGB(62, 64, 70)
	local ground = GameEffects.Kill.ground(state, effect.root, effect.ignore)
	local height = ground and ground.Y or effect.root.Y - 3
	local body = GameEffects.Kill.staticBody(state, effect)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local rotation = environment.CFrame.Angles(0, math.random() * 6.28, 0)
	local specs = {{"Part", environment.Vector3.new(2.2, 0.5, 1.4), environment.CFrame.new(0, 0.25, 0)},
		{"Part", environment.Vector3.new(1.2, 0.6, 0.9), environment.CFrame.new(0, 0.8, 0)},
		{"Part", environment.Vector3.new(2.8, 0.6, 1.3), environment.CFrame.new(0.3, 1.4, 0)},
		{"WedgePart", environment.Vector3.new(1.3, 0.6, 1.2), environment.CFrame.new(-1.7, 1.4, 0) * environment.CFrame.Angles(0, math.pi / 2, 0)}}
	local pieces = {}
	for _, spec in specs do
		local part = environment.Instance.new(spec[1])
		part.Anchored, part.CanCollide, part.CanQuery, part.CanTouch, part.CastShadow = true, false, false, false, true
		part.Size, part.Color, part.Material, part.Reflectance, part.Parent = spec[2], color, environment.Enum.Material.Metal, 0.15, GameEffects.Kill.folder(state)
		table.insert(pieces, part)
	end
	local function place(y)
		local frame = environment.CFrame.new(effect.root.X, y, effect.root.Z) * rotation
		for index, part in pieces do part.CFrame = frame * specs[index][3] end
	end
	local top, bottom = effect.head.Y + 0.7, height + 0.45
	local start = top + 16
	place(start)
	GameEffects.Kill.splat(state, effect.root, 3.5, environment.Color3.new(0, 0, 0), 0.5, effect.ignore, 0.35, state.textures.soft, 1)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.slideWhistle, 0.5, 0.6)
	GameEffects.Kill.animate(state, 0.32, function(progress) place(start + (top - start) * progress * progress) end, function()
		for _, part in body do
			if not part.Parent then continue end
			local y = height + (part.Position.Y - height) * 0.16 + 0.1
			GameEffects.Kill.tween(state, part, 0.08, {CFrame = environment.CFrame.new(part.Position.X, y, part.Position.Z) * part.CFrame.Rotation,
				Size = environment.Vector3.new(part.Size.X * 1.3, math.max(0.08, part.Size.Y * 0.25), part.Size.Z * 1.3)}, environment.Enum.EasingStyle.Quad)
		end
		GameEffects.Kill.animate(state, 0.08, function(progress) place(top + (bottom - top) * progress) end, function()
			GameEffects.Kill.animate(state, 0.26, function(progress) place(bottom + math.sin(progress * math.pi) * 0.7) end)
			local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.root.X, height + 0.2, effect.root.Z), environment.Vector3.new(3, 0.3, 3))
			local attachment = environment.Instance.new("Attachment")
			attachment.Parent = anchor
			GameEffects.Kill.groundRing(state, attachment, state.textures.ringEdge, environment.Color3.fromRGB(220, 215, 205), 2, 12, 0.45, 2)
			local dust = environment.Color3.fromRGB(170, 165, 158)
			GameEffects.Kill.particle(state, anchor, {Texture = state.textures.soft, Color = environment.ColorSequence.new(dust, dust),
				Size = GameEffects.Kill.numberSequence(state, 0, 1.2, 1, 3.5), Transparency = GameEffects.Kill.numberSequence(state, 0, 0.35, 1, 1),
				Lifetime = environment.NumberRange.new(0.5, 0.8), Speed = environment.NumberRange.new(8, 14), SpreadAngle = environment.Vector2.new(85, 85),
				Drag = 4, Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0, LightInfluence = 1, Brightness = 1}, 16)
			local stars = {}
			for index = 1, 4 do
				local star = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.root.X, bottom + 2.6, effect.root.Z), environment.Vector3.new(0.2, 0.2, 0.2))
				local starAttachment = environment.Instance.new("Attachment")
				starAttachment.Parent = star
				local gold = environment.Color3.fromRGB(255, 235, 120)
				local emitter = GameEffects.Kill.particle(state, starAttachment, {Texture = state.textures.star, Color = environment.ColorSequence.new(gold, gold),
					Size = GameEffects.Kill.numberSequence(state, 0, 0.55, 1, 0.55), Lifetime = environment.NumberRange.new(0.12), LockedToPart = true, Brightness = 4, ZOffset = 1}, 0)
				emitter.Rate, emitter.Enabled = 30, true
				table.insert(stars, {part = star, phase = index * math.pi / 2})
			end
			GameEffects.Kill.animate(state, 1.3, function(progress)
				local elapsed = progress * 1.3
				for _, star in stars do
					local angle = star.phase + elapsed * 7
					star.part.CFrame = environment.CFrame.new(effect.root.X + math.cos(angle) * 1.3, bottom + 2.6 + math.sin(elapsed * 9 + star.phase) * 0.12,
						effect.root.Z + math.sin(angle) * 1.3)
				end
			end, function() for _, star in stars do GameEffects.Kill.destroyLater(state, star.part, 0) end end)
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.anvil, 1, 0.8, anchor)
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.bounce, 0.7, 0.8, anchor)
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.metalHeavy, 0.4, 1.4, anchor)
			GameEffects.Kill.shakeCamera(state, environment.Vector3.new(effect.root.X, height, effect.root.Z), 0.9, 0.3)
			GameEffects.Kill.destroyLater(state, anchor, 1.5)
		end)
	end)
	GameEffects.Kill.delay(state, 1.9, function()
		for _, part in pieces do
			if part.Parent then GameEffects.Kill.tween(state, part, 0.4, {Transparency = 1}) end
			GameEffects.Kill.destroyLater(state, part, 0.45)
		end
		GameEffects.Kill.fadeGhost(state, body, 0.4)
	end)
end

function GameEffects.Kill.spiritBomb(state, effect)
	local context, environment = state.context, state.context.environment
	local color, white = environment.Color3.fromRGB(110, 210, 255), environment.Color3.new(1, 1, 1)
	local body = GameEffects.Kill.body(state, effect, environment.Vector3.new(0, 0, 0), nil, 3.6, nil, true)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local params = environment.RaycastParams.new()
	params.FilterType, params.RespectCanCollide = environment.Enum.RaycastFilterType.Exclude, true
	params.FilterDescendantsInstances = {effect.char, context.workspace.CurrentCamera, GameEffects.Kill.bodiesFolder(state)}
	local ceiling = context.workspace:Raycast(effect.chest, environment.Vector3.new(0, 30, 0), params)
	local height = ceiling and math.clamp(ceiling.Distance - 5.5, 6, 26) or 26
	local size = math.min(10, height * 0.8)
	local center = effect.chest + environment.Vector3.new(0, height, 0)
	local orb = environment.Instance.new("Part")
	orb.Shape, orb.Anchored, orb.CanCollide, orb.CanQuery, orb.CanTouch, orb.CastShadow = environment.Enum.PartType.Ball, true, false, false, false, false
	orb.Material, orb.Color, orb.Transparency, orb.Size, orb.CFrame = environment.Enum.Material.Neon, color, 0.25, environment.Vector3.new(0.5, 0.5, 0.5), environment.CFrame.new(center)
	orb.Parent = GameEffects.Kill.folder(state)
	local glow = orb:Clone()
	glow.Color, glow.Transparency, glow.Parent = white, 0.75, GameEffects.Kill.folder(state)
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(center), environment.Vector3.new(30, 30, 30))
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
	local emitter = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.spark, Color = colors(white, color), Size = sequence(0, 0.6, 1, 0.2),
		Lifetime = environment.NumberRange.new(0.6, 0.8), Speed = environment.NumberRange.new(20, 26), Shape = environment.Enum.ParticleEmitterShape.Sphere,
		ShapeStyle = environment.Enum.ParticleEmitterShapeStyle.Surface, ShapeInOut = environment.Enum.ParticleEmitterShapeInOut.Inward,
		Orientation = environment.Enum.ParticleOrientation.VelocityParallel, Brightness = 4}, 0)
	emitter.Rate, emitter.Enabled = 120, true
	local light = environment.Instance.new("PointLight")
	light.Color, light.Range, light.Brightness, light.Shadows, light.Parent = color, 30, 2, false, orb
	GameEffects.Kill.animate(state, 0.9, function(progress)
		local diameter = 0.5 + (size - 0.5) * progress
		orb.Size, glow.Size = environment.Vector3.new(diameter, diameter, diameter), environment.Vector3.new(diameter * 1.2, diameter * 1.2, diameter * 1.2)
		light.Brightness = 2 + 6 * progress
	end, function()
		emitter.Enabled = false
		GameEffects.Kill.destroyLater(state, anchor, 1)
		GameEffects.Kill.animate(state, 0.4, function(progress)
			local position = center:Lerp(effect.chest, progress * progress)
			orb.CFrame, glow.CFrame = environment.CFrame.new(position), environment.CFrame.new(position)
		end, function()
			pcall(function() orb:Destroy() end)
			pcall(function() glow:Destroy() end)
			GameEffects.Kill.flash(state, effect.chest, color, 26, 7)
			local _, attachment = GameEffects.Kill.effectAttachment(state, effect.chest)
			for index = 1, 3 do
				GameEffects.Kill.particle(state, attachment, {Texture = state.textures.ring, Color = colors(index == 2 and white or color),
					Size = sequence(0, 1, 1, 14 + index * 5), Transparency = sequence(0, 0, 1, 1), Lifetime = environment.NumberRange.new(0.5 + index * 0.1), Brightness = 5}, 1)
			end
			GameEffects.Kill.particle(state, attachment, {Texture = state.textures.needles, Color = colors(white, color), Size = sequence(0, 6, 1, 16),
				Transparency = sequence(0, 0.1, 1, 1), Lifetime = environment.NumberRange.new(0.6), Rotation = environment.NumberRange.new(0, 360), Brightness = 5}, 2)
			GameEffects.Kill.ringAtGround(state, effect.root, color, 2, 40, 0.8, nil, effect.ignore)
			GameEffects.Kill.smoke(state, effect.root - environment.Vector3.new(0, 2.5, 0), environment.Color3.fromRGB(170, 170, 180), 18, 14, 3)
			GameEffects.Kill.fragments(state, effect.chest, 14, environment.Color3.fromRGB(90, 90, 100), environment.Enum.Material.Slate, 0.4, 28, 1.6)
			if body then
				body.release(GameEffects.Kill.direction(state, effect) * 25 + environment.Vector3.new(0, 50, 0), nil)
				pcall(function() body.torso.AssemblyAngularVelocity = GameEffects.Kill.randomVector(state, 10) end)
				local highlight = GameEffects.Kill.highlight(state, body.model, color, white, 0.3, 0)
				GameEffects.Kill.delay(state, 0.6, function() if highlight.Parent then GameEffects.Kill.tween(state, highlight, 0.6, {FillTransparency = 1, OutlineTransparency = 1}) end end)
			end
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.artillery, 1, 1.1, nil, 2.5)
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.boomDeep, 0.9, 0.8)
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.sonic2, 0.7, 0.8, nil, 1.5)
			GameEffects.Kill.shakeCamera(state, effect.chest, 2, 0.6)
		end)
	end)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.energyField, 0.8, 0.8, nil, 1.4)
	GameEffects.Kill.delay(state, 0.5, function() GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.energyField, 0.6, 1.1, nil, 1.4) end)
end

function GameEffects.Kill.puppet(state, effect)
	local environment = state.context.environment
	local color = environment.Color3.fromRGB(255, 40, 70)
	local body = GameEffects.Kill.body(state, effect, environment.Vector3.new(0, 6, 0), nil, 3.8)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	if not body then return end
	local force = GameEffects.Kill.upForce(state, body, 0.95)
	local center = effect.chest + environment.Vector3.new(0, 10, 0)
	local forward, right = GameEffects.Kill.cameraDirection(state)
	local wood = environment.Color3.fromRGB(120, 80, 45)
	local crossbar = GameEffects.Kill.beam(state, center - right * 2.2, center + right * 2.2, 0.28, wood, environment.Enum.Material.Wood, 0)
	local lengthwise = GameEffects.Kill.beam(state, center - forward * 1.6, center + forward * 1.6, 0.28, wood, environment.Enum.Material.Wood, 0)
	local offsets = {Head = environment.Vector3.new(0, 0, 0), LeftHand = -right * 2.1, RightHand = right * 2.1, LeftFoot = -forward * 1.5, RightFoot = forward * 1.5}
	local drops = {Head = 5.2, LeftHand = 6.2, RightHand = 6.2, LeftFoot = 9.4, RightFoot = 9.4}
	local strings = {}
	for name, offset in offsets do
		local part = body.model:FindFirstChild(name)
		if not part then continue end
		local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(center + offset), environment.Vector3.new(0.15, 0.15, 0.15))
		local first, second = environment.Instance.new("Attachment"), environment.Instance.new("Attachment")
		first.Parent, second.Parent = anchor, part
		local beam = GameEffects.Kill.attachmentBeam(state, first, second, {Width0 = 0.05, Width1 = 0.05,
			Color = environment.ColorSequence.new(color, color), Transparency = GameEffects.Kill.numberSequence(state, 0, 0, 1, 0), Segments = 2})
		table.insert(strings, {anchor = anchor, part = part, offset = offset, drop = drops[name], beam = beam})
	end
	GameEffects.Kill.animate(state, 1.5, function(progress)
		local elapsed = progress * 1.5
		local rotation = environment.CFrame.fromAxisAngle(environment.Vector3.new(0, 1, 0), math.sin(elapsed * 3) * 0.35)
		local position = center + environment.Vector3.new(math.sin(elapsed * 5) * 0.4, math.sin(elapsed * 7) * 0.3, 0)
		crossbar.CFrame = environment.CFrame.new(position) * rotation * (environment.CFrame.new(center):Inverse() * environment.CFrame.lookAt(center, center + right))
		lengthwise.CFrame = environment.CFrame.new(position) * rotation * (environment.CFrame.new(center):Inverse() * environment.CFrame.lookAt(center, center + forward))
		for _, string in strings do
			local top = position + rotation * string.offset
			string.anchor.CFrame = environment.CFrame.new(top)
			local target = top - environment.Vector3.new(0, string.drop - math.sin(elapsed * 14 + string.drop) * 1.2, 0)
			if string.part.Parent and string.beam.Parent then pcall(function() string.part.AssemblyLinearVelocity = (target - string.part.Position) * 7 end) end
		end
	end, function()
		if force then force:Destroy() end
		for _, string in strings do
			if string.part.Parent then GameEffects.Kill.sparks(state, string.part.Position, color, 6, 12, state.textures.spark) end
			pcall(function() string.beam:Destroy() end)
			GameEffects.Kill.destroyLater(state, string.anchor, 0)
		end
		for _, part in {crossbar, lengthwise} do
			GameEffects.Kill.tween(state, part, 0.4, {Transparency = 1})
			GameEffects.Kill.destroyLater(state, part, 0.45)
		end
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.snip, 1, 1.3)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.rip, 0.8, 1.6)
		GameEffects.Kill.delay(state, 0.9, function()
			local position = body.torso and body.torso.Parent and body.torso.Position or effect.root
			GameEffects.Kill.splat(state, position, 3.5, environment.Color3.fromRGB(125, 0, 12), 2.4, effect.ignore, 0.9)
		end)
	end)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.whisper, 0.4, 1.7)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.servo, 0.5, 0.6)
end

function GameEffects.Kill.jackpot(state, effect)
	local context, environment = state.context, state.context.environment
	local color, white = environment.Color3.fromRGB(255, 200, 60), environment.Color3.new(1, 1, 1)
	local body, model = GameEffects.Kill.staticBody(state, effect)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.chest), environment.Vector3.new(2, 4, 1.4))
	if model then
		local highlight = GameEffects.Kill.highlight(state, model, color, environment.Color3.fromRGB(255, 240, 180), 1, 0)
		GameEffects.Kill.tween(state, highlight, 0.25, {FillTransparency = 0.1})
	end
	local sizes = {}
	for index, part in body do sizes[index] = part.Size end
	GameEffects.Kill.animate(state, 0.3, function(progress)
		for index, part in body do if part.Parent then part.Size = sizes[index] * (1 + 0.15 * progress) end end
	end)
	GameEffects.Kill.delay(state, 0.3, function()
		for _, part in body do pcall(function() part:Destroy() end) end
		if model then pcall(function() model:Destroy() end) end
		local coins = {}
		for _ = 1, 24 do
			local coin = environment.Instance.new("Part")
			coin.Shape, coin.Size = environment.Enum.PartType.Cylinder, environment.Vector3.new(0.14, 0.85, 0.85)
			coin.Material, coin.Color, coin.Reflectance = environment.Enum.Material.Foil, color:Lerp(environment.Color3.fromRGB(255, 235, 140), math.random()), 0.25
			coin.CanQuery, coin.CanTouch = false, false
			pcall(function() coin.CollisionGroup = "Ragdolls" end)
			local offset = environment.Vector3.new((math.random() - 0.5) * 1.4, (math.random() - 0.5) * 2.6, math.random() - 0.5)
			coin.CFrame = environment.CFrame.new(effect.chest + offset) * environment.CFrame.Angles(math.random() * 6.28, math.random() * 6.28, math.random() * 6.28)
			coin.Parent = GameEffects.Kill.bodiesFolder(state)
			table.insert(coins, coin)
			GameEffects.Kill.delay(state, 2.4 + math.random() * 0.4, function() if coin.Parent then GameEffects.Kill.tween(state, coin, 0.4, {Transparency = 1}) end end)
			GameEffects.Kill.destroyLater(state, coin, 3.2)
		end
		local function launch()
			for _, coin in coins do
				if not coin.Parent then continue end
				local offset = coin.Position - effect.chest
				local horizontal = environment.Vector3.new(offset.X, 0, offset.Z)
				local direction = horizontal.Magnitude > 0.05 and horizontal.Unit or environment.Vector3.new(1, 0, 0)
				coin.AssemblyLinearVelocity = direction * (6 + math.random() * 8) + environment.Vector3.new(0, 14 + math.random() * 12, 0)
				coin.AssemblyAngularVelocity = GameEffects.Kill.randomVector(state, 15)
			end
		end
		launch()
		local connection
		connection = context.runService.Heartbeat:Connect(function() connection:Disconnect(); launch() end)
		local attachment = environment.Instance.new("Attachment")
		attachment.Parent = anchor
		local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
		GameEffects.Kill.particle(state, attachment, {Texture = state.textures.star4, Color = environment.ColorSequence.new(white, color),
			Size = sequence(0, 0, 0.3, 1.2, 1, 0), Lifetime = environment.NumberRange.new(0.4, 0.7), Speed = environment.NumberRange.new(6, 14),
			SpreadAngle = environment.Vector2.new(180, 180), Drag = 3, Rotation = environment.NumberRange.new(0, 90), Brightness = 6}, 18)
		GameEffects.Kill.particle(state, attachment, {Texture = state.textures.soft, Color = environment.ColorSequence.new(color, color),
			Size = sequence(0, 3, 1, 7), Transparency = sequence(0, 0.3, 1, 1), Lifetime = environment.NumberRange.new(0.35), Brightness = 3}, 1)
		for _ = 1, 9 do
			GameEffects.Kill.delay(state, 0.45 + math.random() * 1.1, function() GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.coinDrop, 0.3, 1.8 + math.random() * 0.8, anchor) end)
		end
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.cash, 1, 1, anchor)
		GameEffects.Kill.light(state, anchor, color, 7, 16, 0.7)
	end)
	GameEffects.Kill.destroyLater(state, anchor, 3)
end

function GameEffects.Kill.crows(state, effect)
	local environment = state.context.environment
	local color = environment.Color3.fromRGB(14, 12, 18)
	local body = GameEffects.Kill.ghost(state, effect.char, {material = environment.Enum.Material.SmoothPlastic, color = color, transparency = 0})
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.chest), environment.Vector3.new(2.2, 4.6, 1.4))
	for _, part in body do
		local frame = part.CFrame
		GameEffects.Kill.animate(state, 0.35, function(progress)
			if part.Parent then part.CFrame = frame + environment.Vector3.new((math.random() - 0.5) * 0.12 * progress, 0, (math.random() - 0.5) * 0.12 * progress) end
		end)
	end
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.crow, 0.9, 1, anchor)
	GameEffects.Kill.delay(state, 0.35, function()
		GameEffects.Kill.fadeGhost(state, body, 0.2)
		local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
		local colors = function(value) return environment.ColorSequence.new(value, value) end
		GameEffects.Kill.particle(state, anchor, {Texture = state.textures.leaf, Color = colors(color), Size = sequence(0, 0.45, 1, 0.3),
			Lifetime = environment.NumberRange.new(1, 1.6), Speed = environment.NumberRange.new(4, 9), SpreadAngle = environment.Vector2.new(180, 180),
			Drag = 2, Acceleration = environment.Vector3.new(0, -3, 0), Rotation = environment.NumberRange.new(0, 360), RotSpeed = environment.NumberRange.new(-300, 300),
			Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0, LightInfluence = 1, Brightness = 1}, 28)
		GameEffects.Kill.particle(state, anchor, {Texture = state.textures.smokeFB, FlipbookLayout = environment.Enum.ParticleFlipbookLayout.Grid4x4,
			FlipbookMode = environment.Enum.ParticleFlipbookMode.OneShot, Color = colors(environment.Color3.fromRGB(24, 20, 30)), Size = sequence(0, 2, 1, 5),
			Transparency = sequence(0, 0.2, 0.7, 0.45, 1, 1), Lifetime = environment.NumberRange.new(0.8, 1.2), Speed = environment.NumberRange.new(2, 5),
			SpreadAngle = environment.Vector2.new(180, 180), Drag = 3, Rotation = environment.NumberRange.new(0, 360),
			Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0, Brightness = 1}, 10)
		local birds, parts = {}, {}
		local function createPart(size)
			local part = environment.Instance.new("Part")
			part.Anchored, part.CanCollide, part.CanQuery, part.CanTouch, part.CastShadow = true, false, false, false, false
			part.Size, part.Color, part.Material, part.Parent = size, color, environment.Enum.Material.SmoothPlastic, GameEffects.Kill.folder(state)
			table.insert(parts, part)
			return part
		end
		for _ = 1, 16 do
			local horizontal = environment.Vector3.new(math.random() - 0.5, 0, math.random() - 0.5)
			horizontal = (horizontal.Magnitude > 0.05 and horizontal.Unit or environment.Vector3.new(1, 0, 0)) + environment.Vector3.new(0, 0.55 + math.random() * 0.45, 0)
			local position = effect.chest + environment.Vector3.new((math.random() - 0.5) * 1.6, (math.random() - 0.5) * 3, (math.random() - 0.5))
			table.insert(birds, {position = position, velocity = horizontal.Unit * (11 + math.random() * 8), phase = math.random() * 6.28,
				turn = (math.random() - 0.5) * 2.4, body = createPart(environment.Vector3.new(0.4, 0.32, 0.85)),
				left = createPart(environment.Vector3.new(0.85, 0.05, 0.45)), right = createPart(environment.Vector3.new(0.85, 0.05, 0.45))})
		end
		local previous = 0
		GameEffects.Kill.animate(state, 1.9, function(progress)
			local elapsed = progress * 1.9
			local delta = elapsed - previous
			previous = elapsed
			local fade = math.clamp((elapsed - 1.5) / 0.4, 0, 1)
			local frames = {}
			for _, bird in birds do
				bird.velocity = environment.CFrame.fromAxisAngle(environment.Vector3.new(0, 1, 0), bird.turn * delta) * bird.velocity + environment.Vector3.new(0, 3 * delta, 0)
				bird.position += bird.velocity * delta
				local frame = environment.CFrame.lookAt(bird.position, bird.position + bird.velocity)
				local flap = math.sin(elapsed * 26 + bird.phase) * 0.9
				table.insert(frames, frame)
				table.insert(frames, frame * environment.CFrame.new(-0.18, 0.05, 0) * environment.CFrame.Angles(0, 0, flap) * environment.CFrame.new(-0.42, 0, 0))
				table.insert(frames, frame * environment.CFrame.new(0.18, 0.05, 0) * environment.CFrame.Angles(0, 0, -flap) * environment.CFrame.new(0.42, 0, 0))
				if fade > 0 then bird.body.Transparency, bird.left.Transparency, bird.right.Transparency = fade, fade, fade end
			end
			GameEffects.Kill.moveParts(state, parts, frames)
		end, function() for _, part in parts do pcall(function() part:Destroy() end) end end)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.crow, 0.8, 1.15, anchor)
		GameEffects.Kill.delay(state, 0.25, function() GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.crow, 0.7, 0.9, anchor) end)
		for index = 0, 5 do
			GameEffects.Kill.delay(state, index * 0.09, function() GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.batWings, 0.4, 1.6 + math.random() * 0.5, anchor) end)
		end
	end)
	GameEffects.Kill.light(state, anchor, environment.Color3.fromRGB(120, 60, 200), 2, 10, 1.4)
	GameEffects.Kill.destroyLater(state, anchor, 3)
end

function GameEffects.Kill.attachmentBeam(state, first, second, properties)
	local beam = state.context.environment.Instance.new("Beam")
	beam.Attachment0, beam.Attachment1, beam.FaceCamera, beam.LightEmission, beam.LightInfluence, beam.Segments = first, second, true, 1, 0, 12
	for key, value in properties do beam[key] = value end
	beam.Parent = first.Parent
	return beam
end

function GameEffects.Kill.disco(state, effect)
	local context, environment = state.context, state.context.environment
	local colors = {environment.Color3.fromRGB(255, 60, 200), environment.Color3.fromRGB(60, 220, 255), environment.Color3.fromRGB(255, 230, 60),
		environment.Color3.fromRGB(90, 255, 120), environment.Color3.fromRGB(255, 140, 40), environment.Color3.fromRGB(120, 90, 255)}
	local white = environment.Color3.new(1, 1, 1)
	local ground = GameEffects.Kill.ground(state, effect.root, effect.ignore)
	local height = ground and ground.Y or effect.root.Y - 3
	local base = environment.Vector3.new(effect.root.X, height, effect.root.Z)
	local params = environment.RaycastParams.new()
	params.FilterType, params.RespectCanCollide = environment.Enum.RaycastFilterType.Exclude, true
	params.FilterDescendantsInstances = {effect.char, context.workspace.CurrentCamera, GameEffects.Kill.bodiesFolder(state)}
	local ceiling = context.workspace:Raycast(base + environment.Vector3.new(0, 1, 0), environment.Vector3.new(0, 14, 0), params)
	local center = base + environment.Vector3.new(0, ceiling and math.clamp(ceiling.Distance - 1.5, 5, 10) or 10, 0)
	local body = GameEffects.Kill.body(state, effect, environment.Vector3.new(0, 6, 0), nil, 3.8)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local force = GameEffects.Kill.upForce(state, body, 0.98)
	local ball = environment.Instance.new("Part")
	ball.Shape, ball.Anchored, ball.CanCollide, ball.CanQuery, ball.CanTouch = environment.Enum.PartType.Ball, true, false, false, false
	ball.Size, ball.Material, ball.Color = environment.Vector3.new(2.2, 2.2, 2.2), environment.Enum.Material.Foil, environment.Color3.fromRGB(220, 225, 235)
	ball.Reflectance, ball.CFrame, ball.Parent = 0.6, environment.CFrame.new(center + environment.Vector3.new(0, 3, 0)), GameEffects.Kill.folder(state)
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colorSequence = function(color) return environment.ColorSequence.new(color, color) end
	local emitter = GameEffects.Kill.particle(state, ball, {Texture = state.textures.star4, Color = colorSequence(white), Size = sequence(0, 0, 0.5, 0.8, 1, 0),
		Lifetime = environment.NumberRange.new(0.3), Shape = environment.Enum.ParticleEmitterShape.Sphere, Brightness = 6, ZOffset = 1}, 0)
	emitter.Rate, emitter.Enabled = 25, true
	local source = environment.Instance.new("Attachment")
	source.Parent = ball
	local spots = {}
	for index, color in colors do
		local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(base + environment.Vector3.new(0, 0.2, 0)), environment.Vector3.new(0.2, 0.2, 0.2))
		local attachment = environment.Instance.new("Attachment")
		attachment.Parent = anchor
		local beam = GameEffects.Kill.attachmentBeam(state, source, attachment, {Width0 = 0.25, Width1 = 1.6, Color = colorSequence(color), Transparency = sequence(0, 0.45, 1, 0.6), Segments = 1})
		local light = environment.Instance.new("PointLight")
		light.Color, light.Range, light.Brightness, light.Shadows, light.Parent = color, 6, 2, false, anchor
		table.insert(spots, {anchor = anchor, beam = beam, phase = index / #colors * 6.283, radius = 3 + index % 3})
	end
	local highlight = body and GameEffects.Kill.highlight(state, body.model, colors[1], white, 0.5, 0.2)
	local nextBounce = 0
	GameEffects.Kill.animate(state, 2.1, function(progress)
		local elapsed = progress * 2.1
		local lowered = math.min(1, elapsed / 0.3)
		ball.CFrame = environment.CFrame.new(center + environment.Vector3.new(0, 3 * (1 - lowered), 0)) * environment.CFrame.Angles(0, elapsed * 3, 0)
		for _, spot in spots do
			local angle = spot.phase + elapsed * 2.5
			spot.anchor.CFrame = environment.CFrame.new(base + environment.Vector3.new(math.cos(angle) * spot.radius, 0.2, math.sin(angle) * spot.radius))
		end
		if highlight and highlight.Parent then highlight.FillColor = colors[math.floor(elapsed * 7) % #colors + 1] end
		if elapsed < nextBounce or not body or not body.torso or not body.torso.Parent then return end
		nextBounce = elapsed + 0.25
		for _, part in body.body do
			pcall(function() part.AssemblyLinearVelocity += environment.Vector3.new(math.random() - 0.5, math.random() * 0.8, math.random() - 0.5) * 9 end)
		end
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.bounce, 0.35, 1 + math.floor(elapsed * 4) % 2 * 0.3)
	end, function()
		emitter.Enabled = false
		if force then pcall(function() force:Destroy() end) end
		for _, spot in spots do pcall(function() spot.beam:Destroy() end); GameEffects.Kill.destroyLater(state, spot.anchor, 0) end
		if highlight then GameEffects.Kill.tween(state, highlight, 0.4, {FillTransparency = 1, OutlineTransparency = 1}) end
		GameEffects.Kill.tween(state, ball, 0.4, {CFrame = ball.CFrame + environment.Vector3.new(0, 4, 0), Transparency = 1})
		GameEffects.Kill.destroyLater(state, ball, 0.45)
		local _, burst = GameEffects.Kill.effectAttachment(state, center)
		for _, color in colors do
			GameEffects.Kill.particle(state, burst, {Texture = state.textures.square, Color = colorSequence(color), Size = sequence(0, 0.22, 1, 0.18),
				Lifetime = environment.NumberRange.new(1.2, 2), Speed = environment.NumberRange.new(8, 18), SpreadAngle = environment.Vector2.new(180, 180),
				Drag = 2.5, Acceleration = environment.Vector3.new(0, -14, 0), Rotation = environment.NumberRange.new(0, 360), RotSpeed = environment.NumberRange.new(-400, 400),
				LightEmission = 0.2, LightInfluence = 0.6, Brightness = 1.6}, 10)
		end
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.chimes, 0.6, 1.4, nil, 2)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.partyHorn2, 0.5, 1.3)
	end)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.partyHorn2, 0.5, 0.9)
end

function GameEffects.Kill.hollowPurple(state, effect)
	local environment = state.context.environment
	local blue, red, purple = environment.Color3.fromRGB(60, 130, 255), environment.Color3.fromRGB(255, 40, 60), environment.Color3.fromRGB(170, 60, 255)
	local white = environment.Color3.new(1, 1, 1)
	local direction = GameEffects.Kill.direction(state, effect)
	local side = environment.Vector3.new(-direction.Z, 0, direction.X)
	local center = effect.chest - direction * 7
	local body = GameEffects.Kill.staticBody(state, effect)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
	local function makeOrb(color)
		local orb = environment.Instance.new("Part")
		orb.Shape, orb.Anchored, orb.CanCollide, orb.CanQuery, orb.CanTouch, orb.CastShadow = environment.Enum.PartType.Ball, true, false, false, false, false
		orb.Material, orb.Color, orb.Size, orb.Parent = environment.Enum.Material.Neon, color, environment.Vector3.new(1.4, 1.4, 1.4), GameEffects.Kill.folder(state)
		local glow = orb:Clone()
		glow.Transparency, glow.Size, glow.Parent = 0.65, environment.Vector3.new(2.6, 2.6, 2.6), GameEffects.Kill.folder(state)
		local emitter = GameEffects.Kill.particle(state, orb, {Texture = state.textures.spark, Color = colors(white, color), Size = sequence(0, 0.4, 1, 0),
			Lifetime = environment.NumberRange.new(0.2, 0.4), Speed = environment.NumberRange.new(3, 7), SpreadAngle = environment.Vector2.new(180, 180),
			Orientation = environment.Enum.ParticleOrientation.VelocityParallel, Brightness = 5}, 0)
		emitter.Rate, emitter.Enabled = 50, true
		local light = environment.Instance.new("PointLight")
		light.Color, light.Range, light.Brightness, light.Shadows, light.Parent = color, 12, 4, false, orb
		return {orb, glow}
	end
	local first, second = makeOrb(blue), makeOrb(red)
	GameEffects.Kill.animate(state, 0.55, function(progress)
		local eased = progress * progress
		local rotation = environment.CFrame.fromAxisAngle(direction, eased * 3)
		local offset = rotation * side * 6 * (1 - eased)
		first[1].CFrame, first[2].CFrame = environment.CFrame.new(center + offset), environment.CFrame.new(center + offset)
		second[1].CFrame, second[2].CFrame = environment.CFrame.new(center - offset), environment.CFrame.new(center - offset)
	end, function()
		for _, group in {first, second} do for _, part in group do pcall(function() part:Destroy() end) end end
		local orb = environment.Instance.new("Part")
		orb.Shape, orb.Anchored, orb.CanCollide, orb.CanQuery, orb.CanTouch, orb.CastShadow = environment.Enum.PartType.Ball, true, false, false, false, false
		orb.Material, orb.Color, orb.Size, orb.CFrame = environment.Enum.Material.Neon, purple, environment.Vector3.new(0.5, 0.5, 0.5), environment.CFrame.new(center)
		orb.Parent = GameEffects.Kill.folder(state)
		local glow = orb:Clone()
		glow.Color, glow.Transparency, glow.Parent = environment.Color3.fromRGB(90, 20, 160), 0.5, GameEffects.Kill.folder(state)
		local light = environment.Instance.new("PointLight")
		light.Color, light.Range, light.Brightness, light.Shadows, light.Parent = purple, 26, 8, false, orb
		GameEffects.Kill.tween(state, orb, 0.18, {Size = environment.Vector3.new(4.5, 4.5, 4.5)}, environment.Enum.EasingStyle.Back)
		GameEffects.Kill.tween(state, glow, 0.18, {Size = environment.Vector3.new(6, 6, 6)}, environment.Enum.EasingStyle.Back)
		GameEffects.Kill.flash(state, center, purple, 12, 5)
		local emitter = GameEffects.Kill.particle(state, orb, {Texture = state.textures.soft, Color = colors(purple, environment.Color3.fromRGB(60, 0, 120)),
			Size = sequence(0, 3, 1, 0.5), Transparency = sequence(0, 0.3, 1, 1), Lifetime = environment.NumberRange.new(0.5, 0.8),
			Speed = environment.NumberRange.new(0.5, 2), SpreadAngle = environment.Vector2.new(180, 180), Shape = environment.Enum.ParticleEmitterShape.Sphere, Brightness = 3}, 0)
		emitter.Rate, emitter.Enabled = 60, true
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.sonic, 0.8, 0.8, nil, 1.5)
		local hit = false
		GameEffects.Kill.delay(state, 0.2, function()
			GameEffects.Kill.animate(state, 0.6, function(progress)
				local position = center + direction * 55 * progress
				orb.CFrame, glow.CFrame = environment.CFrame.new(position), environment.CFrame.new(position)
				if hit or (position - effect.chest).Magnitude >= 3.5 then return end
				hit = true
				for _, part in body do
					if not part.Parent then continue end
					part.Material, part.Color = environment.Enum.Material.Neon, purple
					GameEffects.Kill.tween(state, part, 0.15, {Transparency = 1, Size = part.Size * 0.4})
					GameEffects.Kill.destroyLater(state, part, 0.2)
				end
				local _, attachment = GameEffects.Kill.effectAttachment(state, effect.chest)
				GameEffects.Kill.particle(state, attachment, {Texture = state.textures.square, Color = colors(white, purple), Size = sequence(0, 0.3, 1, 0),
					Lifetime = environment.NumberRange.new(0.5, 0.9), Speed = environment.NumberRange.new(8, 18), SpreadAngle = environment.Vector2.new(60, 60), Drag = 2, Brightness = 4}, 50)
				GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.boomDeep, 0.8, 0.9)
				GameEffects.Kill.shakeCamera(state, effect.chest, 1.6, 0.4)
			end, function()
				emitter.Enabled = false
				GameEffects.Kill.tween(state, orb, 0.25, {Size = environment.Vector3.new(8, 8, 8), Transparency = 1})
				GameEffects.Kill.tween(state, glow, 0.25, {Size = environment.Vector3.new(10, 10, 10), Transparency = 1})
				GameEffects.Kill.destroyLater(state, orb, 0.3)
				GameEffects.Kill.destroyLater(state, glow, 0.3)
			end)
		end)
		GameEffects.Kill.splat(state, effect.root, 6, environment.Color3.fromRGB(60, 10, 90), 2.4, effect.ignore, 0.3, state.textures.burn, 2)
	end)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.powerUp, 0.7, 0.9, nil, 1.2)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.magicGrowl, 0.6, 0.8)
end

function GameEffects.Kill.blackFlash(state, effect)
	local environment = state.context.environment
	local red, black = environment.Color3.fromRGB(255, 20, 40), environment.Color3.new(0, 0, 0)
	local direction, center = GameEffects.Kill.direction(state, effect), effect.chest
	local body = GameEffects.Kill.body(state, effect, environment.Vector3.new(0, 0, 0), nil, 3.2, nil, true)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local core = environment.Instance.new("Part")
	core.Shape, core.Anchored, core.CanCollide, core.CanQuery, core.CanTouch, core.CastShadow = environment.Enum.PartType.Ball, true, false, false, false, false
	core.Material, core.Color, core.Transparency = environment.Enum.Material.Neon, black, 0.1
	core.Size, core.CFrame, core.Parent = environment.Vector3.new(0.5, 0.5, 0.5), environment.CFrame.new(center), GameEffects.Kill.folder(state)
	local glow = core:Clone()
	glow.Color, glow.Transparency, glow.Parent = red, 0.55, GameEffects.Kill.folder(state)
	GameEffects.Kill.tween(state, core, 0.12, {Size = environment.Vector3.new(5, 5, 5)}, environment.Enum.EasingStyle.Quad)
	GameEffects.Kill.tween(state, glow, 0.14, {Size = environment.Vector3.new(6, 6, 6)}, environment.Enum.EasingStyle.Quad)
	GameEffects.Kill.delay(state, 0.13, function()
		if core.Parent then GameEffects.Kill.tween(state, core, 0.25, {Size = environment.Vector3.new(0.2, 0.2, 0.2), Transparency = 1}) end
		if glow.Parent then GameEffects.Kill.tween(state, glow, 0.3, {Size = environment.Vector3.new(9, 9, 9), Transparency = 1}) end
	end)
	GameEffects.Kill.destroyLater(state, core, 0.5)
	GameEffects.Kill.destroyLater(state, glow, 0.5)
	local bolts = {}
	local function clear()
		for _, part in bolts do pcall(function() part:Destroy() end) end
		table.clear(bolts)
	end
	local function refresh()
		clear()
		for _ = 1, 7 do
			local offset = environment.Vector3.new(math.random() - 0.5, math.random() - 0.4, math.random() - 0.5).Unit * (4 + math.random() * 4)
			local parts = GameEffects.Kill.lightning(state, center, center + offset, red, 0.2, 0.9, 6, black)
			for _, part in parts do table.insert(bolts, part) end
		end
	end
	refresh()
	GameEffects.Kill.delay(state, 0.06, refresh)
	GameEffects.Kill.delay(state, 0.13, refresh)
	GameEffects.Kill.delay(state, 0.22, clear)
	GameEffects.Kill.sparks(state, center, red, 40, 45, state.textures.spark)
	local up = math.abs(direction.Y) < 0.95 and environment.Vector3.new(0, 1, 0) or environment.Vector3.new(1, 0, 0)
	for index = 1, 3 do
		GameEffects.Kill.delay(state, (index - 1) * 0.05, function()
			local frame = environment.CFrame.fromMatrix(center + direction * (index - 1) * 1.2, direction:Cross(up).Unit, direction)
			local ring = GameEffects.Kill.disc(state, frame, 0.5, index == 2 and black or red, environment.Enum.Material.Neon, 0.2)
			GameEffects.Kill.tween(state, ring, 0.3, {Size = environment.Vector3.new(0.04, 9 - index, 9 - index), Transparency = 1}, environment.Enum.EasingStyle.Quad)
			GameEffects.Kill.destroyLater(state, ring, 0.35)
		end)
	end
	GameEffects.Kill.delay(state, 0.05, function()
		if not body then return end
		body.release(direction * 75 + environment.Vector3.new(0, 20, 0), nil)
		pcall(function() body.torso.AssemblyAngularVelocity = GameEffects.Kill.randomVector(state, 10) end)
		local highlight = GameEffects.Kill.highlight(state, body.model, black, red, 0.2, 0)
		environment.task.spawn(function()
			for index = 1, 8 do
				if not highlight.Parent then return end
				highlight.FillColor = index % 2 == 0 and red or black
				environment.task.wait(0.06 / state.speed)
			end
			if highlight.Parent then GameEffects.Kill.tween(state, highlight, 0.4, {FillTransparency = 1, OutlineTransparency = 1}) end
		end)
	end)
	local anchor = GameEffects.Kill.effectAttachment(state, center)
	GameEffects.Kill.light(state, anchor, red, 12, 30, 0.5)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.punch, 1, 1.3)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.bone1, 1, 0.6)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.boomDeep, 0.6, 1.5)
	GameEffects.Kill.shakeCamera(state, center, 2, 0.4)
end

function GameEffects.Kill.cubeCorners(state, frame, size)
	local environment = state.context.environment
	local half, corners = size / 2, {}
	for index = 0, 7 do
		local x = index % 2 == 1 and half or -half
		local y = math.floor(index / 2) % 2 == 1 and half or -half
		local z = math.floor(index / 4) % 2 == 1 and half or -half
		table.insert(corners, frame * environment.Vector3.new(x, y, z))
	end
	return corners
end

function GameEffects.Kill.updateSegment(state, part, start, finish, width)
	local environment = state.context.environment
	local offset = finish - start
	local length = offset.Magnitude
	if length < 0.01 then part.Transparency = 1; return end
	local up = math.abs(offset.Unit.Y) > 0.98 and environment.Vector3.new(1, 0, 0) or environment.Vector3.new(0, 1, 0)
	part.Size, part.CFrame = environment.Vector3.new(width, width, length), environment.CFrame.lookAt((start + finish) / 2, finish, up)
end

function GameEffects.Kill.tesseract(state, effect)
	local environment = state.context.environment
	local color, white = environment.Color3.fromRGB(80, 230, 255), environment.Color3.new(1, 1, 1)
	local body = GameEffects.Kill.staticBody(state, effect)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local center, segments = effect.chest, {}
	for index = 1, 32 do
		local part = environment.Instance.new("Part")
		part.Anchored, part.CanCollide, part.CanQuery, part.CanTouch, part.CastShadow = true, false, false, false, false
		part.Material, part.Color, part.Transparency = environment.Enum.Material.Neon, index > 24 and environment.Color3.fromRGB(170, 120, 255) or color, index > 24 and 0.35 or 0
		part.Size, part.Parent = environment.Vector3.new(0.1, 0.1, 0.1), GameEffects.Kill.folder(state)
		table.insert(segments, part)
	end
	local edges = {{1, 2}, {2, 4}, {4, 3}, {3, 1}, {5, 6}, {6, 8}, {8, 7}, {7, 5}, {1, 5}, {2, 6}, {3, 7}, {4, 8}}
	local frames = {}
	for index, part in body do frames[index] = {frame = part.CFrame, size = part.Size} end
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
	GameEffects.Kill.animate(state, 1.1, function(progress)
		local eased, size = progress * progress, 6.5 * (1 - 0.92 * progress * progress)
		local outer = GameEffects.Kill.cubeCorners(state, environment.CFrame.new(center) * environment.CFrame.Angles(progress * 2.5, progress * 4, progress * 1.5), size)
		local inner = GameEffects.Kill.cubeCorners(state, environment.CFrame.new(center) * environment.CFrame.Angles(-progress * 3, -progress * 5, progress * 2), size * 0.5)
		for index, edge in edges do
			GameEffects.Kill.updateSegment(state, segments[index], outer[edge[1]], outer[edge[2]], 0.14)
			GameEffects.Kill.updateSegment(state, segments[12 + index], inner[edge[1]], inner[edge[2]], 0.1)
		end
		for index = 1, 8 do GameEffects.Kill.updateSegment(state, segments[24 + index], outer[index], inner[index], 0.06) end
		for index, part in body do
			if not part.Parent then continue end
			local original = frames[index]
			part.CFrame = environment.CFrame.new(center + (original.frame.Position - center) * (1 - eased)) * original.frame.Rotation * environment.CFrame.Angles(eased * 3, eased * 2, 0)
			part.Size = original.size * (1 - 0.8 * eased)
		end
	end, function()
		for _, group in {segments, body} do for _, part in group do pcall(function() part:Destroy() end) end end
		GameEffects.Kill.flash(state, center, color, 10, 5)
		local _, attachment = GameEffects.Kill.effectAttachment(state, center)
		GameEffects.Kill.particle(state, attachment, {Texture = state.textures.square, Color = colors(white, color), Size = sequence(0, 0.35, 1, 0),
			Lifetime = environment.NumberRange.new(0.5, 0.9), Speed = environment.NumberRange.new(10, 22), SpreadAngle = environment.Vector2.new(180, 180),
			Drag = 3, Rotation = environment.NumberRange.new(0, 90), Brightness = 5}, 50)
		GameEffects.Kill.particle(state, attachment, {Texture = state.textures.ring, Color = colors(color), Size = sequence(0, 1, 1, 12),
			Transparency = sequence(0, 0, 1, 1), Lifetime = environment.NumberRange.new(0.45), Brightness = 5}, 1)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.synthSpark, 0.7, 1.6)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.sciSynth, 0.7, 0.8, nil, 0.8)
		GameEffects.Kill.shakeCamera(state, center, 0.7, 0.25)
	end)
	local anchor = GameEffects.Kill.effectAttachment(state, center)
	GameEffects.Kill.light(state, anchor, color, 5, 14, 1.2)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.powerUp, 0.6, 1.3, nil, 1.1)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.servo, 0.4, 1.2)
end

function GameEffects.Kill.nuke(state, effect)
	local environment = state.context.environment
	local white = environment.Color3.new(1, 1, 1)
	local ground = GameEffects.Kill.ground(state, effect.root, effect.ignore)
	local height = ground and ground.Y or effect.root.Y - 3
	local position = environment.Vector3.new(effect.root.X, height, effect.root.Z)
	local body = GameEffects.Kill.ghost(state, effect.char, {material = environment.Enum.Material.Neon, color = white, transparency = 0})
	GameEffects.Kill.hideEffectBody(state, effect.char)
	for _, part in body do GameEffects.Kill.tween(state, part, 0.25, {Color = environment.Color3.fromRGB(30, 20, 15)}) end
	GameEffects.Kill.delay(state, 0.25, function()
		GameEffects.Kill.fadeGhost(state, body, 0.3, function(part) return {CFrame = part.CFrame + environment.Vector3.new(0, 1, 0)} end)
	end)
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(position + environment.Vector3.new(0, 2, 0)), environment.Vector3.new(1, 1, 1))
	GameEffects.Kill.light(state, anchor, environment.Color3.fromRGB(255, 235, 200), 20, 60, 1.4)
	local attachment = environment.Instance.new("Attachment")
	attachment.Parent = anchor
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
	GameEffects.Kill.particle(state, attachment, {Texture = state.textures.core, Color = colors(white, environment.Color3.fromRGB(255, 220, 150)),
		Size = sequence(0, 4, 1, 30), Transparency = sequence(0, 0, 1, 1), Lifetime = environment.NumberRange.new(0.4), Rotation = environment.NumberRange.new(0, 360), Brightness = 8, ZOffset = 2}, 2)
	local fire = environment.Instance.new("Part")
	fire.Shape, fire.Anchored, fire.CanCollide, fire.CanQuery, fire.CanTouch, fire.CastShadow = environment.Enum.PartType.Ball, true, false, false, false, false
	local bright, dark = environment.Color3.fromRGB(255, 210, 110), environment.Color3.fromRGB(150, 50, 15)
	fire.Material, fire.Color, fire.Size, fire.CFrame = environment.Enum.Material.Neon, bright, environment.Vector3.new(1, 1, 1), environment.CFrame.new(position + environment.Vector3.new(0, 2, 0))
	fire.Parent = GameEffects.Kill.folder(state)
	local cloud = GameEffects.Kill.anchor(state, environment.CFrame.new(position + environment.Vector3.new(0, 2, 0)), environment.Vector3.new(4, 3, 4))
	local cloudEmitter = GameEffects.Kill.particle(state, cloud, {Texture = state.textures.fsmoke, Color = colors(environment.Color3.fromRGB(200, 110, 50), environment.Color3.fromRGB(60, 40, 35)),
		Size = sequence(0, 4, 1, 10), Transparency = sequence(0, 0.2, 1, 1), Lifetime = environment.NumberRange.new(1.4, 2.2), Speed = environment.NumberRange.new(3, 7),
		SpreadAngle = environment.Vector2.new(180, 60), Rotation = environment.NumberRange.new(0, 360), RotSpeed = environment.NumberRange.new(-30, 30),
		Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0.25, LightInfluence = 0.6, Brightness = 1.3}, 0)
	cloudEmitter.Rate, cloudEmitter.Enabled = 45, true
	local column = GameEffects.Kill.anchor(state, environment.CFrame.new(position + environment.Vector3.new(0, 5, 0)), environment.Vector3.new(2.2, 10, 2.2))
	local columnEmitter = GameEffects.Kill.particle(state, column, {Texture = state.textures.fsmoke, Color = colors(environment.Color3.fromRGB(150, 110, 90), environment.Color3.fromRGB(60, 50, 45)),
		Size = sequence(0, 2.5, 1, 5), Transparency = sequence(0, 0.3, 1, 1), Lifetime = environment.NumberRange.new(1, 1.6), Speed = environment.NumberRange.new(4, 8),
		SpreadAngle = environment.Vector2.new(10, 10), Rotation = environment.NumberRange.new(0, 360), Shape = environment.Enum.ParticleEmitterShape.Box,
		LightEmission = 0.1, LightInfluence = 0.8, Brightness = 1.1}, 0)
	columnEmitter.Rate, columnEmitter.Enabled = 55, true
	GameEffects.Kill.animate(state, 1.6, function(progress)
		local eased = 1 - (1 - progress) ^ 2
		local center = position + environment.Vector3.new(0, 2 + 11 * eased, 0)
		fire.CFrame, cloud.CFrame = environment.CFrame.new(center), environment.CFrame.new(center)
		fire.Size = environment.Vector3.new(1 + 6.5 * eased, 1 + 5.5 * eased, 1 + 6.5 * eased)
		fire.Color, fire.Transparency = bright:Lerp(dark, progress), progress > 0.7 and (progress - 0.7) / 0.3 or 0
	end, function()
		cloudEmitter.Enabled, columnEmitter.Enabled = false, false
		pcall(function() fire:Destroy() end)
		GameEffects.Kill.destroyLater(state, cloud, 2.5)
		GameEffects.Kill.destroyLater(state, column, 2)
	end)
	GameEffects.Kill.ringAtGround(state, effect.root, white, 2, 45, 0.8, state.textures.ringEdge, effect.ignore)
	GameEffects.Kill.delay(state, 0.25, function()
		local ringAnchor = GameEffects.Kill.anchor(state, environment.CFrame.new(position + environment.Vector3.new(0, 7, 0)), environment.Vector3.new(0.4, 0.4, 0.4))
		local ringAttachment = environment.Instance.new("Attachment")
		ringAttachment.Parent = ringAnchor
		GameEffects.Kill.groundRing(state, ringAttachment, state.textures.ring, white, 2, 28, 0.7, 2)
		GameEffects.Kill.destroyLater(state, ringAnchor, 1.5)
	end)
	local smoke = GameEffects.Kill.anchor(state, environment.CFrame.new(position + environment.Vector3.new(0, 0.5, 0)), environment.Vector3.new(14, 1, 14))
	GameEffects.Kill.particle(state, smoke, {Texture = state.textures.smokeFB, FlipbookLayout = environment.Enum.ParticleFlipbookLayout.Grid4x4,
		FlipbookMode = environment.Enum.ParticleFlipbookMode.OneShot, Color = colors(environment.Color3.fromRGB(170, 160, 150)),
		Size = sequence(0, 3, 1, 7), Transparency = sequence(0, 0.25, 0.7, 0.45, 1, 1), Lifetime = environment.NumberRange.new(1.2, 1.8),
		Speed = environment.NumberRange.new(8, 16), SpreadAngle = environment.Vector2.new(85, 85), Drag = 2, Rotation = environment.NumberRange.new(0, 360),
		Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0, LightInfluence = 1, Brightness = 1}, 30)
	GameEffects.Kill.destroyLater(state, smoke, 3)
	GameEffects.Kill.fragments(state, position + environment.Vector3.new(0, 1, 0), 16, environment.Color3.fromRGB(90, 85, 80), environment.Enum.Material.Slate, 0.5, 30, 1.8)
	GameEffects.Kill.splat(state, effect.root, 14, environment.Color3.fromRGB(20, 16, 14), 3, effect.ignore, 0.2, state.textures.burn, 2)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.quake, 1, 0.55, anchor, 3)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.artillery, 0.9, 0.5, anchor, 3)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.quakeRumble, 0.7, 0.6, anchor, 2.5)
	GameEffects.Kill.shakeCamera(state, position, 2.6, 0.9)
	GameEffects.Kill.destroyLater(state, anchor, 2)
end

function GameEffects.Kill.shadowClones(state, effect)
	local environment = state.context.environment
	local color = environment.Color3.fromRGB(150, 60, 255)
	local body = GameEffects.Kill.body(state, effect, environment.Vector3.new(0, 0, 0), nil, 3.4, nil, true)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local source = effect.killer and effect.killer.Parent
	if not source or not source:IsA("Model") or not source:FindFirstChildOfClass("Humanoid") then source = effect.char end
	local root = source:FindFirstChild("HumanoidRootPart") or source:FindFirstChild("UpperTorso")
	local center, clones, angle = effect.chest, {}, math.random() * 6.28
	for index = 1, 5 do
		local parts = GameEffects.Kill.ghost(state, source, {material = environment.Enum.Material.SmoothPlastic, color = environment.Color3.fromRGB(16, 10, 26), transparency = 1})
		local rootFrame = root and root.CFrame or environment.CFrame.new(center)
		local offsets = {}
		for partIndex, part in parts do offsets[partIndex] = rootFrame:Inverse() * part.CFrame end
		local phase = angle + (index - 1) * 1.2566
		local position = environment.Vector3.new(center.X + math.cos(phase) * 7, effect.root.Y, center.Z + math.sin(phase) * 7)
		local clone = {parts = parts, offsets = offsets, position = position}
		table.insert(clones, clone)
		local frame = environment.CFrame.lookAt(position, environment.Vector3.new(center.X, position.Y, center.Z))
		local targets = {}
		for partIndex, offset in offsets do targets[partIndex] = frame * offset end
		GameEffects.Kill.moveParts(state, parts, targets)
		GameEffects.Kill.delay(state, index * 0.05, function()
			for _, part in parts do GameEffects.Kill.tween(state, part, 0.2, {Transparency = 0.15}) end
			GameEffects.Kill.smoke(state, position - environment.Vector3.new(0, 2.5, 0), environment.Color3.fromRGB(40, 20, 60), 4, 3, 2)
		end)
	end
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.magicZoom, 0.8, 0.6)
	for index, clone in clones do
		GameEffects.Kill.delay(state, 0.4 + (index - 1) * 0.11, function()
			local start = clone.position
			local finish = environment.Vector3.new(2 * center.X - start.X, start.Y, 2 * center.Z - start.Z)
			local beam = GameEffects.Kill.beam(state, start + environment.Vector3.new(0, 1, 0), finish + environment.Vector3.new(0, 1, 0), 0.25, color, environment.Enum.Material.Neon, 0.3)
			GameEffects.Kill.tween(state, beam, 0.35, {Transparency = 1, Size = environment.Vector3.new(0.02, 0.02, beam.Size.Z)})
			GameEffects.Kill.destroyLater(state, beam, 0.4)
			GameEffects.Kill.animate(state, 0.1, function(progress)
				local position = start:Lerp(finish, progress)
				local frame = environment.CFrame.lookAt(position, position + (finish - start))
				local targets = {}
				for partIndex, offset in clone.offsets do targets[partIndex] = frame * offset end
				GameEffects.Kill.moveParts(state, clone.parts, targets)
			end, function()
				for _, part in clone.parts do
					GameEffects.Kill.tween(state, part, 0.25, {Transparency = 1})
					GameEffects.Kill.destroyLater(state, part, 0.3)
				end
				GameEffects.Kill.smoke(state, finish - environment.Vector3.new(0, 2.5, 0), environment.Color3.fromRGB(40, 20, 60), 4, 3, 2)
			end)
			GameEffects.Kill.arc(state, center + environment.Vector3.new(0, (index - 3) * 0.3, 0), math.random(0, 180), 3.2, 1, color, 0.6, 0.05, 0.08, math.random(-30, 30))
			GameEffects.Kill.sparks(state, center, color, 10, 20, state.textures.spark)
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.whooshQuick, 0.7, 1 + index * 0.1)
		end)
	end
	GameEffects.Kill.delay(state, 1, function()
		if body then
			body.release(environment.Vector3.new(0, 45, 0), nil)
			pcall(function() body.torso.AssemblyAngularVelocity = GameEffects.Kill.randomVector(state, 10) end)
		end
		GameEffects.Kill.flash(state, center, color, 12, 5)
		GameEffects.Kill.ringAtGround(state, effect.root, color, 2, 16, 0.5, nil, effect.ignore)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.fleshSlash, 0.9, 0.8)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.punch, 0.6, 1.2)
		GameEffects.Kill.shakeCamera(state, center, 1, 0.3)
		GameEffects.Kill.delay(state, 1.2, function()
			local position = body and body.torso and body.torso.Parent and body.torso.Position or effect.root
			GameEffects.Kill.splat(state, position, 4, environment.Color3.fromRGB(125, 0, 12), 2.4, effect.ignore, 1)
		end)
	end)
end

function GameEffects.Kill.orbital(state, effect)
	local environment = state.context.environment
	local blue, red, white = environment.Color3.fromRGB(90, 210, 255), environment.Color3.fromRGB(255, 50, 60), environment.Color3.new(1, 1, 1)
	local ground = GameEffects.Kill.ground(state, effect.root, effect.ignore)
	local height = ground and ground.Y or effect.root.Y - 3
	local base = environment.Vector3.new(effect.root.X, height, effect.root.Z)
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(base + environment.Vector3.new(0, 0.15, 0)), environment.Vector3.new(3, 0.3, 3))
	local attachment = environment.Instance.new("Attachment")
	attachment.Parent = anchor
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
	for _, data in {{state.textures.dial, 9, 3, 260}, {state.textures.reticle, 5, 2, -180}} do
		GameEffects.Kill.particle(state, attachment, {Texture = data[1], Color = colors(red), Size = sequence(0, data[2], 1, data[3]),
			Transparency = sequence(0, 0.2, 0.8, 0, 1, 1), Lifetime = environment.NumberRange.new(0.4), Speed = environment.NumberRange.new(0.01),
			EmissionDirection = environment.Enum.NormalId.Top, Orientation = environment.Enum.ParticleOrientation.VelocityPerpendicular,
			RotSpeed = environment.NumberRange.new(data[4]), Brightness = 4}, 1)
	end
	local body = GameEffects.Kill.staticBody(state, effect)
	local glow = GameEffects.Kill.ghost(state, effect.char, {material = environment.Enum.Material.Neon, color = environment.Color3.fromRGB(200, 240, 255), transparency = 1})
	GameEffects.Kill.hideEffectBody(state, effect.char)
	for index = 0, 2 do
		GameEffects.Kill.delay(state, index * 0.11, function() GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.beep, 0.5, 1.5, anchor) end)
	end
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.charge, 0.7, 1.3, anchor)
	GameEffects.Kill.delay(state, 0.36, function()
		if not state.alive then return end
		for _, part in body do pcall(function() part:Destroy() end) end
		for _, part in glow do
			part.Transparency = 0
			GameEffects.Kill.tween(state, part, 0.35, {CFrame = part.CFrame + environment.Vector3.new(0, 2.5, 0), Transparency = 1, Size = part.Size * 0.4},
				environment.Enum.EasingStyle.Quad, environment.Enum.EasingDirection.In)
			GameEffects.Kill.destroyLater(state, part, 0.4)
		end
		local beam = environment.Instance.new("Part")
		beam.Shape, beam.Anchored, beam.CanCollide, beam.CanQuery, beam.CanTouch, beam.CastShadow = environment.Enum.PartType.Cylinder, true, false, false, false, false
		beam.Material, beam.Color, beam.Size = environment.Enum.Material.Neon, white, environment.Vector3.new(160, 0.2, 0.2)
		beam.CFrame = environment.CFrame.new(base + environment.Vector3.new(0, 80, 0)) * environment.CFrame.Angles(0, 0, math.pi / 2)
		beam.Parent = GameEffects.Kill.folder(state)
		local outer = beam:Clone()
		outer.Color, outer.Transparency, outer.Size, outer.Parent = blue, 0.55, environment.Vector3.new(160, 0.4, 0.4), GameEffects.Kill.folder(state)
		GameEffects.Kill.tween(state, beam, 0.08, {Size = environment.Vector3.new(160, 2.6, 2.6)}, environment.Enum.EasingStyle.Quad)
		GameEffects.Kill.tween(state, outer, 0.1, {Size = environment.Vector3.new(160, 5.5, 5.5)}, environment.Enum.EasingStyle.Quad)
		GameEffects.Kill.delay(state, 0.42, function()
			if beam.Parent then GameEffects.Kill.tween(state, beam, 0.3, {Size = environment.Vector3.new(160, 0.05, 0.05), Transparency = 1}, environment.Enum.EasingStyle.Quad, environment.Enum.EasingDirection.In) end
			if outer.Parent then GameEffects.Kill.tween(state, outer, 0.35, {Size = environment.Vector3.new(160, 0.1, 0.1), Transparency = 1}, environment.Enum.EasingStyle.Quad, environment.Enum.EasingDirection.In) end
		end)
		GameEffects.Kill.destroyLater(state, beam, 0.9)
		GameEffects.Kill.destroyLater(state, outer, 0.9)
		GameEffects.Kill.particle(state, attachment, {Texture = state.textures.core, Color = colors(white, blue), Size = sequence(0, 3, 1, 14),
			Transparency = sequence(0, 0, 1, 1), Lifetime = environment.NumberRange.new(0.45), Rotation = environment.NumberRange.new(0, 360), Brightness = 5, ZOffset = 1}, 2)
		GameEffects.Kill.groundRing(state, attachment, state.textures.ringEdge, blue, 3, 26, 0.7, 4)
		GameEffects.Kill.groundRing(state, attachment, state.textures.ring, white, 2, 16, 0.4, 5)
		GameEffects.Kill.particle(state, attachment, {Texture = state.textures.fsparks, Color = colors(white, blue), Size = sequence(0, 0.6, 1, 0),
			Lifetime = environment.NumberRange.new(0.5, 0.9), Speed = environment.NumberRange.new(25, 45), SpreadAngle = environment.Vector2.new(75, 75),
			Drag = 2, Acceleration = environment.Vector3.new(0, -45, 0), Orientation = environment.Enum.ParticleOrientation.VelocityParallel, Brightness = 5}, 45)
		GameEffects.Kill.particle(state, attachment, {Texture = state.textures.rock, Color = colors(environment.Color3.fromRGB(70, 66, 62)),
			Size = sequence(0, 0.6, 1, 0.35), Lifetime = environment.NumberRange.new(0.6, 1), Speed = environment.NumberRange.new(14, 24),
			SpreadAngle = environment.Vector2.new(40, 40), Acceleration = environment.Vector3.new(0, -60, 0), Rotation = environment.NumberRange.new(0, 360),
			RotSpeed = environment.NumberRange.new(-300, 300), LightEmission = 0, LightInfluence = 1, Brightness = 1}, 22)
		GameEffects.Kill.particle(state, anchor, {Texture = state.textures.fsmoke, Color = colors(environment.Color3.fromRGB(150, 160, 170), environment.Color3.fromRGB(60, 64, 70)),
			Size = sequence(0, 3, 1, 8), Transparency = sequence(0, 0.3, 1, 1), Lifetime = environment.NumberRange.new(1.2, 1.8), Speed = environment.NumberRange.new(3, 6),
			SpreadAngle = environment.Vector2.new(60, 60), Acceleration = environment.Vector3.new(0, 3, 0), Rotation = environment.NumberRange.new(0, 360),
			RotSpeed = environment.NumberRange.new(-40, 40), Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0, LightInfluence = 1, Brightness = 1}, 12, 0.15)
		GameEffects.Kill.splat(state, effect.root, 7.5, environment.Color3.fromRGB(255, 120, 40), 0.9, effect.ignore, 0.12, state.textures.ringEdge, 1)
		GameEffects.Kill.splat(state, effect.root, 7, environment.Color3.fromRGB(18, 16, 16), 2.6, effect.ignore, 0.12, state.textures.burn, 2)
		GameEffects.Kill.light(state, anchor, blue, 14, 50, 0.8)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.boom2, 1, 1, anchor)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.boomDeep, 0.7, 0.8, anchor)
		GameEffects.Kill.shakeCamera(state, base, 2.2, 0.55)
	end)
	GameEffects.Kill.destroyLater(state, anchor, 4.5)
end

function GameEffects.Kill.laser(state, effect)
	local environment = state.context.environment
	local color, white = environment.Color3.fromRGB(255, 30, 60), environment.Color3.new(1, 1, 1)
	local body = GameEffects.Kill.staticBody(state, effect)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local direction, right = GameEffects.Kill.cameraDirection(state)
	local ground = GameEffects.Kill.ground(state, effect.root, effect.ignore)
	local height = ground and ground.Y or effect.root.Y - 3
	local top = effect.head.Y + 0.8
	local cuts = {height + (top - height) * 0.28, height + (top - height) * 0.52, height + (top - height) * 0.76}
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.chest), environment.Vector3.new(0.3, 0.3, 0.3))
	local emitter = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.spark, Color = environment.ColorSequence.new(white, color),
		Size = GameEffects.Kill.numberSequence(state, 0, 0.5, 1, 0), Lifetime = environment.NumberRange.new(0.15, 0.3), Speed = environment.NumberRange.new(8, 16),
		SpreadAngle = environment.Vector2.new(180, 180), Drag = 5, Orientation = environment.Enum.ParticleOrientation.VelocityParallel, Brightness = 5}, 0)
	for index, y in cuts do
		local side = index % 2 == 0 and -1 or 1
		GameEffects.Kill.delay(state, (index - 1) * 0.13, function()
			local origin = environment.Vector3.new(0, 0, 0)
			local core = GameEffects.Kill.beam(state, origin, direction * 14, 0.07, white)
			local glow = GameEffects.Kill.beam(state, origin, direction * 14, 0.3, color, environment.Enum.Material.Neon, 0.45)
			GameEffects.Kill.animate(state, 0.14, function(progress)
				local position = environment.Vector3.new(effect.root.X, y, effect.root.Z) + right * (-3.5 + 7 * progress) * side
				core.CFrame = environment.CFrame.lookAt(position, position + direction)
				glow.CFrame, anchor.CFrame = core.CFrame, environment.CFrame.new(position)
				if math.abs(progress - 0.5) < 0.3 then emitter:Emit(3) end
			end, function()
				for _, beam in {core, glow} do
					GameEffects.Kill.tween(state, beam, 0.12, {Transparency = 1, Size = environment.Vector3.new(0.01, 0.01, beam.Size.Z)})
					GameEffects.Kill.destroyLater(state, beam, 0.15)
				end
			end)
			local ring = GameEffects.Kill.disc(state, environment.CFrame.new(effect.root.X, y, effect.root.Z), 2.6, color, environment.Enum.Material.Neon, 0.4)
			GameEffects.Kill.tween(state, ring, 0.7, {Transparency = 1, Size = environment.Vector3.new(0.04, 3.2, 3.2)}, environment.Enum.EasingStyle.Quad)
			GameEffects.Kill.destroyLater(state, ring, 0.75)
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.laser1, 0.6, 2 + index * 0.15, anchor)
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.laser2, 0.3, 2)
		end)
	end
	GameEffects.Kill.delay(state, 0.48, function()
		local levels, shifts, axes = {height, cuts[1], cuts[2], cuts[3]}, {0, 0.5, -0.8, 1.2}, {}
		for index = 1, 4 do axes[index] = environment.Vector3.new(math.random() - 0.5, 0, math.random() - 0.5).Unit end
		for _, part in body do
			if not part.Parent then continue end
			local section = 1
			for index, y in cuts do if part.Position.Y > y then section = index + 1 end end
			local shift = right * shifts[section]
			local fall = levels[section] - height
			local pivot = environment.Vector3.new(effect.root.X, levels[section], effect.root.Z)
			GameEffects.Kill.tween(state, part, 0.16, {CFrame = part.CFrame + shift}, environment.Enum.EasingStyle.Quad)
			GameEffects.Kill.delay(state, 0.2, function()
				if not part.Parent then return end
				local rotation = environment.CFrame.new(pivot + shift) * environment.CFrame.fromAxisAngle(axes[section], 0.5 + section * 0.15) * environment.CFrame.new(-(pivot + shift))
				GameEffects.Kill.tween(state, part, 0.45, {CFrame = rotation * part.CFrame - environment.Vector3.new(0, fall * 0.9, 0)},
					environment.Enum.EasingStyle.Quad, environment.Enum.EasingDirection.In)
			end)
		end
		GameEffects.Kill.delay(state, 0.9, function() GameEffects.Kill.fadeGhost(state, body, 0.4) end)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.sear, 0.5, 1.4, anchor)
	end)
	GameEffects.Kill.light(state, anchor, color, 5, 12, 1)
	GameEffects.Kill.destroyLater(state, anchor, 2.5)
end

function GameEffects.Kill.voidRift(state, effect)
	local environment = state.context.environment
	local color, white = environment.Color3.fromRGB(170, 70, 255), environment.Color3.new(1, 1, 1)
	local direction = GameEffects.Kill.cameraDirection(state)
	local center = effect.chest + direction * 2.4
	local body = GameEffects.Kill.body(state, effect, environment.Vector3.new(0, 0, 0), nil, 3.4, nil, true)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local roll = math.random(-20, 20)
	local frame = environment.CFrame.lookAt(center, center - direction) * environment.CFrame.Angles(0, 0, math.rad(roll))
	local parts = {}
	for index = 1, 3 do
		local part = environment.Instance.new("Part")
		part.Anchored, part.CanCollide, part.CanQuery, part.CanTouch, part.CastShadow = true, false, false, false, false
		part.Material, part.Color, part.Transparency = environment.Enum.Material.Neon, index == 1 and environment.Color3.new(0, 0, 0) or color, 0
		part.Size, part.CFrame, part.Parent = environment.Vector3.new(0.05, 7, 0.1), frame, GameEffects.Kill.folder(state)
		table.insert(parts, part)
	end
	local function resize(width)
		parts[1].Size = environment.Vector3.new(math.max(0.05, width), 7 * math.min(1, 0.3 + width), 0.1)
		parts[2].Size = environment.Vector3.new(0.12, parts[1].Size.Y + 0.2, 0.14)
		parts[3].Size = parts[2].Size
		parts[2].CFrame = frame * environment.CFrame.new(-width / 2, 0, -0.02)
		parts[3].CFrame = frame * environment.CFrame.new(width / 2, 0, -0.02)
	end
	resize(0.05)
	GameEffects.Kill.arc(state, center, 90 + roll, 5, 0.6, color, 0.8, 0.08, 0.1)
	GameEffects.Kill.animate(state, 0.35, function(progress) resize(2.4 * (1 - (1 - progress) ^ 3)) end)
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(center), environment.Vector3.new(10, 10, 10))
	local emitter = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.spark, Color = environment.ColorSequence.new(white, color),
		Size = GameEffects.Kill.numberSequence(state, 0, 0.5, 1, 0.1), Lifetime = environment.NumberRange.new(0.35, 0.5), Speed = environment.NumberRange.new(12, 18),
		Shape = environment.Enum.ParticleEmitterShape.Sphere, ShapeStyle = environment.Enum.ParticleEmitterShapeStyle.Surface,
		ShapeInOut = environment.Enum.ParticleEmitterShapeInOut.Inward, Orientation = environment.Enum.ParticleOrientation.VelocityParallel, Brightness = 4}, 0)
	emitter.Rate, emitter.Enabled = 90, true
	GameEffects.Kill.light(state, anchor, color, 6, 18, 1.8)
	GameEffects.Kill.delay(state, 0.35, function()
		if body then body.release(environment.Vector3.new(0, 2, 0), nil) end
		GameEffects.Kill.animate(state, 0.9, function(progress)
			if not body then return end
			for _, part in body.parts do
				if not part.Parent or part.Transparency >= 1 then continue end
				local offset = center - part.Position
				if offset.Magnitude < 1.3 then
					part.Transparency = 1
					for _, child in part:GetChildren() do if child:IsA("Decal") then child.Transparency = 1 end end
					continue
				end
				if not part.Massless then pcall(function() part.AssemblyLinearVelocity = offset.Unit * (14 + 34 * progress) end) end
			end
		end)
	end)
	GameEffects.Kill.delay(state, 1.3, function()
		emitter.Enabled = false
		GameEffects.Kill.animate(state, 0.15, function(progress) resize(2.4 * (1 - progress)) end, function()
			for _, part in parts do pcall(function() part:Destroy() end) end
			if body then pcall(function() body.model:Destroy() end) end
			GameEffects.Kill.flash(state, center, color, 12, 5)
			GameEffects.Kill.ringAtGround(state, effect.root, color, 2, 14, 0.5, nil, effect.ignore)
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.sonic2, 0.7, 1.4, nil, 1.5)
			GameEffects.Kill.shakeCamera(state, center, 0.8, 0.25)
		end)
	end)
	GameEffects.Kill.destroyLater(state, anchor, 2.2)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.rip, 0.7, 0.6)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.suck, 0.8, 0.7)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.vortexBlast, 0.5, 0.8)
end

function GameEffects.Kill.levitate(state, effect)
	local environment = state.context.environment
	local color, white = environment.Color3.fromRGB(150, 110, 255), environment.Color3.new(1, 1, 1)
	local ground = GameEffects.Kill.ground(state, effect.root, effect.ignore)
	local height = ground and ground.Y or effect.root.Y - 3
	local body = GameEffects.Kill.body(state, effect, environment.Vector3.new(0, 1.5, 0), GameEffects.Kill.randomVector(state, 1.2), 3.4)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local force = GameEffects.Kill.upForce(state, body, 1.03)
	if body and body.torso then GameEffects.Kill.highlight(state, body.model, color, color, 0.75, 0.2) end
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.root.X, height + 0.2, effect.root.Z), environment.Vector3.new(6, 0.4, 6))
	local attachment = environment.Instance.new("Attachment")
	attachment.Parent = anchor
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
	local rocks = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.rock, Color = colors(environment.Color3.fromRGB(100, 94, 88)),
		Size = sequence(0, 0.45, 1, 0.3), Lifetime = environment.NumberRange.new(1.4, 2), Speed = environment.NumberRange.new(1.5, 3),
		SpreadAngle = environment.Vector2.new(15, 15), Acceleration = environment.Vector3.new(0, 1.5, 0), Rotation = environment.NumberRange.new(0, 360),
		RotSpeed = environment.NumberRange.new(-90, 90), Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0, LightInfluence = 1, Brightness = 1}, 6)
	rocks.Rate, rocks.Enabled = 14, true
	local glow = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.soft, Color = colors(color, white), Size = sequence(0, 0.4, 1, 0),
		Lifetime = environment.NumberRange.new(1, 1.6), Speed = environment.NumberRange.new(1.5, 3), SpreadAngle = environment.Vector2.new(20, 20),
		Shape = environment.Enum.ParticleEmitterShape.Box, Brightness = 3}, 0)
	glow.Rate, glow.Enabled = 22, true
	GameEffects.Kill.groundRing(state, attachment, state.textures.ring, color, 2, 8, 1.2, 2.5)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.forceField, 0.5, 0.7, anchor, 1.6)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.magicGlow, 0.3, 1.8, anchor)
	GameEffects.Kill.delay(state, 1.45, function()
		rocks.Enabled, glow.Enabled = false, false
		if force then force:Destroy() end
		if not body or not body.torso or not body.torso.Parent then return end
		for _, part in body.body do pcall(function() part.AssemblyLinearVelocity = environment.Vector3.new(0, -95, 0) end) end
		local landed = false
		local function impact(position)
			if landed then return end
			landed = true
			local burst = GameEffects.Kill.anchor(state, environment.CFrame.new(position.X, height + 0.2, position.Z), environment.Vector3.new(3, 0.4, 3))
			local burstAttachment = environment.Instance.new("Attachment")
			burstAttachment.Parent = burst
			GameEffects.Kill.groundRing(state, burstAttachment, state.textures.ringEdge, color, 2, 16, 0.5, 4)
			GameEffects.Kill.groundRing(state, burstAttachment, state.textures.cracks, color, 5, 6, 1, 3)
			GameEffects.Kill.particle(state, burst, {Texture = state.textures.soft, Color = colors(environment.Color3.fromRGB(150, 145, 140)),
				Size = sequence(0, 1.5, 1, 4.5), Transparency = sequence(0, 0.35, 1, 1), Lifetime = environment.NumberRange.new(0.6, 1),
				Speed = environment.NumberRange.new(8, 14), SpreadAngle = environment.Vector2.new(85, 85), Drag = 4,
				Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0, LightInfluence = 1, Brightness = 1}, 16)
			GameEffects.Kill.particle(state, burst, {Texture = state.textures.rock, Color = colors(environment.Color3.fromRGB(90, 84, 78)),
				Size = sequence(0, 0.45, 1, 0.3), Lifetime = environment.NumberRange.new(0.6, 0.9), Speed = environment.NumberRange.new(10, 18),
				SpreadAngle = environment.Vector2.new(40, 40), Acceleration = environment.Vector3.new(0, -60, 0), Rotation = environment.NumberRange.new(0, 360),
				RotSpeed = environment.NumberRange.new(-300, 300), Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0, LightInfluence = 1, Brightness = 1}, 20)
			GameEffects.Kill.light(state, burst, color, 8, 22, 0.5)
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.quake2, 1, 0.9, burst, 1.5)
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.boom2, 0.5, 0.9, burst)
			GameEffects.Kill.shakeCamera(state, position, 1.2, 0.35)
			GameEffects.Kill.destroyLater(state, burst, 2)
		end
		local position = body.torso.Position
		GameEffects.Kill.animate(state, 0.7, function(progress)
			if not body.torso.Parent then return end
			position = body.torso.Position
			if progress > 0.05 and body.torso.AssemblyLinearVelocity.Y > -25 then impact(position) end
		end, function() impact(position) end)
	end)
	GameEffects.Kill.destroyLater(state, anchor, 3.5)
end

function GameEffects.Kill.matrix(state, effect)
	local environment = state.context.environment
	local green, gold, white = environment.Color3.fromRGB(80, 255, 120), environment.Color3.fromRGB(255, 215, 120), environment.Color3.new(1, 1, 1)
	local fallback, origin = GameEffects.Kill.direction(state, effect)
	if effect.killer and effect.killer.Parent then origin = effect.killer.Position + environment.Vector3.new(0, 0.6, 0) end
	local target = effect.head
	local offset = target - origin
	local direction = offset.Magnitude > 0.5 and offset.Unit or fallback
	local body = GameEffects.Kill.body(state, effect, environment.Vector3.new(0, 0, 0), nil, 3.8, nil, true)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
	local rain = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.chest + environment.Vector3.new(0, 7, 0)), environment.Vector3.new(12, 1, 12))
	local emitter = GameEffects.Kill.particle(state, rain, {Texture = state.textures.square, Color = colors(environment.Color3.fromRGB(190, 255, 200), green),
		Size = sequence(0, 0.16, 1, 0.1), Lifetime = environment.NumberRange.new(0.6, 1), Speed = environment.NumberRange.new(14, 22),
		EmissionDirection = environment.Enum.NormalId.Bottom, Shape = environment.Enum.ParticleEmitterShape.Box, Brightness = 3}, 0)
	emitter.Rate, emitter.Enabled = 140, true
	GameEffects.Kill.delay(state, 1.6, function() if emitter.Parent then emitter.Enabled = false end end)
	GameEffects.Kill.destroyLater(state, rain, 2.8)
	local start = target - direction * 12
	local bullet = environment.Instance.new("Part")
	bullet.Anchored, bullet.CanCollide, bullet.CanQuery, bullet.CanTouch, bullet.CastShadow = true, false, false, false, false
	bullet.Size, bullet.Material, bullet.Color = environment.Vector3.new(0.14, 0.14, 0.45), environment.Enum.Material.Neon, gold
	bullet.CFrame, bullet.Parent = environment.CFrame.lookAt(start, target), GameEffects.Kill.folder(state)
	local nextRing = 0
	GameEffects.Kill.animate(state, 1, function(progress)
		local position = start:Lerp(target, progress)
		bullet.CFrame = environment.CFrame.lookAt(position, position + direction)
		if progress < nextRing then return end
		nextRing = progress + 0.11
		local ring = GameEffects.Kill.disc(state, GameEffects.Kill.bladeFrame(state, position, direction), 0.3, white, environment.Enum.Material.Neon, 0.5)
		GameEffects.Kill.tween(state, ring, 0.5, {Size = environment.Vector3.new(0.03, 2.6, 2.6), Transparency = 1}, environment.Enum.EasingStyle.Quad)
		GameEffects.Kill.destroyLater(state, ring, 0.55)
	end, function()
		pcall(function() bullet:Destroy() end)
		GameEffects.Kill.flash(state, target, gold, 6, 4)
		local _, attachment = GameEffects.Kill.effectAttachment(state, target)
		GameEffects.Kill.particle(state, attachment, {Texture = state.textures.splat, Color = colors(environment.Color3.fromRGB(170, 0, 18), environment.Color3.fromRGB(90, 0, 10)),
			Size = sequence(0, 0.4, 1, 0.15), Lifetime = environment.NumberRange.new(0.8, 1.4), Speed = environment.NumberRange.new(3, 7),
			SpreadAngle = environment.Vector2.new(50, 50), Acceleration = environment.Vector3.new(0, -12, 0), Rotation = environment.NumberRange.new(0, 360),
			RotSpeed = environment.NumberRange.new(-60, 60), LightEmission = 0, Brightness = 1}, 20)
		if body then
			body.release(direction * 22 + environment.Vector3.new(0, 6, 0), function(result)
				if result.head then result.head.AssemblyLinearVelocity = direction * 30 + environment.Vector3.new(0, 6, 0) end
			end)
			local force = GameEffects.Kill.upForce(state, body, 0.85)
			GameEffects.Kill.delay(state, 1.2, function() if force then pcall(function() force:Destroy() end) end end)
		end
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.sniper, 0.9, 0.5)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.snap, 0.8, 0.6)
		GameEffects.Kill.shakeCamera(state, target, 0.6, 0.3)
	end)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.suck, 0.7, 0.35)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.sciSynth, 0.3, 0.6, nil, 0.8)
end

function GameEffects.Kill.thunder(state, effect)
	local environment = state.context.environment
	local color, white = environment.Color3.fromRGB(120, 200, 255), environment.Color3.new(1, 1, 1)
	local ground = GameEffects.Kill.ground(state, effect.root, effect.ignore)
	local height = ground and ground.Y or effect.root.Y - 3
	local base = environment.Vector3.new(effect.root.X, height, effect.root.Z)
	local impact = effect.chest + environment.Vector3.new(0, 0.5, 0)
	local start = base + environment.Vector3.new((math.random() - 0.5) * 10, 80, (math.random() - 0.5) * 10)
	local bolts = {}
	local function refresh(width)
		for _, part in bolts do pcall(function() part:Destroy() end) end
		local points
		bolts, points = GameEffects.Kill.lightning(state, start, impact, color, width, 3.2, 16)
		for _ = 1, 2 do
			local point = points[math.random(4, #points - 4)]
			local destination = point + environment.Vector3.new((math.random() - 0.5) * 16, -(6 + math.random() * 10), (math.random() - 0.5) * 16)
			local parts = GameEffects.Kill.lightning(state, point, destination, color, width * 0.55, 1.6, 6)
			for _, part in parts do table.insert(bolts, part) end
		end
		local parts = GameEffects.Kill.lightning(state, impact, base, color, width, 0.6, 4)
		for _, part in parts do table.insert(bolts, part) end
	end
	refresh(0.32)
	GameEffects.Kill.delay(state, 0.07, function() if state.alive then refresh(0.24) end end)
	GameEffects.Kill.delay(state, 0.15, function() if state.alive then refresh(0.36) end end)
	GameEffects.Kill.delay(state, 0.26, function()
		local old = bolts
		bolts = {}
		for _, part in old do
			if not part.Parent then continue end
			GameEffects.Kill.tween(state, part, 0.25, {Transparency = 1, Size = environment.Vector3.new(0.02, 0.02, part.Size.Z)}, environment.Enum.EasingStyle.Quad)
			GameEffects.Kill.destroyLater(state, part, 0.3)
		end
	end)
	local body = GameEffects.Kill.ghost(state, effect.char, {material = environment.Enum.Material.Neon, color = environment.Color3.fromRGB(210, 240, 255), transparency = 0.1})
	GameEffects.Kill.hideEffectBody(state, effect.char)
	environment.task.spawn(function()
		for index = 1, 6 do
			for _, part in body do if part.Parent then part.Transparency = index % 2 == 0 and 0.1 or 0.75 end end
			environment.task.wait(0.05 / state.speed)
		end
		for _, part in body do if part.Parent then GameEffects.Kill.tween(state, part, 0.3, {Color = environment.Color3.fromRGB(35, 35, 42), Transparency = 0}) end end
		environment.task.wait(0.35 / state.speed)
		GameEffects.Kill.fadeGhost(state, body, 0.6, function(part) return {CFrame = part.CFrame + environment.Vector3.new(0, 0.6, 0)} end)
	end)
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(base + environment.Vector3.new(0, 0.2, 0)), environment.Vector3.new(2, 0.4, 2))
	local attachment = environment.Instance.new("Attachment")
	attachment.Parent = anchor
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
	GameEffects.Kill.particle(state, attachment, {Texture = state.textures.core, Color = colors(white, color), Size = sequence(0, 3, 1, 10),
		Transparency = sequence(0, 0, 1, 1), Lifetime = environment.NumberRange.new(0.3), Rotation = environment.NumberRange.new(0, 360), Brightness = 5, ZOffset = 1}, 2)
	GameEffects.Kill.groundRing(state, attachment, state.textures.ringEdge, color, 2, 18, 0.5, 4)
	GameEffects.Kill.groundRing(state, attachment, state.textures.cracks, color, 5, 6.5, 0.9, 3)
	GameEffects.Kill.particle(state, attachment, {Texture = state.textures.fsparks, Color = colors(white, color), Size = sequence(0, 0.5, 1, 0),
		Lifetime = environment.NumberRange.new(0.4, 0.8), Speed = environment.NumberRange.new(20, 40), SpreadAngle = environment.Vector2.new(70, 70),
		Drag = 2, Acceleration = environment.Vector3.new(0, -50, 0), Orientation = environment.Enum.ParticleOrientation.VelocityParallel, Brightness = 5}, 40)
	GameEffects.Kill.particle(state, attachment, {Texture = state.textures.rock, Color = colors(environment.Color3.fromRGB(60, 60, 66)), Size = sequence(0, 0.45, 1, 0.3),
		Lifetime = environment.NumberRange.new(0.5, 0.9), Speed = environment.NumberRange.new(12, 20), SpreadAngle = environment.Vector2.new(45, 45),
		Acceleration = environment.Vector3.new(0, -60, 0), Rotation = environment.NumberRange.new(0, 360), RotSpeed = environment.NumberRange.new(-300, 300),
		LightEmission = 0, LightInfluence = 1, Brightness = 1}, 16)
	GameEffects.Kill.particle(state, anchor, {Texture = state.textures.fsmoke, Color = colors(environment.Color3.fromRGB(90, 95, 105), environment.Color3.fromRGB(40, 42, 48)),
		Size = sequence(0, 2, 1, 6), Transparency = sequence(0, 0.3, 1, 1), Lifetime = environment.NumberRange.new(1, 1.6), Speed = environment.NumberRange.new(2, 4),
		SpreadAngle = environment.Vector2.new(40, 40), Acceleration = environment.Vector3.new(0, 3, 0), Rotation = environment.NumberRange.new(0, 360),
		RotSpeed = environment.NumberRange.new(-40, 40), LightEmission = 0, LightInfluence = 1, Brightness = 1}, 8, 0.25)
	GameEffects.Kill.splat(state, effect.root, 6, environment.Color3.fromRGB(20, 20, 24), 2.6, effect.ignore, 0.15, state.textures.burn, 2)
	GameEffects.Kill.light(state, anchor, environment.Color3.fromRGB(200, 230, 255), 14, 50, 0.5)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.bolt, 1, 1, anchor)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.boom, 0.45, 1.4, anchor)
	GameEffects.Kill.shakeCamera(state, base, 1.6, 0.45)
	GameEffects.Kill.destroyLater(state, anchor, 3)
end

function GameEffects.Kill.lightning(state, start, finish, color, width, jitter, segments, coreColor)
	local environment = state.context.environment
	local offset = finish - start
	local direction, points = offset.Unit, {start}
	segments = segments or 12
	for index = 1, segments - 1 do
		local progress = index / segments
		local random = environment.Vector3.new(math.random() - 0.5, math.random() - 0.5, math.random() - 0.5) * 2
		random -= direction * random:Dot(direction)
		table.insert(points, start + offset * progress + random * jitter * (0.35 + 0.65 * math.sin(progress * math.pi)))
	end
	table.insert(points, finish)
	local parts = {}
	for index = 1, #points - 1 do
		table.insert(parts, GameEffects.Kill.beam(state, points[index], points[index + 1], width, coreColor or environment.Color3.new(1, 1, 1)))
		table.insert(parts, GameEffects.Kill.beam(state, points[index], points[index + 1], width * 3.2, color, environment.Enum.Material.Neon, 0.72))
	end
	return parts, points
end

function GameEffects.Kill.lightningBlade(state, effect)
	local context, environment = state.context, state.context.environment
	local color, white = environment.Color3.fromRGB(120, 210, 255), environment.Color3.new(1, 1, 1)
	local center = effect.chest
	local body = GameEffects.Kill.body(state, effect, environment.Vector3.new(0, 0, 0), nil, 3.2, nil, true)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	GameEffects.Kill.arc(state, center, math.random(20, 40), 3.8, 1.1, color, 0.9, 0.07, 0.15)
	local camera = context.workspace.CurrentCamera
	local frame = camera and camera.CFrame or environment.CFrame.new()
	local bolts = {}
	local function clear()
		for _, part in bolts do pcall(function() part:Destroy() end) end
		table.clear(bolts)
	end
	local function refresh()
		clear()
		for _ = 1, 4 do
			local start = center + frame.RightVector * (math.random() - 0.5) * 5 + frame.UpVector * (math.random() - 0.5) * 4
			local direction = (frame.RightVector * (math.random() - 0.5) + frame.UpVector * (math.random() - 0.5)).Unit * 2.5
			local parts = GameEffects.Kill.lightning(state, start, start + direction, color, 0.08, 0.5, 5)
			for _, part in parts do table.insert(bolts, part) end
		end
	end
	refresh()
	GameEffects.Kill.delay(state, 0.07, refresh)
	GameEffects.Kill.delay(state, 0.15, refresh)
	GameEffects.Kill.delay(state, 0.24, clear)
	GameEffects.Kill.delay(state, 0.1, function()
		if body then
			body.release(GameEffects.Kill.direction(state, effect) * 40 + environment.Vector3.new(0, 15, 0), nil)
			local highlight = GameEffects.Kill.highlight(state, body.model, color, white, 0.3, 0)
			environment.task.spawn(function()
				for index = 1, 10 do
					if not highlight.Parent then return end
					highlight.FillTransparency = index % 2 == 0 and 0.15 or 0.8
					environment.task.wait(0.06 / state.speed)
				end
				if highlight.Parent then GameEffects.Kill.tween(state, highlight, 0.4, {FillColor = environment.Color3.fromRGB(20, 20, 26), FillTransparency = 0.2, OutlineTransparency = 1}) end
			end)
			local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(center), environment.Vector3.new(1, 1, 1))
			local emitter = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.spark, Color = environment.ColorSequence.new(white, color),
				Size = GameEffects.Kill.numberSequence(state, 0, 0.5, 1, 0), Lifetime = environment.NumberRange.new(0.2, 0.4), Speed = environment.NumberRange.new(4, 10),
				SpreadAngle = environment.Vector2.new(180, 180), Orientation = environment.Enum.ParticleOrientation.VelocityParallel,
				Shape = environment.Enum.ParticleEmitterShape.Box, Brightness = 5}, 0)
			emitter.Rate, emitter.Enabled = 50, true
			GameEffects.Kill.animate(state, 0.9, function()
				if body.torso and body.torso.Parent then anchor.CFrame = body.torso.CFrame end
			end, function() emitter.Enabled = false; GameEffects.Kill.destroyLater(state, anchor, 0.6) end)
		end
		local ground = GameEffects.Kill.ground(state, effect.root, effect.ignore)
		local height = ground and ground.Y or effect.root.Y - 3
		local branches = {}
		for index = 1, 5 do
			local angle = index / 5 * 6.283 + math.random() * 0.5
			local position = environment.Vector3.new(effect.root.X + math.cos(angle) * 4, height, effect.root.Z + math.sin(angle) * 4)
			local parts = GameEffects.Kill.lightning(state, center, position, color, 0.12, 1, 7)
			for _, part in parts do table.insert(branches, part) end
			GameEffects.Kill.sparks(state, position, color, 6, 12, state.textures.spark)
		end
		GameEffects.Kill.delay(state, 0.12, function() for _, part in branches do pcall(function() part:Destroy() end) end end)
		GameEffects.Kill.flash(state, center, color, 10, 5)
	end)
	for index = 1, 14 do
		GameEffects.Kill.delay(state, math.random() * 0.6, function()
			GameEffects.Kill.sound(state, index % 3 == 0 and GameEffects.Kill.soundIds.zap3 or GameEffects.Kill.soundIds.zap1, 0.6, 1.6 + math.random() * 1.6)
		end)
	end
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.whooshQuick, 1, 1.3)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.zap2, 0.8, 1.5)
	GameEffects.Kill.shakeCamera(state, center, 0.8, 0.3)
end

function GameEffects.Kill.railgun(state, effect)
	local environment = state.context.environment
	local color, white = environment.Color3.fromRGB(80, 200, 255), environment.Color3.new(1, 1, 1)
	local fallback, origin = GameEffects.Kill.direction(state, effect)
	if effect.killer and effect.killer.Parent then origin = effect.killer.Position + environment.Vector3.new(0, 0.6, 0) end
	local target = effect.chest
	local offset = target - origin
	local direction = offset.Magnitude > 0.5 and offset.Unit or fallback
	local body = GameEffects.Kill.body(state, effect, environment.Vector3.new(0, 0, 0), nil, 3.4, nil, true)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local start = origin + direction * 1.5
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(start), environment.Vector3.new(4, 4, 4))
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
	local charge = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.spark, Color = colors(white, color),
		Size = sequence(0, 0.5, 1, 0.1), Lifetime = environment.NumberRange.new(0.25, 0.35), Speed = environment.NumberRange.new(10, 14),
		Shape = environment.Enum.ParticleEmitterShape.Sphere, ShapeStyle = environment.Enum.ParticleEmitterShapeStyle.Surface,
		ShapeInOut = environment.Enum.ParticleEmitterShapeInOut.Inward, Orientation = environment.Enum.ParticleOrientation.VelocityParallel, Brightness = 5}, 0)
	charge.Rate, charge.Enabled = 120, true
	local orb = environment.Instance.new("Part")
	orb.Shape, orb.Anchored, orb.CanCollide, orb.CanQuery, orb.CanTouch, orb.CastShadow = environment.Enum.PartType.Ball, true, false, false, false, false
	orb.Material, orb.Color, orb.Size, orb.CFrame = environment.Enum.Material.Neon, color, environment.Vector3.new(0.1, 0.1, 0.1), environment.CFrame.new(start)
	orb.Parent = GameEffects.Kill.folder(state)
	GameEffects.Kill.tween(state, orb, 0.35, {Size = environment.Vector3.new(1.4, 1.4, 1.4)}, environment.Enum.EasingStyle.Quad)
	GameEffects.Kill.light(state, anchor, color, 6, 12, 0.5)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.rise, 0.7, 1.6, anchor)
	GameEffects.Kill.delay(state, 0.35, function()
		charge.Enabled = false
		GameEffects.Kill.destroyLater(state, anchor, 0.5)
		pcall(function() orb:Destroy() end)
		local finish = target + direction * 45
		local beams = {GameEffects.Kill.beam(state, start, finish, 0.3, white), GameEffects.Kill.beam(state, start, finish, 1.2, color, environment.Enum.Material.Neon, 0.45)}
		for _, beam in beams do
			GameEffects.Kill.tween(state, beam, 0.45, {Transparency = 1, Size = environment.Vector3.new(0.02, 0.02, beam.Size.Z)}, environment.Enum.EasingStyle.Quad)
			GameEffects.Kill.destroyLater(state, beam, 0.5)
		end
		for index = 0, math.floor((finish - start).Magnitude / 3) do
			local frame = GameEffects.Kill.bladeFrame(state, start + direction * (index * 3), direction)
			local ring = GameEffects.Kill.disc(state, frame, 0.6, color, environment.Enum.Material.Neon, 0.3)
			GameEffects.Kill.tween(state, ring, 0.35, {Size = environment.Vector3.new(0.04, 3.5, 3.5), Transparency = 1}, environment.Enum.EasingStyle.Quad)
			GameEffects.Kill.destroyLater(state, ring, 0.4)
		end
		GameEffects.Kill.flash(state, target, color, 14, 6)
		GameEffects.Kill.sparks(state, target, color, 40, 50, state.textures.spark)
		if body then
			body.release(direction * 110 + environment.Vector3.new(0, 18, 0), nil)
			pcall(function() body.torso.AssemblyAngularVelocity = GameEffects.Kill.randomVector(state, 8) end)
			local highlight = GameEffects.Kill.highlight(state, body.model, color, white, 0.3, 0)
			GameEffects.Kill.delay(state, 0.6, function()
				if highlight.Parent then GameEffects.Kill.tween(state, highlight, 0.5, {FillTransparency = 1, OutlineTransparency = 1}) end
			end)
			local trail = GameEffects.Kill.anchor(state, environment.CFrame.new(target), environment.Vector3.new(1, 1, 1))
			local emitter = GameEffects.Kill.particle(state, trail, {Texture = state.textures.spark, Color = colors(white, color), Size = sequence(0, 0.6, 1, 0),
				Lifetime = environment.NumberRange.new(0.2, 0.4), Speed = environment.NumberRange.new(2, 6), SpreadAngle = environment.Vector2.new(180, 180),
				Shape = environment.Enum.ParticleEmitterShape.Box, Brightness = 5}, 0)
			emitter.Rate, emitter.Enabled = 60, true
			GameEffects.Kill.animate(state, 0.9, function()
				if body.torso and body.torso.Parent then trail.CFrame = body.torso.CFrame end
			end, function() emitter.Enabled = false; GameEffects.Kill.destroyLater(state, trail, 0.6) end)
		end
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.sniper, 1, 0.7)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.sonic, 0.6, 1.6, nil, 1.4)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.laser3, 0.6, 1.4)
		GameEffects.Kill.shakeCamera(state, target, 1.3, 0.35)
	end)
end

function GameEffects.Kill.starFall(state, effect)
	local environment = state.context.environment
	local gold, white = environment.Color3.fromRGB(255, 225, 120), environment.Color3.new(1, 1, 1)
	local body = GameEffects.Kill.body(state, effect, environment.Vector3.new(0, 0, 0), nil, 3.6, nil, true)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local direction = GameEffects.Kill.cameraDirection(state)
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
	for index = 1, 7 do
		GameEffects.Kill.delay(state, (index - 1) * 0.1, function()
			local target = effect.chest
			if index < 7 then
				local offset = environment.Vector3.new(math.random() * 7 - 3.5, 0, math.random() * 7 - 3.5)
				target = GameEffects.Kill.ground(state, effect.root + offset, effect.ignore) or effect.root - environment.Vector3.new(0, 3, 0)
			end
			local start = target + environment.Vector3.new(math.random() * 8 - 4, 26, 0) - direction * 8
			local star = environment.Instance.new("Part")
			star.Shape, star.Anchored, star.CanCollide, star.CanQuery, star.CanTouch, star.CastShadow = environment.Enum.PartType.Ball, true, false, false, false, false
			star.Material, star.Color, star.Size, star.CFrame = environment.Enum.Material.Neon, gold, environment.Vector3.new(0.7, 0.7, 0.7), environment.CFrame.new(start)
			star.Parent = GameEffects.Kill.folder(state)
			local emitter = GameEffects.Kill.particle(state, star, {Texture = state.textures.star, Color = colors(white, gold), Size = sequence(0, 0.6, 1, 0),
				Lifetime = environment.NumberRange.new(0.3, 0.6), Speed = environment.NumberRange.new(0.2, 1), Rotation = environment.NumberRange.new(0, 360), Brightness = 5}, 0)
			emitter.Rate, emitter.Enabled = 70, true
			GameEffects.Kill.animate(state, 0.28, function(progress) star.CFrame = environment.CFrame.new(start:Lerp(target, progress * progress)) end, function()
				star.Transparency, emitter.Enabled = 1, false
				GameEffects.Kill.destroyLater(state, star, 0.7)
				local _, attachment = GameEffects.Kill.effectAttachment(state, target)
				GameEffects.Kill.particle(state, attachment, {Texture = state.textures.star4, Color = colors(white, gold), Size = sequence(0, 0, 0.3, 2, 1, 0),
					Lifetime = environment.NumberRange.new(0.4, 0.6), Speed = environment.NumberRange.new(6, 12), SpreadAngle = environment.Vector2.new(180, 180),
					Drag = 3, Rotation = environment.NumberRange.new(0, 90), Brightness = 6}, 10)
				GameEffects.Kill.particle(state, attachment, {Texture = state.textures.ring, Color = colors(gold), Size = sequence(0, 0.5, 1, 5),
					Transparency = sequence(0, 0, 1, 1), Lifetime = environment.NumberRange.new(0.3), Brightness = 4}, 1)
				GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.synthSpark, 0.45, 1.5 + index * 0.08)
				if index ~= 7 or not body then return end
				body.release(environment.Vector3.new(0, 65, 0), nil)
				pcall(function() body.torso.AssemblyAngularVelocity = GameEffects.Kill.randomVector(state, 5) end)
				GameEffects.Kill.highlight(state, body.model, gold, white, 0.4, 0)
				GameEffects.Kill.delay(state, 0.33, function()
					if not body.model.Parent then return end
					local positions = {}
					for _, name in {"Head", "UpperTorso", "LowerTorso", "LeftHand", "RightHand", "LeftFoot", "RightFoot"} do
						local part = body.model:FindFirstChild(name)
						if part then positions[name] = part.Position end
					end
					local beams = {}
					for _, pair in {{"Head", "UpperTorso"}, {"UpperTorso", "LowerTorso"}, {"UpperTorso", "LeftHand"}, {"UpperTorso", "RightHand"}, {"LowerTorso", "LeftFoot"}, {"LowerTorso", "RightFoot"}} do
						if positions[pair[1]] and positions[pair[2]] then
							table.insert(beams, GameEffects.Kill.beam(state, positions[pair[1]], positions[pair[2]], 0.07, gold, environment.Enum.Material.Neon, 0.1))
						end
					end
					for _, position in positions do
						local _, sparkle = GameEffects.Kill.effectAttachment(state, position)
						GameEffects.Kill.particle(state, sparkle, {Texture = state.textures.star4, Color = colors(white, gold),
							Size = sequence(0, 0, 0.2, 1.6, 0.8, 1.4, 1, 0), Lifetime = environment.NumberRange.new(1.4), RotSpeed = environment.NumberRange.new(60), Brightness = 6}, 1)
					end
					for _, beam in beams do
						GameEffects.Kill.tween(state, beam, 1.3, {Transparency = 1})
						GameEffects.Kill.destroyLater(state, beam, 1.4)
					end
					pcall(function() body.model:Destroy() end)
					GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.deskBell, 0.6, 1.3)
				end)
			end)
		end)
	end
end

function GameEffects.Kill.cameraDirection(state)
	local context, environment = state.context, state.context.environment
	local camera = context.workspace.CurrentCamera
	local look = camera and camera.CFrame.LookVector or environment.Vector3.new(0, 0, -1)
	local direction = environment.Vector3.new(look.X, 0, look.Z)
	direction = direction.Magnitude > 0.05 and direction.Unit or environment.Vector3.new(0, 0, -1)
	return direction, environment.Vector3.new(-direction.Z, 0, direction.X)
end

function GameEffects.Kill.meteor(state, effect)
	local environment = state.context.environment
	local color = environment.Color3.fromRGB(255, 120, 30)
	local ground = GameEffects.Kill.ground(state, effect.root, effect.ignore)
	local height = ground and ground.Y or effect.root.Y - 3
	local position = environment.Vector3.new(effect.root.X, height, effect.root.Z)
	local start = position + environment.Vector3.new(0, 70, 0) + GameEffects.Kill.cameraDirection(state) * 40
	local body = GameEffects.Kill.body(state, effect, environment.Vector3.new(0, 0, 0), nil, 3.4, nil, true)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local model = environment.Instance.new("Model")
	model.Parent = GameEffects.Kill.folder(state)
	local rock = environment.Instance.new("Part")
	rock.Shape, rock.Anchored, rock.CanCollide, rock.CanQuery, rock.CanTouch = environment.Enum.PartType.Ball, true, false, false, false
	rock.Material, rock.Color, rock.Size, rock.CFrame = environment.Enum.Material.Slate, environment.Color3.fromRGB(45, 32, 28), environment.Vector3.new(3.2, 3.2, 3.2), environment.CFrame.new(start)
	rock.Parent = model
	local highlight = GameEffects.Kill.highlight(state, model, color, environment.Color3.fromRGB(255, 200, 90), 0.55, 0)
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
	local flame = GameEffects.Kill.particle(state, rock, {Texture = state.textures.flame, Color = colors(environment.Color3.fromRGB(255, 220, 120), environment.Color3.fromRGB(220, 50, 10)),
		Size = sequence(0, 3, 1, 0.5), Transparency = sequence(0, 0.2, 1, 1), Lifetime = environment.NumberRange.new(0.3, 0.5), Speed = environment.NumberRange.new(0.5, 2),
		SpreadAngle = environment.Vector2.new(180, 180), Rotation = environment.NumberRange.new(0, 360), Shape = environment.Enum.ParticleEmitterShape.Sphere, Brightness = 3}, 0)
	flame.Rate, flame.Enabled = 110, true
	local smoke = GameEffects.Kill.particle(state, rock, {Texture = state.textures.fsmoke, Color = colors(environment.Color3.fromRGB(70, 60, 55), environment.Color3.fromRGB(30, 28, 26)),
		Size = sequence(0, 2.5, 1, 6), Transparency = sequence(0, 0.3, 1, 1), Lifetime = environment.NumberRange.new(0.8, 1.2),
		Speed = environment.NumberRange.new(0.5, 1.5), SpreadAngle = environment.Vector2.new(180, 180), Rotation = environment.NumberRange.new(0, 360),
		LightEmission = 0, LightInfluence = 1, Brightness = 1}, 0)
	smoke.Rate, smoke.Enabled = 45, true
	local impact = position + environment.Vector3.new(0, 1, 0)
	GameEffects.Kill.animate(state, 0.55, function(progress) rock.CFrame = environment.CFrame.new(start:Lerp(impact, progress ^ 1.6)) end, function()
		flame.Enabled, smoke.Enabled = false, false
		GameEffects.Kill.tween(state, highlight, 1.5, {FillColor = environment.Color3.fromRGB(40, 20, 10), FillTransparency = 0.2, OutlineTransparency = 0.6})
		GameEffects.Kill.delay(state, 2.2, function() if rock.Parent then GameEffects.Kill.tween(state, rock, 0.5, {Transparency = 1}) end end)
		GameEffects.Kill.destroyLater(state, model, 2.8)
		GameEffects.Kill.flash(state, impact, color, 20, 6)
		GameEffects.Kill.sparks(state, impact, color, 40, 40)
		GameEffects.Kill.smoke(state, position, environment.Color3.fromRGB(120, 105, 95), 18, 12, 3)
		GameEffects.Kill.ringAtGround(state, effect.root, color, 2, 30, 0.7, state.textures.ringEdge, effect.ignore)
		GameEffects.Kill.fragments(state, impact, 20, environment.Color3.fromRGB(70, 60, 55), environment.Enum.Material.Slate, 0.5, 30, 1.8)
		GameEffects.Kill.splat(state, effect.root, 11, environment.Color3.fromRGB(22, 16, 14), 3, effect.ignore, 0.15, state.textures.burn, 2)
		GameEffects.Kill.splat(state, effect.root, 9, color, 1.6, effect.ignore, 0.2, state.textures.cracks, 1)
		if body then
			local horizontal = environment.Vector3.new(effect.chest.X - position.X, 0, effect.chest.Z - position.Z)
			local direction = horizontal.Magnitude > 0.1 and horizontal.Unit or GameEffects.Kill.direction(state, effect)
			body.release(direction * 20 + environment.Vector3.new(0, 55, 0), nil)
			pcall(function() body.torso.AssemblyAngularVelocity = GameEffects.Kill.randomVector(state, 10) end)
			local bodyHighlight = GameEffects.Kill.highlight(state, body.model, color, environment.Color3.fromRGB(255, 220, 120), 0.4, 0)
			GameEffects.Kill.delay(state, 0.5, function()
				if bodyHighlight.Parent then GameEffects.Kill.tween(state, bodyHighlight, 0.6, {FillColor = environment.Color3.fromRGB(20, 8, 4), FillTransparency = 0.1, OutlineTransparency = 1}) end
			end)
		end
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.boomDeep, 1, 0.8, rock)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.quakeDebris, 1, 0.7, rock)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.fireball2, 0.8, 0.6, rock)
		GameEffects.Kill.shakeCamera(state, impact, 2.2, 0.6)
	end)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.whoosh, 0.8, 0.6)
end

function GameEffects.Kill.timeStop(state, effect)
	local environment = state.context.environment
	local gold, white = environment.Color3.fromRGB(255, 215, 120), environment.Color3.new(1, 1, 1)
	local direction = GameEffects.Kill.direction(state, effect)
	local body = GameEffects.Kill.body(state, effect, environment.Vector3.new(0, 0, 0), nil, 3.6, nil, true)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local original, gray = {}, {}
	if body then
		for _, part in body.parts do original[part] = part.Transparency end
		gray = GameEffects.Kill.transmute(state, body.parts, environment.Enum.Material.SmoothPlastic, environment.Color3.fromRGB(150, 150, 150), 0.15)
	end
	local _, attachment = GameEffects.Kill.effectAttachment(state, effect.chest)
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(value) return environment.ColorSequence.new(value, value) end
	GameEffects.Kill.particle(state, attachment, {Texture = state.textures.dial, Color = colors(gold), Size = sequence(0, 11, 1, 12),
		Transparency = sequence(0, 1, 0.1, 0.2, 0.85, 0.3, 1, 1), Lifetime = environment.NumberRange.new(1.2), RotSpeed = environment.NumberRange.new(-90), Brightness = 3, ZOffset = -1}, 1)
	GameEffects.Kill.particle(state, attachment, {Texture = state.textures.reticle, Color = colors(white), Size = sequence(0, 6, 1, 6.5),
		Transparency = sequence(0, 1, 0.1, 0.4, 0.85, 0.5, 1, 1), Lifetime = environment.NumberRange.new(1.2), RotSpeed = environment.NumberRange.new(140), Brightness = 3, ZOffset = -1}, 1)
	for index = 0, 3 do
		GameEffects.Kill.delay(state, index * 0.28, function() GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.click, 0.9, index % 2 == 0 and 0.7 or 0.55) end)
	end
	local target, start = effect.head, effect.head - direction * 3
	local bullet = environment.Instance.new("Part")
	bullet.Anchored, bullet.CanCollide, bullet.CanQuery, bullet.CanTouch, bullet.CastShadow = true, false, false, false, false
	bullet.Size, bullet.Material, bullet.Color = environment.Vector3.new(0.14, 0.14, 0.45), environment.Enum.Material.Neon, gold
	bullet.CFrame, bullet.Parent = environment.CFrame.lookAt(start, target), GameEffects.Kill.folder(state)
	local ring = GameEffects.Kill.disc(state, GameEffects.Kill.bladeFrame(state, start, direction), 0.9, gold, environment.Enum.Material.Neon, 0.6)
	GameEffects.Kill.delay(state, 1.15, function()
		for _, part in gray do pcall(function() part:Destroy() end) end
		for part, transparency in original do
			if not part.Parent then continue end
			part.Transparency = transparency
			for _, child in part:GetChildren() do if child:IsA("Decal") then child.Transparency = 0 end end
		end
		pcall(function() ring:Destroy() end)
		GameEffects.Kill.animate(state, 0.05, function(progress)
			bullet.CFrame = environment.CFrame.lookAt(start:Lerp(target, progress), target + direction)
		end, function()
			pcall(function() bullet:Destroy() end)
			if body then
				body.release(direction * 50 + environment.Vector3.new(0, 18, 0), function(result)
					if result.head then result.head.AssemblyLinearVelocity = direction * 70 + environment.Vector3.new(0, 20, 0) end
				end)
			end
			GameEffects.Kill.flash(state, target, gold, 10, 5)
			local _, burst = GameEffects.Kill.effectAttachment(state, effect.chest)
			GameEffects.Kill.particle(state, burst, {Texture = state.textures.shards, Color = environment.ColorSequence.new(white, gold),
				Size = sequence(0, 1.2, 1, 0.2), Lifetime = environment.NumberRange.new(0.4, 0.8), Speed = environment.NumberRange.new(12, 24),
				SpreadAngle = environment.Vector2.new(180, 180), Drag = 3, Rotation = environment.NumberRange.new(0, 360), Brightness = 5}, 30)
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.glassSmash, 1, 1)
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.sniper, 0.9, 1)
			GameEffects.Kill.shakeCamera(state, target, 1, 0.3)
		end)
	end)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.scratch2, 0.8, 0.5)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.synthPulse, 0.5, 0.3, nil, 1.2)
end

function GameEffects.Kill.supernova(state, effect)
	local environment = state.context.environment
	local center, white = effect.chest, environment.Color3.new(1, 1, 1)
	local body, model = GameEffects.Kill.staticBody(state, effect)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	if model then GameEffects.Kill.highlight(state, model, white, white, 0.2, 0) end
	local frames = {}
	for index, part in body do frames[index] = {frame = part.CFrame, size = part.Size} end
	local core = environment.Instance.new("Part")
	core.Shape, core.Anchored, core.CanCollide, core.CanQuery, core.CanTouch, core.CastShadow = environment.Enum.PartType.Ball, true, false, false, false, false
	core.Material, core.Color, core.Size, core.CFrame = environment.Enum.Material.Neon, environment.Color3.fromRGB(255, 250, 230), environment.Vector3.new(0.1, 0.1, 0.1), environment.CFrame.new(center)
	core.Parent = GameEffects.Kill.folder(state)
	local anchor, attachment = GameEffects.Kill.effectAttachment(state, center)
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
	local warm = environment.Color3.fromRGB(255, 240, 200)
	local emitter = GameEffects.Kill.particle(state, attachment, {Texture = state.textures.corona, Color = colors(warm, environment.Color3.fromRGB(255, 180, 90)),
		Size = sequence(0, 3, 1, 5), Transparency = sequence(0, 0.2, 1, 1), Lifetime = environment.NumberRange.new(0.5),
		Rotation = environment.NumberRange.new(0, 360), RotSpeed = environment.NumberRange.new(60), Brightness = 4}, 0)
	emitter.Rate, emitter.Enabled = 10, true
	local light = environment.Instance.new("PointLight")
	light.Color, light.Range, light.Brightness, light.Shadows, light.Parent = warm, 20, 1, false, anchor
	GameEffects.Kill.animate(state, 0.6, function(progress)
		local eased = progress * progress
		for index, part in body do
			if not part.Parent then continue end
			local original = frames[index]
			part.CFrame = environment.CFrame.new(center + (original.frame.Position - center) * (1 - eased)) * original.frame.Rotation
			part.Size = original.size * (1 - 0.9 * eased)
		end
		local size = 0.1 + 2.4 * progress
		core.Size, light.Brightness = environment.Vector3.new(size, size, size), 1 + 8 * progress
	end, function()
		for _, part in body do pcall(function() part:Destroy() end) end
		emitter.Enabled = false
		GameEffects.Kill.tween(state, core, 0.1, {Size = environment.Vector3.new(0.3, 0.3, 0.3)}, environment.Enum.EasingStyle.Quad, environment.Enum.EasingDirection.In)
		GameEffects.Kill.delay(state, 0.12, function()
			pcall(function() core:Destroy() end)
			local palette = {environment.Color3.fromRGB(255, 60, 70), environment.Color3.fromRGB(255, 150, 40), environment.Color3.fromRGB(255, 230, 70),
				environment.Color3.fromRGB(90, 255, 110), environment.Color3.fromRGB(70, 210, 255), environment.Color3.fromRGB(90, 110, 255), environment.Color3.fromRGB(190, 90, 255)}
			for index, color in palette do
				GameEffects.Kill.delay(state, index * 0.03, function()
					local _, burst = GameEffects.Kill.effectAttachment(state, center)
					GameEffects.Kill.particle(state, burst, {Texture = state.textures.ring, Color = colors(color), Size = sequence(0, 1, 1, 10 + index * 2.2),
						Transparency = sequence(0, 0, 1, 1), Lifetime = environment.NumberRange.new(0.6), Brightness = 5}, 1)
					GameEffects.Kill.particle(state, burst, {Texture = state.textures.star, Color = colors(white, color), Size = sequence(0, 0.6, 1, 0),
						Lifetime = environment.NumberRange.new(0.6, 1), Speed = environment.NumberRange.new(18, 36), SpreadAngle = environment.Vector2.new(180, 180), Drag = 2, Brightness = 5}, 8)
				end)
			end
			local _, burst = GameEffects.Kill.effectAttachment(state, center)
			GameEffects.Kill.particle(state, burst, {Texture = state.textures.needles, Color = colors(white, environment.Color3.fromRGB(255, 230, 160)),
				Size = sequence(0, 6, 1, 16), Transparency = sequence(0, 0.1, 1, 1), Lifetime = environment.NumberRange.new(0.6), Rotation = environment.NumberRange.new(0, 360), Brightness = 5}, 2)
			GameEffects.Kill.flash(state, center, white, 26, 8)
			GameEffects.Kill.ringAtGround(state, effect.root, white, 2, 30, 0.7, nil, effect.ignore)
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.sonic2, 0.9, 1.2, nil, 2)
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.chimes, 0.7, 2, nil, 2)
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.boom2, 0.6, 1.2)
			GameEffects.Kill.shakeCamera(state, center, 1.8, 0.45)
		end)
	end)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.synthPulse, 0.8, 1.2, nil, 1.2)
end

function GameEffects.Kill.moveParts(state, parts, frames)
	local context, environment = state.context, state.context.environment
	local ok = pcall(function() context.workspace:BulkMoveTo(parts, frames, environment.Enum.BulkMoveMode.FireCFrameChanged) end)
	if ok then return end
	for index, part in parts do pcall(function() part.CFrame = frames[index] end) end
end

function GameEffects.Kill.glacier(state, effect)
	local environment = state.context.environment
	local color, white = environment.Color3.fromRGB(170, 225, 255), environment.Color3.new(1, 1, 1)
	local ground = GameEffects.Kill.ground(state, effect.root, effect.ignore)
	local height = ground and ground.Y or effect.root.Y - 3
	local body = GameEffects.Kill.body(state, effect, environment.Vector3.new(0, 0, 0), nil, 3.8, nil, true)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local base = environment.Vector3.new(effect.root.X, height - 0.3, effect.root.Z)
	local direction = environment.Vector3.new(math.random() - 0.5, 3.5, math.random() - 0.5).Unit
	local crystals = {}
	local central, axis = GameEffects.Kill.spike(state, base, base + direction * 12, 0.9, 1.4, color, environment.Enum.Material.Ice)
	for _, part in central do
		part.Transparency, part.Reflectance = 0.1, 0.25
		local frame = part.CFrame
		part.CFrame = frame - axis * 12.5
		GameEffects.Kill.tween(state, part, 0.22, {CFrame = frame}, environment.Enum.EasingStyle.Back)
		table.insert(crystals, part)
	end
	for index = 1, 6 do
		local angle = index / 6 * 6.283 + math.random() * 0.4
		local start = base + environment.Vector3.new(math.cos(angle) * 2.8, 0, math.sin(angle) * 2.8)
		local finish = start + environment.Vector3.new(math.cos(angle) * 1.2, 3 + math.random() * 2.5, math.sin(angle) * 1.2)
		local parts, spikeDirection, length = GameEffects.Kill.spike(state, start, finish, 0.35, 0.6, color:Lerp(white, 0.3), environment.Enum.Material.Ice)
		for _, part in parts do
			part.Transparency = 0.15
			local frame = part.CFrame
			part.CFrame = frame - spikeDirection * (length + 0.3)
			GameEffects.Kill.delay(state, 0.05 + index * 0.03, function()
				if part.Parent then GameEffects.Kill.tween(state, part, 0.18, {CFrame = frame}, environment.Enum.EasingStyle.Back) end
			end)
			table.insert(crystals, part)
		end
	end
	if body then
		local frames = {}
		for index, part in body.parts do frames[index] = part.CFrame end
		GameEffects.Kill.animate(state, 0.22, function(progress)
			local offset = direction * 7 * (1 - (1 - progress) ^ 2)
			local targets = {}
			for index, frame in frames do targets[index] = frame + offset end
			GameEffects.Kill.moveParts(state, body.parts, targets)
		end)
		local highlight = GameEffects.Kill.highlight(state, body.model, color, white, 0.55, 0.2)
		GameEffects.Kill.delay(state, 1.2, function()
			if highlight.Parent then GameEffects.Kill.tween(state, highlight, 0.3, {FillTransparency = 1, OutlineTransparency = 1}) end
		end)
	end
	GameEffects.Kill.smoke(state, base + environment.Vector3.new(0, 0.3, 0), environment.Color3.fromRGB(225, 240, 255), 10, 6, 2.5)
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(base + environment.Vector3.new(0, 4, 0)), environment.Vector3.new(5, 8, 5))
	local emitter = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.soft, Color = environment.ColorSequence.new(white, white),
		Size = GameEffects.Kill.numberSequence(state, 0, 0.25, 1, 0), Lifetime = environment.NumberRange.new(0.8, 1.3), Speed = environment.NumberRange.new(0.5, 2),
		Acceleration = environment.Vector3.new(0, -4, 0), Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0.3, Brightness = 2}, 0)
	emitter.Rate, emitter.Enabled = 40, true
	GameEffects.Kill.light(state, anchor, color, 5, 18, 1.4)
	GameEffects.Kill.delay(state, 1.3, function()
		emitter.Enabled = false
		GameEffects.Kill.destroyLater(state, anchor, 1.2)
		for _, part in crystals do pcall(function() part:Destroy() end) end
		GameEffects.Kill.fragments(state, base + direction * 4, 30, color, environment.Enum.Material.Ice, 0.55, 18, 1.8)
		if body then body.release(environment.Vector3.new(0, 4, 0), nil) end
		GameEffects.Kill.flash(state, base + direction * 5, color, 12, 4)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.iceShatter, 1, 0.8)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.iceSplinter, 0.8, 0.7, nil, 1.8)
		GameEffects.Kill.shakeCamera(state, base, 1, 0.3)
	end)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.iceSplinter, 1, 0.8, nil, 1.8)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.quakeDebris, 0.7, 1.1)
	GameEffects.Kill.shakeCamera(state, base, 0.9, 0.3)
end

function GameEffects.Kill.gore(state, effect)
	local environment = state.context.environment
	local center = effect.chest
	local body = GameEffects.Kill.body(state, effect, environment.Vector3.new(0, 0, 0), nil, 3.4, nil, true)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local highlight = body and GameEffects.Kill.highlight(state, body.model, environment.Color3.fromRGB(200, 0, 20), environment.Color3.fromRGB(255, 80, 80), 1, 1)
	environment.task.spawn(function()
		for index = 1, 4 do
			if highlight and highlight.Parent then
				highlight.FillTransparency, highlight.OutlineTransparency = index % 2 == 0 and 0.15 or 0.75, 0.2
			end
			environment.task.wait(0.07 / state.speed)
		end
	end)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.boneSquish, 0.5, 0.45)
	GameEffects.Kill.delay(state, 0.3, function()
		if body then
			body.release(environment.Vector3.new(0, 0, 0), function(result) GameEffects.Kill.scatterBody(state, result, center, 24, 16, 12, 15) end)
			if highlight then GameEffects.Kill.tween(state, highlight, 0.6, {FillTransparency = 1, OutlineTransparency = 1}) end
		end
		local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
		local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
		local anchor, attachment = GameEffects.Kill.effectAttachment(state, center)
		GameEffects.Kill.particle(state, attachment, {Texture = state.textures.splat, Color = colors(environment.Color3.fromRGB(200, 10, 30), environment.Color3.fromRGB(100, 0, 12)),
			Size = sequence(0, 0.9, 1, 0.3), Lifetime = environment.NumberRange.new(0.7, 1.3), Speed = environment.NumberRange.new(18, 40),
			SpreadAngle = environment.Vector2.new(180, 180), Acceleration = environment.Vector3.new(0, -60, 0), Rotation = environment.NumberRange.new(0, 360),
			RotSpeed = environment.NumberRange.new(-200, 200), LightEmission = 0, Brightness = 1.2}, 110)
		GameEffects.Kill.particle(state, attachment, {Texture = state.textures.soft, Color = colors(environment.Color3.fromRGB(160, 0, 18)),
			Size = sequence(0, 3, 1, 10), Transparency = sequence(0, 0.3, 1, 1), Lifetime = environment.NumberRange.new(0.8, 1.3),
			Speed = environment.NumberRange.new(4, 9), SpreadAngle = environment.Vector2.new(180, 180), LightEmission = 0.3, Brightness = 1.2}, 14)
		local rain = GameEffects.Kill.anchor(state, environment.CFrame.new(center + environment.Vector3.new(0, 6, 0)), environment.Vector3.new(8, 1, 8))
		local rainColor = environment.Color3.fromRGB(170, 0, 20)
		local emitter = GameEffects.Kill.particle(state, rain, {Texture = state.textures.splat, Color = colors(rainColor),
			Size = sequence(0, 0.25, 1, 0.12), Lifetime = environment.NumberRange.new(0.6, 0.9), Acceleration = environment.Vector3.new(0, -70, 0),
			Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0, Brightness = 1}, 0)
		emitter.Rate, emitter.Enabled = 70, true
		GameEffects.Kill.delay(state, 1, function() if emitter.Parent then emitter.Enabled = false end end)
		GameEffects.Kill.destroyLater(state, rain, 2.2)
		GameEffects.Kill.flash(state, center, environment.Color3.fromRGB(255, 30, 40), 10, 4)
		local blood = environment.Color3.fromRGB(125, 0, 12)
		GameEffects.Kill.splatRays(state, center, 16, blood, 18, effect.ignore, 1.2, 3.4, 3.4)
		GameEffects.Kill.splat(state, effect.root, 7, blood, 3.4, effect.ignore, 0.6)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.guts, 1, 0.7, anchor)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.guts, 1, 1.1, anchor)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.fleshHit, 0.6, 0.6, anchor)
		GameEffects.Kill.shakeCamera(state, center, 1.3, 0.35)
	end)
end

function GameEffects.Kill.claws(state, effect)
	local context, environment = state.context, state.context.environment
	local color = environment.Color3.fromRGB(255, 60, 40)
	local body = GameEffects.Kill.body(state, effect, environment.Vector3.new(0, 0, 0), nil, 3.2, nil, true)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local camera = context.workspace.CurrentCamera
	local frame = camera and camera.CFrame or environment.CFrame.new()
	local roll = math.random(35, 55) * (math.random() < 0.5 and -1 or 1)
	local angle = math.rad(roll)
	local direction = frame.RightVector * math.cos(angle) + frame.UpVector * math.sin(angle)
	local across = -frame.RightVector * math.sin(angle) + frame.UpVector * math.cos(angle)
	for index = -1, 1 do
		GameEffects.Kill.delay(state, (index + 1) * 0.02, function()
			GameEffects.Kill.arc(state, effect.chest + across * index * 0.6, roll, 3.8, 1, color, 0.45, 0.07, 0.14, 0, environment.Color3.fromRGB(255, 230, 220))
		end)
	end
	GameEffects.Kill.delay(state, 0.08, function()
		local horizontal = environment.Vector3.new(direction.X, 0, direction.Z)
		horizontal = horizontal.Magnitude > 0.05 and horizontal.Unit or GameEffects.Kill.direction(state, effect)
		if body then
			body.release(horizontal * 35 + environment.Vector3.new(0, 10, 0), nil)
			pcall(function() body.torso.AssemblyAngularVelocity = GameEffects.Kill.randomVector(state, 8) end)
		end
		local ground = GameEffects.Kill.ground(state, effect.root, effect.ignore)
		if ground then
			for index = -1, 1 do
				local part = environment.Instance.new("Part")
				part.Anchored, part.CanCollide, part.CanQuery, part.CanTouch, part.CastShadow = true, false, false, false, false
				part.Transparency, part.Size = 1, environment.Vector3.new(0.35, 0.05, 0.2)
				local side = environment.Vector3.new(-horizontal.Z, 0, horizontal.X)
				local position = ground + side * index * 0.7 + environment.Vector3.new(0, 0.04, 0)
				part.CFrame = environment.CFrame.lookAt(position, position + horizontal)
				local decal = environment.Instance.new("Decal")
				decal.Texture, decal.Face, decal.Color3, decal.Parent = state.textures.splat, environment.Enum.NormalId.Top, environment.Color3.fromRGB(90, 0, 10), part
				part.Parent = GameEffects.Kill.folder(state)
				GameEffects.Kill.tween(state, part, 0.25, {Size = environment.Vector3.new(0.35, 0.05, 5)}, environment.Enum.EasingStyle.Quad)
				GameEffects.Kill.delay(state, 2.8, function() if decal.Parent then GameEffects.Kill.tween(state, decal, 1.2, {Transparency = 1}) end end)
				GameEffects.Kill.destroyLater(state, part, 4.2)
			end
		end
		local anchor, attachment = GameEffects.Kill.effectAttachment(state, effect.chest)
		GameEffects.Kill.particle(state, attachment, {Texture = state.textures.splat,
			Color = environment.ColorSequence.new(environment.Color3.fromRGB(190, 10, 30), environment.Color3.fromRGB(100, 0, 12)),
			Size = GameEffects.Kill.numberSequence(state, 0, 0.6, 1, 0.25), Lifetime = environment.NumberRange.new(0.6, 1),
			Speed = environment.NumberRange.new(10, 22), SpreadAngle = environment.Vector2.new(70, 70), Acceleration = environment.Vector3.new(0, -60, 0),
			Rotation = environment.NumberRange.new(0, 360), LightEmission = 0, Brightness = 1.1}, 40)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.bone1, 1, 0.8, anchor)
		GameEffects.Kill.shakeCamera(state, effect.chest, 0.8, 0.25)
	end)
	for index = 0, 2 do
		GameEffects.Kill.delay(state, index * 0.03, function() GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.fleshSlash, 0.8, 1.1 + index * 0.12) end)
	end
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.growl, 0.6, 0.4)
end

function GameEffects.Kill.bladestorm(state, effect)
	local environment = state.context.environment
	local color, white = environment.Color3.fromRGB(215, 220, 230), environment.Color3.new(1, 1, 1)
	local center = effect.chest
	local body = GameEffects.Kill.body(state, effect, environment.Vector3.new(0, 0, 0), nil, 3.4, nil, true)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local blades = {}
	for index = 1, 10 do
		local parts, offsets = GameEffects.Kill.blade(state, color, environment.Enum.Material.Metal, 1.6, 0.36)
		table.insert(blades, {parts = parts, offsets = offsets, phase = index / 10 * 6.283, radius = 2.1 + index % 3 * 0.35, height = -2.4 + index % 5 * 0.2})
	end
	GameEffects.Kill.animate(state, 1.2, function(progress)
		local elapsed = progress * 1.2
		for _, blade in blades do
			local angle = blade.phase + elapsed * 14
			local position = center + environment.Vector3.new(math.cos(angle) * blade.radius, blade.height + progress * 4.5, math.sin(angle) * blade.radius)
			local direction = environment.Vector3.new(-math.sin(angle), 0.15, math.cos(angle)).Unit
			local frame = GameEffects.Kill.bladeFrame(state, position, direction) * environment.CFrame.Angles(0, elapsed * 30, 0)
			GameEffects.Kill.positionBlade(blade.parts, blade.offsets, frame)
		end
	end, function()
		for _, blade in blades do
			for _, part in blade.parts do
				GameEffects.Kill.tween(state, part, 0.25, {Transparency = 1})
				GameEffects.Kill.destroyLater(state, part, 0.3)
			end
		end
		if body then
			body.release(environment.Vector3.new(0, 0, 0), function(result)
				GameEffects.Kill.scatterBody(state, result, center, 10, 8, 10, 10)
			end)
		end
		local anchor, attachment = GameEffects.Kill.effectAttachment(state, center)
		GameEffects.Kill.particle(state, attachment, {Texture = state.textures.splat,
			Color = environment.ColorSequence.new(environment.Color3.fromRGB(190, 10, 30), environment.Color3.fromRGB(100, 0, 12)),
			Size = GameEffects.Kill.numberSequence(state, 0, 0.6, 1, 0.25), Lifetime = environment.NumberRange.new(0.6, 1),
			Speed = environment.NumberRange.new(10, 24), SpreadAngle = environment.Vector2.new(180, 180), Acceleration = environment.Vector3.new(0, -60, 0),
			Rotation = environment.NumberRange.new(0, 360), LightEmission = 0, Brightness = 1.1}, 60)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.rip, 1, 0.7, anchor)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.guts2, 1, 0.9, anchor)
		GameEffects.Kill.shakeCamera(state, center, 0.9, 0.3)
		GameEffects.Kill.delay(state, 0.6, function() GameEffects.Kill.splat(state, effect.root, 6, environment.Color3.fromRGB(125, 0, 12), 3, effect.ignore, 1.1) end)
	end)
	for index = 1, 6 do
		GameEffects.Kill.delay(state, index * 0.17, function()
			GameEffects.Kill.arc(state, center + environment.Vector3.new(0, -1 + index * 0.4, 0), math.random(0, 180), 2.8, 1,
				environment.Color3.fromRGB(255, 60, 70), 0.45, 0.05, 0.06, math.random(-40, 40))
			GameEffects.Kill.sparks(state, center, white, 6, 18, state.textures.spark)
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.swordWhip, 0.55, 1.3 + index * 0.1)
		end)
	end
	GameEffects.Kill.smoke(state, effect.root - environment.Vector3.new(0, 2.5, 0), environment.Color3.fromRGB(170, 165, 158), 8, 6, 2)
end

function GameEffects.Kill.phantomBlades(state, effect)
	local environment = state.context.environment
	local color, white = environment.Color3.fromRGB(90, 230, 255), environment.Color3.new(1, 1, 1)
	local center = effect.chest
	local body = GameEffects.Kill.body(state, effect, environment.Vector3.new(0, 0, 0), nil, 3.2, nil, true)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local blades = {}
	for index = 1, 8 do
		local angle = (index - 1) / 8 * 6.283
		local position = center + environment.Vector3.new(math.cos(angle) * 5, index % 2 == 0 and 0.9 or -0.6, math.sin(angle) * 5)
		local direction = (center - position).Unit
		local parts, offsets = GameEffects.Kill.blade(state, color, environment.Enum.Material.Neon, 2.2, 0.5, 1)
		for _, part in parts do
			part.Color, part.Material = color, environment.Enum.Material.Neon
			GameEffects.Kill.tween(state, part, 0.25, {Transparency = 0.15})
		end
		GameEffects.Kill.positionBlade(parts, offsets, GameEffects.Kill.bladeFrame(state, position, direction))
		table.insert(blades, {parts = parts, offsets = offsets, position = position, direction = direction})
	end
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(center), environment.Vector3.new(10, 3, 10))
	GameEffects.Kill.particle(state, anchor, {Texture = state.textures.sparkBright, Color = environment.ColorSequence.new(white, color),
		Size = GameEffects.Kill.numberSequence(state, 0, 0.5, 1, 0), Lifetime = environment.NumberRange.new(0.3, 0.5),
		Shape = environment.Enum.ParticleEmitterShape.Box, Brightness = 5}, 20)
	GameEffects.Kill.destroyLater(state, anchor, 2)
	GameEffects.Kill.animate(state, 0.55, function(progress)
		for index, blade in blades do
			local bob = math.sin(progress * 12 + index) * 0.15
			local position = blade.position + environment.Vector3.new(0, bob, 0) - blade.direction * progress * 0.8
			GameEffects.Kill.positionBlade(blade.parts, blade.offsets, GameEffects.Kill.bladeFrame(state, position, blade.direction))
		end
	end, function()
		for _, blade in blades do
			local start, finish = blade.position - blade.direction * 0.8, center - blade.direction * 1.8
			GameEffects.Kill.animate(state, 0.09, function(progress)
				GameEffects.Kill.positionBlade(blade.parts, blade.offsets, GameEffects.Kill.bladeFrame(state, start:Lerp(finish, progress * progress), blade.direction))
			end, function()
				GameEffects.Kill.delay(state, 0.08, function()
					for _, part in blade.parts do
						GameEffects.Kill.tween(state, part, 0.2, {Transparency = 1})
						GameEffects.Kill.destroyLater(state, part, 0.25)
					end
				end)
			end)
		end
		GameEffects.Kill.delay(state, 0.1, function()
			GameEffects.Kill.flash(state, center, color, 12, 5)
			local _, attachment = GameEffects.Kill.effectAttachment(state, center)
			GameEffects.Kill.particle(state, attachment, {Texture = state.textures.shards, Color = environment.ColorSequence.new(white, color),
				Size = GameEffects.Kill.numberSequence(state, 0, 1.2, 1, 0.2), Lifetime = environment.NumberRange.new(0.4, 0.7),
				Speed = environment.NumberRange.new(14, 26), SpreadAngle = environment.Vector2.new(180, 180), Drag = 4, Rotation = environment.NumberRange.new(0, 360), Brightness = 5}, 30)
			if body then
				body.release(environment.Vector3.new(0, 42, 0), nil)
				pcall(function() body.torso.AssemblyAngularVelocity = GameEffects.Kill.randomVector(state, 9) end)
				local highlight = GameEffects.Kill.highlight(state, body.model, color, white, 0.3, 0)
				GameEffects.Kill.delay(state, 0.5, function()
					if highlight.Parent then GameEffects.Kill.tween(state, highlight, 0.5, {FillTransparency = 1, OutlineTransparency = 1}) end
				end)
			end
			GameEffects.Kill.ringAtGround(state, effect.root, color, 2, 14, 0.5, nil, effect.ignore)
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.glassSmash, 0.9, 1.2)
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.stab2, 0.8, 0.9)
			GameEffects.Kill.shakeCamera(state, center, 0.9, 0.3)
		end)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.magicZoom, 0.9, 1.6)
	end)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.magicGlow, 0.7, 1.4)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.rise, 0.3, 2)
end

function GameEffects.Kill.firework(state, effect)
	local environment = state.context.environment
	local palette = {environment.Color3.fromRGB(255, 70, 90), environment.Color3.fromRGB(255, 200, 60), environment.Color3.fromRGB(80, 220, 255),
		environment.Color3.fromRGB(190, 90, 255), environment.Color3.fromRGB(110, 255, 120)}
	local white = environment.Color3.new(1, 1, 1)
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
	local body = GameEffects.Kill.body(state, effect, GameEffects.Kill.direction(state, effect) * 5 + environment.Vector3.new(0, 105, 0), GameEffects.Kill.randomVector(state, 6), 1.6)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.chest), environment.Vector3.new(0.8, 0.8, 0.8))
	local emitter = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.fsparks, Color = colors(white, environment.Color3.fromRGB(255, 190, 80)),
		Size = sequence(0, 0.45, 1, 0), Lifetime = environment.NumberRange.new(0.25, 0.45), Speed = environment.NumberRange.new(4, 9),
		SpreadAngle = environment.Vector2.new(180, 180), Drag = 3, Orientation = environment.Enum.ParticleOrientation.VelocityParallel, Brightness = 5}, 0)
	emitter.Rate, emitter.Enabled = 110, true
	local fuse = GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.fuse, 0.7, 1, anchor)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.rocket, 0.45, 1.5, anchor)
	local exploded, position = false, effect.chest
	local function explode(at)
		if exploded then return end
		exploded, emitter.Enabled = true, false
		if fuse then pcall(function() fuse:Stop() end) end
		if body then pcall(function() body.model:Destroy() end) end
		local burst = GameEffects.Kill.anchor(state, environment.CFrame.new(at), environment.Vector3.new(1, 1, 1))
		local attachment = environment.Instance.new("Attachment")
		attachment.Parent = burst
		for index = 1, 3 do
			local color = palette[math.random(1, #palette)]
			GameEffects.Kill.delay(state, (index - 1) * 0.12, function()
				GameEffects.Kill.particle(state, attachment, {Texture = state.textures.spark, Color = colors(white, color), Size = sequence(0, 0.8, 0.7, 0.5, 1, 0),
					Lifetime = environment.NumberRange.new(1, 1.5), Speed = environment.NumberRange.new(30 - index * 5, 38 - index * 5),
					SpreadAngle = environment.Vector2.new(180, 180), Drag = 2.2, Acceleration = environment.Vector3.new(0, -10, 0),
					Orientation = environment.Enum.ParticleOrientation.VelocityParallel, Brightness = 6}, 60)
				GameEffects.Kill.particle(state, attachment, {Texture = state.textures.soft, Color = colors(color), Size = sequence(0, 4, 1, 10),
					Transparency = sequence(0, 0.2, 1, 1), Lifetime = environment.NumberRange.new(0.35), Brightness = 4}, 1)
				GameEffects.Kill.light(state, burst, color, 10, 36, 0.6)
				GameEffects.Kill.sound(state, index == 1 and GameEffects.Kill.soundIds.explode or GameEffects.Kill.soundIds.boom, 0.5, 1.1 + index * 0.12, burst)
			end)
		end
		GameEffects.Kill.delay(state, 0.4, function()
			GameEffects.Kill.particle(state, attachment, {Texture = state.textures.star, Color = colors(white, environment.Color3.fromRGB(255, 220, 120)),
				Size = sequence(0, 0.35, 1, 0), Transparency = sequence(0, 0, 0.2, 0.8, 0.4, 0, 0.6, 0.8, 0.8, 0, 1, 1),
				Lifetime = environment.NumberRange.new(1.2, 1.8), Speed = environment.NumberRange.new(6, 14), SpreadAngle = environment.Vector2.new(180, 180),
				Drag = 1.5, Acceleration = environment.Vector3.new(0, -6, 0), Brightness = 5}, 40)
		end)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.fireworks, 0.8, 1, burst, 2.2)
		GameEffects.Kill.shakeCamera(state, at, 0.9, 0.3)
		GameEffects.Kill.destroyLater(state, burst, 3.2)
	end
	local previous = environment.Vector3.new(0, 105, 0)
	GameEffects.Kill.animate(state, 0.8, function(progress)
		if exploded or not body or not body.torso or not body.torso.Parent then return end
		anchor.CFrame, position = body.torso.CFrame, body.torso.Position
		local velocity = body.torso.AssemblyLinearVelocity
		if progress > 0.08 and previous.Y > 30 and velocity.Y < previous.Y * 0.3 then explode(position) end
		previous = velocity
	end, function() explode(position) end)
	local launch = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.root), environment.Vector3.new(1, 1, 1))
	GameEffects.Kill.particle(state, launch, {Texture = state.textures.soft, Color = colors(environment.Color3.fromRGB(230, 230, 230)),
		Size = sequence(0, 1.5, 1, 3.5), Transparency = sequence(0, 0.2, 1, 1), Lifetime = environment.NumberRange.new(0.5, 0.8),
		Speed = environment.NumberRange.new(5, 10), SpreadAngle = environment.Vector2.new(80, 80), Drag = 4, LightEmission = 0, LightInfluence = 0.8, Brightness = 1.2}, 12)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.boom, 0.35, 1.8, launch)
	GameEffects.Kill.destroyLater(state, launch, 1.5)
	GameEffects.Kill.destroyLater(state, anchor, 2)
end

function GameEffects.Kill.earthquake(state, effect)
	local environment = state.context.environment
	local direction, origin = GameEffects.Kill.direction(state, effect)
	local offset = environment.Vector3.new(effect.root.X - origin.X, 0, effect.root.Z - origin.Z)
	local distance = math.min(offset.Magnitude, 26)
	local path = offset.Magnitude > 0.5 and offset.Unit or direction
	local start = effect.root - path * distance
	local body = GameEffects.Kill.body(state, effect, environment.Vector3.new(0, 0, 0), nil, 3.8, nil, true)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local count = math.max(4, math.floor(distance / 2.2))
	for index = 1, count do
		GameEffects.Kill.delay(state, index * 0.045, function()
			local position = start + path * (distance * index / count)
			local ground = GameEffects.Kill.ground(state, position + environment.Vector3.new(0, 2, 0), effect.ignore)
			if not ground then return end
			local last = index == count
			local height = last and 7 or 2 + math.random() * 2.5
			local width = last and 2.6 or 1.1 + math.random() * 0.8
			local rock = environment.Instance.new("Part")
			rock.Anchored, rock.CanCollide, rock.CanQuery, rock.CanTouch, rock.CastShadow = true, false, false, false, true
			rock.Size, rock.Material = environment.Vector3.new(width, height, width), environment.Enum.Material.Slate
			rock.Color = environment.Color3.fromRGB(105, 98, 92):Lerp(environment.Color3.fromRGB(70, 64, 60), math.random())
			local rotation = environment.CFrame.Angles((math.random() - 0.5) * 0.3, math.random() * 6.28, (math.random() - 0.5) * 0.3)
			rock.CFrame = environment.CFrame.new(ground - environment.Vector3.new(0, height / 2 + 0.2, 0)) * rotation
			rock.Parent = GameEffects.Kill.folder(state)
			GameEffects.Kill.tween(state, rock, 0.12, {CFrame = environment.CFrame.new(ground + environment.Vector3.new(0, height / 2 - 0.4, 0)) * rotation}, environment.Enum.EasingStyle.Back)
			GameEffects.Kill.smoke(state, ground, environment.Color3.fromRGB(140, 130, 120), 3, 5, 1.5)
			GameEffects.Kill.splat(state, position, 2.4, environment.Color3.fromRGB(30, 26, 24), 2.2, effect.ignore, 0.1, state.textures.cracks, 1)
			if index % 2 == 0 then GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.rockCrack, 0.5, 0.9 + math.random() * 0.4) end
			GameEffects.Kill.delay(state, 1.5, function()
				if rock.Parent then GameEffects.Kill.tween(state, rock, 0.45, {CFrame = rock.CFrame - environment.Vector3.new(0, height, 0)}, environment.Enum.EasingStyle.Quad, environment.Enum.EasingDirection.In) end
			end)
			GameEffects.Kill.destroyLater(state, rock, 2.1)
			if not last then return end
			if body then
				body.release(environment.Vector3.new(0, 70, 0) + path * 10, nil)
				pcall(function() body.torso.AssemblyAngularVelocity = GameEffects.Kill.randomVector(state, 9) end)
			end
			GameEffects.Kill.smoke(state, ground, environment.Color3.fromRGB(150, 140, 130), 14, 10, 2.5)
			GameEffects.Kill.fragments(state, ground + environment.Vector3.new(0, 1, 0), 14, environment.Color3.fromRGB(95, 88, 82), environment.Enum.Material.Slate, 0.45, 26, 1.8)
			GameEffects.Kill.ringAtGround(state, ground, environment.Color3.fromRGB(210, 200, 190), 2, 20, 0.5, nil, effect.ignore)
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.quake, 0.9, 0.7)
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.rockCrack, 1, 0.7)
			GameEffects.Kill.shakeCamera(state, ground, 1.8, 0.4)
		end)
	end
	GameEffects.Kill.shakeCamera(state, effect.root, 1, 0.9)
end

function GameEffects.Kill.sand(state, effect)
	local environment = state.context.environment
	local color, shade = environment.Color3.fromRGB(218, 188, 128), environment.Color3.fromRGB(150, 120, 70)
	local ground = GameEffects.Kill.ground(state, effect.root, effect.ignore)
	local height = ground and ground.Y or effect.root.Y - 3
	local body = GameEffects.Kill.staticBody(state, effect)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local sand = GameEffects.Kill.transmute(state, body, environment.Enum.Material.Sand, function() return color:Lerp(shade, math.random() * 0.3) end, 0.35, false)
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.chest), environment.Vector3.new(2, 4.4, 1.2))
	local emitter = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.square, Color = environment.ColorSequence.new(color, environment.Color3.fromRGB(170, 140, 90)),
		Size = GameEffects.Kill.numberSequence(state, 0, 0.14, 1, 0.08), Lifetime = environment.NumberRange.new(0.5, 0.8), Speed = environment.NumberRange.new(0.5, 2),
		SpreadAngle = environment.Vector2.new(60, 60), Acceleration = environment.Vector3.new(0, -45, 0), Rotation = environment.NumberRange.new(0, 360),
		Shape = environment.Enum.ParticleEmitterShape.Box, ShapeStyle = environment.Enum.ParticleEmitterShapeStyle.Volume, LightEmission = 0, LightInfluence = 1, Brightness = 1.2}, 0)
	GameEffects.Kill.delay(state, 0.4, function()
		for _, part in body do pcall(function() part:Destroy() end) end
		emitter.Rate, emitter.Enabled = 110, true
		local top = effect.head.Y + 0.8
		for _, part in sand do
			if not part.Parent then continue end
			local delay = (1 - math.clamp((part.Position.Y - height) / math.max(top - height, 1), 0, 1)) * 0.45
			GameEffects.Kill.delay(state, delay, function()
				if not part.Parent then return end
				GameEffects.Kill.tween(state, part, 0.6, {Size = environment.Vector3.new(part.Size.X * 1.15, 0.05, part.Size.Z * 1.15),
					CFrame = environment.CFrame.new(part.Position.X, height + 0.1, part.Position.Z) * part.CFrame.Rotation}, environment.Enum.EasingStyle.Quad, environment.Enum.EasingDirection.In)
				GameEffects.Kill.delay(state, 0.6, function() if part.Parent then GameEffects.Kill.tween(state, part, 0.3, {Transparency = 1}) end end)
				GameEffects.Kill.destroyLater(state, part, 1)
			end)
		end
		local pile = environment.Instance.new("Part")
		pile.Shape, pile.Anchored, pile.CanCollide, pile.CanQuery, pile.CanTouch, pile.CastShadow = environment.Enum.PartType.Ball, true, false, false, false, false
		pile.Material, pile.Color, pile.Size = environment.Enum.Material.Sand, color, environment.Vector3.new(0.2, 0.05, 0.2)
		pile.CFrame, pile.Parent = environment.CFrame.new(effect.root.X, height, effect.root.Z), GameEffects.Kill.folder(state)
		GameEffects.Kill.tween(state, pile, 1.1, {Size = environment.Vector3.new(4.2, 1.7, 4.2)}, environment.Enum.EasingStyle.Quad)
		GameEffects.Kill.delay(state, 1.2, function() if emitter.Parent then emitter.Enabled = false end end)
		GameEffects.Kill.delay(state, 2.6, function()
			if pile.Parent then GameEffects.Kill.tween(state, pile, 0.9, {Size = environment.Vector3.new(4.8, 0.05, 4.8), Transparency = 1}, environment.Enum.EasingStyle.Quad, environment.Enum.EasingDirection.In) end
		end)
		GameEffects.Kill.destroyLater(state, pile, 3.6)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.sandPour, 0.7, 0.35, anchor, 2)
	end)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.poof, 0.6, 0.55, anchor)
	GameEffects.Kill.destroyLater(state, anchor, 2.5)
end

function GameEffects.Kill.splatRays(state, position, count, color, distance, ignore, minimum, maximum, lifetime)
	local context, environment = state.context, state.context.environment
	local params = environment.RaycastParams.new()
	params.FilterType, params.RespectCanCollide = environment.Enum.RaycastFilterType.Exclude, true
	local excluded = {context.workspace.CurrentCamera, GameEffects.Kill.bodiesFolder(state)}
	for _, object in ignore or {} do if environment.typeof(object) == "Instance" then table.insert(excluded, object) end end
	params.FilterDescendantsInstances = excluded
	for index = 1, count do
		local direction = environment.Vector3.new(math.random() - 0.5, math.random() * 1.2 - 0.8, math.random() - 0.5).Unit
		local result = context.workspace:Raycast(position, direction * (distance or 14), params)
		if not result or result.Instance.Transparency >= 0.9 then continue end
		local model = result.Instance:FindFirstAncestorOfClass("Model")
		if model and model:FindFirstChildOfClass("Humanoid") then continue end
		local selected = type(color) == "function" and color(index) or color
		GameEffects.Kill.delay(state, result.Distance / 45, function()
			local size = (minimum or 1.2) + math.random() * ((maximum or 3) - (minimum or 1.2))
			GameEffects.Kill.groundDecal(state, result.Position, result.Normal, size, selected, lifetime or 3, 0.12, state.textures.splat, 2)
		end)
	end
end

function GameEffects.Kill.bloodRitual(state, effect)
	local environment = state.context.environment
	local red, blood = environment.Color3.fromRGB(230, 20, 40), environment.Color3.fromRGB(125, 0, 12)
	local body, model = GameEffects.Kill.staticBody(state, effect)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local highlight = model and GameEffects.Kill.highlight(state, model, red, environment.Color3.fromRGB(255, 120, 120), 0.7, 0.2)
	GameEffects.Kill.splat(state, effect.root, 10, red, 1.6, effect.ignore, 0.5, state.textures.mandala, 1)
	local ring = GameEffects.Kill.ringAtGround(state, effect.root, red, 9, 9, 1.5, state.textures.dial, effect.ignore)
	ring.RotSpeed = environment.NumberRange.new(90)
	local ground = GameEffects.Kill.ground(state, effect.root, effect.ignore) or effect.root - environment.Vector3.new(0, 3, 0)
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(ground + environment.Vector3.new(0, 0.3, 0)), environment.Vector3.new(7, 0.2, 7))
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
	local emitter = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.soft, Color = colors(red, environment.Color3.fromRGB(90, 0, 10)),
		Size = sequence(0, 0.35, 1, 0), Lifetime = environment.NumberRange.new(1, 1.6), Speed = environment.NumberRange.new(2, 5),
		SpreadAngle = environment.Vector2.new(5, 5), Shape = environment.Enum.ParticleEmitterShape.Box, Brightness = 4}, 0)
	emitter.Rate, emitter.Enabled = 60, true
	local frames = {}
	for index, part in body do frames[index] = part.CFrame end
	GameEffects.Kill.animate(state, 1.3, function(progress)
		local rotation = environment.CFrame.fromAxisAngle(environment.Vector3.new(0, 1, 0), progress * progress * 6)
		local rise = environment.Vector3.new(0, 3 * math.min(1, progress * 1.5), 0)
		for index, part in body do
			if part.Parent then part.CFrame = environment.CFrame.new(effect.chest + rise + rotation * (frames[index].Position - effect.chest)) * rotation * frames[index].Rotation end
		end
		if highlight then highlight.FillTransparency = 0.7 - 0.5 * progress end
	end, function()
		emitter.Enabled = false
		local position = effect.chest + environment.Vector3.new(0, 3, 0)
		for _, part in body do pcall(function() part:Destroy() end) end
		local burst, attachment = GameEffects.Kill.effectAttachment(state, position)
		GameEffects.Kill.particle(state, attachment, {Texture = state.textures.splat, Color = colors(environment.Color3.fromRGB(190, 10, 30), environment.Color3.fromRGB(100, 0, 12)),
			Size = sequence(0, 0.8, 1, 0.3), Lifetime = environment.NumberRange.new(0.7, 1.2), Speed = environment.NumberRange.new(16, 34),
			SpreadAngle = environment.Vector2.new(180, 180), Acceleration = environment.Vector3.new(0, -60, 0), Rotation = environment.NumberRange.new(0, 360),
			RotSpeed = environment.NumberRange.new(-200, 200), LightEmission = 0, Brightness = 1.2}, 80)
		GameEffects.Kill.particle(state, attachment, {Texture = state.textures.soft, Color = colors(environment.Color3.fromRGB(150, 0, 18)), Size = sequence(0, 3, 1, 9),
			Transparency = sequence(0, 0.35, 1, 1), Lifetime = environment.NumberRange.new(0.8, 1.2), Speed = environment.NumberRange.new(3, 7),
			SpreadAngle = environment.Vector2.new(180, 180), LightEmission = 0.3, Brightness = 1.2}, 12)
		GameEffects.Kill.flash(state, position, red, 16, 5)
		GameEffects.Kill.splatRays(state, position, 14, blood, 16, effect.ignore, 1.2, 3, 3.2)
		GameEffects.Kill.splat(state, effect.root, 6, blood, 3.2, effect.ignore, 0.8)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.guts, 1, 0.8, burst)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.spurt, 0.7, 0.6, burst)
		GameEffects.Kill.shakeCamera(state, position, 1.2, 0.35)
	end)
	GameEffects.Kill.light(state, anchor, red, 5, 18, 1.8)
	GameEffects.Kill.destroyLater(state, anchor, 2)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.whisper, 0.6, 0.5)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.ghostWind, 0.6, 0.5, nil, 2)
end

function GameEffects.Kill.disableCharacterCollisions(character)
	for _, part in character:GetDescendants() do
		if part:IsA("BasePart") then pcall(function() part.CanCollide, part.CollisionGroup = false, "Characters" end) end
	end
end

function GameEffects.Kill.ninja(state, effect)
	local context, environment = state.context, state.context.environment
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.chest), environment.Vector3.new(3, 5, 3))
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local white = environment.Color3.new(1, 1, 1)
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
	GameEffects.Kill.particle(state, anchor, {Texture = state.textures.smokeFB, FlipbookLayout = environment.Enum.ParticleFlipbookLayout.Grid4x4,
		FlipbookMode = environment.Enum.ParticleFlipbookMode.OneShot, Color = colors(environment.Color3.fromRGB(240, 240, 245), environment.Color3.fromRGB(170, 170, 180)),
		Size = sequence(0, 2.5, 1, 6.5), Transparency = sequence(0, 0.05, 0.7, 0.3, 1, 1), Lifetime = environment.NumberRange.new(0.9, 1.3),
		Speed = environment.NumberRange.new(3, 8), SpreadAngle = environment.Vector2.new(180, 180), Drag = 3, Rotation = environment.NumberRange.new(0, 360),
		Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0, LightInfluence = 0.9, Brightness = 1.3}, 24)
	GameEffects.Kill.particle(state, anchor, {Texture = state.textures.sparkBright, Color = colors(white), Size = sequence(0, 0.6, 1, 0),
		Lifetime = environment.NumberRange.new(0.2, 0.4), Speed = environment.NumberRange.new(12, 20), SpreadAngle = environment.Vector2.new(180, 180), Drag = 5, Brightness = 5}, 12)
	GameEffects.Kill.particle(state, anchor, {Texture = state.textures.leaf, Color = colors(environment.Color3.fromRGB(120, 200, 80), environment.Color3.fromRGB(70, 140, 50)),
		Size = sequence(0, 0.4, 1, 0.3), Lifetime = environment.NumberRange.new(1.4, 2.2), Speed = environment.NumberRange.new(4, 8),
		SpreadAngle = environment.Vector2.new(180, 180), Drag = 2.2, Acceleration = environment.Vector3.new(0, -4, 0), Rotation = environment.NumberRange.new(0, 360),
		RotSpeed = environment.NumberRange.new(-220, 220), LightEmission = 0, LightInfluence = 1, Brightness = 1.2}, 16)
	GameEffects.Kill.disableCharacterCollisions(effect.char)
	local log = environment.Instance.new("Part")
	log.Shape, log.Material, log.Color = environment.Enum.PartType.Cylinder, environment.Enum.Material.Wood, environment.Color3.fromRGB(125, 84, 48)
	log.Size = environment.Vector3.new(3.6, 1.25, 1.25)
	log.CFrame = environment.CFrame.new(effect.chest - environment.Vector3.new(0, 0.6, 0)) * environment.CFrame.Angles(0, math.random() * 6.28, math.pi / 2)
	log.CanQuery, log.CanTouch = false, false
	pcall(function() log.CollisionGroup = "Ragdolls" end)
	log.Parent = GameEffects.Kill.bodiesFolder(state)
	local direction = GameEffects.Kill.direction(state, effect)
	local function launch()
		if not log.Parent then return end
		log.AssemblyLinearVelocity = direction * 3 + environment.Vector3.new(0, 10, 0)
		log.AssemblyAngularVelocity = environment.Vector3.new(direction.Z, 0, -direction.X) * 5
	end
	launch()
	local connection
	connection = context.runService.Heartbeat:Connect(function() connection:Disconnect(); launch() end)
	GameEffects.Kill.delay(state, 0.55, function() GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.plop, 0.9, 0.55, log) end)
	GameEffects.Kill.delay(state, 2.6, function() if log.Parent then GameEffects.Kill.tween(state, log, 0.5, {Transparency = 1}) end end)
	GameEffects.Kill.destroyLater(state, log, 3.2)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.poof, 1, 1, anchor)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.whooshAiry, 0.5, 1.4, anchor)
	GameEffects.Kill.destroyLater(state, anchor, 2.5)
end

function GameEffects.Kill.petrify(state, effect)
	local context, environment = state.context, state.context.environment
	local color, black = environment.Color3.fromRGB(125, 122, 116), environment.Color3.new(0, 0, 0)
	local ground = GameEffects.Kill.ground(state, effect.root, effect.ignore)
	local height = ground and ground.Y or effect.root.Y - 3
	local body = GameEffects.Kill.staticBody(state, effect)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local top, copies, converted = effect.head.Y + 1, {}, {}
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.chest), environment.Vector3.new(2.4, 5, 1.6))
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(value) return environment.ColorSequence.new(value, value) end
	local emitter = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.soft, Color = colors(environment.Color3.fromRGB(160, 156, 150)),
		Size = sequence(0, 0.8, 1, 2), Transparency = sequence(0, 0.5, 1, 1), Lifetime = environment.NumberRange.new(0.5, 0.8),
		Speed = environment.NumberRange.new(0.5, 1.5), SpreadAngle = environment.Vector2.new(180, 180), Shape = environment.Enum.ParticleEmitterShape.Box,
		LightEmission = 0, LightInfluence = 1, Brightness = 1}, 0)
	emitter.Rate, emitter.Enabled = 30, true
	local function convert(part)
		converted[part] = true
		local copy = GameEffects.Kill.materialCopy(state, part, environment.Enum.Material.Slate, color:Lerp(black, math.random() * 0.18), 0, 0)
		if copy then table.insert(copies, copy) end
		part.Transparency = 1
		for _, child in part:GetChildren() do if child:IsA("Decal") then child.Transparency = 1 end end
	end
	GameEffects.Kill.animate(state, 0.55, function(progress)
		local y = height + (top - height) * progress
		for _, part in body do
			if not converted[part] and part.Parent and part.Position.Y - part.Size.Y * 0.3 < y then convert(part) end
		end
	end, function()
		for _, part in body do if not converted[part] and part.Parent then convert(part) end end
		emitter.Enabled = false
		GameEffects.Kill.particle(state, anchor, {Texture = state.textures.cracks, Color = colors(environment.Color3.fromRGB(40, 38, 36)),
			Size = sequence(0, 1.3, 1, 1.5), Transparency = sequence(0, 0.2, 0.8, 0.3, 1, 1), Lifetime = environment.NumberRange.new(0.5),
			Rotation = environment.NumberRange.new(0, 360), Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0, Brightness = 1, ZOffset = 0.6}, 10)
	end)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.rocks, 0.6, 0.55, anchor)
	GameEffects.Kill.delay(state, 1.05, function()
		for _, part in body do pcall(function() part:Destroy() end) end
		GameEffects.Kill.disableCharacterCollisions(effect.char)
		local falling = {}
		for _, part in copies do
			if not part.Parent then continue end
			part.Size, part.Anchored, part.CanCollide, part.CanQuery, part.CanTouch = part.Size * 0.9, false, true, false, false
			pcall(function() part.CollisionGroup = "Ragdolls" end)
			part.Parent = GameEffects.Kill.bodiesFolder(state)
			table.insert(falling, part)
			GameEffects.Kill.delay(state, 1.7 + math.random() * 0.5, function()
				if part.Parent then GameEffects.Kill.tween(state, part, 0.4, {Size = part.Size * 0.2, Transparency = 1}) end
			end)
			GameEffects.Kill.destroyLater(state, part, 2.8)
		end
		local function launch()
			for _, part in falling do
				if not part.Parent then continue end
				local offset = part.Position - effect.chest
				part.AssemblyLinearVelocity = environment.Vector3.new(offset.X, 0, offset.Z) * 2 + environment.Vector3.new(0, 2 + math.random() * 4, 0)
				part.AssemblyAngularVelocity = GameEffects.Kill.randomVector(state, 4)
			end
		end
		launch()
		local connection
		connection = context.runService.Heartbeat:Connect(function() connection:Disconnect(); launch() end)
		GameEffects.Kill.particle(state, anchor, {Texture = state.textures.rock, Color = colors(environment.Color3.fromRGB(110, 106, 100)),
			Size = sequence(0, 0.5, 1, 0.3), Lifetime = environment.NumberRange.new(0.6, 1), Speed = environment.NumberRange.new(6, 14),
			SpreadAngle = environment.Vector2.new(180, 180), Acceleration = environment.Vector3.new(0, -60, 0), Rotation = environment.NumberRange.new(0, 360),
			RotSpeed = environment.NumberRange.new(-300, 300), Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0, LightInfluence = 1, Brightness = 1}, 26)
		GameEffects.Kill.particle(state, anchor, {Texture = state.textures.smokeFB, FlipbookLayout = environment.Enum.ParticleFlipbookLayout.Grid4x4,
			FlipbookMode = environment.Enum.ParticleFlipbookMode.OneShot, Color = colors(environment.Color3.fromRGB(170, 165, 158)),
			Size = sequence(0, 2.5, 1, 6), Transparency = sequence(0, 0.2, 0.7, 0.45, 1, 1), Lifetime = environment.NumberRange.new(1, 1.5),
			Speed = environment.NumberRange.new(2, 5), SpreadAngle = environment.Vector2.new(180, 180), Drag = 2, Rotation = environment.NumberRange.new(0, 360),
			Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0, LightInfluence = 1, Brightness = 1}, 12)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.quakeDebris, 1, 0.9, anchor)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.rocks, 0.6, 0.7, anchor)
		GameEffects.Kill.shakeCamera(state, effect.chest, 0.7, 0.3)
	end)
	GameEffects.Kill.destroyLater(state, anchor, 3.5)
end

function GameEffects.Kill.blackHole(state, effect)
	local environment = state.context.environment
	local purple, orange, white = environment.Color3.fromRGB(150, 70, 255), environment.Color3.fromRGB(255, 150, 60), environment.Color3.new(1, 1, 1)
	local center = effect.chest + GameEffects.Kill.direction(state, effect) * 3 + environment.Vector3.new(0, 1.3, 0)
	local body = GameEffects.Kill.staticBody(state, effect)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local core = environment.Instance.new("Part")
	core.Shape, core.Anchored, core.CanCollide, core.CanQuery, core.CanTouch, core.CastShadow = environment.Enum.PartType.Ball, true, false, false, false, false
	core.Material, core.Color, core.Size, core.CFrame = environment.Enum.Material.Neon, environment.Color3.new(0, 0, 0), environment.Vector3.new(0.1, 0.1, 0.1), environment.CFrame.new(center)
	core.Parent = GameEffects.Kill.folder(state)
	local glow = core:Clone()
	glow.Color, glow.Transparency, glow.Parent = purple, 0.55, GameEffects.Kill.folder(state)
	GameEffects.Kill.tween(state, core, 0.3, {Size = environment.Vector3.new(2.4, 2.4, 2.4)}, environment.Enum.EasingStyle.Back)
	GameEffects.Kill.tween(state, glow, 0.3, {Size = environment.Vector3.new(3, 3, 3)}, environment.Enum.EasingStyle.Back)
	local frame = environment.CFrame.new(center) * environment.CFrame.Angles(math.rad(22), math.random() * 6.28, math.rad(12))
	local axis = frame.UpVector
	local ringAnchor = GameEffects.Kill.anchor(state, frame, environment.Vector3.new(1, 1, 1))
	local attachment = environment.Instance.new("Attachment")
	attachment.Parent = ringAnchor
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
	GameEffects.Kill.particle(state, attachment, {Texture = state.textures.vortex, Color = colors(orange, purple), Size = sequence(0, 6.5, 1, 6.5),
		Transparency = sequence(0, 1, 0.15, 0.15, 0.85, 0.2, 1, 1), Lifetime = environment.NumberRange.new(1.6), Speed = environment.NumberRange.new(0.01),
		EmissionDirection = environment.Enum.NormalId.Top, Orientation = environment.Enum.ParticleOrientation.VelocityPerpendicular,
		RotSpeed = environment.NumberRange.new(-260), Brightness = 4, ZOffset = 0.5}, 1, 0.05)
	GameEffects.Kill.particle(state, attachment, {Texture = state.textures.ringEdge, Color = colors(purple), Size = sequence(0, 7.5, 1, 7.5),
		Transparency = sequence(0, 1, 0.15, 0.3, 0.85, 0.35, 1, 1), Lifetime = environment.NumberRange.new(1.6), Speed = environment.NumberRange.new(0.01),
		EmissionDirection = environment.Enum.NormalId.Top, Orientation = environment.Enum.ParticleOrientation.VelocityPerpendicular,
		RotSpeed = environment.NumberRange.new(180), Brightness = 3}, 1, 0.05)
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(center), environment.Vector3.new(9, 9, 9))
	local emitter = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.spark, Color = colors(orange, purple),
		Size = sequence(0, 0.5, 1, 0.1), Transparency = sequence(0, 0.2, 1, 0.6), Lifetime = environment.NumberRange.new(0.35, 0.5),
		Speed = environment.NumberRange.new(10, 16), Shape = environment.Enum.ParticleEmitterShape.Sphere, ShapeStyle = environment.Enum.ParticleEmitterShapeStyle.Surface,
		ShapeInOut = environment.Enum.ParticleEmitterShapeInOut.Inward, Orientation = environment.Enum.ParticleOrientation.VelocityParallel, Brightness = 4}, 0)
	emitter.Rate, emitter.Enabled = 90, true
	local parts = {}
	for index, part in body do
		local offset = part.Position - center
		parts[index] = {frame = part.CFrame, offset = offset, size = part.Size, delay = 0.25 + math.clamp(offset.Magnitude / 6, 0, 1) * 0.35,
			duration = 0.7 + math.random() * 0.25, spin = (math.random() - 0.5) * 8}
	end
	GameEffects.Kill.animate(state, 1.45, function(progress)
		for index, part in body do
			local data = parts[index]
			local amount = math.clamp((progress * 1.45 - data.delay) / data.duration, 0, 1)
			if amount <= 0 or not part.Parent then continue end
			local eased = amount * amount
			local rotation = environment.CFrame.fromAxisAngle(axis, eased * 4.5)
			part.CFrame = environment.CFrame.new(center + rotation * (data.offset * (1 - eased))) * rotation * data.frame.Rotation
				* environment.CFrame.Angles(data.spin * eased, 0, data.spin * eased * 0.5)
			part.Size = data.size * (1 - 0.85 * eased)
			part.Transparency = eased > 0.85 and (eased - 0.85) / 0.15 or 0
		end
	end)
	GameEffects.Kill.delay(state, 1.45, function()
		emitter.Enabled = false
		for _, part in body do pcall(function() part:Destroy() end) end
		GameEffects.Kill.tween(state, core, 0.15, {Size = environment.Vector3.new(0.05, 0.05, 0.05)}, environment.Enum.EasingStyle.Quad, environment.Enum.EasingDirection.In)
		GameEffects.Kill.tween(state, glow, 0.15, {Size = environment.Vector3.new(0.05, 0.05, 0.05), Transparency = 1}, environment.Enum.EasingStyle.Quad, environment.Enum.EasingDirection.In)
		GameEffects.Kill.destroyLater(state, core, 0.2)
		GameEffects.Kill.destroyLater(state, glow, 0.2)
		GameEffects.Kill.delay(state, 0.15, function()
			local burst = GameEffects.Kill.anchor(state, environment.CFrame.new(center), environment.Vector3.new(1, 1, 1))
			local burstAttachment = environment.Instance.new("Attachment")
			burstAttachment.Parent = burst
			GameEffects.Kill.particle(state, burstAttachment, {Texture = state.textures.core, Color = colors(white, purple), Size = sequence(0, 1, 1, 12),
				Transparency = sequence(0, 0, 1, 1), Lifetime = environment.NumberRange.new(0.4), Rotation = environment.NumberRange.new(0, 360), Brightness = 5, ZOffset = 1}, 2)
			GameEffects.Kill.particle(state, burstAttachment, {Texture = state.textures.ring, Color = colors(purple), Size = sequence(0, 1, 1, 16),
				Transparency = sequence(0, 0, 1, 1), Lifetime = environment.NumberRange.new(0.5), Brightness = 4}, 1)
			GameEffects.Kill.particle(state, burstAttachment, {Texture = state.textures.sparkBright, Color = colors(white, purple), Size = sequence(0, 0.8, 1, 0),
				Lifetime = environment.NumberRange.new(0.4, 0.8), Speed = environment.NumberRange.new(18, 34), SpreadAngle = environment.Vector2.new(180, 180),
				Drag = 3, Orientation = environment.Enum.ParticleOrientation.VelocityParallel, Brightness = 5}, 36)
			GameEffects.Kill.light(state, burst, purple, 10, 30, 0.6)
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.boomDeep, 0.8, 0.75, burst)
			GameEffects.Kill.shakeCamera(state, center, 1.4, 0.4)
			GameEffects.Kill.destroyLater(state, burst, 1.5)
		end)
	end)
	GameEffects.Kill.light(state, ringAnchor, purple, 5, 16, 1.6)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.vortexBlast, 0.7, 0.55, ringAnchor)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.suck, 0.6, 0.4, ringAnchor)
	GameEffects.Kill.destroyLater(state, ringAnchor, 2.2)
	GameEffects.Kill.destroyLater(state, anchor, 2.2)
end

function GameEffects.Kill.midas(state, effect)
	local environment = state.context.environment
	local gold, pale, white = environment.Color3.fromRGB(255, 190, 60), environment.Color3.fromRGB(255, 236, 160), environment.Color3.new(1, 1, 1)
	local ground = GameEffects.Kill.ground(state, effect.root, effect.ignore)
	local height = ground and ground.Y or effect.root.Y - 3
	local body = GameEffects.Kill.staticBody(state, effect)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local top = effect.head.Y + 1
	local disk = GameEffects.Kill.disc(state, environment.CFrame.new(effect.root.X, height + 0.1, effect.root.Z), 3.6, pale, environment.Enum.Material.Neon, 0.3)
	disk.Size = environment.Vector3.new(0.06, 3.6, 3.6)
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.chest), environment.Vector3.new(2.4, 5, 1.6))
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
	local emitter = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.star4, Color = colors(white, pale),
		Size = sequence(0, 0, 0.5, 1.1, 1, 0), Lifetime = environment.NumberRange.new(0.35, 0.5), Rotation = environment.NumberRange.new(0, 90),
		Shape = environment.Enum.ParticleEmitterShape.Box, ShapeStyle = environment.Enum.ParticleEmitterShapeStyle.Volume, Brightness = 5, ZOffset = 1.5}, 0)
	emitter.Rate, emitter.Enabled = 18, true
	local converted, copies = {}, {}
	local function convert(part)
		converted[part] = true
		local clone = GameEffects.Kill.materialCopy(state, part, environment.Enum.Material.Foil, gold, 0.35, 0)
		if clone then table.insert(copies, clone) end
		part.Transparency = 1
		for _, child in part:GetChildren() do if child:IsA("Decal") then child.Transparency = 1 end end
	end
	GameEffects.Kill.animate(state, 0.6, function(progress)
		local y = height + (top - height) * progress
		disk.CFrame = environment.CFrame.new(effect.root.X, y, effect.root.Z) * environment.CFrame.Angles(0, 0, math.pi / 2)
		for _, part in body do
			if not converted[part] and part.Parent and part.Position.Y - part.Size.Y * 0.3 < y then convert(part) end
		end
	end, function()
		for _, part in body do if not converted[part] and part.Parent then convert(part) end end
		if disk.Parent then GameEffects.Kill.tween(state, disk, 0.2, {Transparency = 1}) end
		GameEffects.Kill.destroyLater(state, disk, 0.25)
		local attachment = environment.Instance.new("Attachment")
		attachment.Parent, attachment.WorldPosition = anchor, effect.head + environment.Vector3.new(0.3, 0.3, 0)
		GameEffects.Kill.particle(state, attachment, {Texture = state.textures.star4, Color = colors(white), Size = sequence(0, 0, 0.3, 4, 1, 0),
			Lifetime = environment.NumberRange.new(0.45), RotSpeed = environment.NumberRange.new(120), Brightness = 8, ZOffset = 2}, 1)
	end)
	GameEffects.Kill.delay(state, 1.3, function()
		emitter.Enabled = false
		for _, parts in {copies, body} do for _, part in parts do pcall(function() part:Destroy() end) end end
		GameEffects.Kill.scatter(state, effect.chest, 34, gold, environment.Enum.Material.Foil, 6, 1.2)
		GameEffects.Kill.particle(state, anchor, {Texture = state.textures.sparkBright, Color = colors(white, gold), Size = sequence(0, 0.7, 1, 0),
			Lifetime = environment.NumberRange.new(0.3, 0.6), Speed = environment.NumberRange.new(10, 20), SpreadAngle = environment.Vector2.new(180, 180),
			Drag = 4, Shape = environment.Enum.ParticleEmitterShape.Box, Brightness = 5}, 24)
		GameEffects.Kill.particle(state, anchor, {Texture = state.textures.square, Color = colors(pale, gold), Size = sequence(0, 0.18, 1, 0),
			Lifetime = environment.NumberRange.new(0.8, 1.3), Speed = environment.NumberRange.new(1, 3), SpreadAngle = environment.Vector2.new(180, 180),
			Acceleration = environment.Vector3.new(0, -8, 0), Shape = environment.Enum.ParticleEmitterShape.Box,
			ShapeStyle = environment.Enum.ParticleEmitterShapeStyle.Volume, Brightness = 3}, 40)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.glass, 0.9, 0.85, anchor)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.cash, 0.5, 1.2, anchor)
	end)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.shopbell, 0.6, 1, anchor)
	GameEffects.Kill.light(state, anchor, gold, 5, 14, 1.8)
	GameEffects.Kill.destroyLater(state, anchor, 3.5)
end

function GameEffects.Kill.tornado(state, effect)
	local environment = state.context.environment
	local ground = GameEffects.Kill.ground(state, effect.root, effect.ignore)
	local height = ground and ground.Y or effect.root.Y - 3
	local position = environment.Vector3.new(effect.root.X, height, effect.root.Z)
	local body = GameEffects.Kill.body(state, effect, environment.Vector3.new(0, 8, 0), nil, 3.4)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local clouds = {}
	for index = 1, 7 do
		local y = (index - 1) * 2
		local radius = 0.8 + y * 0.3
		local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(position + environment.Vector3.new(radius, y, 0)), environment.Vector3.new(0.6, 0.6, 0.6))
		local emitter = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.soft,
			Color = environment.ColorSequence.new(environment.Color3.fromRGB(215, 215, 222), environment.Color3.fromRGB(150, 150, 162)),
			Size = sequence(0, 0.9 + y * 0.12, 1, 1.6 + y * 0.18), Transparency = sequence(0, 0.45, 1, 1),
			Lifetime = environment.NumberRange.new(0.5, 0.7), Speed = environment.NumberRange.new(0.2), LightEmission = 0, LightInfluence = 0.8, Brightness = 1.2}, 0)
		emitter.Rate, emitter.Enabled = 55, true
		table.insert(clouds, {anchor = anchor, emitter = emitter, height = y, radius = radius, phase = math.random() * 6.28})
	end
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(position + environment.Vector3.new(0, 0.3, 0)), environment.Vector3.new(5, 0.4, 5))
	local attachment = environment.Instance.new("Attachment")
	attachment.Parent = anchor
	local rockColor = environment.Color3.fromRGB(90, 84, 78)
	local rocks = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.rock, Color = environment.ColorSequence.new(rockColor, rockColor),
		Size = sequence(0, 0.35, 1, 0.25), Lifetime = environment.NumberRange.new(0.8, 1.2), Speed = environment.NumberRange.new(8, 14),
		SpreadAngle = environment.Vector2.new(20, 20), Acceleration = environment.Vector3.new(0, -12, 0), Rotation = environment.NumberRange.new(0, 360),
		RotSpeed = environment.NumberRange.new(-400, 400), Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0, LightInfluence = 1, Brightness = 1}, 0)
	rocks.Rate, rocks.Enabled = 22, true
	local ring = GameEffects.Kill.groundRing(state, attachment, state.textures.vortex, environment.Color3.fromRGB(200, 200, 210), 3, 9, 1.6, 1.5)
	ring.RotSpeed = environment.NumberRange.new(-300)
	GameEffects.Kill.animate(state, 1.8, function(progress)
		local elapsed = progress * 1.8
		local scale = math.min(1, elapsed / 0.3) * (elapsed > 1.5 and math.max(0, 1 - (elapsed - 1.5) / 0.3) or 1)
		for _, cloud in clouds do
			local angle = cloud.phase + elapsed * 11
			cloud.anchor.CFrame = environment.CFrame.new(position + environment.Vector3.new(math.cos(angle) * cloud.radius * scale, cloud.height * scale, math.sin(angle) * cloud.radius * scale))
		end
		if not body or elapsed >= 1.35 then return end
		for _, part in body.body do
			if not part.Parent then continue end
			local offset = part.Position - position
			local horizontal = environment.Vector3.new(offset.X, 0, offset.Z)
			local distance = horizontal.Magnitude
			local radial = distance > 0.05 and horizontal / distance or environment.Vector3.new(1, 0, 0)
			part.AssemblyLinearVelocity = environment.Vector3.new(-radial.Z, 0, radial.X) * 24 + radial * (2.2 - distance) * 6
				+ environment.Vector3.new(0, offset.Y < 9 and 9 or 0, 0)
		end
	end, function()
		for _, cloud in clouds do cloud.emitter.Enabled = false; GameEffects.Kill.destroyLater(state, cloud.anchor, 1) end
		rocks.Enabled = false
	end)
	GameEffects.Kill.delay(state, 1.35, function()
		if not body or not body.torso or not body.torso.Parent then return end
		local offset = body.torso.Position - position
		local horizontal = environment.Vector3.new(offset.X, 0, offset.Z)
		local direction = horizontal.Magnitude > 0.05 and horizontal.Unit or GameEffects.Kill.direction(state, effect)
		for _, part in body.body do pcall(function() part.AssemblyLinearVelocity = direction * 55 + environment.Vector3.new(0, 22, 0) end) end
		pcall(function() body.torso.AssemblyAngularVelocity = GameEffects.Kill.randomVector(state, 8) end)
	end)
	local sound = GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.windHowl, 0.6, 0.45, anchor, 2)
	GameEffects.Kill.delay(state, 1.8, function() if sound and sound.Parent then GameEffects.Kill.tween(state, sound, 0.4, {Volume = 0}) end end)
	GameEffects.Kill.shakeCamera(state, position, 0.45, 1.4)
	GameEffects.Kill.destroyLater(state, anchor, 3)
end

function GameEffects.Kill.hologram(state, effect)
	local environment = state.context.environment
	local color, white = environment.Color3.fromRGB(40, 230, 255), environment.Color3.new(1, 1, 1)
	local ground = GameEffects.Kill.ground(state, effect.root, effect.ignore)
	local height = ground and ground.Y or effect.root.Y - 3
	local hologram = GameEffects.Kill.ghost(state, effect.char, {material = environment.Enum.Material.Neon, color = color, transparency = 0.72})
	local field = GameEffects.Kill.ghost(state, effect.char, {material = environment.Enum.Material.ForceField, color = color, transparency = 0})
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local parts = {}
	for _, part in hologram do table.insert(parts, part) end
	for _, part in field do table.insert(parts, part) end
	environment.task.spawn(function()
		for index = 1, 4 do
			for _, part in hologram do if part.Parent then part.Transparency = index % 2 == 0 and 0.72 or 0.9 end end
			environment.task.wait(0.05 / state.speed)
		end
	end)
	local top = effect.head.Y + 0.9
	local scanner = environment.Instance.new("Part")
	scanner.Anchored, scanner.CanCollide, scanner.CanQuery, scanner.CanTouch, scanner.CastShadow = true, false, false, false, false
	scanner.Material, scanner.Color, scanner.Transparency, scanner.Size = environment.Enum.Material.Neon, color, 0.35, environment.Vector3.new(4.2, 0.05, 4.2)
	scanner.CFrame, scanner.Parent = environment.CFrame.new(effect.root.X, top, effect.root.Z), GameEffects.Kill.folder(state)
	local glow = scanner:Clone()
	glow.Transparency, glow.Size, glow.Parent = 0.82, environment.Vector3.new(5.6, 0.03, 5.6), GameEffects.Kill.folder(state)
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.chest), environment.Vector3.new(1, 1, 1))
	local emitter = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.square, Color = environment.ColorSequence.new(white, color),
		Size = GameEffects.Kill.numberSequence(state, 0, 0.22, 1, 0), Lifetime = environment.NumberRange.new(0.4, 0.8),
		Speed = environment.NumberRange.new(1.5, 4), SpreadAngle = environment.Vector2.new(180, 180), Acceleration = environment.Vector3.new(0, 5, 0), Drag = 2,
		Shape = environment.Enum.ParticleEmitterShape.Box, ShapeStyle = environment.Enum.ParticleEmitterShapeStyle.Volume, Brightness = 4}, 0)
	local scanned = {}
	GameEffects.Kill.delay(state, 0.22, function()
		GameEffects.Kill.animate(state, 0.85, function(progress)
			local y = top + (height - top) * progress
			scanner.CFrame = environment.CFrame.new(effect.root.X, y, effect.root.Z)
			glow.CFrame = scanner.CFrame
			for _, part in parts do
				if scanned[part] or not part.Parent or part.Position.Y <= y then continue end
				scanned[part] = true
				if part.Material == environment.Enum.Material.Neon then
					anchor.CFrame, anchor.Size = part.CFrame, part.Size
					emitter:Emit(math.clamp(math.floor(part.Size.X * part.Size.Y * part.Size.Z * 3), 3, 12))
				end
				part.Transparency = 1
				GameEffects.Kill.destroyLater(state, part, 0.1)
			end
		end, function()
			for _, part in {scanner, glow} do
				if part.Parent then GameEffects.Kill.tween(state, part, 0.2, {Transparency = 1, Size = environment.Vector3.new(6.5, 0.02, 6.5)}) end
				GameEffects.Kill.destroyLater(state, part, 0.25)
			end
			for _, part in parts do pcall(function() part:Destroy() end) end
			local floor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.root.X, height + 0.1, effect.root.Z), environment.Vector3.new(1, 0.2, 1))
			GameEffects.Kill.groundRing(state, floor, state.textures.ring, color, 1, 8, 0.45, 4)
			GameEffects.Kill.destroyLater(state, floor, 1)
		end)
	end)
	GameEffects.Kill.light(state, anchor, color, 4, 12, 1.2)
	GameEffects.Kill.cameraClicks(state, anchor, 5)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.sciSynth, 0.4, 0.7, anchor, 1.8)
	GameEffects.Kill.destroyLater(state, anchor, 2.5)
end

function GameEffects.Kill.shadow(state, effect)
	local context, environment = state.context, state.context.environment
	local dark, purple = environment.Color3.fromRGB(8, 6, 12), environment.Color3.fromRGB(140, 60, 255)
	local ground = GameEffects.Kill.ground(state, effect.root, effect.ignore)
	local height = ground and ground.Y or effect.root.Y - 3
	local parts = GameEffects.Kill.ghost(state, effect.char, {material = environment.Enum.Material.SmoothPlastic, color = dark, transparency = 0})
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local camera = context.workspace.CurrentCamera
	local right = camera and camera.CFrame.RightVector or environment.Vector3.new(1, 0, 0)
	local view = camera and (camera.CFrame.Position - effect.head).Unit or environment.Vector3.new(0, 0, 1)
	for side = -1, 1, 2 do
		local eye = environment.Instance.new("Part")
		eye.Shape, eye.Anchored, eye.CanCollide, eye.CanQuery, eye.CanTouch, eye.CastShadow = environment.Enum.PartType.Ball, true, false, false, false, false
		eye.Material, eye.Color, eye.Size = environment.Enum.Material.Neon, environment.Color3.fromRGB(255, 30, 50), environment.Vector3.new(0.05, 0.05, 0.05)
		eye.CFrame = environment.CFrame.new(effect.head + view * 0.62 + right * 0.2 * side + environment.Vector3.new(0, 0.1, 0))
		eye.Parent = GameEffects.Kill.folder(state)
		GameEffects.Kill.tween(state, eye, 0.15, {Size = environment.Vector3.new(0.26, 0.26, 0.26)}, environment.Enum.EasingStyle.Back)
		GameEffects.Kill.delay(state, 0.45, function()
			if eye.Parent then GameEffects.Kill.tween(state, eye, 0.2, {Size = environment.Vector3.new(0.02, 0.02, 0.02), Transparency = 1}) end
		end)
		GameEffects.Kill.destroyLater(state, eye, 0.8)
	end
	GameEffects.Kill.delay(state, 0.4, function()
		for _, part in parts do
			if not part.Parent then continue end
			local duration = 0.5 + math.clamp((part.Position.Y - height) / 6, 0, 1) * 0.5
			GameEffects.Kill.tween(state, part, duration, {CFrame = environment.CFrame.new(part.Position.X, height + 0.1, part.Position.Z) * part.CFrame.Rotation,
				Size = environment.Vector3.new(part.Size.X * 1.5, 0.1, part.Size.Z * 1.5)}, environment.Enum.EasingStyle.Quad, environment.Enum.EasingDirection.In)
			GameEffects.Kill.delay(state, duration, function() if part.Parent then GameEffects.Kill.tween(state, part, 0.8, {Transparency = 1}) end end)
			GameEffects.Kill.destroyLater(state, part, duration + 0.9)
		end
	end)
	GameEffects.Kill.delay(state, 0.45, function() GameEffects.Kill.splat(state, effect.root, 5.5, dark, 1.4, effect.ignore, 0.8) end)
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.root.X, height + 0.2, effect.root.Z), environment.Vector3.new(3.5, 0.2, 3.5))
	GameEffects.Kill.particle(state, anchor, {Texture = state.textures.ribbon, Color = colors(environment.Color3.fromRGB(60, 20, 90), environment.Color3.fromRGB(10, 5, 20)),
		Size = sequence(0, 0.8, 0.4, 1.4, 1, 0.3), Transparency = sequence(0, 0.3, 1, 1), Lifetime = environment.NumberRange.new(0.8, 1.3),
		Speed = environment.NumberRange.new(4, 8), SpreadAngle = environment.Vector2.new(10, 10), Orientation = environment.Enum.ParticleOrientation.VelocityParallel,
		Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0.3, Brightness = 1.5}, 18, 0.5)
	GameEffects.Kill.particle(state, anchor, {Texture = state.textures.smokeFB, FlipbookLayout = environment.Enum.ParticleFlipbookLayout.Grid4x4,
		FlipbookMode = environment.Enum.ParticleFlipbookMode.OneShot, Color = colors(environment.Color3.fromRGB(14, 10, 20)), Size = sequence(0, 2, 1, 4),
		Transparency = sequence(0, 0.25, 0.7, 0.45, 1, 1), Lifetime = environment.NumberRange.new(0.9, 1.3), Speed = environment.NumberRange.new(1, 2.5),
		SpreadAngle = environment.Vector2.new(50, 50), Rotation = environment.NumberRange.new(0, 360), Shape = environment.Enum.ParticleEmitterShape.Box,
		LightEmission = 0, Brightness = 1}, 10, 0.4)
	local attachment = environment.Instance.new("Attachment")
	attachment.Parent = anchor
	GameEffects.Kill.delay(state, 0.5, function()
		if attachment.Parent then GameEffects.Kill.groundRing(state, attachment, state.textures.ringEdge, purple, 1, 7, 0.8, 2) end
	end)
	GameEffects.Kill.light(state, anchor, purple, 3, 12, 1.4)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.slime, 0.8, 0.7, anchor)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.ghostWind, 0.6, 0.8, anchor, 1.8)
	GameEffects.Kill.destroyLater(state, anchor, 3)
end

function GameEffects.Kill.portalDisk(state, position, normal, color)
	local environment = state.context.environment
	local reference = math.abs(normal.Z) < 0.9 and environment.Vector3.new(0, 0, 1) or environment.Vector3.new(1, 0, 0)
	local frame = environment.CFrame.fromMatrix(position, normal:Cross(reference).Unit, normal)
	local outer = GameEffects.Kill.disc(state, frame, 0.2, color, environment.Enum.Material.Neon, 0)
	local inner = GameEffects.Kill.disc(state, frame + normal * 0.03, 0.15, environment.Color3.new(0, 0, 0), environment.Enum.Material.Neon, 0)
	GameEffects.Kill.tween(state, outer, 0.25, {Size = environment.Vector3.new(0.05, 4.6, 4.6)}, environment.Enum.EasingStyle.Back)
	GameEffects.Kill.tween(state, inner, 0.25, {Size = environment.Vector3.new(0.06, 3.9, 3.9)}, environment.Enum.EasingStyle.Back)
	local anchor = GameEffects.Kill.anchor(state, frame + normal * 0.08, environment.Vector3.new(1, 0.1, 1))
	local attachment = environment.Instance.new("Attachment")
	attachment.Parent = anchor
	local ring = GameEffects.Kill.groundRing(state, attachment, state.textures.vortex, color, 3.8, 3.8, 1.3, 3)
	ring.RotSpeed = environment.NumberRange.new(-320)
	GameEffects.Kill.particle(state, anchor, {Texture = state.textures.spark, Color = environment.ColorSequence.new(environment.Color3.new(1, 1, 1), color),
		Size = GameEffects.Kill.numberSequence(state, 0, 0.4, 1, 0), Lifetime = environment.NumberRange.new(0.3, 0.6),
		Speed = environment.NumberRange.new(3, 7), SpreadAngle = environment.Vector2.new(60, 60), Brightness = 4}, 14)
	GameEffects.Kill.light(state, anchor, color, 5, 12, 1.2)
	return function()
		for _, part in {outer, inner} do
			if part.Parent then GameEffects.Kill.tween(state, part, 0.2, {Size = environment.Vector3.new(0.05, 0.05, 0.05)}, environment.Enum.EasingStyle.Quad, environment.Enum.EasingDirection.In) end
			GameEffects.Kill.destroyLater(state, part, 0.25)
		end
		GameEffects.Kill.destroyLater(state, anchor, 0.3)
	end
end

function GameEffects.Kill.portal(state, effect)
	local context, environment = state.context, state.context.environment
	local orange, blue = environment.Color3.fromRGB(255, 140, 30), environment.Color3.fromRGB(40, 160, 255)
	local ground, normal = GameEffects.Kill.ground(state, effect.root, effect.ignore)
	ground, normal = ground or effect.root - environment.Vector3.new(0, 3, 0), normal or environment.Vector3.new(0, 1, 0)
	local closeGround = GameEffects.Kill.portalDisk(state, ground + normal * 0.03, normal, orange)
	local body = GameEffects.Kill.body(state, effect, environment.Vector3.new(0, -6, 0), GameEffects.Kill.randomVector(state, 2), 3.4, function(result)
		for _, part in result.parts do part.CanCollide = false end
	end)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	local direction = GameEffects.Kill.direction(state, effect)
	local exitGround = GameEffects.Kill.ground(state, effect.root + direction * 6, effect.ignore) or ground + direction * 6
	local params = environment.RaycastParams.new()
	params.FilterType, params.RespectCanCollide = environment.Enum.RaycastFilterType.Exclude, true
	params.FilterDescendantsInstances = {effect.char, context.workspace.CurrentCamera, GameEffects.Kill.bodiesFolder(state)}
	local hit = context.workspace:Raycast(exitGround + environment.Vector3.new(0, 0.5, 0), environment.Vector3.new(0, 14, 0), params)
	local height = hit and math.max(4.5, hit.Distance - 1) or 11
	local exit = exitGround + environment.Vector3.new(0, math.min(height, 11), 0)
	GameEffects.Kill.delay(state, 0.35, function()
		local closeExit = GameEffects.Kill.portalDisk(state, exit, environment.Vector3.new(0, -1, 0), blue)
		GameEffects.Kill.delay(state, 0.2, function()
			if body and body.model.Parent and body.torso and body.torso.Parent then
				local offset = exit - environment.Vector3.new(0, 1.4, 0) - body.torso.Position
				for _, part in body.body do
					pcall(function()
						part.CFrame += offset
						part.CanCollide = true
						part.AssemblyLinearVelocity = environment.Vector3.new(0, -22, 0) + direction * 3
					end)
				end
			end
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.teleport, 0.8, 1.3)
		end)
		GameEffects.Kill.delay(state, 1.2, closeExit)
	end)
	GameEffects.Kill.delay(state, 0.9, closeGround)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.teleport, 1, 0.9)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.whooshAiry, 0.6, 0.7)
end

function GameEffects.Kill.blastOff(state, effect)
	local environment = state.context.environment
	local ground = GameEffects.Kill.ground(state, effect.root, effect.ignore)
	local height = ground and ground.Y or effect.root.Y - 3
	local direction = GameEffects.Kill.direction(state, effect)
	local side = environment.Vector3.new(-direction.Z, 0, direction.X) * (math.random() < 0.5 and -1 or 1)
	local body = GameEffects.Kill.body(state, effect, direction * 26 + side * 6 + environment.Vector3.new(0, 95, 0), GameEffects.Kill.randomVector(state, 10), 2.6)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	GameEffects.Kill.upForce(state, body, 0.55)
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
	local white = environment.Color3.new(1, 1, 1)
	local groundAnchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.root.X, height + 0.3, effect.root.Z), environment.Vector3.new(2, 0.4, 2))
	local attachment = environment.Instance.new("Attachment")
	attachment.Parent = groundAnchor
	GameEffects.Kill.particle(state, attachment, {Texture = state.textures.core,
		Color = colors(environment.Color3.fromRGB(255, 240, 200), environment.Color3.fromRGB(255, 150, 60)),
		Size = sequence(0, 1.5, 1, 6), Transparency = sequence(0, 0, 1, 1), Lifetime = environment.NumberRange.new(0.3),
		Rotation = environment.NumberRange.new(0, 360), Brightness = 4}, 2)
	GameEffects.Kill.particle(state, groundAnchor, {Texture = state.textures.soft,
		Color = colors(environment.Color3.fromRGB(250, 250, 250), environment.Color3.fromRGB(200, 200, 205)),
		Size = sequence(0, 1.5, 1, 4), Transparency = sequence(0, 0.1, 1, 1), Lifetime = environment.NumberRange.new(0.6, 0.9),
		Speed = environment.NumberRange.new(8, 14), SpreadAngle = environment.Vector2.new(85, 85), Drag = 5,
		Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0, LightInfluence = 0.8, Brightness = 1.2}, 16)
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.chest), environment.Vector3.new(1.5, 1.5, 1.5))
	local emitter = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.soft,
		Color = colors(environment.Color3.fromRGB(245, 245, 245), environment.Color3.fromRGB(180, 180, 190)),
		Size = sequence(0, 1, 1, 2.8), Transparency = sequence(0, 0.2, 1, 1), Lifetime = environment.NumberRange.new(0.5, 0.8),
		Speed = environment.NumberRange.new(0.5, 1.5), SpreadAngle = environment.Vector2.new(180, 180),
		Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0.2, LightInfluence = 0.6, Brightness = 1.2}, 0)
	emitter.Rate, emitter.Enabled = 70, true
	local position = effect.chest
	GameEffects.Kill.animate(state, 1.9, function()
		if body and body.torso and body.torso.Parent then
			position = body.torso.Position
			anchor.CFrame = environment.CFrame.new(position)
		end
	end, function()
		emitter.Enabled = false
		if body then pcall(function() body.model:Destroy() end) end
		local burst = GameEffects.Kill.anchor(state, environment.CFrame.new(position), environment.Vector3.new(1, 1, 1))
		local burstAttachment = environment.Instance.new("Attachment")
		burstAttachment.Parent = burst
		GameEffects.Kill.particle(state, burstAttachment, {Texture = state.textures.star4, Color = colors(white, environment.Color3.fromRGB(255, 240, 170)),
			Size = sequence(0, 0, 0.3, 9, 1, 0), Lifetime = environment.NumberRange.new(0.55), RotSpeed = environment.NumberRange.new(160), Brightness = 8, ZOffset = 2}, 1)
		GameEffects.Kill.particle(state, burstAttachment, {Texture = state.textures.sparkBright, Color = colors(white, environment.Color3.fromRGB(255, 230, 150)),
			Size = sequence(0, 1.2, 1, 0), Lifetime = environment.NumberRange.new(0.4, 0.7), Speed = environment.NumberRange.new(6, 12),
			SpreadAngle = environment.Vector2.new(180, 180), Drag = 3, Brightness = 6}, 8)
		GameEffects.Kill.particle(state, burst, {Texture = state.textures.soft, Color = colors(white), Size = sequence(0, 2, 1, 5),
			Transparency = sequence(0, 0.2, 1, 1), Lifetime = environment.NumberRange.new(0.5, 0.7), Speed = environment.NumberRange.new(2, 5),
			SpreadAngle = environment.Vector2.new(180, 180), LightEmission = 0, LightInfluence = 0.8, Brightness = 1.2}, 8)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.timerBell, 0.8, 1.2)
		GameEffects.Kill.destroyLater(state, burst, 1.2)
		GameEffects.Kill.destroyLater(state, anchor, 1.2)
	end)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.rocket, 0.6, 1.1, groundAnchor)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.boom, 0.4, 1.7, groundAnchor)
	GameEffects.Kill.shakeCamera(state, effect.root, 0.6, 0.25)
	GameEffects.Kill.destroyLater(state, groundAnchor, 2)
end

function GameEffects.Kill.ricochet(state, effect)
	local context, environment = state.context, state.context.environment
	local color, white = environment.Color3.fromRGB(255, 220, 120), environment.Color3.new(1, 1, 1)
	local direction, origin = GameEffects.Kill.direction(state, effect)
	if effect.killer and effect.killer.Parent then origin = effect.killer.Position + environment.Vector3.new(0, 0.6, 0) end
	local target = effect.head
	local params = environment.RaycastParams.new()
	params.FilterType, params.RespectCanCollide = environment.Enum.RaycastFilterType.Exclude, true
	params.FilterDescendantsInstances = {effect.char, context.workspace.CurrentCamera, GameEffects.Kill.bodiesFolder(state), context.player.Character}
	local points = {origin}
	local aim, last = target - origin, origin
	aim = aim.Magnitude > 0.5 and aim.Unit or direction
	for index = 1, 3 do
		local shot = (aim + environment.Vector3.new(math.random() - 0.5, (math.random() - 0.5) * 0.6, math.random() - 0.5) * 1.6).Unit
		local hit = context.workspace:Raycast(last, shot * 28, params)
		last = hit and hit.Position or effect.chest + environment.Vector3.new(math.cos(index * 2.1) * 6, math.random() * 3, math.sin(index * 2.1) * 6)
		table.insert(points, last)
	end
	table.insert(points, target)
	local body = GameEffects.Kill.body(state, effect, environment.Vector3.new(0, 0, 0), nil, 3.4, nil, true)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	for index = 1, #points - 1 do
		GameEffects.Kill.delay(state, (index - 1) * 0.08, function()
			local start, finish = points[index], points[index + 1]
			local beams = {GameEffects.Kill.beam(state, start, finish, 0.08, white),
				GameEffects.Kill.beam(state, start, finish, 0.3, color, environment.Enum.Material.Neon, 0.5)}
			for _, beam in beams do
				GameEffects.Kill.tween(state, beam, 0.5, {Transparency = 1, Size = environment.Vector3.new(0.01, 0.01, beam.Size.Z)}, environment.Enum.EasingStyle.Quad)
				GameEffects.Kill.destroyLater(state, beam, 0.55)
			end
			if index > 1 then
				GameEffects.Kill.sparks(state, start, color, 10, 18, state.textures.spark)
				GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.ding, 0.5, 2 + math.random() * 0.4)
			end
		end)
	end
	GameEffects.Kill.delay(state, (#points - 1) * 0.08, function()
		local impact = points[#points] - points[#points - 1]
		impact = impact.Magnitude > 0.1 and impact.Unit or direction
		if body then
			body.release(impact * 45 + environment.Vector3.new(0, 12, 0), function(result)
				if result.head then result.head.AssemblyLinearVelocity = impact * 65 + environment.Vector3.new(0, 15, 0) end
			end)
		end
		GameEffects.Kill.flash(state, target, color, 8, 5)
		local _, attachment = GameEffects.Kill.effectAttachment(state, target)
		GameEffects.Kill.particle(state, attachment, {Texture = state.textures.splat,
			Color = environment.ColorSequence.new(environment.Color3.fromRGB(170, 0, 18), environment.Color3.fromRGB(90, 0, 10)),
			Size = GameEffects.Kill.numberSequence(state, 0, 0.5, 1, 0.2), Lifetime = environment.NumberRange.new(0.5, 0.9),
			Speed = environment.NumberRange.new(10, 18), SpreadAngle = environment.Vector2.new(60, 60), Acceleration = environment.Vector3.new(0, -60, 0),
			Rotation = environment.NumberRange.new(0, 360), LightEmission = 0, Brightness = 1}, 24)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.snap, 0.9, 0.8)
		GameEffects.Kill.shakeCamera(state, target, 0.8, 0.25)
	end)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.sniper, 0.9, 1.1)
end

function GameEffects.Kill.volcano(state, effect)
	local environment = state.context.environment
	local color = environment.Color3.fromRGB(255, 90, 20)
	local ground = GameEffects.Kill.ground(state, effect.root, effect.ignore)
	local height = ground and ground.Y or effect.root.Y - 3
	local position = environment.Vector3.new(effect.root.X, height, effect.root.Z)
	local body = GameEffects.Kill.body(state, effect, environment.Vector3.new(0, 0, 0), nil, 3.6, nil, true)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	GameEffects.Kill.splat(state, effect.root, 8, environment.Color3.fromRGB(255, 120, 30), 2.2, effect.ignore, 0.3, state.textures.cracks, 2)
	GameEffects.Kill.smoke(state, position, environment.Color3.fromRGB(110, 95, 85), 6, 4, 2)
	GameEffects.Kill.shakeCamera(state, position, 0.6, 0.5)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.quakeRumble, 0.7, 0.6, nil, 2)
	GameEffects.Kill.delay(state, 0.4, function()
		local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(position + environment.Vector3.new(0, 0.3, 0)), environment.Vector3.new(2, 0.4, 2))
		local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
		local flame = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.flame,
			Color = environment.ColorSequence.new({environment.ColorSequenceKeypoint.new(0, environment.Color3.fromRGB(255, 230, 140)),
				environment.ColorSequenceKeypoint.new(0.4, color), environment.ColorSequenceKeypoint.new(1, environment.Color3.fromRGB(120, 20, 5))}),
			Size = sequence(0, 1.3, 1, 0.5), Transparency = sequence(0, 0.2, 1, 0.8), Lifetime = environment.NumberRange.new(0.8, 1.2),
			Speed = environment.NumberRange.new(40, 60), SpreadAngle = environment.Vector2.new(8, 8), Acceleration = environment.Vector3.new(0, -80, 0),
			Rotation = environment.NumberRange.new(0, 360), Shape = environment.Enum.ParticleEmitterShape.Box, Brightness = 3}, 0)
		flame.Rate, flame.Enabled = 130, true
		local smoke = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.fsmoke,
			Color = environment.ColorSequence.new(environment.Color3.fromRGB(70, 55, 50), environment.Color3.fromRGB(30, 26, 24)),
			Size = sequence(0, 3, 1, 8), Transparency = sequence(0, 0.3, 1, 1), Lifetime = environment.NumberRange.new(1.4, 2),
			Speed = environment.NumberRange.new(14, 22), SpreadAngle = environment.Vector2.new(12, 12), Rotation = environment.NumberRange.new(0, 360),
			LightEmission = 0, LightInfluence = 1, Brightness = 1}, 0)
		smoke.Rate, smoke.Enabled = 30, true
		GameEffects.Kill.delay(state, 1.1, function() flame.Enabled, smoke.Enabled = false, false end)
		GameEffects.Kill.destroyLater(state, anchor, 3.5)
		GameEffects.Kill.light(state, anchor, color, 12, 26, 1.6)
		GameEffects.Kill.fragments(state, position + environment.Vector3.new(0, 1, 0), 14, color, environment.Enum.Material.Neon, 0.5, 35, 1.8)
		if body then
			body.release(environment.Vector3.new(0, 75, 0) + GameEffects.Kill.direction(state, effect) * 6, nil)
			pcall(function() body.torso.AssemblyAngularVelocity = GameEffects.Kill.randomVector(state, 8) end)
			local highlight = GameEffects.Kill.highlight(state, body.model, color, environment.Color3.fromRGB(255, 220, 120), 0.35, 0)
			GameEffects.Kill.delay(state, 0.6, function()
				if highlight.Parent then GameEffects.Kill.tween(state, highlight, 0.6, {FillColor = environment.Color3.fromRGB(20, 8, 4), FillTransparency = 0.1, OutlineTransparency = 1}) end
			end)
		end
		GameEffects.Kill.splat(state, effect.root, 7, environment.Color3.fromRGB(22, 16, 14), 3, effect.ignore, 0.2, state.textures.burn, 2)
		GameEffects.Kill.splat(state, effect.root, 4, color, 2.2, effect.ignore, 0.3, state.textures.splat, 1)
		GameEffects.Kill.flash(state, position + environment.Vector3.new(0, 1, 0), color, 12, 5)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.fireball2, 0.9, 0.7, anchor)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.fireWhoosh, 0.7, 0.5, anchor)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.boomDeep, 0.7, 0.6, anchor)
		GameEffects.Kill.shakeCamera(state, position, 1.6, 0.5)
	end)
end

function GameEffects.Kill.ringAtGround(state, position, color, startSize, endSize, duration, texture, ignore)
	local environment = state.context.environment
	local ground = GameEffects.Kill.ground(state, position, ignore) or position
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(ground + environment.Vector3.new(0, 0.15, 0)), environment.Vector3.new(0.4, 0.2, 0.4))
	local attachment = environment.Instance.new("Attachment")
	attachment.Parent = anchor
	local ring = GameEffects.Kill.groundRing(state, attachment, texture or state.textures.ringEdge, color, startSize, endSize, duration, 3)
	GameEffects.Kill.destroyLater(state, anchor, duration + 0.5)
	return ring, anchor
end

function GameEffects.Kill.hellfire(state, effect)
	local environment = state.context.environment
	local color = environment.Color3.fromRGB(255, 110, 20)
	local direction = GameEffects.Kill.direction(state, effect)
	local body = GameEffects.Kill.body(state, effect, direction * 2 + environment.Vector3.new(0, 4, 0), GameEffects.Kill.randomVector(state, 2), 3.4)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	GameEffects.Kill.splat(state, effect.root, 9, environment.Color3.fromRGB(255, 120, 30), 1.6, effect.ignore, 0.25, state.textures.cracks, 2)
	GameEffects.Kill.splat(state, effect.root, 6, environment.Color3.fromRGB(20, 10, 8), 2.4, effect.ignore, 0.5, state.textures.burn, 2)
	GameEffects.Kill.ringAtGround(state, effect.root, color, 2, 12, 0.8, state.textures.ringEdge, effect.ignore)
	local ground = GameEffects.Kill.ground(state, effect.root, effect.ignore) or effect.root - environment.Vector3.new(0, 3, 0)
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
	for index = 0, 5 do
		local angle, radius = index / 6 * 6.283 + math.random() * 0.4, index == 0 and 0 or 3
		local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(ground + environment.Vector3.new(math.cos(angle) * radius, 0.2, math.sin(angle) * radius)),
			environment.Vector3.new(1.2, 0.2, 1.2))
		local emitter = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.flame,
			Color = environment.ColorSequence.new({environment.ColorSequenceKeypoint.new(0, environment.Color3.fromRGB(255, 240, 170)),
				environment.ColorSequenceKeypoint.new(0.4, color), environment.ColorSequenceKeypoint.new(1, environment.Color3.fromRGB(150, 20, 5))}),
			Size = sequence(0, 1.4, 0.5, 2.2, 1, 0.4), Transparency = sequence(0, 0.4, 0.15, 0, 1, 1), Lifetime = environment.NumberRange.new(0.5, 0.8),
			Speed = environment.NumberRange.new(index == 0 and 30 or 18, index == 0 and 45 or 28), SpreadAngle = environment.Vector2.new(8, 8),
			Rotation = environment.NumberRange.new(-20, 20), Shape = environment.Enum.ParticleEmitterShape.Box, Brightness = 3}, 0)
		GameEffects.Kill.delay(state, index * 0.08, function()
			if emitter.Parent then emitter.Rate, emitter.Enabled = index == 0 and 140 or 70, true end
		end)
		GameEffects.Kill.delay(state, 1.2 + index * 0.05, function() if emitter.Parent then emitter.Enabled = false end end)
		GameEffects.Kill.destroyLater(state, anchor, 2.4)
	end
	if body then
		local highlight = GameEffects.Kill.highlight(state, body.model, color, environment.Color3.fromRGB(255, 220, 120), 0.3, 0)
		GameEffects.Kill.delay(state, 0.7, function()
			if highlight.Parent then GameEffects.Kill.tween(state, highlight, 0.6, {FillColor = environment.Color3.fromRGB(20, 8, 4), FillTransparency = 0.05, OutlineTransparency = 1}) end
		end)
		GameEffects.Kill.delay(state, 0.9, function() for _, part in body.parts do pcall(function() part.CanCollide = false end) end end)
	end
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(ground + environment.Vector3.new(0, 1, 0)), environment.Vector3.new(4, 1, 4))
	GameEffects.Kill.particle(state, anchor, {Texture = state.textures.fsparks, Color = colors(environment.Color3.fromRGB(255, 220, 120), color),
		Size = sequence(0, 0.4, 1, 0), Lifetime = environment.NumberRange.new(0.8, 1.5), Speed = environment.NumberRange.new(6, 16),
		SpreadAngle = environment.Vector2.new(30, 30), Acceleration = environment.Vector3.new(0, 4, 0), Shape = environment.Enum.ParticleEmitterShape.Box, Brightness = 5}, 50, 0.2)
	GameEffects.Kill.particle(state, anchor, {Texture = state.textures.fsmoke, Color = colors(environment.Color3.fromRGB(60, 40, 35), environment.Color3.fromRGB(20, 16, 15)),
		Size = sequence(0, 3, 1, 8), Transparency = sequence(0, 0.35, 1, 1), Lifetime = environment.NumberRange.new(1.4, 2), Speed = environment.NumberRange.new(4, 8),
		SpreadAngle = environment.Vector2.new(25, 25), Rotation = environment.NumberRange.new(0, 360), Shape = environment.Enum.ParticleEmitterShape.Box,
		LightEmission = 0, LightInfluence = 1, Brightness = 1}, 14, 0.4)
	GameEffects.Kill.light(state, anchor, color, 10, 24, 1.8)
	GameEffects.Kill.destroyLater(state, anchor, 3)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.sear, 0.8, 0.45, anchor)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.fireball, 0.7, 0.6, anchor)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.demon, 0.5, 0.8, anchor, 2)
	GameEffects.Kill.shakeCamera(state, effect.root, 1, 0.6)
end

function GameEffects.Kill.materialCopy(state, part, material, color, reflectance, transparency, keepDecals)
	local ok, clone = pcall(function() return part:Clone() end)
	if not ok or not clone then return nil end
	if type(color) == "function" then color = color() end
	for _, child in clone:GetChildren() do
		if child:IsA("SpecialMesh") then child.TextureId = ""; continue end
		if keepDecals and child:IsA("Decal") then continue end
		child:Destroy()
	end
	pcall(function() if clone:IsA("MeshPart") then clone.TextureID = "" end end)
	clone.Material, clone.Color, clone.Transparency = material, color, transparency or 0
	if reflectance ~= false then clone.Reflectance = reflectance or 0 end
	clone.Parent = GameEffects.Kill.folder(state)
	return clone
end

function GameEffects.Kill.transmute(state, parts, material, color, duration, reflectance, keepDecals)
	local environment = state.context.environment
	local result = {}
	for _, part in parts do
		local clone = GameEffects.Kill.materialCopy(state, part, material, color, reflectance, 1, keepDecals)
		if clone then
			clone.Anchored, clone.CanCollide, clone.CanQuery, clone.CanTouch = true, false, false, false
			table.insert(result, clone)
			GameEffects.Kill.tween(state, clone, duration, {Transparency = 0}, environment.Enum.EasingStyle.Quad)
		end
		GameEffects.Kill.tween(state, part, duration, {Transparency = 1}, environment.Enum.EasingStyle.Quad)
		for _, child in part:GetChildren() do
			if child:IsA("Decal") then GameEffects.Kill.tween(state, child, duration, {Transparency = 1}) end
		end
	end
	return result
end

function GameEffects.Kill.smoke(state, position, color, count, speed, size)
	local environment = state.context.environment
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(position), environment.Vector3.new(2, 0.5, 2))
	GameEffects.Kill.particle(state, anchor, {Texture = state.textures.smokeFB, FlipbookLayout = environment.Enum.ParticleFlipbookLayout.Grid4x4,
		FlipbookMode = environment.Enum.ParticleFlipbookMode.OneShot, Color = environment.ColorSequence.new(color, color),
		Size = GameEffects.Kill.numberSequence(state, 0, (size or 2) * 0.6, 1, (size or 2) * 1.6),
		Transparency = GameEffects.Kill.numberSequence(state, 0, 0.2, 0.7, 0.45, 1, 1), Lifetime = environment.NumberRange.new(0.8, 1.3),
		Speed = environment.NumberRange.new(speed * 0.4, speed), SpreadAngle = environment.Vector2.new(85, 85), Drag = 3,
		Rotation = environment.NumberRange.new(0, 360), Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0, LightInfluence = 1, Brightness = 1}, count)
	GameEffects.Kill.destroyLater(state, anchor, 2.5)
	return anchor
end

function GameEffects.Kill.frostBite(state, effect)
	local environment = state.context.environment
	local color, white = environment.Color3.fromRGB(160, 225, 255), environment.Color3.new(1, 1, 1)
	local body = GameEffects.Kill.staticBody(state, effect)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	GameEffects.Kill.arc(state, effect.chest, 30, 3.4, 1.05, color, 0.8, 0.07, 0.08, -10)
	GameEffects.Kill.delay(state, 0.08, function() GameEffects.Kill.arc(state, effect.chest, 150, 3.4, 1.05, color, 0.8, 0.07, 0.08, 10) end)
	local ice = GameEffects.Kill.transmute(state, body, environment.Enum.Material.Ice, color, 0.25, 0.25)
	local spikes = {}
	GameEffects.Kill.delay(state, 0.2, function()
		for _ = 1, 10 do
			local part = ice[math.random(1, math.max(1, #ice))]
			if not part then continue end
			local direction = environment.Vector3.new(math.random() - 0.5, math.random() * 0.8, math.random() - 0.5).Unit
			local pieces = GameEffects.Kill.spike(state, part.Position, part.Position + direction * (0.9 + math.random() * 0.8), 0.14, 0.2,
				white:Lerp(color, 0.5), environment.Enum.Material.Glass)
			for _, piece in pieces do piece.Transparency = 0.2; table.insert(spikes, piece) end
		end
	end)
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.chest), environment.Vector3.new(2.6, 5, 2))
	local emitter = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.soft, Color = environment.ColorSequence.new(white, white),
		Size = GameEffects.Kill.numberSequence(state, 0, 0.25, 1, 0), Lifetime = environment.NumberRange.new(0.8, 1.3),
		Speed = environment.NumberRange.new(0.5, 1.5), Acceleration = environment.Vector3.new(0, -3, 0),
		Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0.3, Brightness = 2}, 0)
	emitter.Rate, emitter.Enabled = 40, true
	GameEffects.Kill.smoke(state, effect.root - environment.Vector3.new(0, 2.5, 0), environment.Color3.fromRGB(220, 235, 255), 8, 3, 2.5)
	GameEffects.Kill.delay(state, 0.95, function()
		emitter.Enabled = false
		for _, group in {ice, body, spikes} do for _, part in group do pcall(function() part:Destroy() end) end end
		GameEffects.Kill.fragments(state, effect.chest, 28, color, environment.Enum.Material.Ice, 0.4, 16, 1.8)
		local _, attachment = GameEffects.Kill.effectAttachment(state, effect.chest)
		GameEffects.Kill.particle(state, attachment, {Texture = state.textures.soft, Color = environment.ColorSequence.new(white, white),
			Size = GameEffects.Kill.numberSequence(state, 0, 1.2, 1, 3.5), Transparency = GameEffects.Kill.numberSequence(state, 0, 0.3, 1, 1),
			Lifetime = environment.NumberRange.new(0.6, 1), Speed = environment.NumberRange.new(6, 12), SpreadAngle = environment.Vector2.new(180, 180),
			Drag = 3, LightEmission = 0.3, Brightness = 2}, 20)
		GameEffects.Kill.flash(state, effect.chest, color, 10, 4)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.iceShatter, 1, 1.1)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.iceCrack, 0.7, 1.3, nil, 1.5)
		GameEffects.Kill.shakeCamera(state, effect.chest, 0.7, 0.25)
	end)
	GameEffects.Kill.light(state, anchor, color, 4, 14, 1.2)
	GameEffects.Kill.destroyLater(state, anchor, 2.4)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.whooshQuick, 0.9, 1.2)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.iceCrack, 1, 1, nil, 1.5)
end

function GameEffects.Kill.rainbow(state, effect)
	local environment = state.context.environment
	local colors = {environment.Color3.fromRGB(255, 60, 70), environment.Color3.fromRGB(255, 150, 40),
		environment.Color3.fromRGB(255, 230, 60), environment.Color3.fromRGB(80, 230, 100),
		environment.Color3.fromRGB(70, 150, 255), environment.Color3.fromRGB(170, 90, 255)}
	local white = environment.Color3.new(1, 1, 1)
	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colorSequence = function(first, second) return environment.ColorSequence.new(first, second or first) end
	local direction = GameEffects.Kill.direction(state, effect)
	local body = GameEffects.Kill.body(state, effect, direction * 26 + environment.Vector3.new(0, 60, 0), GameEffects.Kill.randomVector(state, 4), 3.2)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	if body and body.torso then
		local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(body.torso.Position), environment.Vector3.new(0.2, 0.2, 0.2))
		local trails = {}
		for index, color in colors do
			local first, second = environment.Instance.new("Attachment"), environment.Instance.new("Attachment")
			first.Position, first.Parent = environment.Vector3.new(0, (3.5 - index) * 0.36 + 0.18, 0), anchor
			second.Position, second.Parent = environment.Vector3.new(0, (3.5 - index) * 0.36 - 0.18, 0), anchor
			local trail = environment.Instance.new("Trail")
			trail.Attachment0, trail.Attachment1 = first, second
			trail.Color, trail.Transparency = colorSequence(color), sequence(0, 0.1, 1, 1)
			trail.Lifetime, trail.LightEmission, trail.FaceCamera, trail.Parent = 1.1, 0.6, true, anchor
			table.insert(trails, trail)
		end
		local emitter = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.star, Color = colorSequence(white, colors[3]),
			Size = sequence(0, 0.5, 1, 0), Lifetime = environment.NumberRange.new(0.4, 0.8), Speed = environment.NumberRange.new(1, 3),
			SpreadAngle = environment.Vector2.new(180, 180), Brightness = 4}, 0)
		emitter.Rate, emitter.Enabled = 30, true
		GameEffects.Kill.animate(state, 1.7, function()
			if body.torso.Parent then anchor.CFrame = environment.CFrame.new(body.torso.Position) end
		end, function()
			emitter.Enabled = false
			for _, trail in trails do trail.Enabled = false end
			local _, attachment = GameEffects.Kill.effectAttachment(state, anchor.Position)
			GameEffects.Kill.particle(state, attachment, {Texture = state.textures.star4, Color = colorSequence(white, colors[3]),
				Size = sequence(0, 0, 0.3, 2, 1, 0), Lifetime = environment.NumberRange.new(0.5), Speed = environment.NumberRange.new(6, 12),
				SpreadAngle = environment.Vector2.new(180, 180), Drag = 3, Brightness = 6}, 14)
			GameEffects.Kill.destroyLater(state, anchor, 1.3)
			GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.chimes, 0.6, 1.5)
		end)
	end
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.root), environment.Vector3.new(2, 1, 2))
	GameEffects.Kill.particle(state, anchor, {Texture = state.textures.soft, Color = colorSequence(white), Size = sequence(0, 1.5, 1, 4),
		Transparency = sequence(0, 0.1, 1, 1), Lifetime = environment.NumberRange.new(0.6, 1), Speed = environment.NumberRange.new(6, 12),
		SpreadAngle = environment.Vector2.new(85, 85), Drag = 4, Shape = environment.Enum.ParticleEmitterShape.Box,
		LightEmission = 0, LightInfluence = 0.8, Brightness = 1.3}, 16)
	GameEffects.Kill.destroyLater(state, anchor, 1.5)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.slideWhistle, 0.6, 1.2)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.partyHorn2, 0.6, 1.1)
	for index = 0, 2 do
		GameEffects.Kill.delay(state, 0.25 + index * 0.09, function() GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.chimes, 0.4, 1.2 + index * 0.25) end)
	end
end

function GameEffects.Kill.inferno(state, effect)
	local environment = state.context.environment
	local color = environment.Color3.fromRGB(255, 120, 30)
	local ground = GameEffects.Kill.ground(state, effect.root, effect.ignore)
	local height = ground and ground.Y or effect.root.Y - 3
	local parts = GameEffects.Kill.ghost(state, effect.char, {material = environment.Enum.Material.Neon,
		color = environment.Color3.fromRGB(255, 150, 60), transparency = 0})
	GameEffects.Kill.hideEffectBody(state, effect.char)
	for _, part in parts do
		GameEffects.Kill.tween(state, part, 0.9, {Color = environment.Color3.fromRGB(28, 14, 8)}, environment.Enum.EasingStyle.Quad)
	end
	GameEffects.Kill.delay(state, 1, function()
		for _, part in parts do
			if not part.Parent then continue end
			local offset = math.max(0, part.Position.Y - (height + 0.3)) * 0.85
			GameEffects.Kill.tween(state, part, 0.55, {CFrame = part.CFrame - environment.Vector3.new(0, offset, 0), Size = part.Size * 0.55,
				Transparency = 1}, environment.Enum.EasingStyle.Quad, environment.Enum.EasingDirection.In)
			GameEffects.Kill.destroyLater(state, part, 0.6)
		end
	end)

	local sequence = function(...) return GameEffects.Kill.numberSequence(state, ...) end
	local colors = function(first, second) return environment.ColorSequence.new(first, second or first) end
	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.chest - environment.Vector3.new(0, 0.6, 0)), environment.Vector3.new(2.4, 4.4, 1.6))
	local flame = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.flame,
		Color = environment.ColorSequence.new({environment.ColorSequenceKeypoint.new(0, environment.Color3.fromRGB(255, 240, 170)),
			environment.ColorSequenceKeypoint.new(0.35, environment.Color3.fromRGB(255, 130, 30)),
			environment.ColorSequenceKeypoint.new(1, environment.Color3.fromRGB(200, 30, 10))}),
		Size = sequence(0, 0.8, 0.3, 1.8, 1, 0.2), Transparency = sequence(0, 0.6, 0.15, 0.05, 0.8, 0.4, 1, 1),
		Lifetime = environment.NumberRange.new(0.45, 0.8), Speed = environment.NumberRange.new(2, 5), Acceleration = environment.Vector3.new(0, 9, 0),
		SpreadAngle = environment.Vector2.new(15, 15), Rotation = environment.NumberRange.new(-15, 15), Shape = environment.Enum.ParticleEmitterShape.Box,
		ShapeStyle = environment.Enum.ParticleEmitterShapeStyle.Volume, Brightness = 3, ZOffset = 1}, 30)
	flame.Rate, flame.Enabled = 110, true
	GameEffects.Kill.delay(state, 1.25, function() if flame.Parent then flame.Enabled = false end end)
	GameEffects.Kill.particle(state, anchor, {Texture = state.textures.fsparks, Color = colors(environment.Color3.fromRGB(255, 220, 120), color),
		Size = sequence(0, 0.35, 1, 0), Lifetime = environment.NumberRange.new(0.8, 1.4), Speed = environment.NumberRange.new(2, 6),
		Acceleration = environment.Vector3.new(0, 6, 0), SpreadAngle = environment.Vector2.new(50, 50), Shape = environment.Enum.ParticleEmitterShape.Box,
		Brightness = 4}, 30, 0.3)
	GameEffects.Kill.particle(state, anchor, {Texture = state.textures.square, Color = colors(environment.Color3.fromRGB(80, 75, 70), environment.Color3.fromRGB(30, 28, 26)),
		Size = sequence(0, 0.2, 1, 0.08), Lifetime = environment.NumberRange.new(1, 1.6), Speed = environment.NumberRange.new(0.5, 2),
		Acceleration = environment.Vector3.new(0, -4, 0), Drag = 1, Rotation = environment.NumberRange.new(0, 360), RotSpeed = environment.NumberRange.new(-200, 200),
		Shape = environment.Enum.ParticleEmitterShape.Box, LightEmission = 0, LightInfluence = 1, Brightness = 1}, 50, 1)
	local attachment = environment.Instance.new("Attachment")
	attachment.Parent = anchor
	GameEffects.Kill.particle(state, attachment, {Texture = state.textures.core, Color = colors(environment.Color3.fromRGB(255, 230, 160), color),
		Size = sequence(0, 2, 1, 7), Transparency = sequence(0, 0, 1, 1), Lifetime = environment.NumberRange.new(0.35),
		Rotation = environment.NumberRange.new(0, 360), Brightness = 4}, 2)
	local floor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.root.X, height + 0.1, effect.root.Z), environment.Vector3.new(1, 0.2, 1))
	GameEffects.Kill.groundRing(state, floor, state.textures.ringEdge, color, 2, 11, 0.55, 3)
	local light = environment.Instance.new("PointLight")
	light.Color, light.Range, light.Shadows, light.Brightness, light.Parent = color, 16, false, 0, anchor
	GameEffects.Kill.animate(state, 1.7, function(progress) light.Brightness = (1 - progress) * (4 + math.noise(progress * 22, 0.37) * 4) end)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.fireball, 0.45, 0.55, anchor)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.fireWhoosh, 0.6, 0.5, anchor)
	GameEffects.Kill.destroyLater(state, anchor, 3)
	GameEffects.Kill.destroyLater(state, floor, 1.5)
end

function GameEffects.Kill.highlight(state, model, color, outline, transparency, outlineTransparency)
	local environment = state.context.environment
	local highlight = environment.Instance.new("Highlight")
	highlight.FillColor, highlight.OutlineColor = color, outline or color
	highlight.FillTransparency, highlight.OutlineTransparency = transparency or 0.5, outlineTransparency or 0
	highlight.DepthMode = environment.Enum.HighlightDepthMode.Occluded
	highlight.Adornee, highlight.Parent = model, model
	return highlight
end

function GameEffects.Kill.crystalPrison(state, effect)
	local environment = state.context.environment
	local color, white = environment.Color3.fromRGB(170, 90, 255), environment.Color3.new(1, 1, 1)
	local ground = GameEffects.Kill.ground(state, effect.root, effect.ignore)
	local height = ground and ground.Y or effect.root.Y - 3
	local body, model = GameEffects.Kill.staticBody(state, effect)
	GameEffects.Kill.hideEffectBody(state, effect.char)
	if model then GameEffects.Kill.highlight(state, model, color, environment.Color3.fromRGB(230, 200, 255), 0.45, 0) end

	local crystals = {}
	local top = effect.head + environment.Vector3.new(0, 1.2, 0)
	for index = 1, 9 do
		local angle, radius = index / 9 * 6.283 + math.random() * 0.3, 2.2 + math.random() * 0.6
		local start = environment.Vector3.new(effect.root.X + math.cos(angle) * radius, height - 0.2, effect.root.Z + math.sin(angle) * radius)
		local finish = top + environment.Vector3.new(math.cos(angle) * 0.4, math.random() * 0.8, math.sin(angle) * 0.4)
		local parts, direction, length = GameEffects.Kill.spike(state, start, finish, 0.45, 0.6 + math.random() * 0.25,
			color:Lerp(white, math.random() * 0.3), environment.Enum.Material.Glass)
		for _, part in parts do
			part.Transparency, part.Reflectance = 0.2, 0.3
			local frame = part.CFrame
			part.CFrame = frame - direction * (length + 0.3)
			GameEffects.Kill.delay(state, index * 0.035, function()
				if part.Parent then GameEffects.Kill.tween(state, part, 0.3, {CFrame = frame}, environment.Enum.EasingStyle.Back) end
			end)
			table.insert(crystals, part)
		end
	end

	local anchor = GameEffects.Kill.anchor(state, environment.CFrame.new(effect.chest), environment.Vector3.new(4, 5, 4))
	local emitter = GameEffects.Kill.particle(state, anchor, {Texture = state.textures.star4, Color = environment.ColorSequence.new(white, color),
		Size = GameEffects.Kill.numberSequence(state, 0, 0, 0.5, 0.9, 1, 0), Lifetime = environment.NumberRange.new(0.3, 0.5),
		Rotation = environment.NumberRange.new(0, 90), Shape = environment.Enum.ParticleEmitterShape.Box, Brightness = 5, ZOffset = 1}, 0)
	emitter.Rate, emitter.Enabled = 14, true
	GameEffects.Kill.light(state, anchor, color, 5, 16, 1.4)
	GameEffects.Kill.destroyLater(state, anchor, 3)
	GameEffects.Kill.delay(state, 1.15, function()
		emitter.Enabled = false
		for _, part in crystals do pcall(function() part:Destroy() end) end
		for _, part in body do pcall(function() part:Destroy() end) end
		GameEffects.Kill.fragments(state, effect.chest, 26, color, environment.Enum.Material.Glass, 0.45, 18, 1.6)
		GameEffects.Kill.flash(state, effect.chest, color, 12, 5)
		GameEffects.Kill.sparks(state, effect.chest, color, 30, 30, state.textures.shards)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.glassSmash2, 1, 0.8)
		GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.iceFreeze, 0.6, 0.7, nil, 1.6)
		GameEffects.Kill.shakeCamera(state, effect.chest, 0.9, 0.3)
	end)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.iceFreeze, 0.8, 0.6, nil, 1.6)
	GameEffects.Kill.sound(state, GameEffects.Kill.soundIds.synthSpark, 0.4, 1.6)
end

function GameEffects.Kill.spike(state, start, finish, width, depth, color, material)
	local environment = state.context.environment
	local offset = finish - start
	local length, direction = offset.Magnitude, offset.Unit
	local reference = math.abs(direction.Z) < 0.9 and environment.Vector3.new(0, 0, 1) or environment.Vector3.new(1, 0, 0)
	local frame = environment.CFrame.fromMatrix(start, direction:Cross(reference).Unit, direction)
	local parts = {}
	for index = 0, 3 do
		local part = environment.Instance.new("WedgePart")
		part.Anchored, part.CanCollide, part.CanQuery, part.CanTouch, part.CastShadow = true, false, false, false, false
		part.Material, part.Color, part.Reflectance = material, color, 0.15
		part.Size = environment.Vector3.new(width, length, depth)
		part.CFrame = frame * environment.CFrame.Angles(0, index * math.pi / 2, 0) * environment.CFrame.new(0, length / 2, -depth / 2)
		part.Parent = GameEffects.Kill.folder(state)
		table.insert(parts, part)
	end
	return parts, direction, length
end

function GameEffects.Kill.fragments(state, position, count, color, material, size, speed, lifetime)
	local context, environment = state.context, state.context.environment
	local parts = {}
	for _ = 1, count do
		local part = environment.Instance.new("Part")
		local scale = size * (0.5 + math.random())
		part.Size = environment.Vector3.new(scale, scale * (0.6 + math.random() * 0.6), scale * (0.7 + math.random() * 0.5))
		part.Material, part.Color = material or environment.Enum.Material.Slate, color
		part.CanQuery, part.CanTouch = false, false
		pcall(function() part.CollisionGroup = "Ragdolls" end)
		local offset = environment.Vector3.new((math.random() - 0.5) * 1.5, math.random() * 0.8, (math.random() - 0.5) * 1.5)
		part.CFrame = environment.CFrame.new(position + offset) * environment.CFrame.Angles(math.random() * 6, math.random() * 6, math.random() * 6)
		part.Parent = GameEffects.Kill.bodiesFolder(state)
		table.insert(parts, part)
		local duration = (lifetime or 2) + math.random() * 0.6
		GameEffects.Kill.delay(state, duration, function()
			if part.Parent then GameEffects.Kill.tween(state, part, 0.4, {Size = part.Size * 0.2, Transparency = 1}) end
		end)
		GameEffects.Kill.destroyLater(state, part, duration + 0.5)
	end

	local function launch()
		for _, part in parts do
			if not part.Parent then continue end
			local direction = environment.Vector3.new(math.random() - 0.5, 0, math.random() - 0.5)
			direction = direction.Magnitude > 0.05 and direction.Unit or environment.Vector3.new(1, 0, 0)
			part.AssemblyLinearVelocity = direction * speed * (0.4 + math.random() * 0.6) + environment.Vector3.new(0, speed * (0.6 + math.random() * 0.6), 0)
			part.AssemblyAngularVelocity = GameEffects.Kill.randomVector(state, 8)
		end
	end
	launch()
	local connection
	connection = context.runService.Heartbeat:Connect(function() connection:Disconnect(); launch() end)
	return parts
end

function GameEffects.Kill.flash(state, position, color, size, brightness)
	local environment = state.context.environment
	local anchor, attachment = GameEffects.Kill.effectAttachment(state, position)
	local white = environment.Color3.new(1, 1, 1)
	GameEffects.Kill.particle(state, attachment, {Texture = state.textures.core, Color = environment.ColorSequence.new(white, color),
		Size = GameEffects.Kill.numberSequence(state, 0, size * 0.2, 1, size), Transparency = GameEffects.Kill.numberSequence(state, 0, 0, 1, 1),
		Lifetime = environment.NumberRange.new(0.35), Rotation = environment.NumberRange.new(0, 360), Brightness = brightness or 5, ZOffset = 1}, 2)
	GameEffects.Kill.light(state, anchor, color, 10, math.min(60, size * 3), 0.5)
	return anchor, attachment
end

function GameEffects.Kill.sparks(state, position, color, count, speed, texture)
	local environment = state.context.environment
	local anchor, attachment = GameEffects.Kill.effectAttachment(state, position)
	local white = environment.Color3.new(1, 1, 1)
	GameEffects.Kill.particle(state, attachment, {Texture = texture or state.textures.fsparks, Color = environment.ColorSequence.new(white, color),
		Size = GameEffects.Kill.numberSequence(state, 0, 0.5, 1, 0), Lifetime = environment.NumberRange.new(0.3, 0.7),
		Speed = environment.NumberRange.new(speed * 0.5, speed), SpreadAngle = environment.Vector2.new(180, 180), Drag = 3,
		Acceleration = environment.Vector3.new(0, -25, 0), Orientation = environment.Enum.ParticleOrientation.VelocityParallel, Brightness = 5}, count)
	return anchor, attachment
end

function GameEffects.Kill.track(state, signal, callback)
	local connection = signal:Connect(callback)
	table.insert(state.connections, connection)
	return connection
end

function GameEffects.Kill.observeCharacter(state, player, character)
	if state.hooked[character] then return end
	state.hooked[character] = true

	state.context.environment.task.spawn(function()
		local humanoid = character:WaitForChild("Humanoid", 8)
		if not humanoid or not state.alive then return end

		local handled, connections = false, {}
		local function onDeath()
			if handled then return end
			handled = true
			GameEffects.Kill.onDeath(state, player, character)
		end

		table.insert(connections, humanoid.Died:Connect(onDeath))
		table.insert(connections, humanoid.HealthChanged:Connect(function(health)
			if health <= 0 then onDeath() end
		end))
		table.insert(connections, character.AncestryChanged:Connect(function(_, parent)
			if parent then return end
			for _, connection in connections do connection:Disconnect() end
			state.characterConnections[character], state.hooked[character] = nil, nil
		end))
		state.characterConnections[character] = connections
	end)
end

function GameEffects.Kill.observePlayer(state, player)
	if player == state.context.player then return end
	if player.Character then GameEffects.Kill.observeCharacter(state, player, player.Character) end
	GameEffects.Kill.track(state, player.CharacterAdded, function(character)
		GameEffects.Kill.observeCharacter(state, player, character)
	end)
end

function GameEffects.Kill.observeBlade(state, blade)
	if blade.Name ~= "ThrowingKnife" then return end
	local environment = state.context.environment

	environment.task.spawn(function()
		local part = blade:FindFirstChild("BladePosition") or blade:WaitForChild("BladePosition", 1)
		if not part and blade:IsA("BasePart") then part = blade end

		local started = environment.os.clock()
		while part and part.Parent and blade.Parent and state.alive and environment.os.clock() - started < 6 do
			GameEffects.Kill.recordBlade(state, part.Position)
			environment.task.wait(0.03)
		end
	end)
end

function GameEffects.Kill.observe(state)
	local context, environment = state.context, state.context.environment
	for _, player in context.players:GetPlayers() do GameEffects.Kill.observePlayer(state, player) end

	GameEffects.Kill.track(state, context.players.PlayerAdded, function(player) GameEffects.Kill.observePlayer(state, player) end)
	GameEffects.Kill.track(state, context.workspace.DescendantAdded, function(model) GameEffects.Kill.recordRagdoll(state, model) end)
	GameEffects.Kill.track(state, context.workspace.ChildAdded, function(blade) GameEffects.Kill.observeBlade(state, blade) end)

	environment.task.spawn(function()
		local services = context.storage:WaitForChild("ClientServices", 30)
		local weapons = services and services:WaitForChild("WeaponService", 30)
		local fired = weapons and weapons:WaitForChild("GunFired", 30)
		if not state.alive or not fired or not fired:IsA("RemoteEvent") then return end

		GameEffects.Kill.track(state, fired.OnClientEvent, function(shooter, _, position, hit)
			GameEffects.Kill.recordShot(state, shooter, position, hit)
		end)
	end)
end

function GameEffects.Kill.stop(state)
	state.alive = false
	state.showing = false
	GameEffects.Kill.resetShake(state)

	for _, connection in state.connections do pcall(function() connection:Disconnect() end) end
	for _, connections in state.characterConnections do
		for _, connection in connections do pcall(function() connection:Disconnect() end) end
	end

	table.clear(state.connections)
	table.clear(state.characterConnections)
	if state.folder then pcall(function() state.folder:Destroy() end); state.folder = nil end
end

function GameEffects.Kill.preview(state, name, options, title, generation)
	local context, environment = state.context, state.context.environment
	environment.task.spawn(function()
		local camera = context.workspace.CurrentCamera
		if not camera then return end

		if not state.dummyDescription then
			pcall(function() state.dummyDescription = context.players:GetHumanoidDescriptionFromUserId(context.player.UserId) end)
		end
		if not state.dummyDescription then return end

		local ok, model = pcall(function()
			return context.players:CreateHumanoidModelFromDescription(state.dummyDescription, environment.Enum.HumanoidRigType.R15)
		end)
		if not ok or not model then return end

		model.Name = "PulseKillPreview"
		local frame = camera.CFrame
		local direction = environment.Vector3.new(frame.LookVector.X, 0, frame.LookVector.Z)
		direction = direction.Magnitude > 0.01 and direction.Unit or environment.Vector3.new(0, 0, -1)
		local character = context.player.Character
		local root = character and character:FindFirstChild("HumanoidRootPart")
		local position = (root and root.Position or frame.Position) + direction * 9
		local localHumanoid = character and character:FindFirstChildOfClass("Humanoid")
		local ground
		if root then ground = root.Position.Y - root.Size.Y / 2 - (localHumanoid and localHumanoid.HipHeight or 2) end
		if not ground then
			local hit = GameEffects.Kill.ground(state, position, {a = character, b = camera})
			ground = hit and hit.Y or position.Y - 3
		end

		local humanoid = model:FindFirstChildOfClass("Humanoid")
		local previewRoot = model:FindFirstChild("HumanoidRootPart")
		previewRoot.Anchored = true
		for _, part in model:GetDescendants() do
			if part:IsA("BasePart") then part.CanCollide, part.CanQuery, part.CanTouch = false, false, false end
		end
		if humanoid then humanoid.DisplayDistanceType = environment.Enum.HumanoidDisplayDistanceType.None end

		local center = environment.Vector3.new(position.X, ground + (humanoid and humanoid.HipHeight or 2) + previewRoot.Size.Y / 2, position.Z)
		model:PivotTo(environment.CFrame.lookAt(center, environment.Vector3.new(frame.Position.X, center.Y, frame.Position.Z)))
		model.Parent = GameEffects.Kill.folder(state)
		if title and context.window then
			pcall(function() context.window:Notify({Title = context.translation.tr(title), Text = context.translation.tr(name), Kind = "info", Duration = 2}) end)
		end

		environment.task.wait(0.45)
		if generation and (state.showGen ~= generation or not state.showing) then pcall(function() model:Destroy() end); return end

		character = context.player.Character
		local killer = character and (character:FindFirstChild("UpperTorso") or character:FindFirstChild("Torso") or character:FindFirstChild("HumanoidRootPart"))
		GameEffects.Kill.play(state, name, options, model, killer)
		environment.task.wait(2.6 / state.speed)
		pcall(function() model:Destroy() end)
	end)
end

function GameEffects.Kill.clearShow(state)
	for _, folder in {state.folder, state.bodies} do
		if not folder then continue end
		for _, child in folder:GetChildren() do pcall(function() child:Destroy() end) end
	end
	pcall(GameEffects.Kill.resetShake, state)
end

function GameEffects.Kill.showLabel(state, showing)
	local button, environment = state.showButton, state.context.environment
	if environment.typeof(button) ~= "Instance" then return end

	local start = state.context.translation.tr("Show All Effects")
	local stop = state.context.translation.tr("Stop Showing")
	local text = showing and stop or start
	local objects = button:GetDescendants()
	table.insert(objects, button)
	for _, object in objects do
		if not object:IsA("TextLabel") and not object:IsA("TextButton") then continue end
		if object.Text == start or object.Text == stop then object.Text = text end
	end
end

function GameEffects.Kill.previewAll(state)
	local environment = state.context.environment
	state.showGen += 1
	local generation = state.showGen
	if state.showing then
		state.showing = false
		GameEffects.Kill.clearShow(state)
		environment.task.spawn(function()
			for _ = 1, 16 do
				environment.task.wait(0.2)
				if state.showing or state.showGen ~= generation then break end
				GameEffects.Kill.clearShow(state)
			end
		end)
		GameEffects.Kill.showLabel(state, false)
		return
	end

	state.showing = true
	GameEffects.Kill.showLabel(state, true)
	environment.task.spawn(function()
		local function active() return state.alive and state.showing and state.showGen == generation end
		for _, group in {{GameEffects.Kill.knifeEffects, "Knife Kill"}, {GameEffects.Kill.gunEffects, "Gun Kill"}} do
			for _, name in group[1] do
				if not active() then break end
				GameEffects.Kill.preview(state, name, group[1], group[2], generation)
				local started = environment.os.clock()
				while active() and environment.os.clock() - started < 3.2 / state.speed do environment.task.wait(0.05) end
			end
		end
		if state.showGen == generation then
			state.showing = false
			GameEffects.Kill.showLabel(state, false)
		end
	end)
end

function GameEffects.Kill.options(names)
	local options = {}
	for _, name in names do
		table.insert(options, {code = name, label = name:gsub("(%l)(%u)", "%1 %2")})
	end
	table.insert(options, {code = "Random", label = "Random"})
	return options
end

function GameEffects.Kill.install(context)
	local environment, section = context.environment, context.section
	local globals = environment.getgenv()
	if type(globals.__pulseKillFXStop) == "function" then pcall(globals.__pulseKillFXStop) end

	local state = GameEffects.Kill.create(context)
	state.showGen = 0
	state.stop = function() GameEffects.Kill.stop(state) end
	globals.__pulseKillFX, globals.__pulseKillFXStop = state, state.stop
	GameEffects.Kill.observe(state)

	section:Group({Title = "Kill Effects", Side = "Right"})
	section._curSub = "KillFX"
	section:Toggle({Text = "Kill Effects", Default = false, Callback = function(value) state.on = value == true end})
	section:Dropdown({Text = "Knife Kill", Default = "Slash", Options = GameEffects.Kill.options(GameEffects.Kill.knifeEffects), Callback = function(value)
		if value then state.knife = value end
	end})
	section:Dropdown({Text = "Gun Kill", Default = "Headshot", Options = GameEffects.Kill.options(GameEffects.Kill.gunEffects), Callback = function(value)
		if value then state.gun = value end
	end})
	section:Toggle({Text = "Screen Shake", Default = true, Callback = function(value)
		state.shake = value == true
		if not state.shake then GameEffects.Kill.resetShake(state) end
	end})
	section:Toggle({Text = "Only My Kills", Default = false, Callback = function(value) state.mine = value == true end})
	section:Toggle({Text = "Kill Sounds", Default = true, Callback = function(value) state.sound = value == true end, Settings = function()
		section:Slider({Text = "Kill Volume", Min = 0, Max = 100, Default = 60, Decimals = 0, Suffix = "%", Callback = function(value) state.volume = value end})
	end})
	section:Button({Text = "Preview Knife Kill", Callback = function() GameEffects.Kill.preview(state, state.knife, GameEffects.Kill.knifeEffects, "Knife Kill") end})
	section:Button({Text = "Preview Gun Kill", Callback = function() GameEffects.Kill.preview(state, state.gun, GameEffects.Kill.gunEffects, "Gun Kill") end})
	state.showButton = section:Button({Text = "Show All Effects", Callback = function() GameEffects.Kill.previewAll(state) end})
	return state.stop
end

local AuraEngine = {}
local AURA_CLASSES = {P = "ParticleEmitter", B = "Beam", T = "Trail", L = "PointLight", S = "SpotLight", U = "SurfaceLight", A = "Attachment",
	FI = "Fire", SM = "Smoke", SP = "Sparkles", F = "Folder", PT = "Part", SH = "SpecialMesh", HL = "Highlight", MD = "Model"}
local AURA_HAT_EFFECTS = {P = true, B = true, T = true, L = true, S = true, U = true}

function AuraEngine.decode(environment, value)
	if type(value) ~= "table" then return value end
	local kind = value[1]
	if kind == 1 then return environment.Color3.new(value[2], value[3], value[4]) end
	if kind == 2 then return environment.Vector3.new(value[2], value[3], value[4]) end
	if kind == 3 then return environment.Vector2.new(value[2], value[3]) end
	if kind == 4 then return environment.NumberRange.new(value[2], value[3]) end
	if kind == 5 then
		local points = {}
		for index = 2, #value, 3 do table.insert(points, environment.NumberSequenceKeypoint.new(value[index], value[index + 1], value[index + 2])) end
		return environment.NumberSequence.new(points)
	end
	if kind == 6 then
		local points = {}
		for index = 2, #value, 4 do
			table.insert(points, environment.ColorSequenceKeypoint.new(value[index], environment.Color3.new(value[index + 1], value[index + 2], value[index + 3])))
		end
		return environment.ColorSequence.new(points)
	end
	if kind == 7 then return environment.CFrame.new(table.unpack(value, 2, 13)) end
	if kind == 8 then
		local name = tostring(value[2]):gsub("^Enum%.", "")
		local ok, item = pcall(function() return environment.Enum[name][value[3]] end)
		return ok and item or nil
	end
	return nil
end

function AuraEngine.sequence(environment, sequence, scale, fade)
	local points = {}
	for _, point in sequence.Keypoints do
		local value = fade and 1 - (1 - point.Value) * scale or point.Value * scale
		table.insert(points, environment.NumberSequenceKeypoint.new(point.Time, value, point.Envelope * scale))
	end
	return environment.NumberSequence.new(points)
end

function AuraEngine.recolor(environment, sequence, tint)
	if environment.typeof(sequence) ~= "ColorSequence" then return environment.ColorSequence.new(tint) end
	local points = {}
	for _, point in sequence.Keypoints do
		local original = point.Value
		local high, low = math.max(original.R, original.G, original.B), math.min(original.R, original.G, original.B)
		local brightness = 0.3 + 0.7 * high
		local color = environment.Color3.new(tint.R * brightness, tint.G * brightness, tint.B * brightness)
		if low > 0.72 then color = color:Lerp(environment.Color3.new(1, 1, 1), (low - 0.72) / 0.28 * 0.75) end
		table.insert(points, environment.ColorSequenceKeypoint.new(point.Time, color))
	end
	return environment.ColorSequence.new(points)
end

function AuraEngine.tune(environment, object, options)
	local size, density, bright, alpha = options.size or 1, options.density or 1, options.bright or 1, options.alpha or 1
	pcall(function()
		if object:IsA("ParticleEmitter") then
			if size ~= 1 then
				object.Size = AuraEngine.sequence(environment, object.Size, size, false)
				object.Speed = environment.NumberRange.new(object.Speed.Min * size, object.Speed.Max * size)
				object.Acceleration *= size
			end
			if density ~= 1 then object.Rate *= density end
			if bright ~= 1 then object.Brightness *= bright end
			if alpha ~= 1 then object.Transparency = AuraEngine.sequence(environment, object.Transparency, alpha, true) end
			return
		end
		if object:IsA("Beam") then
			if size ~= 1 then
				object.Width0, object.Width1 = object.Width0 * size, object.Width1 * size
				object.CurveSize0, object.CurveSize1 = object.CurveSize0 * size, object.CurveSize1 * size
			end
			if bright ~= 1 then object.Brightness *= bright end
			if alpha ~= 1 then object.Transparency = AuraEngine.sequence(environment, object.Transparency, alpha, true) end
			return
		end
		if object:IsA("Trail") then
			if bright ~= 1 then object.Brightness *= bright end
			if alpha ~= 1 then object.Transparency = AuraEngine.sequence(environment, object.Transparency, alpha, true) end
			return
		end
		if object:IsA("Light") then
			if size ~= 1 then object.Range *= size end
			if bright ~= 1 then object.Brightness *= bright end
		end
	end)
end

function AuraEngine.build(environment, data, parent, build)
	if data.g and build.off[data.g] then return nil end
	local class = AURA_CLASSES[data.c]
	if not class then return nil end
	local object = environment.Instance.new(class)
	object.Name = data.n or class
	for property, value in data.p or {} do pcall(function() object[property] = AuraEngine.decode(environment, value) end) end
	if data.c == "A" then
		local position = object.Position
		if build.hatHost then
			object.Position = position * ((build.hatK or 1) * build.size)
		else
			local fit = build.fit
			if build.mapA then
				object.Position = build.mapA(position)
			else
				if fit then position = environment.Vector3.new(position.X * fit.x, fit.f + (position.Y + 3) * fit.y, position.Z * fit.z) end
				object.Position = position * build.size + build.liftV
			end
		end
	end
	if data.c == "PT" then
		object.Anchored, object.CanCollide, object.CanQuery, object.CanTouch, object.Massless, object.CastShadow = false, false, false, false, true, false
		local scale = (build.hatK or 1) * build.size
		object.Size *= scale
		local frame = AuraEngine.decode(environment, data.r) or environment.CFrame.new()
		frame = environment.CFrame.new((frame.Position - environment.Vector3.new(0, build.hatCrown or 0, 0)) * scale) * frame.Rotation
		if build.hatHost then
			object.CFrame = build.hatHost.CFrame * frame
			local weld = environment.Instance.new("Weld")
			weld.Part0, weld.Part1, weld.C0, weld.Parent = build.hatHost, object, frame, object
		end
		local alpha = build.options.alpha or 1
		if alpha ~= 1 then object.Transparency = 1 - (1 - object.Transparency) * alpha end
	end
	if data.c == "SH" then
		local scale = (build.hatK or 1) * build.size
		object.Scale, object.Offset = object.Scale * scale, object.Offset * scale
	end
	if data.c == "HL" then
		local alpha, bright = build.options.alpha or 1, build.options.bright or 1
		object.FillTransparency = 1 - math.clamp((1 - object.FillTransparency) * alpha * bright, 0, 1)
		object.OutlineTransparency = 1 - math.clamp((1 - object.OutlineTransparency) * alpha, 0, 1)
	end
	if data.c == "FI" and build.hatHost then object.Size = math.clamp(object.Size * (build.hatK or 1) * build.size, 2, 30) end
	if data.c == "P" then object.LockedToPart = true end
	if data.c == "T" then object.Lifetime = math.min(object.Lifetime, 0.3) end
	if data.i then build.ids[data.i] = object end
	if data.a or data.b then table.insert(build.links, {object, data.a, data.b}) end
	if data.g then AuraEngine.tune(environment, object, build.options) end
	if not data.g and build.hatTune and AURA_HAT_EFFECTS[data.c] then AuraEngine.tune(environment, object, build.hatTune) end
	object:SetAttribute("PulseVFX", true)
	object:SetAttribute("PulseVFXKey", build.key)
	for _, child in data.k or {} do AuraEngine.build(environment, child, object, build) end
	object.Parent = parent
	return object
end

function AuraEngine.link(build)
	for _, link in build.links do
		pcall(function()
			if link[2] and build.ids[link[2]] then link[1].Attachment0 = build.ids[link[2]] end
			if link[3] and build.ids[link[3]] then link[1].Attachment1 = build.ids[link[3]] end
		end)
	end
end

local AURA_R15 = {HumanoidRootPart = true, Head = true, UpperTorso = true, LowerTorso = true, LeftUpperArm = true, LeftLowerArm = true, LeftHand = true,
	RightUpperArm = true, RightLowerArm = true, RightHand = true, LeftUpperLeg = true, LeftLowerLeg = true, LeftFoot = true, RightUpperLeg = true, RightLowerLeg = true, RightFoot = true}
local AURA_R6 = {HumanoidRootPart = true, Head = true, Torso = true, ["Left Arm"] = true, ["Right Arm"] = true, ["Left Leg"] = true, ["Right Leg"] = true}
local AURA_LIMBS = {["Left Arm"] = "LeftUpperArm", ["Right Arm"] = "RightUpperArm", ["Left Leg"] = "LeftUpperLeg", ["Right Leg"] = "RightUpperLeg"}

function AuraEngine.fit(environment, character, root)
	local head, foot, torso = character:FindFirstChild("Head"), character:FindFirstChild("LeftFoot"), character:FindFirstChild("UpperTorso")
	if not head or not foot or not torso or not head:IsA("BasePart") or not foot:IsA("BasePart") or not torso:IsA("BasePart") then return nil end
	local rest, links = {[root] = environment.CFrame.new()}, {}
	for _, joint in character:GetDescendants() do
		if joint:IsA("Motor6D") and joint.Part0 and joint.Part1 then
			table.insert(links, {joint.Part0, joint.Part1, joint.C0, joint.C1})
			continue
		end
		if not joint:IsA("AnimationConstraint") or not joint.Attachment0 or not joint.Attachment1 then continue end
		local first, second = joint.Attachment0, joint.Attachment1
		if first.Parent and second.Parent and first.Parent:IsA("BasePart") and second.Parent:IsA("BasePart") then
			table.insert(links, {first.Parent, second.Parent, first.CFrame, second.CFrame})
		end
	end
	local changed = true
	while changed do
		changed = false
		for _, link in links do
			if not rest[link[1]] or rest[link[2]] then continue end
			rest[link[2]] = rest[link[1]] * link[3] * link[4]:Inverse()
			changed = true
		end
	end
	if not rest[head] or not rest[foot] then return nil end
	local floor = rest[foot].Position.Y - foot.Size.Y / 2
	local height = (rest[head].Position.Y - floor) / 4.5
	if floor > -1 or height < 0.4 or height > 2 then return nil end
	return {x = math.clamp(torso.Size.X / 2, 0.45, 1.8), y = height, z = math.clamp(torso.Size.Z, 0.45, 1.8), f = floor, rest = rest}
end

function AuraEngine.put(state, character, root, key, options)
	local environment = state.context.environment
	local data = state.data[key]
	if not data then return end
	options = options or {}
	if data.hat then return AuraEngine.putHat(state, character, data, key, options) end
	local scale, lift = options.size or 1, options.lift or 0
	local isR15 = character:FindFirstChild("UpperTorso") ~= nil
	local fit = isR15 and AuraEngine.fit(environment, character, root) or nil
	local build = {key = key, options = options, off = options.off or {}, size = scale, ids = {}, links = {}, liftV = environment.Vector3.zero}
	local rigScale, mapPosition
	if data.rig and fit then
		local torso, head = character:FindFirstChild("UpperTorso"), character:FindFirstChild("Head")
		local torsoRest, headRest = torso and fit.rest[torso], head and fit.rest[head]
		if torsoRest and headRest and headRest.Position.Y > torsoRest.Position.Y + 0.2 then
			local rig = data.rig
			local y = (headRest.Position.Y - torsoRest.Position.Y) / (rig.hy - rig.ty)
			local x, z = math.clamp(torso.Size.X / rig.tx, 0.3, 2.5), math.clamp(torso.Size.Z / rig.tz, 0.3, 2.5)
			local originY = torsoRest.Position.Y
			rigScale = environment.Vector3.new(x, y, z)
			mapPosition = function(position) return environment.Vector3.new(position.X * x, originY + (position.Y - rig.ty) * y, position.Z * z) end
		end
	end
	for _, hostData in data.h or {} do
		build.mapA = nil
		local part = character:FindFirstChild(hostData.n)
		local allowed = isR15 and AURA_R15[hostData.n] or not isR15 and AURA_R6[hostData.n]
		local host
		if part and part:IsA("BasePart") and allowed then
			build.liftV = part.CFrame:VectorToObjectSpace(environment.Vector3.new(0, lift, 0))
			build.fit = part == root and fit or nil
			if mapPosition then
				local localLift = build.liftV
				if part == root then
					build.mapA = function(position) return mapPosition(position) * scale + localLift end
				else
					local reference = AuraEngine.decode(environment, hostData.s) or part.Size
					local ratios = environment.Vector3.new(part.Size.X / math.max(reference.X, 0.01), part.Size.Y / math.max(reference.Y, 0.01), part.Size.Z / math.max(reference.Z, 0.01))
					build.mapA = function(position) return environment.Vector3.new(position.X * ratios.X, position.Y * ratios.Y, position.Z * ratios.Z) * scale + localLift end
				end
			end
			host = part
		else
			build.liftV, build.fit = environment.Vector3.zero, nil
			local original = AuraEngine.decode(environment, hostData.cf) or environment.CFrame.new()
			local position = original.Position
			if mapPosition then position = mapPosition(position) end
			if not mapPosition and fit then position = environment.Vector3.new(position.X * fit.x, fit.f + (position.Y + 3) * fit.y, position.Z * fit.z) end
			local frame = environment.CFrame.new(position * scale + environment.Vector3.new(0, lift, 0)) * original.Rotation
			if mapPosition then
				build.mapA = function(localPosition)
					return frame:PointToObjectSpace(mapPosition(original:PointToWorldSpace(localPosition)) * scale + environment.Vector3.new(0, lift, 0))
				end
			end
			host = environment.Instance.new("Part")
			host.Name = "PulseAuraHost"
			host.Size = (AuraEngine.decode(environment, hostData.s) or environment.Vector3.new(1, 1, 1)) * scale
			if rigScale then host.Size = environment.Vector3.new(host.Size.X * rigScale.X, host.Size.Y * rigScale.Y, host.Size.Z * rigScale.Z) end
			host.Transparency, host.CanCollide, host.CanQuery, host.CanTouch, host.CastShadow, host.Massless = 1, false, false, false, false, true
			local limb = fit and AURA_LIMBS[hostData.n] and character:FindFirstChild(AURA_LIMBS[hostData.n])
			local anchor, offset = root, frame
			if limb and limb:IsA("BasePart") and fit.rest[limb] then anchor, offset = limb, fit.rest[limb]:Inverse() * frame end
			host.CFrame = anchor.CFrame * offset
			local weld = environment.Instance.new("Weld")
			weld.Part0, weld.Part1, weld.C0, weld.Parent = anchor, host, offset, host
			host:SetAttribute("PulseVFX", true)
			host:SetAttribute("PulseVFXKey", key)
			host.Parent = character
		end
		for _, child in hostData.k or {} do AuraEngine.build(environment, child, host, build) end
	end
	AuraEngine.link(build)
end

local AURA_HAT_DEFAULTS = { ph_wire = { "Spin", "Wave" }, ph_galaxy = { "Float" }, ph_galaxyflame = { "Float" }, ph_phantom = { "Float" }, ph_glass = { "Spin" },
                ph_rainbowedge = { "Spin" }, ph_reddevil = { "Float" }, ph_evilrainbow = { "Float" }, ph_amethyst = { "Float" }, ph_molten = { "Float" },
                ph_toonblue = { "Float" }, ph_toonneon = { "Float" }, ph_goldflame = { "Float" }, ph_raidenglass = { "Spin" }, ph_pinkgold = { "Sway" },
                ph_pastel = { "Sway" }, ph_immember = { "Spin" }, ph_immtoxic = { "Spin" }, ph_lantred = { "Spin" }, ph_lantgreen = { "Spin" }, ph_jade = { "Sway" },
                ph_cyberoni = { "Float" }, ph_cyberronin = { "Float" }, ph_crane = { "Spin" }, ph_redglow = { "Spin" }, ph_bells = { "Sway" }, ph_bluekasa = { "Spin" } }
local AURA_HAT_FIT = { ph_amethyst = 0.773, ph_bamboo = 0.701, ph_bells = 0.711, ph_bluekasa = 0.793, ph_crane = 0.704, ph_cyberoni = 0.694, ph_cyberronin = 0.708,
                ph_dragon = 0.723, ph_evilrainbow = 0.773, ph_galaxy = 0.682, ph_galaxyflame = 0.682, ph_glass = 0.731, ph_goldflame = 1.017, ph_goldiron = 0.578,
                ph_immblack = 0.745, ph_immember = 0.745, ph_immpurple = 0.745, ph_immred = 0.745, ph_immtoxic = 0.745, ph_jade = 0.78, ph_lantgreen = 0.729,
                ph_lantred = 0.729, ph_molten = 0.773, ph_mossy = 1.024, ph_panda = 0.93, ph_pastel = 0.724, ph_phantom = 0.581, ph_pinkgold = 0.93, ph_purple = 0.719,
                ph_raidenglass = 0.902, ph_rainbowedge = 0.705, ph_reddevil = 0.705, ph_redglow = 0.797, ph_redronin = 0.723, ph_ronin = 0.776, ph_shadowkasa = 0.748,
                ph_toonblue = 0.701, ph_toonneon = 0.812, ph_veil = 0.794, ph_wire = 0.579 }
local AuraHat = {}

function AuraHat.accessoryKind(environment, accessory)
	local kind
	pcall(function()
		if accessory.AccessoryType == environment.Enum.AccessoryType.Hair then kind = "hair" end
		if accessory.AccessoryType == environment.Enum.AccessoryType.Hat then kind = "hat" end
	end)
	if kind then return kind end
	local handle = accessory:FindFirstChild("Handle")
	if handle and handle:FindFirstChild("HairAttachment") then return "hair" end
	if handle and handle:FindFirstChild("HatAttachment") then return "hat" end
	return nil
end

function AuraHat.hiddenParts(environment, character, hide)
	local result = {}
	for _, accessory in character:GetChildren() do
		if not accessory:IsA("Accessory") then continue end
		local kind = AuraHat.accessoryKind(environment, accessory)
		if not (kind == "hat" and hide.hat or kind == "hair" and hide.hair) then continue end
		for _, object in accessory:GetDescendants() do if object:IsA("BasePart") then table.insert(result, object) end end
	end
	return result
end

function AuraHat.hairLift(environment, character, head, crown)
	local top
	for _, accessory in character:GetChildren() do
		if not accessory:IsA("Accessory") or AuraHat.accessoryKind(environment, accessory) ~= "hair" then continue end
		local handle = accessory:FindFirstChild("Handle")
		if not handle or not handle:IsA("MeshPart") or handle.Transparency >= 0.95 then continue end
		local frame, size = head.CFrame:ToObjectSpace(handle.CFrame), handle.Size
		if math.abs(frame.X) >= head.Size.X or math.abs(frame.Z) >= head.Size.Z then continue end
		local height = frame.Y + math.abs(frame.XVector.Y) * size.X / 2 + math.abs(frame.YVector.Y) * size.Y / 2 + math.abs(frame.ZVector.Y) * size.Z / 2
		if not top or height > top then top = height end
	end
	return top and math.clamp((top - crown.Y) * 0.7, 0, 0.9) or 0
end

function AuraHat.collect(state, hat, roots)
	local environment = state.context.environment
	local objects = {}
	for _, root in roots do
		table.insert(objects, root)
		for _, object in root:GetDescendants() do table.insert(objects, object) end
	end
	for _, object in objects do
		local record
		if object:IsA("BasePart") then record = {object = object, kind = "part", color = object.Color, transparency = object.Transparency} end
		if object:IsA("SpecialMesh") then
			local material = object.Parent and object.Parent:IsA("BasePart") and object.Parent.Material
			record = {object = object, kind = "mesh", color = object.VertexColor, multiplier = material == environment.Enum.Material.ForceField and 0 or (material == environment.Enum.Material.Neon and 0.9 or 1.3)}
		end
		if object:IsA("Highlight") then record = {object = object, kind = "highlight", color = object.OutlineColor, second = object.FillColor, transparency = object.FillTransparency, outline = object.OutlineTransparency} end
		if object:IsA("Fire") then record = {object = object, kind = "fire", color = object.Color, second = object.SecondaryColor} end
		if object:IsA("ParticleEmitter") or object:IsA("Beam") or object:IsA("Trail") then record = {object = object, kind = "sequence", color = object.Color} end
		if object:IsA("Light") then record = {object = object, kind = "light", color = object.Color} end
		if not record then continue end
		local part = object:IsA("BasePart") and object or object:FindFirstAncestorWhichIsA("BasePart")
		local position = part and hat.root.CFrame:PointToObjectSpace(part.Position) or environment.Vector3.zero
		record.phase = math.atan2(position.Z, position.X) / (2 * math.pi) % 1
		table.insert(hat.colors, record)
	end
end

function AuraHat.restore(hat)
	for _, record in hat.colors do
		pcall(function()
			local object = record.object
			if record.kind == "part" then object.Color, object.Transparency = record.color, record.transparency; return end
			if record.kind == "mesh" then object.VertexColor = record.color; return end
			if record.kind == "highlight" then
				object.OutlineColor, object.FillColor, object.FillTransparency, object.OutlineTransparency = record.color, record.second, record.transparency, record.outline
				return
			end
			if record.kind == "fire" then object.Color, object.SecondaryColor = record.color, record.second; return end
			object.Color = record.color
		end)
	end
end

function AuraHat.paint(state, hat, phase, wave)
	local environment = state.context.environment
	for _, record in hat.colors do
		local object = record.object
		local color = environment.Color3.fromHSV((phase + (wave and record.phase or 0)) % 1, 0.78, 1)
		if record.kind == "part" then object.Color = color; continue end
		if record.kind == "mesh" then
			if record.multiplier > 0 then object.VertexColor = environment.Vector3.new(color.R, color.G, color.B) * record.multiplier end
			continue
		end
		if record.kind == "highlight" then object.OutlineColor, object.FillColor = color, color; continue end
		if record.kind == "fire" then object.Color, object.SecondaryColor = color, color:Lerp(environment.Color3.new(1, 1, 1), 0.35); continue end
		if record.kind == "sequence" then object.Color = environment.ColorSequence.new(color); continue end
		object.Color = color
	end
end

function AuraHat.pulse(hat, value)
	for _, record in hat.colors do
		if record.kind == "part" and record.transparency < 1 then record.object.Transparency = record.transparency + (1 - record.transparency) * 0.6 * value end
		if record.kind == "highlight" then record.object.FillTransparency = record.transparency + (1 - record.transparency) * 0.8 * value end
	end
end

function AuraHat.step(state)
	local environment, now = state.context.environment, state.context.environment.os.clock()
	local hats, hidden = {}, {}
	for _, hat in state.hats do
		if not hat.root.Parent or not hat.weld.Parent then continue end
		table.insert(hats, hat)
		local elapsed, motion, scale, frame = (now - hat.started) * hat.speed, hat.motion, hat.scale, hat.base
		if motion == "Spin" then frame *= environment.CFrame.Angles(0, elapsed * 1.5, 0) end
		if motion == "Float" then frame *= environment.CFrame.new(0, (math.sin(elapsed * 2.2) + 1) * 0.08 * scale, 0) end
		if motion == "Spin + Float" then frame *= environment.CFrame.new(0, (math.sin(elapsed * 2.2) + 1) * 0.08 * scale, 0) * environment.CFrame.Angles(0, elapsed * 1.5, 0) end
		if motion == "Sway" then frame *= environment.CFrame.Angles(math.sin(elapsed * 1.7) * 0.1, 0, math.sin(elapsed * 1.3 + 1.1) * 0.1) end
		if motion == "Wobble" then frame *= environment.CFrame.fromAxisAngle(environment.Vector3.new(math.cos(elapsed * 2.6), 0, math.sin(elapsed * 2.6)), 0.13) end
		if motion == "Hover" then frame *= environment.CFrame.new(0, (0.45 + math.sin(elapsed * 1.8) * 0.1) * scale, 0) * environment.CFrame.Angles(0, elapsed * 0.9, 0) end
		if motion == "Bounce" then frame *= environment.CFrame.new(0, math.abs(math.sin(elapsed * 3.2)) * 0.2 * scale, 0) end
		if motion ~= "None" or not hat.still then hat.weld.C0, hat.still = frame, motion == "None" end
		if hat.fx ~= "None" and now - (hat.fxAt or 0) >= 0.025 then
			hat.fxAt = now
			if hat.fx == "Rainbow" or hat.fx == "Wave" then AuraHat.paint(state, hat, elapsed * 0.22 % 1, hat.fx == "Wave") end
			if hat.fx == "Pulse" then AuraHat.pulse(hat, 0.5 - 0.5 * math.cos(elapsed * 3.2)) end
		end
		if hat.hide then
			if now - (hat.hideAt or 0) > 0.5 then hat.hideAt, hat.hideList = now, AuraHat.hiddenParts(environment, hat.character, hat.hide) end
			for _, part in hat.hideList or {} do
				hidden[part] = true
				if part.LocalTransparencyModifier < 1 then part.LocalTransparencyModifier = 1 end
			end
		end
	end
	state.hats = hats
	for part in state.hidden do if not hidden[part] then pcall(function() part.LocalTransparencyModifier = 0 end) end end
	state.hidden = hidden
end

function AuraEngine.putHat(state, character, data, key, options)
	local environment = state.context.environment
	local head = character:FindFirstChild("Head")
	if not head or not head:IsA("BasePart") then return end
	local size = options.size or 1
	local width = head:IsA("MeshPart") and (head.Size.X + head.Size.Z) / 2 or math.min(head.Size.X, head.Size.Z) * 1.2
	local fit = math.clamp(width / 1.196, 0.5, 2.5) * (AURA_HAT_FIT[key] or 1)
	local attachment = head:FindFirstChild("HatAttachment")
	local crown = attachment and attachment:IsA("Attachment") and attachment.CFrame or environment.CFrame.new(0, head.Size.Y / 2, 0)
	local hair = 0
	if not (options.mine and options.hideHair == true) then
		local ok, value = pcall(AuraHat.hairLift, environment, character, head, crown)
		if ok then hair = value end
	end
	local base = crown * environment.CFrame.new(0, (options.lift or 0) + hair, 0)
	local root = environment.Instance.new("Part")
	root.Name, root.Size, root.Transparency, root.Anchored = "PulseHatRoot", environment.Vector3.new(0.05, 0.05, 0.05), 1, false
	root.CanCollide, root.CanQuery, root.CanTouch, root.Massless, root.CastShadow = false, false, false, true, false
	root.CFrame = head.CFrame * base
	local weld = environment.Instance.new("Weld")
	weld.Name, weld.Part0, weld.Part1, weld.C0, weld.Parent = "PulseHatWeld", head, root, base, root
	root:SetAttribute("PulseVFX", true)
	root:SetAttribute("PulseVFXKey", key)
	root.Parent = character
	local build = {key = key, options = options, off = options.off or {}, size = size, ids = {}, links = {}, liftV = environment.Vector3.zero,
		hatHost = root, hatK = fit, hatCrown = data.crown or 0.6,
		hatTune = {size = fit * size, density = options.density or 1, bright = options.bright or 1, alpha = options.alpha or 1}}
	local roots = {}
	for _, host in data.h or {} do
		for _, child in host.k or {} do
			local built = AuraEngine.build(environment, child, character, build)
			if built then table.insert(roots, built) end
		end
	end
	AuraEngine.link(build)
	local defaults = AURA_HAT_DEFAULTS[key] or {}
	local hat = {character = character, root = root, weld = weld, base = base, scale = fit * size, key = key, started = environment.os.clock(), still = true,
		colors = {}, motion = options.motion or defaults[1] or "None", fx = options.cfx or defaults[2] or "None", speed = math.clamp(tonumber(options.aspd) or 1, 0.1, 3)}
	if options.mine and (options.hideHat ~= false or options.hideHair == true) then hat.hide = {hat = options.hideHat ~= false, hair = options.hideHair == true} end
	AuraHat.collect(state, hat, roots)
	table.insert(state.hats, hat)
end

local AuraTint = {}

function AuraTint.roots(state, character)
	local roots = {}
	if not character then return roots end
	table.insert(roots, character)
	local context, globals = state.context, state.context.environment.getgenv()
	local model
	if character == context.player.Character then
		if type(globals.__pulseSkinModel) == "function" then
			local ok, result = pcall(globals.__pulseSkinModel)
			if ok then model = result end
		end
	else
		local player = context.players:GetPlayerFromCharacter(character)
		local remote = rawget(globals, "__pulseRemoteSkin")
		if player and type(remote) == "table" and type(remote.liveModel) == "function" then
			local ok, result = pcall(remote.liveModel, player)
			if ok then model = result end
		end
	end
	if model then table.insert(roots, model) end
	return roots
end

function AuraTint.applyObject(state, object, color, glow, remote)
	local environment = state.context.environment
	local sequence = object:IsA("ParticleEmitter") or object:IsA("Beam") or object:IsA("Trail")
	local light = object:IsA("PointLight") or object:IsA("SpotLight") or object:IsA("SurfaceLight")
	if sequence then
		if state.colors[object] == nil then state.colors[object] = object.Color end
		if state.emission[object] == nil then state.emission[object] = object.LightEmission end
		object.Color = color and AuraEngine.recolor(environment, state.colors[object], color) or state.colors[object]
		object.LightEmission = color and state.emission[object] * glow or state.emission[object]
		return
	end
	if light then
		if state.colors[object] == nil then state.colors[object] = object.Color end
		if state.secondary[object] == nil then state.secondary[object] = object.Brightness end
		object.Color, object.Brightness = color or state.colors[object], color and state.secondary[object] * glow or state.secondary[object]
		return
	end
	if remote then return end
	if object:IsA("BasePart") and object.Name ~= "PulseAuraHost" or object:IsA("Fire") then
		if state.colors[object] == nil then state.colors[object] = object.Color end
		object.Color = color or state.colors[object]
		return
	end
	if object:IsA("Highlight") then
		if state.colors[object] == nil then state.colors[object] = object.OutlineColor end
		if state.secondary[object] == nil then state.secondary[object] = object.FillColor end
		object.OutlineColor, object.FillColor = color or state.colors[object], color or state.secondary[object]
		return
	end
	if object:IsA("SpecialMesh") then
		local material = object.Parent and object.Parent:IsA("BasePart") and object.Parent.Material
		if material == environment.Enum.Material.ForceField then return end
		if state.colors[object] == nil then state.colors[object] = object.VertexColor end
		object.VertexColor = color and environment.Vector3.new(color.R, color.G, color.B) * (material == environment.Enum.Material.Neon and 1 or 1.6) or state.colors[object]
	end
end

function AuraTint.apply(state, character, remoteOptions)
	local context, environment = state.context, state.context.environment
	character = character or context.player.Character
	if not character then return end
	local remote = remoteOptions ~= nil
	local globals = environment.getgenv()
	local common = not remote and globals.__pulseFxTintOn and globals.__pulseFxColor and globals.__pulseFxColor() or nil
	local options = context.configuration.vfxCol or {}
	for _, root in AuraTint.roots(state, character) do
		for _, object in root:GetDescendants() do
			if not object:GetAttribute("PulseVFX") then continue end
			pcall(function()
				local key = object:GetAttribute("PulseVFXKey")
				local color, glow = common, 1
				if remote then
					local packed = remoteOptions[key]
					if type(packed) == "number" and packed > 1 then
						local brightness, rgb = math.floor(packed / 16777216), packed % 16777216
						color = environment.Color3.fromRGB(math.floor(rgb / 65536) % 256, math.floor(rgb / 256) % 256, rgb % 256)
						if brightness > 0 then glow = brightness / 100 end
					end
				else
					local custom = key and options[key]
					if custom and custom.custom then
						color = environment.Color3.fromRGB(custom.r, custom.g, custom.b)
						glow = custom.glow and custom.glow / 100 or 1
					end
				end
				AuraTint.applyObject(state, object, color, glow, remote)
				for _, child in object:GetDescendants() do AuraTint.applyObject(state, child, color, glow, remote) end
			end)
		end
	end
end

function AuraTint.install(context)
	local environment, globals = context.environment, context.environment.getgenv()
	local state = {context = context, colors = setmetatable({}, {__mode = "k"}), emission = setmetatable({}, {__mode = "k"}), secondary = setmetatable({}, {__mode = "k"})}
	local apply = function() AuraTint.apply(state) end
	local applyFor = function(character, options) if character and type(options) == "table" then AuraTint.apply(state, character, options) end end
	globals.__pulseVFXTint, globals.__pulseVFXTintFor = apply, applyFor
	context.connect(context.player.CharacterAdded, function()
		environment.task.wait(0.8)
		pcall(apply)
	end)
	return state, function()
		for object in state.colors do pcall(AuraTint.applyObject, state, object, nil, 1, false) end
		if globals.__pulseVFXTint == apply then globals.__pulseVFXTint = nil end
		if globals.__pulseVFXTintFor == applyFor then globals.__pulseVFXTintFor = nil end
	end
end

