	Aurora = {foot = {{acc = {0, 1.2, 0}, color = {{255, 255, 255}, {120, 230, 255}}, life = {0.8, 1.4}, rate = 16, size = {0.12, 0}, speed = {0.6, 1.6}, spread = 40, tex = "rbxassetid://16512006463"}, {color = {{255, 255, 255}, {170, 140, 255}}, life = {0.5, 0.9}, rate = 6, rot = 60, size = {0.2, 0}, speed = {0.3, 0.8}, spread = 90, tex = "rbxassetid://14221498728"}}, rib = {{120, 255, 210}, {80, 190, 255}, {180, 110, 255}}, ribLife = 0.9, step = {{color = {{120, 240, 255}}, life = 0.9, n = 1, size = {0.4, 3.2}, tex = "rbxassetid://12403112662"}}, sw = {{80, 255, 200}, {180, 110, 255}}, width = 0.55},
	Comet = {foot = {{acc = {0, -2, 0}, color = {{255, 255, 255}, {255, 210, 120}}, life = {0.5, 1}, rate = 22, rot = 180, size = {0.22, 0}, speed = {1, 2.5}, spread = 70, tex = "rbxassetid://14221498728"}}, rib = {{255, 255, 255}, {255, 230, 160}, {255, 170, 70}}, ribLife = 0.7, step = {{color = {{255, 220, 150}}, life = 0.6, n = 1, size = {0.6, 2.6}, tex = "rbxassetid://7216856402"}}, sw = {{255, 250, 230}, {255, 190, 90}}, width = 0.45},
