	Frost = {foot = {{color = {{255, 255, 255}, {160, 220, 255}}, life = {0.7, 1.2}, par = true, rate = 12, size = {0.22, 0.08}, speed = {1.4, 2.6}, spread = 25, tex = "rbxassetid://7016382152"}, {color = {{230, 245, 255}}, le = 0.3, life = {1, 1.6}, rate = 6, size = {0.8, 2}, speed = {0.2, 0.5}, spread = 80, tex = "rbxasset://textures/particles/smoke_main.dds", tr = 0.7}}, rib = {{255, 255, 255}, {170, 225, 255}, {110, 180, 255}}, ribLife = 1, step = {{color = {{200, 236, 255}}, life = 1.1, n = 1, size = {0.4, 3.4}, tex = "rbxassetid://12403112662"}}, sw = {{230, 248, 255}, {110, 190, 255}}, width = 0.5},
	Rainbow = {foot = {{acc = {0, 1, 0}, color = {{255, 120, 120}, {255, 230, 120}, {120, 220, 255}, {210, 140, 255}}, life = {0.6, 1.1}, rate = 14, rot = 90, size = {0.25, 0}, speed = {0.8, 1.8}, spread = 60, tex = "rbxassetid://17391818367"}}, rib = {{255, 80, 80}, {255, 180, 60}, {255, 240, 80}, {90, 230, 120}, {80, 170, 255}, {190, 110, 255}}, ribLife = 1, step = {{color = {{255, 150, 220}, {140, 200, 255}}, life = 0.9, n = 1, size = {0.4, 3}, tex = "rbxassetid://12403112662"}}, sw = {{255, 90, 90}, {90, 140, 255}}, width = 0.6},
	Neon = {foot = {{color = {{255, 120, 230}, {80, 230, 255}}, life = {0.4, 0.8}, rate = 14, size = {0.12, 0}, speed = {0.5, 1.5}, spread = 90, tex = "rbxassetid://16512006463"}}, glow = 4, rib = {{255, 70, 200}, {160, 70, 255}, {0, 220, 255}}, ribLife = 0.8, step = {{color = {{255, 80, 210}}, life = 0.7, n = 1, size = {0.3, 2.6}, tex = "rbxassetid://12403112662"}, {color = {{40, 220, 255}}, life = 0.9, n = 1, size = {0.2, 1.8}, tex = "rbxassetid://12403112662"}}, sw = {{255, 60, 200}, {0, 230, 255}}, width = 0.35},
