local Weather = {}
local WEATHER_QUALITIES = {Light = {rate = 0.45, probeInterval = 0.6}, Balanced = {rate = 0.8, probeInterval = 0.45},
	High = {rate = 1.15, probeInterval = 0.4}, Ultra = {rate = 1.6, probeInterval = 0.35}}
local WEATHER_LIMITS = {amount = {60, 0, 100}, opacity = {80, 20, 100}, scale = {1, 0.5, 1.8}, speed = {100, 60, 150},
	wind = {5, 0, 18}, windAngle = {35, 0, 360}, soundVolume = {60, 0, 100}, stormPower = {50, 0, 100},
	wetness = {55, 0, 100}, radius = {30, 12, 50}}
local WEATHER_ORDER = {"Snow", "Blossom", "Leaves", "Fireflies", "Mist", "Embers", "Ash", "Pollen"}

function Weather.defaults(environment)
	local rgb = environment.Color3.fromRGB
	return {on = false, kind = "Snow", amount = 60, quality = "Balanced", opacity = 80, scale = 1, speed = 100,
		wind = 5, windAngle = 35, gusts = true, shelter = true, grade = true, sound = true, soundVolume = 60,
		thunder = false, stormPower = 50, wet = true, wetness = 55, radius = 30, ripples = true, matchLight = true,
		snowColour = rgb(240, 246, 255), petalColour = rgb(255, 255, 255), leafColour = rgb(255, 255, 255),
		mistColour = rgb(214, 222, 232), emberColour = rgb(255, 140, 44), ashColour = rgb(168, 164, 160),
		fireflyColour = rgb(196, 255, 96), pollenColour = rgb(255, 238, 190), scene = ""}
end

function Weather.validate(state)
	local values = state.values
	if not state.recipes[values.kind] then values.kind = "Snow" end
	if not WEATHER_QUALITIES[values.quality] then values.quality = "Balanced" end
	for key, limits in pairs(WEATHER_LIMITS) do
		local value = tonumber(values[key])
		if not value or value ~= value or math.abs(value) == math.huge then value = limits[1] end
		values[key] = math.clamp(value, limits[2], limits[3])
	end
	for _, key in ipairs({"snowColour", "petalColour", "leafColour", "mistColour", "emberColour", "ashColour", "fireflyColour", "pollenColour"}) do
		if state.context.environment.typeof(values[key]) ~= "Color3" then values[key] = state.defaults[key] end
	end
end

function Weather.stop(state)
	for _, object in ipairs({state.folder, state.grade}) do if object then pcall(function() object:Destroy() end) end end
	state.folder, state.grade, state.camera, state.builtKind, state.builtQuality, state.builtSound = nil, nil, nil, nil, nil, nil
	state.character, state.position, state.params = nil, nil, nil
	table.clear(state.nodes)
	table.clear(state.voices)
	state.visibility, state.frameElapsed, state.probeElapsed = 0, 0, 1
	state.covered, state.suspended, state.dirty, state.squash = nil, nil, true, nil
	state.audioLevel, state.coverBlend, state.gradeLevel = 0, 0, 0
end

function Weather.filter(state)
	local env = state.context.environment
	local excluded = {state.camera}
	for _, player in ipairs(state.context.players:GetPlayers()) do if player.Character then table.insert(excluded, player.Character) end end
	for part in pairs(state.invisible) do if part.Parent then table.insert(excluded, part) end end
	local params = env.RaycastParams.new()
	params.FilterType, params.FilterDescendantsInstances, params.IgnoreWater = env.Enum.RaycastFilterType.Exclude, excluded, true
	pcall(function() params.RespectCanCollide = true end)
	state.params = params
end

function Weather.cast(state, origin, direction)
	if not state.params then return nil, false end
	for _ = 1, 6 do
		local ok, result = pcall(state.context.workspace.Raycast, state.context.workspace, origin, direction, state.params)
		if not ok then return nil, false end
		if not result then return nil, true end
		local part = result.Instance
		if not part:IsA("BasePart") or part.Transparency < 0.95 then return result, true end
		state.invisible[part] = true
		pcall(function() state.params:AddToFilter(part) end)
	end
	return nil, true
end

function Weather.volume(state, name)
	local env = state.context.environment
	local part = env.Instance.new("Part")
	part.Name, part.Anchored, part.CanCollide, part.CanTouch, part.CanQuery = name, true, false, false, false
	part.CastShadow, part.Transparency, part.Size, part.Parent = false, 1, env.Vector3.new(1, 1, 1), state.folder
	return part
end

function Weather.build(state, camera)
	Weather.stop(state)
	local env, values = state.context.environment, state.values
	state.camera, state.character = camera, state.context.player.Character
	state.builtKind, state.builtQuality, state.builtSound = values.kind, values.quality, values.sound
	state.folder = env.Instance.new("Folder")
	state.folder.Name, state.folder.Parent = "PulseWeather", camera
	local recipe = state.recipes[values.kind]
	for index, layer in ipairs(recipe.layers) do
		local grid = layer.noShelter and 1 or 3
		local center = (grid + 1) / 2
		for row = 1, grid do
			for column = 1, grid do
				local part = Weather.volume(state, "WeatherVolume" .. index .. "_" .. row .. "_" .. column)
				local emitter = env.Instance.new("ParticleEmitter")
				emitter.Name, emitter.Enabled, emitter.Rate, emitter.LockedToPart = "WeatherParticles", false, 0, false
				emitter.VelocityInheritance, emitter.EmissionDirection = 0, layer.lift and env.Enum.NormalId.Top or env.Enum.NormalId.Bottom
				pcall(function()
					emitter.Shape, emitter.ShapeStyle, emitter.ShapeInOut = env.Enum.ParticleEmitterShape.Box,
						env.Enum.ParticleEmitterShapeStyle.Volume, env.Enum.ParticleEmitterShapeInOut.Outward
				end)
				emitter.Parent = part
				table.insert(state.nodes, {part = part, emitter = emitter, layer = layer, grid = grid, slots = grid * grid,
					gx = column - center, gz = row - center, seed = math.random() * 6.2832, blocked = true})
			end
		end
	end
	state.grade = env.Instance.new("ColorCorrectionEffect")
	state.grade.Name, state.grade.Parent = "PulseWeatherGrade", camera
	if values.sound then
		for _, spec in ipairs(recipe.voices or {}) do
			local sound, equalizer = env.Instance.new("Sound"), env.Instance.new("EqualizerSoundEffect")
			sound.Name, sound.SoundId, sound.Looped, sound.Volume = "Voice", spec.id, true, 0
			sound.RollOffMode, sound.Parent = env.Enum.RollOffMode.Linear, state.folder
			equalizer.LowGain, equalizer.MidGain, equalizer.HighGain, equalizer.Parent = 0, 0, 0, sound
			pcall(function() sound:Play() end)
			table.insert(state.voices, {sound = sound, equalizer = equalizer, spec = spec, level = 0})
		end
	end
	Weather.filter(state)
	state.dirty = true
end

function Weather.sequence(environment, points)
	local keypoints = {}
	for _, point in ipairs(points) do table.insert(keypoints, environment.NumberSequenceKeypoint.new(table.unpack(point))) end
	return environment.NumberSequence.new(keypoints)
end

function Weather.configure(state)
	local env, v, recipe = state.context.environment, state.values, state.recipes[state.values.kind]
	local color, opacity, speed = v[recipe.colour], v.opacity / 100, v.speed / 100
	local white, dark = env.Color3.new(1, 1, 1), state.envDark
	for _, node in ipairs(state.nodes) do
		local layer, emitter = node.layer, node.emitter
		node.tile = v.radius * 2 * layer.reach / node.grid
		node.part.Size = env.Vector3.new(node.tile, layer.h, node.tile)
		local amount = v.amount / 100
		local rate = layer.from and amount < layer.from and 0 or layer.rate[1] + (layer.rate[2] - layer.rate[1]) * amount
		node.rate = rate * WEATHER_QUALITIES[v.quality].rate * (v.radius / 30) ^ 2 / node.slots
		emitter.Texture = state.textures[layer.tex]
		local base, tint, fire = layer.col or color, layer.tint or 0.2, layer.col2 and v[layer.col2] or color
		if layer.fire then
			emitter.Color = env.ColorSequence.new({env.ColorSequenceKeypoint.new(0, fire:Lerp(env.Color3.fromRGB(255, 246, 210), 0.65)),
				env.ColorSequenceKeypoint.new(0.35, fire), env.ColorSequenceKeypoint.new(1, fire:Lerp(env.Color3.fromRGB(140, 20, 6), 0.65))})
		else
			emitter.Color = env.ColorSequence.new(base:Lerp(white, layer.pulse and 0.35 or tint), base)
		end
		emitter.LightInfluence = layer.light or 0.3
		emitter.LightEmission = math.clamp((layer.glow or 0) * (0.4 + 0.6 * dark), 0, 1)
		emitter.Lifetime = env.NumberRange.new(layer.life[1] / speed, layer.life[2] / speed)
		emitter.Speed = env.NumberRange.new(layer.speed[1] * speed, layer.speed[2] * speed)
		local low, high = layer.size[1] * v.scale, layer.size[2] * v.scale
		local midpoint, spread = (low + high) * 0.5, (high - low) * 0.5
		local sizes = {{0, midpoint * 0.9, spread}, {0.2, midpoint, spread}, {1, midpoint * 0.92, spread}}
		if layer.pulse then sizes = {{0, 0}, {0.12, midpoint}, {0.3, high * 0.45}, {0.5, high}, {0.72, low * 0.5}, {0.88, midpoint * 0.8}, {1, 0}} end
		if layer.fire then sizes = {{0, midpoint, spread}, {0.7, midpoint * 0.75, spread * 0.7}, {1, midpoint * 0.2, 0}} end
		emitter.Size = Weather.sequence(env, sizes)
		local alpha = math.clamp(opacity * (layer.alpha or 1) * (0.9 + 0.2 * dark), 0, 1)
		local fade = {{0, 1}, {0.1, 1 - alpha}, {0.78, 1 - alpha}, {1, 1}}
		if layer.pulse or layer.flicker then
			fade = {{0, 1}, {0.1, 1 - alpha}, {0.3, 1 - alpha * 0.15}, {0.5, 1 - alpha * 0.1},
				{0.68, 1 - alpha}, {0.85, 1 - alpha * 0.25}, {1, 1}}
		end
		emitter.Transparency = Weather.sequence(env, fade)
		emitter.SpreadAngle, emitter.Drag = env.Vector2.new(layer.spread or 5, layer.spread or 5), layer.drag or 0
		emitter.Rotation = layer.rot and env.NumberRange.new(0, 360) or env.NumberRange.new(0)
		emitter.RotSpeed = layer.rot and env.NumberRange.new(-layer.rot, layer.rot) or env.NumberRange.new(0)
		emitter.Orientation, emitter.Enabled = env.Enum.ParticleOrientation.FacingCamera, true
		pcall(function() emitter.FlipbookLayout = env.Enum.ParticleFlipbookLayout.None end)
	end
	state.dirty = false
end

function Weather.updateSquash(state)
	local env = state.context.environment
	local stretch = state.context.configuration.ui and tonumber(state.context.configuration.ui.stretch) or 0
	local squash = stretch > 0 and math.floor(-math.log(math.max(0.1, 1 - stretch / 100 * 0.6), 2) * 100 + 0.5) / 100 or 0
	if state.squash == squash then return end
	state.squash = squash
	for _, node in ipairs(state.nodes) do
		local layer, emitter = node.layer, node.emitter
		local rotating = layer.rot and not (squash > 0 and not layer.flutter)
		emitter.Rotation = rotating and env.NumberRange.new(0, 360) or env.NumberRange.new(0)
		emitter.RotSpeed = rotating and env.NumberRange.new(-layer.rot, layer.rot) or env.NumberRange.new(0)
		pcall(function()
			if layer.flutter then
				emitter.Squash = Weather.sequence(env, {{0, 0}, {0.14, 0.75}, {0.29, -0.55}, {0.43, 0.65},
					{0.57, -0.7}, {0.71, 0.5}, {0.86, -0.6}, {1, 0.2}})
			else emitter.Squash = env.NumberSequence.new(math.clamp(squash, -3, 3)) end
		end)
	end
end

function Weather.clearParticles(state)
	for _, node in ipairs(state.nodes) do pcall(function() node.emitter:Clear() end) end
end

function Weather.covered(state, position, height)
	local vector = state.context.environment.Vector3
	local hit, valid = Weather.cast(state, position + vector.new(0, 0.4, 0), vector.new(0, height or 40, 0))
	return not valid or hit ~= nil
end

function Weather.probe(state, focus)
	local vector, v = state.context.environment.Vector3, state.values
	Weather.filter(state)
	local covered = v.shelter and Weather.covered(state, focus) or false
	if covered and not state.covered then
		for _, node in ipairs(state.nodes) do if not node.layer.noShelter then node.emitter:Clear() end end
	end
	state.covered = covered
	for _, node in ipairs(state.nodes) do
		local blocked = false
		if not node.layer.noShelter then
			blocked = covered or v.shelter and Weather.covered(state, vector.new(node.part.Position.X, focus.Y, node.part.Position.Z), math.max(node.layer.h, 8) + 8)
		end
		if blocked and not node.blocked then node.emitter:Clear() end
		node.blocked = blocked
	end
end

function Weather.gust(state)
	if not state.values.gusts then return 1 end
	local phase = state.phase
	return 0.8 + math.sin(phase * 0.7) * 0.2 + math.sin(phase * 1.9) * 0.08 + math.sin(phase * 0.23 + 1.3) * 0.1
end

function Weather.audio(state, delta)
	local v = state.values
	local target = v.amount > 0 and 1 or 0
	state.audioLevel += (target - state.audioLevel) * (1 - math.exp(-delta * 2.5))
	target = state.covered and 1 or 0
	state.coverBlend += (target - state.coverBlend) * (1 - math.exp(-delta * 3))
	local fade, amount = 1 - math.exp(-delta * 3.5), v.amount / 100
	for _, voice in ipairs(state.voices) do
		local spec = voice.spec
		local level = spec.lo + (spec.hi - spec.lo) * amount
		if spec.from then level *= math.clamp((amount - spec.from) / 0.2, 0, 1) end
		level *= spec.base
		if spec.wind then level *= 0.35 + 0.65 * math.clamp(v.wind / 10, 0, 1.4) * Weather.gust(state) end
		local shelter = 1 - state.coverBlend * 0.55
		if spec.roof then shelter = state.coverBlend end
		if spec.open then shelter = 1 - state.coverBlend * 0.75 end
		if spec.steady then shelter = 1 end
		level *= v.soundVolume / 100 * state.audioLevel * shelter
		voice.level += (level - voice.level) * fade
		voice.sound.Volume = voice.level
		local highGain = state.coverBlend > 0.5 and not spec.roof and -14 or 0
		voice.equalizer.HighGain += (highGain - voice.equalizer.HighGain) * fade
	end
end

function Weather.gradeStep(state, delta)
	local v = state.values
	local grade = v.grade and state.grades[state.recipes[v.kind].grade or ""] or nil
	local target = grade and v.amount > 0 and 0.35 + 0.65 * v.amount / 100 or 0
	state.gradeLevel += (target - state.gradeLevel) * (1 - math.exp(-delta * 1.5))
	if not grade then state.grade.Enabled = false; return end
	state.grade.Enabled = true
	state.grade.TintColor = state.context.environment.Color3.new(1, 1, 1):Lerp(grade.tint, state.gradeLevel)
	state.grade.Saturation, state.grade.Contrast, state.grade.Brightness = grade.saturation * state.gradeLevel,
		grade.contrast * state.gradeLevel, grade.brightness * state.gradeLevel
end

function Weather.groundY(state, focus)
	local now = os.clock()
	if state.groundAt and now - state.groundAt < 0.5 and state.groundY then return state.groundY end
	local vector = state.context.environment.Vector3
	local hit = Weather.cast(state, focus + vector.new(0, 4, 0), vector.new(0, -60, 0))
	state.groundAt, state.groundY = now, hit and hit.Position.Y or focus.Y - 3
	return state.groundY
end

function Weather.step(state, delta)
	local context, v = state.context, state.values
	if not v.on or not context.isAlive() then if state.folder then Weather.stop(state) end; return end
	local camera = context.workspace.CurrentCamera
	if not camera then if state.folder then Weather.stop(state) end; return end
	delta = tonumber(delta) or 1 / 60
	if delta ~= delta or math.abs(delta) == math.huge then delta = 1 / 60 end
	state.frameElapsed += math.clamp(delta, 0, 0.1)
	if state.frameElapsed < 1 / 30 then return end
	delta, state.frameElapsed = state.frameElapsed, 0
	state.phase += delta
	Weather.validate(state)
	state.envClock += delta
	if state.envClock > 1 then
		state.envClock = 0
		local lighting = context.lighting
		local time, ambient = lighting.ClockTime, lighting.OutdoorAmbient
		local day = math.clamp((time - 5.5) / 1.5, 0, 1) * math.clamp((19.5 - time) / 1.5, 0, 1)
		local dark = math.clamp(1 - (ambient.R + ambient.G + ambient.B) / 3 / 0.55, 0, 1)
		local nextDark = math.max(1 - day, dark * 0.8)
		if math.abs(state.envDark - nextDark) > 0.08 then state.dirty = true end
		state.envDark = nextDark
	end
	if state.camera ~= camera or not state.folder or state.folder.Parent ~= camera or state.builtKind ~= v.kind
		or state.builtQuality ~= v.quality or state.builtSound ~= v.sound then Weather.build(state, camera) end
	local env, frame, character = context.environment, camera.CFrame, context.player.Character
	local focus = frame.Position
	local root = character and character:FindFirstChild("HumanoidRootPart")
	if root and (root.Position - focus).Magnitude < 70 then focus = root.Position end
	local look = env.Vector3.new(frame.LookVector.X, 0, frame.LookVector.Z)
	if look.Magnitude > 0.05 then focus += look.Unit * 4 end
	if state.character ~= character or state.position and (focus - state.position).Magnitude > 48 then
		Weather.clearParticles(state)
		state.visibility, state.probeElapsed = 0, 1
		Weather.filter(state)
	end
	state.character, state.position = character, focus
	if state.dirty then Weather.configure(state); state.squash = nil end
	Weather.updateSquash(state)
	local ground = Weather.groundY(state, focus)
	for _, node in ipairs(state.nodes) do
		local height = node.layer.base == "ground" and ground + node.layer.y or focus.Y + node.layer.y
		node.part.CFrame = env.CFrame.new(focus.X + node.gx * node.tile, height, focus.Z + node.gz * node.tile)
	end
	state.probeElapsed += delta
	if state.probeElapsed >= WEATHER_QUALITIES[v.quality].probeInterval then state.probeElapsed = 0; Weather.probe(state, focus) end
	local suspended = v.amount == 0
	if suspended and not state.suspended then Weather.clearParticles(state) end
	state.suspended = suspended
	local target = suspended and 0 or 1
	state.visibility += (target - state.visibility) * (1 - math.exp(-delta * 5))
	if suspended then state.visibility = 0 end
	local angle = math.rad(v.windAngle)
	local direction = env.Vector3.new(math.cos(angle), 0, math.sin(angle))
	local sideways = env.Vector3.new(-direction.Z, 0, direction.X)
	local wind = v.wind * 0.3 * Weather.gust(state) * (v.speed / 100) ^ 2
	for _, node in ipairs(state.nodes) do
		local layer = node.layer
		local sway = math.sin(state.phase * 0.9 + node.seed) * 0.6 + math.sin(state.phase * 2.3 + node.seed * 1.7 + 1.7) * 0.4
		local along = math.cos(state.phase * 1.3 + node.seed * 0.7) * 0.5
		local force = layer.noWind and env.Vector3.zero or direction * wind * (layer.windK or 1)
		if layer.still then force = direction * (layer.drift or 0.3) * v.wind * 0.1
		else force += sideways * (layer.sway or 0) * sway + direction * (layer.sway or 0) * along * 0.5 + env.Vector3.new(0, (layer.lift or 0) - (layer.fall or 0), 0) end
		node.emitter.Acceleration = force
		node.emitter.Rate = (node.blocked or state.covered and not layer.noShelter) and 0 or node.rate * state.visibility
	end
	Weather.audio(state, delta)
	Weather.gradeStep(state, delta)
end

local WEATHER_SCENES = {
	{name = "Misty Morning", sky = "fog", look = "Overcast", weather = {kind = "Mist", amount = 70, wind = 2}},
	{name = "Snow Day", sky = "whiteout", look = "Overcast", weather = {kind = "Snow", amount = 55, wind = 4}},
	{name = "Blizzard", sky = "whiteout", look = "Overcast", weather = {kind = "Snow", amount = 100, wind = 16, speed = 130}},
	{name = "Winter Night", sky = "aurora1", look = "Night", weather = {kind = "Snow", amount = 45, wind = 3}},
	{name = "Cherry Blossom", sky = "rose", look = "Dusk", weather = {kind = "Blossom", amount = 62, wind = 5}},
	{name = "Autumn", sky = "golden", look = "Golden Hour", weather = {kind = "Leaves", amount = 58, wind = 7}},
	{name = "Golden Pollen", sky = "sunset", look = "Golden Hour", weather = {kind = "Pollen", amount = 62, wind = 2}},
	{name = "Firefly Night", sky = "mountains", look = "Night", weather = {kind = "Fireflies", amount = 65, wind = 1}},
	{name = "Bonfire Night", sky = "dusk", look = "Night", weather = {kind = "Embers", amount = 55, wind = 3}},
	{name = "Volcano", sky = "fiery", look = "Dusk", weather = {kind = "Ash", amount = 70, wind = 5}},
	{name = "Northern Lights", sky = "aurora2", look = "Night", fx = {"stars", "meteors"}},
	{name = "Clear Day", sky = "clear", look = "Natural"},
	{name = "Deep Space", sky = "nebula", look = "Night", fx = {"stars", "comets"}},
	{name = "Starry Night", sky = "mountains", look = "Night", fx = {"stars", "meteors"}},
	{name = "Meteor Shower", sky = "nebula", look = "Night", fx = {"stars", "meteors", "comets"}},
	{name = "Magic Night", sky = "aurora3", look = "Night", fx = {"stars", "runes", "dust", "net"}},
	{name = "Constellation Night", sky = "mountains", look = "Night", fx = {"net"}},
}

function Weather.syncUI(state)
	for key, control in pairs(state.controls) do
		if control.SetSilent then pcall(control.SetSilent, state.values[key]) end
	end
	if state.paintScenes then state.paintScenes() end
	if state.paintSkies then state.paintSkies() end
end

function Weather.changed(state)
	Weather.validate(state)
	state.dirty, state.probeElapsed = true, 1
	if not state.values.on then Weather.stop(state) end
end

function Weather.setSky(state, key)
	local api = state.context.environment.getgenv().__pulseSkyAPI
	if not api then return end
	if key and key ~= "" then api.activate(key, true) else api.clear() end
	if state.paintSkies then state.paintSkies() end
end

function Weather.takeLook(state, name)
	local world = state.context.visualWorld
	if not state.lookByWeather then state.previousLook = {preset = world.values.preset, on = world.values.on} end
	VisualWorld.preset(world, name)
	state.lookByWeather = true
end

function Weather.restoreLook(state)
	if not state.lookByWeather then return end
	state.lookByWeather = false
	local previous = state.previousLook
	state.previousLook = nil
	if previous and previous.on and previous.preset ~= "Original" then VisualWorld.preset(state.context.visualWorld, previous.preset); return end
	VisualWorld.preset(state.context.visualWorld, "Original")
end

function Weather.pickSky(state, key)
	local api = state.context.environment.getgenv().__pulseSkyAPI
	if api and api.active() == key then
		Weather.setSky(state, nil)
		if state.values.matchLight then Weather.restoreLook(state) end
		return
	end
	Weather.setSky(state, key)
	if not state.values.matchLight then return end
	for _, sky in ipairs(state.skies) do if sky.key == key and sky.look then Weather.takeLook(state, sky.look); return end end
end

function Weather.scene(state, name)
	local scene
	for _, item in ipairs(WEATHER_SCENES) do if item.name == name then scene = item; break end end
	if not scene then return end
	Weather.stop(state)
	local keep = {quality = true, shelter = true, sound = true, soundVolume = true, wet = true, wetness = true,
		grade = true, matchLight = true, radius = true, scale = true, ripples = true, gusts = true}
	for key, value in pairs(state.defaults) do
		if not keep[key] and not key:find("olour", 1, true) then state.values[key] = value end
	end
	state.values.scene, state.values.on = name, scene.weather ~= nil
	for key, value in pairs(scene.weather or {}) do state.values[key] = value end
	Weather.changed(state)
	Weather.setSky(state, scene.sky)
	if scene.look then Weather.takeLook(state, scene.look) end
	local skyFx = state.context.environment.getgenv().__pulseSkyFx
	if type(skyFx) == "table" then
		if scene.fx then pcall(skyFx.scene, scene.fx) else pcall(skyFx.sceneEnd) end
	end
	Weather.syncUI(state)
end

function Weather.clearScene(state)
	local skyFx = state.context.environment.getgenv().__pulseSkyFx
	if type(skyFx) == "table" then pcall(skyFx.sceneEnd) end
	state.values.scene, state.values.on = "", false
	Weather.changed(state)
	Weather.setSky(state, nil)
	Weather.restoreLook(state)
	Weather.syncUI(state)
end

function Weather.applyExtra(state, preset)
	local extra
	for _, item in ipairs(state.context.visualWorld.presets) do if item.name == preset then extra = item.extra; break end end
	if not extra then
		if not state.extrasOn then return end
		state.extrasOn = false
		state.values.scene, state.values.on = "", false
		Weather.changed(state)
		if state.extrasSky then Weather.setSky(state, nil) end
		state.extrasSky = nil
		Weather.syncUI(state)
		return
	end
	Weather.stop(state)
	local keep = {quality = true, shelter = true, sound = true, soundVolume = true, wet = true, wetness = true,
		grade = true, matchLight = true, radius = true, scale = true, ripples = true, gusts = true}
	for key, value in pairs(state.defaults) do
		if not keep[key] and not key:find("olour", 1, true) then state.values[key] = value end
	end
	state.values.scene, state.values.on = "", type(extra.weather) == "table"
	for key, value in pairs(extra.weather or {}) do state.values[key] = value end
	Weather.changed(state)
	if extra.sky then Weather.setSky(state, extra.sky); state.extrasSky = extra.sky end
	state.extrasOn = true
	Weather.syncUI(state)
end

function Weather.sceneGallery(state)
	local context, env = state.context, state.context.environment
	local container = context.section:Container()
	if not container then return false end
	local create = context.create
	local frame = create("Frame", {Size = env.UDim2.new(1, 0, 0, 0), AutomaticSize = env.Enum.AutomaticSize.Y, BackgroundTransparency = 1}, container)
	create("UIGridLayout", {CellSize = env.UDim2.new(0.5, -4, 0, 34), CellPadding = env.UDim2.fromOffset(8, 8), SortOrder = env.Enum.SortOrder.LayoutOrder}, frame)
	local swatches = {
		["Misty Morning"] = {{226, 232, 238}, {150, 164, 178}}, ["Snow Day"] = {{250, 252, 255}, {150, 180, 220}},
		Blizzard = {{240, 246, 255}, {150, 160, 178}}, ["Winter Night"] = {{80, 255, 170}, {30, 40, 90}},
		["Cherry Blossom"] = {{255, 196, 214}, {255, 140, 176}}, Autumn = {{255, 176, 60}, {176, 52, 24}},
		["Golden Pollen"] = {{255, 232, 150}, {255, 150, 60}}, ["Firefly Night"] = {{210, 255, 100}, {20, 30, 70}},
		["Bonfire Night"] = {{255, 220, 120}, {220, 60, 10}}, Volcano = {{120, 116, 118}, {255, 96, 30}},
		["Northern Lights"] = {{60, 255, 150}, {150, 90, 255}}, ["Clear Day"] = {{120, 190, 255}, {255, 255, 255}},
		["Deep Space"] = {{150, 70, 230}, {20, 12, 50}}, ["Starry Night"] = {{230, 236, 255}, {16, 22, 60}},
		["Meteor Shower"] = {{150, 210, 255}, {40, 20, 80}}, ["Magic Night"] = {{190, 120, 255}, {255, 200, 110}},
		["Constellation Night"] = {{150, 205, 255}, {12, 16, 40}},
	}
	local tiles = {}
	for index, scene in ipairs(WEATHER_SCENES) do
		local button = create("TextButton", {Text = "", AutoButtonColor = false, BorderSizePixel = 0, LayoutOrder = index}, frame)
		context.corner(button, 10)
		context.nova.Theme.bind(button, "BackgroundColor3", "Surface2")
		local stroke = create("UIStroke", {Thickness = 1, Transparency = 0.86, ApplyStrokeMode = env.Enum.ApplyStrokeMode.Border}, button)
		context.nova.Theme.bind(stroke, "Color", "Glass")
		local swatch = create("Frame", {AnchorPoint = env.Vector2.new(0, 0.5), Position = env.UDim2.new(0, 9, 0.5, 0),
			Size = env.UDim2.fromOffset(16, 16), BorderSizePixel = 0, BackgroundColor3 = env.Color3.new(1, 1, 1)}, button)
		context.corner(swatch, 8)
		local colors = swatches[scene.name]
		create("UIGradient", {Color = env.ColorSequence.new(env.Color3.fromRGB(table.unpack(colors[1])), env.Color3.fromRGB(table.unpack(colors[2]))), Rotation = 45}, swatch)
		local label = context.nova.label({Parent = button, Text = context.translation.tr(scene.name), Font = context.nova.Font.Semi(),
			Size = 12, Pos = env.UDim2.fromOffset(31, 0), Box = env.UDim2.new(1, -34, 1, 0), Truncate = true, Color = "Muted"})
		context.translation.bind(label, scene.name)
		local tile = {key = scene.name, button = button, stroke = stroke, label = label, hover = false}
		table.insert(tiles, tile)
		context.connect(button.MouseButton1Click, function()
			if state.values.scene == scene.name then Weather.clearScene(state) else Weather.scene(state, scene.name) end
		end)
		context.connect(button.MouseEnter, function() tile.hover = true; state.paintScenes() end)
		context.connect(button.MouseLeave, function() tile.hover = false; state.paintScenes() end)
	end
	state.paintScenes = function()
		for _, tile in ipairs(tiles) do
			local selected = state.values.scene == tile.key
			context.nova.paint(tile.button, "BackgroundColor3", selected and "Accent" or "Surface2", "Quick")
			tile.button.BackgroundTransparency = selected and 0.82 or 0
			context.nova.paint(tile.stroke, "Color", (selected or tile.hover) and "Accent" or "Glass", "Quick")
			tile.stroke.Transparency, tile.stroke.Thickness = selected and 0.1 or (tile.hover and 0.45 or 0.86), selected and 1.5 or 1
			context.nova.paint(tile.label, "TextColor3", (selected or tile.hover) and "Text" or "Muted", "Quick")
		end
	end
	state.paintScenes()
	return true
end

function Weather.skyGallery(state)
	local context, env = state.context, state.context.environment
	local container = context.section:Container()
	if not container then return false end
	local create = context.create
	local frame = create("Frame", {Size = env.UDim2.new(1, 0, 0, 0), AutomaticSize = env.Enum.AutomaticSize.Y, BackgroundTransparency = 1}, container)
	create("UIGridLayout", {CellSize = env.UDim2.new(0.5, -4, 0, 66), CellPadding = env.UDim2.fromOffset(8, 8), SortOrder = env.Enum.SortOrder.LayoutOrder}, frame)
	local tiles, entries = {}, {{key = "", name = "Default sky"}}
	for _, sky in ipairs(state.skies) do table.insert(entries, sky) end
	for index, sky in ipairs(entries) do
		local button = create("TextButton", {Text = "", AutoButtonColor = false, BorderSizePixel = 0, LayoutOrder = index}, frame)
		context.corner(button, 10)
		context.nova.Theme.bind(button, "BackgroundColor3", "Surface2")
		local picture = create("ImageLabel", {BackgroundTransparency = 1, Size = env.UDim2.fromScale(1, 1), ScaleType = env.Enum.ScaleType.Crop}, button)
		context.corner(picture, 10)
		if sky.key ~= "" then
			env.task.defer(function()
				local path = "PulseHub/textures/weather/sky_" .. sky.key .. "-" .. tostring(sky.tlen) .. ".jpg"
				local ok, image = pcall(env.getcustomasset, path)
				if ok and picture.Parent then picture.Image = image end
			end)
		end
		local shade = create("Frame", {AnchorPoint = env.Vector2.new(0, 1), Position = env.UDim2.new(0, 5, 1, -5),
			Size = env.UDim2.new(1, -10, 0, 18), BorderSizePixel = 0, BackgroundColor3 = env.Color3.new(0, 0, 0),
			BackgroundTransparency = 0.4}, button)
		context.corner(shade, 6)
		local label = context.nova.label({Parent = shade, Text = context.translation.tr(sky.name), Font = context.nova.Font.Semi(),
			Size = 11, Pos = env.UDim2.fromOffset(7, 0), Box = env.UDim2.new(1, -12, 1, 0), Truncate = true, Color = "Text"})
		context.translation.bind(label, sky.name)
		local stroke = create("UIStroke", {Thickness = 1, Transparency = 0.8, ApplyStrokeMode = env.Enum.ApplyStrokeMode.Border}, button)
		context.nova.Theme.bind(stroke, "Color", "Glass")
		local tile = {key = sky.key, stroke = stroke, shade = shade, hover = false}
		table.insert(tiles, tile)
		context.connect(button.MouseButton1Click, function()
			if sky.key == "" then
				Weather.setSky(state, nil)
				if state.values.matchLight then Weather.restoreLook(state) end
			else Weather.pickSky(state, sky.key) end
			state.values.scene = ""
			if state.paintScenes then state.paintScenes() end
		end)
		context.connect(button.MouseEnter, function() tile.hover = true; state.paintSkies() end)
		context.connect(button.MouseLeave, function() tile.hover = false; state.paintSkies() end)
	end
	state.paintSkies = function()
		local api = env.getgenv().__pulseSkyAPI
		local active = api and api.active() or ""
		for _, tile in ipairs(tiles) do
			local selected = tile.key == active
			context.nova.paint(tile.stroke, "Color", (selected or tile.hover) and "Accent" or "Glass", "Quick")
			tile.stroke.Transparency, tile.stroke.Thickness = selected and 0 or (tile.hover and 0.4 or 0.8), selected and 2 or 1
			tile.shade.BackgroundTransparency = selected and 0.62 or 0.4
		end
	end
	state.paintSkies()
	return true
end

function Weather.install(context)
	local env, section = context.environment, context.section
	local defaults = Weather.defaults(env)
	local textures, sounds, recipes, grades = weatherData(env)
	local state = {context = context, defaults = defaults, values = table.clone(defaults), textures = textures, sounds = sounds,
		recipes = recipes, grades = grades, skies = weatherSkies(env), controls = {}, nodes = {}, voices = {},
		invisible = setmetatable({}, {__mode = "k"}), phase = 0, envClock = 0, envDark = 0, visibility = 0,
		frameElapsed = 0, probeElapsed = 1, audioLevel = 0, coverBlend = 0, gradeLevel = 0, dirty = true, batch = true}
	local v = state.values
	local function changed(key, value)
		v[key] = value
		if not state.batch then Weather.changed(state) end
	end
	local function toggle(text, key, settings)
		state.controls[key] = section:Toggle({Text = text, Default = v[key], Settings = settings, Callback = function(value) changed(key, value) end})
	end
	local function slider(text, key, min, max, decimals, suffix)
		state.controls[key] = section:Slider({Text = text, Min = min, Max = max, Decimals = decimals or 0, Suffix = suffix,
			Default = v[key], Callback = function(value) changed(key, value) end})
	end
	local function dropdown(text, key, values)
		local options = {}
		for _, value in ipairs(values) do table.insert(options, {code = value, label = value}) end
		state.controls[key] = section:Dropdown({Text = text, Default = v[key], Options = options, Callback = function(value)
			if value ~= nil then changed(key, value) end
		end})
	end
	local function color(text, key)
		state.controls[key] = section:Colorpicker({Text = text, Default = v[key], Callback = function(value)
			if env.typeof(value) == "Color3" then changed(key, value) end
		end})
	end
	section:Sub("Weather")
	section:Columns()
	section:Group({Title = "Weather", Side = "Left"})
	toggle("Enabled", "on")
	dropdown("Weather type", "kind", WEATHER_ORDER)
	slider("Amount", "amount", 0, 100, 0, "%")
	slider("Visibility", "opacity", 20, 100, 0, "%")
	slider("Particle size", "scale", 0.5, 1.8, 2, "x")
	section:Group({Title = "Scenes", Side = "Right"})
	local scenesReady, scenesShown = pcall(Weather.sceneGallery, state)
	if not scenesReady or not scenesShown then
		local scenes = {{code = "", label = "Clear scene"}}
		for _, scene in ipairs(WEATHER_SCENES) do table.insert(scenes, {code = scene.name, label = scene.name}) end
		local sceneControl = section:Dropdown({Text = "Scene", Options = scenes, Default = "", NoSave = true, Callback = function(name)
			if state.batch then return end
			if name == "" then Weather.clearScene(state) else Weather.scene(state, name) end
		end})
		state.paintScenes = function() if sceneControl.SetSilent then sceneControl.SetSilent(v.scene) end end
	end
	section:Button({Text = "Reset all", Callback = function()
		Weather.clearScene(state)
		for key, value in pairs(state.defaults) do v[key] = value end
		Weather.changed(state)
		Weather.syncUI(state)
	end})
	section:Group({Title = "Wind", Side = "Left"})
	slider("Wind strength", "wind", 0, 18, 1)
	slider("Wind direction", "windAngle", 0, 360, 0, "Â°")
	slider("Falling speed", "speed", 60, 150, 0, "%")
	toggle("Gentle gusts", "gusts")
	section:Group({Title = "Sky", Side = "Right"})
	toggle("Match lighting", "matchLight")
	local skiesReady, skiesShown = pcall(Weather.skyGallery, state)
	if not skiesReady or not skiesShown then
		local skies = {{code = "", label = "Default sky"}}
		for _, sky in ipairs(state.skies) do table.insert(skies, {code = sky.key, label = sky.name}) end
		local skyControl = section:Dropdown({Text = "Sky", Options = skies, Default = "", NoSave = true, Callback = function(key)
			if state.batch then return end
			if key == "" then Weather.setSky(state, nil); if v.matchLight then Weather.restoreLook(state) end
			else Weather.pickSky(state, key) end
			v.scene = ""
			if state.paintScenes then state.paintScenes() end
		end})
		state.paintSkies = function()
			local api = env.getgenv().__pulseSkyAPI
			if skyControl.SetSilent then skyControl.SetSilent(api and api.active() or "") end
		end
	end
	section:Group({Title = "Sound", Side = "Left"})
	toggle("Weather sound", "sound", function() slider("Weather volume", "soundVolume", 0, 100, 0, "%") end)
	toggle("Weather tint", "grade")
	section:Group({Title = "Detail", Side = "Right"})
	dropdown("Particle budget", "quality", {"Light", "Balanced", "High", "Ultra"})
	slider("Coverage", "radius", 12, 50, 0, " st")
	toggle("Pause indoors", "shelter")
	section:Group({Title = "Particle colors", Side = "Right"})
	for _, entry in ipairs({{"Snow color", "snowColour"}, {"Petal tint", "petalColour"}, {"Leaf tint", "leafColour"},
		{"Mist color", "mistColour"}, {"Ember color", "emberColour"}, {"Ash color", "ashColour"},
		{"Firefly color", "fireflyColour"}, {"Pollen color", "pollenColour"}}) do color(entry[1], entry[2]) end
	state.batch = false
	local api = env.getgenv().__pulseSkyAPI
	if api then for _, sky in ipairs(state.skies) do api.register(sky.key, sky.spec) end end
	local savedSky = context.configuration.visuals and context.configuration.visuals.sky
	if api and savedSky and savedSky ~= "" then env.task.defer(function()
		if context.isAlive() then api.activate(savedSky, true); state.paintSkies() end
	end) end
	context.visualWorld.context.applyWeatherExtra = function(name) Weather.applyExtra(state, name) end
	env.getgenv().__pulseWeather = state
	if context.runService.RenderStepped then context.connect(context.runService.RenderStepped, function(delta)
		if state.failureAt and os.clock() < state.failureAt then return end
		local ok, message = pcall(Weather.step, state, delta)
		if not ok then
			state.failureAt = os.clock() + 3
			Weather.stop(state)
			env.warn("[PulseHub] weather step failed: " .. tostring(message))
		end
	end) end
	return state, function()
		Weather.stop(state)
		if env.getgenv().__pulseWeather == state then env.getgenv().__pulseWeather = nil end
	end
end

local SkyFx = {}
local SKY_FX_ORDER = {"stars", "meteors", "comets", "net", "runes", "dust"}
local SKY_FX_TEXTURES = {dot = "rbxassetid://16512006463", soft = "rbxassetid://1075864321", spark = "rbxassetid://14590086212",
	sharp = "rbxassetid://17391818367", runes = "rbxassetid://11910560348", glyphs = "rbxassetid://10713705343",
	const1 = "rbxassetid://14101033134", const2 = "rbxassetid://14101036795", beam = "rbxassetid://12781750620", rays = "rbxassetid://4553095322"}

function SkyFx.defaults(env)
	local rgb = env.Color3.fromRGB
	return {general = {bright = 100}, stars = {on = false, density = 60, size = 100, twinkle = 60, tint = "Natural"},
		meteors = {on = false, rate = 45, length = 100, color = rgb(190, 225, 255)},
		comets = {on = false, rate = 40, size = 100, color = rgb(120, 210, 255)},
		net = {on = false, nodes = 80, reach = 50, speed = 40, place = "Sky", color = rgb(150, 205, 255), figures = true, pulses = true, rainbow = false, cursor = true},
		runes = {on = false, amount = 50, size = 100, set = "Runes", color = rgb(130, 220, 255)},
		dust = {on = false, amount = 50, palette = "Gold"}}
end

function SkyFx.palettes(env)
	local rgb = env.Color3.fromRGB
	return {stars = {Natural = {rgb(232, 240, 255), rgb(170, 200, 255), rgb(255, 226, 190)},
		Cold = {rgb(205, 225, 255), rgb(140, 185, 255), rgb(190, 240, 255)},
		Warm = {rgb(255, 238, 214), rgb(255, 205, 150), rgb(255, 180, 140)},
		Pastel = {rgb(255, 205, 236), rgb(195, 255, 232), rgb(214, 196, 255)}},
		dust = {Gold = {rgb(255, 220, 130), rgb(255, 190, 90)}, Silver = {rgb(235, 242, 255), rgb(190, 210, 255)},
		Pink = {rgb(255, 170, 220), rgb(255, 120, 190)}, Aqua = {rgb(140, 255, 235), rgb(110, 200, 255)}}}
end

function SkyFx.create(state, class, parent, properties)
	local object = state.context.environment.Instance.new(class)
	for key, value in pairs(properties or {}) do object[key] = value end
	object.Parent = parent
	return object
end

function SkyFx.part(state, parent, name)
	local env = state.context.environment
	return SkyFx.create(state, "Part", parent, {Name = name, Anchored = true, CanCollide = false, CanTouch = false,
		CanQuery = false, CastShadow = false, Transparency = 1, Locked = true, Size = env.Vector3.new(1, 1, 1)})
end

function SkyFx.emitter(state, parent, texture, life, speed, brightness, locked)
	local env = state.context.environment
	return SkyFx.create(state, "ParticleEmitter", parent, {Enabled = false, Rate = 0, Texture = texture,
		LightEmission = 1, LightInfluence = 0, Brightness = brightness, Lifetime = env.NumberRange.new(life[1], life[2] or life[1]),
		Speed = env.NumberRange.new(speed and speed[1] or 0, speed and (speed[2] or speed[1]) or 0),
		LockedToPart = locked == true, Orientation = env.Enum.ParticleOrientation.FacingCamera})
end

function SkyFx.sequence(state, points)
	local env, result = state.context.environment, {}
	for _, point in ipairs(points) do table.insert(result, env.NumberSequenceKeypoint.new(point[1], point[2], point[3] or 0)) end
	return env.NumberSequence.new(result)
end

function SkyFx.rainbow(state, offset)
	local env, result = state.context.environment, {}
	for index = 0, 6 do table.insert(result, env.ColorSequenceKeypoint.new(index / 6, env.Color3.fromHSV((offset + index / 6) % 1, 0.55, 1))) end
	return env.ColorSequence.new(result)
end

function SkyFx.particle(state, parent, texture, life, speed, brightness, locked, sphere)
	local emitter = SkyFx.emitter(state, parent, texture, life, speed, brightness, locked)
	local env = state.context.environment
	emitter.Shape = sphere and env.Enum.ParticleEmitterShape.Sphere or env.Enum.ParticleEmitterShape.Box
	emitter.ShapeStyle = sphere and env.Enum.ParticleEmitterShapeStyle.Surface or env.Enum.ParticleEmitterShapeStyle.Volume
	if sphere then
		emitter.ShapeInOut, emitter.EmissionDirection = env.Enum.ParticleEmitterShapeInOut.Outward, env.Enum.NormalId.Top
		pcall(function() emitter.ShapePartial = 0.5 end)
	end
	return emitter
end

function SkyFx.buildParticles(state, name, folder)
	local env, texture = state.context.environment, SKY_FX_TEXTURES
	local part = SkyFx.part(state, folder, name)
	local fx = {folder = folder, part = part, dirty = true, filled = false}
	if name == "stars" then
		fx.small = SkyFx.particle(state, part, texture.dot, {4, 9}, nil, 2.6, true, true)
		fx.tint = SkyFx.particle(state, part, texture.dot, {4, 8}, nil, 2.8, true, true)
		fx.big = SkyFx.particle(state, part, texture.spark, {5, 10}, nil, 3, true, true)
		return fx
	end
	if name == "runes" then
		part.Size = env.Vector3.new(80, 22, 80)
		fx.main = SkyFx.particle(state, part, texture.runes, {6, 10}, {0.5, 1.5}, 2.6)
		fx.main.Drag, fx.main.EmissionDirection, fx.main.SpreadAngle = 0.3, env.Enum.NormalId.Top, env.Vector2.new(25, 25)
		fx.main.FlipbookLayout, fx.main.FlipbookMode = env.Enum.ParticleFlipbookLayout.Grid4x4, env.Enum.ParticleFlipbookMode.OneShot
		fx.main.FlipbookFramerate, fx.main.FlipbookStartRandom = env.NumberRange.new(0, 0), true
		fx.glow = SkyFx.particle(state, part, texture.dot, {3, 6}, {0.3, 1}, 2)
		fx.glow.EmissionDirection = env.Enum.NormalId.Top
		return fx
	end
	part.Size = env.Vector3.new(90, 30, 90)
	fx.main = SkyFx.particle(state, part, texture.spark, {4, 8}, {0.1, 0.5}, 2.6)
	fx.glow = SkyFx.particle(state, part, texture.dot, {3, 7}, {0.1, 0.4}, 2.2)
	fx.main.SpreadAngle, fx.glow.SpreadAngle = env.Vector2.new(180, 180), env.Vector2.new(180, 180)
	fx.main.Acceleration, fx.glow.Acceleration = env.Vector3.new(0, -0.15, 0), env.Vector3.new(0, -0.1, 0)
	return fx
end

function SkyFx.applyStars(state, fx)
	local env, cfg, radius = state.context.environment, state.cfg.stars, state.radius
	local brightness, size = state.cfg.general.bright / 100, cfg.size / 100
	fx.part.Size = env.Vector3.new(1, 1, 1) * math.min(radius * 2, 2040)
	local twinkle = 0.08 + 0.62 * cfg.twinkle / 100
	local transparency = SkyFx.sequence(state, {{0, 1}, {0.1, 0.04}, {0.22, twinkle}, {0.34, 0.04}, {0.46, twinkle * 0.8},
		{0.58, 0.04}, {0.7, twinkle}, {0.82, 0.08}, {1, 1}})
	fx.small.Transparency, fx.tint.Transparency = transparency, transparency
	fx.small.Size = SkyFx.sequence(state, {{0, radius * 0.03 * size, radius * 0.012 * size}, {1, radius * 0.03 * size, radius * 0.012 * size}})
	fx.tint.Size = SkyFx.sequence(state, {{0, radius * 0.036 * size, radius * 0.012 * size}, {1, radius * 0.036 * size, radius * 0.012 * size}})
	local large = radius * 0.055 * size
	fx.big.Size = SkyFx.sequence(state, {{0, 0}, {0.14, large}, {0.3, large * 0.55}, {0.46, large}, {0.62, large * 0.6}, {0.8, large}, {1, 0}})
	fx.big.Transparency = SkyFx.sequence(state, {{0, 1}, {0.12, 0.05}, {0.88, 0.1}, {1, 1}})
	fx.small.Brightness, fx.tint.Brightness, fx.big.Brightness = 2.6 * brightness, 2.8 * brightness, 3 * brightness
	fx.small.Rate, fx.tint.Rate, fx.big.Rate = cfg.density * 1.25, cfg.density * 0.36, cfg.density * 0.07
	fx.small.Enabled, fx.tint.Enabled, fx.big.Enabled = cfg.density > 0, cfg.density > 0, cfg.density > 0
	if cfg.tint == "Rainbow" then
		fx.small.Color, fx.tint.Color, fx.big.Color = SkyFx.rainbow(state, 0), SkyFx.rainbow(state, 0.5), SkyFx.rainbow(state, 0.25)
	else
		local colors = state.palettes.stars[cfg.tint] or state.palettes.stars.Natural
		fx.small.Color, fx.tint.Color, fx.big.Color = env.ColorSequence.new(colors[1]), env.ColorSequence.new(colors[2], colors[3]), env.ColorSequence.new(colors[1])
	end
	if not fx.filled and cfg.density > 0 then
		fx.filled = true
		fx.small:Emit(math.floor(cfg.density * 3.6))
		fx.tint:Emit(math.floor(cfg.density))
		fx.big:Emit(math.floor(cfg.density * 0.2))
	end
end

function SkyFx.applyRunes(state, fx)
	local env, cfg = state.context.environment, state.cfg.runes
	local size, brightness = cfg.size / 100, state.cfg.general.bright / 100
	fx.main.Texture = cfg.set == "Glyphs" and SKY_FX_TEXTURES.glyphs or SKY_FX_TEXTURES.runes
	fx.main.Size = SkyFx.sequence(state, {{0, 1.02 * size}, {0.15, 1.7 * size}, {0.85, 1.7 * size}, {1, 1.36 * size}})
	fx.main.Transparency = SkyFx.sequence(state, {{0, 1}, {0.15, 0.05}, {0.75, 0.15}, {1, 1}})
	fx.glow.Size = SkyFx.sequence(state, {{0, 0.5 * size}, {1, 0}})
	fx.glow.Transparency = SkyFx.sequence(state, {{0, 0.3}, {1, 1}})
	fx.main.Color, fx.glow.Color = env.ColorSequence.new(cfg.color), env.ColorSequence.new(cfg.color)
	fx.main.Brightness, fx.glow.Brightness = 2.6 * brightness, 2 * brightness
	fx.main.Rate, fx.glow.Rate = cfg.amount * 0.32, cfg.amount * 0.3
	fx.main.Enabled, fx.glow.Enabled = cfg.amount > 0, cfg.amount > 0
	if not fx.filled and cfg.amount > 0 then fx.filled = true; fx.main:Emit(math.floor(cfg.amount * 1.6)) end
end

function SkyFx.applyDust(state, fx)
	local env, cfg = state.context.environment, state.cfg.dust
	fx.main.Size = SkyFx.sequence(state, {{0, 0}, {0.15, 0.75}, {0.3, 0.2625}, {0.45, 0.75}, {0.6, 0.3}, {0.78, 0.75}, {1, 0}})
	fx.main.Transparency = SkyFx.sequence(state, {{0, 1}, {0.12, 0}, {0.85, 0.1}, {1, 1}})
	fx.glow.Size = SkyFx.sequence(state, {{0, 0.38}, {1, 0.14}})
	fx.glow.Transparency = SkyFx.sequence(state, {{0, 1}, {0.15, 0.1}, {0.5, 0.5}, {0.75, 0.1}, {1, 1}})
	if cfg.palette == "Rainbow" then fx.main.Color, fx.glow.Color = SkyFx.rainbow(state, 0), SkyFx.rainbow(state, 0.4)
	else
		local colors = state.palettes.dust[cfg.palette] or state.palettes.dust.Gold
		fx.main.Color, fx.glow.Color = env.ColorSequence.new(colors[1]), env.ColorSequence.new(colors[2])
	end
	local brightness = state.cfg.general.bright / 100
	fx.main.Brightness, fx.glow.Brightness = 3.2 * brightness, 2.6 * brightness
	fx.main.Rate, fx.glow.Rate = cfg.amount * 0.9, cfg.amount * 1.1
	fx.main.Enabled, fx.glow.Enabled = cfg.amount > 0, cfg.amount > 0
	if not fx.filled and cfg.amount > 0 then
		fx.filled = true
		fx.main:Emit(math.floor(cfg.amount * 3))
		fx.glow:Emit(math.floor(cfg.amount * 3))
	end
end

function SkyFx.beam(state, parent, first, second, brightness)
	local env = state.context.environment
	return SkyFx.create(state, "Beam", parent, {Attachment0 = first, Attachment1 = second, FaceCamera = true, LightEmission = 1,
		LightInfluence = 0, Brightness = brightness, Segments = 1, Width0 = 0, Width1 = 1,
		Texture = SKY_FX_TEXTURES.beam, TextureMode = env.Enum.TextureMode.Stretch, Enabled = false})
end

function SkyFx.buildTrails(state, name, folder)
	local env = state.context.environment
	local anchor = SkyFx.part(state, folder, name .. "Anchor")
	anchor.CFrame = env.CFrame.new()
	local fx = {folder = folder, anchor = anchor, pool = {}, dirty = true, nextSpawn = state.time + (name == "meteors" and 0.5 or 1.2)}
	local count = name == "meteors" and 7 or 2
	for _ = 1, count do
		local first, second = SkyFx.create(state, "Attachment", anchor), SkyFx.create(state, "Attachment", anchor)
		local trail = {first = first, second = second, beams = {}, active = false}
		if name == "comets" then trail.ion = SkyFx.create(state, "Attachment", anchor) end
		local beamCount = name == "meteors" and 2 or 5
		for index = 1, beamCount do
			local beam = SkyFx.beam(state, anchor, first, index > 3 and trail.ion or second, index == 1 and 3.2 or 1.4)
			if name == "comets" then beam.Segments = index <= 3 and 24 or 12 end
			table.insert(trail.beams, beam)
		end
		trail.head = SkyFx.part(state, folder, name .. "Head")
		trail.head.CFrame = env.CFrame.new(0, -10000, 0)
		trail.glow = SkyFx.emitter(state, trail.head, SKY_FX_TEXTURES.soft, {name == "meteors" and 30 or 60}, nil, 1.4, true)
		trail.star = SkyFx.emitter(state, trail.head, name == "meteors" and SKY_FX_TEXTURES.spark or SKY_FX_TEXTURES.dot,
			{name == "meteors" and 30 or 60}, nil, 3, true)
		trail.dust = SkyFx.emitter(state, trail.head, SKY_FX_TEXTURES.dot, {0.3, 0.8}, {0.2, 1}, 2.2)
		trail.dust.SpreadAngle = env.Vector2.new(180, 180)
		if name == "comets" then
			trail.flare = SkyFx.emitter(state, trail.head, SKY_FX_TEXTURES.spark, {1.6, 2.4}, nil, 2.4, true)
			trail.dust2 = SkyFx.emitter(state, trail.head, SKY_FX_TEXTURES.dot, {2, 4}, {0.2, 1.5}, 2)
			trail.dust2.SpreadAngle = env.Vector2.new(180, 180)
		end
		table.insert(fx.pool, trail)
	end
	return fx
end

function SkyFx.applyTrails(state, name, fx)
	local env, cfg = state.context.environment, state.cfg[name]
	local scale = name == "comets" and cfg.size / 100 or 1
	for _, trail in ipairs(fx.pool) do
		for _, beam in ipairs(trail.beams) do beam.Color = env.ColorSequence.new(cfg.color) end
		local white = env.Color3.new(1, 1, 1)
		if name == "meteors" then
			trail.beams[1].Color = env.ColorSequence.new({env.ColorSequenceKeypoint.new(0, cfg.color),
				env.ColorSequenceKeypoint.new(0.7, cfg.color:Lerp(white, 0.5)), env.ColorSequenceKeypoint.new(1, white)})
		else
			trail.beams[1].Color = env.ColorSequence.new({env.ColorSequenceKeypoint.new(0, white),
				env.ColorSequenceKeypoint.new(0.12, cfg.color:Lerp(white, 0.35)), env.ColorSequenceKeypoint.new(1, cfg.color)})
			trail.beams[2].Color = env.ColorSequence.new(cfg.color:Lerp(white, 0.3), cfg.color)
			trail.beams[4].Color = env.ColorSequence.new(white, env.Color3.fromRGB(120, 175, 255))
			trail.beams[5].Color = env.ColorSequence.new(env.Color3.fromRGB(120, 175, 255))
		end
		trail.glow.Color, trail.dust.Color = env.ColorSequence.new(cfg.color), env.ColorSequence.new(cfg.color)
		trail.glow.Size, trail.star.Size = env.NumberSequence.new(state.radius * 0.032 * scale), env.NumberSequence.new(state.radius * 0.03 * scale)
		trail.dust.Size = SkyFx.sequence(state, {{0, state.radius * 0.007 * scale}, {1, 0}})
		trail.dust.Transparency = SkyFx.sequence(state, {{0, 0.1}, {1, 1}})
		if name == "comets" then
			trail.flare.Size = SkyFx.sequence(state, {{0, state.radius * 0.042 * scale}, {0.5, state.radius * 0.07 * scale}, {1, state.radius * 0.042 * scale}})
			trail.flare.Transparency = SkyFx.sequence(state, {{0, 1}, {0.3, 0.2}, {0.7, 0.2}, {1, 1}})
			trail.dust2.Size = SkyFx.sequence(state, {{0, state.radius * 0.006 * scale}, {1, 0}})
			trail.dust2.Transparency = SkyFx.sequence(state, {{0, 0.2}, {1, 1}})
			trail.dust2.Color = env.ColorSequence.new(cfg.color)
		end
	end
end

function SkyFx.direction(state, azimuth, elevation)
	local cos = math.cos(elevation)
	return state.context.environment.Vector3.new(cos * math.cos(azimuth), math.sin(elevation), cos * math.sin(azimuth))
end

function SkyFx.arc(first, second, t)
	local angle = math.acos(math.clamp(first:Dot(second), -1, 1))
	if angle < 0.0001 then return first end
	local sine = math.sin(angle)
	return first * (math.sin((1 - t) * angle) / sine) + second * (math.sin(t * angle) / sine)
end

function SkyFx.spawnTrail(state, name, fx, look)
	local trail
	for _, candidate in ipairs(fx.pool) do if not candidate.active then trail = candidate; break end end
	if not trail then return end
	local comet = name == "comets"
	local azimuth = math.atan2(look.Z, look.X) + (math.random() * 2 - 1) * (comet and 0.96 or 1.05)
	if not comet and math.random() >= 0.8 then azimuth = math.random() * math.pi * 2 end
	local elevation = math.rad(comet and 26 + math.random() * 26 or 30 + math.random() * 42)
	local direction = math.random() < 0.5 and -1 or 1
	trail.start = SkyFx.direction(state, azimuth, elevation)
	trail.finish = SkyFx.direction(state, azimuth + direction * math.rad(comet and 26 + math.random() * 18 or 16 + math.random() * 24),
		elevation + math.rad(comet and -12 + math.random() * 20 or -14 - math.random() * 14))
	trail.started, trail.duration, trail.active = state.time, comet and 18 + math.random() * 10 or 0.6 + math.random() * 0.7, true
	trail.tail = comet and 0.3 or 0.3 * state.cfg.meteors.length / 100 * (0.8 + math.random() * 0.45)
	for _, beam in ipairs(trail.beams) do beam.Enabled = true end
	trail.glow:Emit(1)
	trail.star:Emit(1)
	trail.dust.Rate, trail.dust.Enabled = comet and 26 or 80, true
	if comet then
		trail.flare.Rate, trail.flare.Enabled = 1.4, true
		trail.dust2.Rate, trail.dust2.Enabled = 34, true
	end
end

function SkyFx.stepTrails(state, name, fx, position, look)
	local cfg = state.cfg[name]
	local comet = name == "comets"
	if state.time >= fx.nextSpawn then
		SkyFx.spawnTrail(state, name, fx, look)
		local delay = comet and 6 + 70 * (1 - cfg.rate / 100) ^ 2 or 0.3 + 9 * (1 - cfg.rate / 100) ^ 2
		fx.nextSpawn = state.time + delay * (comet and 0.5 + math.random() or 0.35 + 1.3 * math.random())
	end
	local brightness = state.cfg.general.bright / 100
	for _, trail in ipairs(fx.pool) do
		if not trail.active then continue end
		local progress = (state.time - trail.started) / trail.duration
		if progress >= 1 + (comet and 0 or trail.tail) then
			trail.active, trail.dust.Enabled = false, false
			if comet then trail.flare.Enabled, trail.dust2.Enabled = false, false end
			for _, beam in ipairs(trail.beams) do beam.Enabled = false end
			trail.glow:Clear()
			trail.star:Clear()
			trail.head.CFrame = state.context.environment.CFrame.new(0, -10000, 0)
			continue
		end
		local direction = SkyFx.arc(trail.start, trail.finish, math.min(progress, 1))
		local head = position + direction * state.radius
		local fade
		if comet then
			local ahead = SkyFx.arc(trail.start, trail.finish, math.min(progress + 0.01, 1)) - direction
			local tangent = ahead.Magnitude > 1e-6 and ahead.Unit or state.context.environment.Vector3.new(1, 0, 0)
			local side = tangent:Cross(direction).Unit
			local size = cfg.size / 100
			local dust = (direction - tangent * 0.3 * size + side * 0.04 * size).Unit
			local ion = (direction - tangent * 0.42 * size - side * 0.02 * size).Unit
			trail.first.CFrame = state.context.environment.CFrame.fromMatrix(head, side, direction)
			trail.second.CFrame = state.context.environment.CFrame.fromMatrix(position + dust * state.radius, side, dust)
			trail.ion.Position = position + ion * state.radius
			fade = math.clamp(math.min(progress * trail.duration / 2.5, (1 - progress) * trail.duration / 3), 0, 1)
			local widths = {{0.022, 0.08}, {0.04, 0.15}, {0.065, 0.24}, {0.012, 0.03}, {0.026, 0.07}}
			local alphas = {0.75, 0.45, 0.25, 0.7, 0.3}
			local levels = {1.4, 0.9, 0.6, 1.8, 0.8}
			for index, beam in ipairs(trail.beams) do
				beam.Width0, beam.Width1 = state.radius * size * widths[index][1], state.radius * size * widths[index][2]
				beam.CurveSize0, beam.CurveSize1 = index <= 3 and state.radius * 0.05 * size or 0, 0
				beam.Brightness = levels[index] * brightness
				beam.Transparency = SkyFx.sequence(state, {{0, 1 - alphas[index] * fade}, {1, 1}})
			end
			trail.flare.Brightness, trail.dust2.Brightness = 2.4 * brightness * fade, 2 * brightness * fade
		else
			local tail = position + SkyFx.arc(trail.start, trail.finish, math.clamp(progress - trail.tail, 0, 1)) * state.radius
			trail.first.Position, trail.second.Position = tail, head
			fade = math.clamp(math.min(progress / 0.12, (1 + trail.tail - progress) / (trail.tail + 0.2)), 0, 1)
			for index, beam in ipairs(trail.beams) do
				beam.Width0, beam.Width1 = 0, state.radius * (index == 1 and 0.016 or 0.055)
				beam.Brightness = (index == 1 and 3.2 or 1.4) * brightness
				beam.Transparency = SkyFx.sequence(state, {{0, 1}, {1, 1 - fade * (index == 1 and 1 or 0.4)}})
			end
		end
		trail.head.CFrame = state.context.environment.CFrame.new(head)
		trail.glow.Brightness, trail.star.Brightness = 1.4 * brightness * fade, 3 * brightness * fade
		if progress > 0.95 and not comet then trail.dust.Enabled = false end
	end
end

function SkyFx.buildNet(state, folder)
	local env, cfg = state.context.environment, state.cfg.net
	local fx = {folder = folder, nodes = {}, links = {}, dirty = true, count = math.clamp(math.floor(cfg.nodes), 8, 140), place = cfg.place, linkClock = 1}
	local look = state.camera.CFrame.LookVector
	local forward = math.atan2(look.Z, look.X)
	for index = 1, fx.count do
		local part = SkyFx.part(state, folder, "Node")
		local attachment = SkyFx.create(state, "Attachment", part)
		local emitter = SkyFx.emitter(state, part, index % 6 == 0 and SKY_FX_TEXTURES.spark or SKY_FX_TEXTURES.dot, {12}, nil, 2.8, true)
		local node = {part = part, attachment = attachment, emitter = emitter, big = index % 6 == 0,
			azimuth = math.random() < 0.75 and forward + (math.random() * 2 - 1) * 1.25 or math.random() * math.pi * 2,
			elevation = math.rad(14 + math.random() * 58),
			drift = (math.random() * 2 - 1) * 0.022, vertical = (math.random() * 2 - 1) * 0.014,
			relative = env.Vector3.new((math.random() * 2 - 1) * 44, -10 + math.random() * 24, (math.random() * 2 - 1) * 44),
			velocity = env.Vector3.new(math.random() * 2 - 1, (math.random() * 2 - 1) * 0.4, math.random() * 2 - 1),
			nextEmit = state.time + math.random() * 6, hue = math.random()}
		table.insert(fx.nodes, node)
	end
	fx.cursorAnchor = SkyFx.part(state, folder, "CursorAnchor")
	fx.cursorAnchor.CFrame = env.CFrame.new()
	fx.cursor = SkyFx.create(state, "Attachment", fx.cursorAnchor)
	for _ = 1, fx.count * 2 + 6 do
		local beam = SkyFx.beam(state, folder, nil, nil, 1.8)
		local pulse = SkyFx.beam(state, folder, nil, nil, 3)
		pulse.Texture, pulse.TextureMode = SKY_FX_TEXTURES.rays, env.Enum.TextureMode.Wrap
		table.insert(fx.links, {beam = beam, pulse = pulse})
	end
	fx.shell = SkyFx.part(state, folder, "Constellations")
	fx.figures = {SkyFx.particle(state, fx.shell, SKY_FX_TEXTURES.const1, {9, 13}, nil, 1.8, true, true),
		SkyFx.particle(state, fx.shell, SKY_FX_TEXTURES.const2, {9, 13}, nil, 1.8, true, true)}
	return fx
end

function SkyFx.applyNet(state, fx)
	local env, cfg = state.context.environment, state.cfg.net
	local sky, brightness = cfg.place ~= "Around me", state.cfg.general.bright / 100
	for _, node in ipairs(fx.nodes) do
		local size = sky and state.radius * (node.big and 0.06 or 0.036) or (node.big and 1.7 or 1)
		node.emitter.Size = env.NumberSequence.new(size)
		node.emitter.Color = env.ColorSequence.new(cfg.color:Lerp(env.Color3.new(1, 1, 1), 0.45))
		node.emitter.Transparency = SkyFx.sequence(state, {{0, 1}, {0.15, 0}, {0.85, 0}, {1, 1}})
		node.emitter.Brightness = 2.8 * brightness
		if not node.seeded then node.seeded = true; node.emitter:Emit(1) end
	end
	for _, link in ipairs(fx.links) do
		local width = sky and state.radius * 0.0075 or 0.16
		link.beam.Width0, link.beam.Width1 = width, width
		link.pulse.Width0, link.pulse.Width1 = width * 1.9, width * 1.9
		link.pulse.TextureLength, link.pulse.TextureSpeed = sky and state.radius * 0.2 or 7, 0.35 + 0.6 * cfg.speed / 100
		link.beam.Color, link.pulse.Color = env.ColorSequence.new(cfg.color), env.ColorSequence.new(cfg.color)
		link.beam.Brightness, link.pulse.Brightness = 1.8 * brightness, 5 * brightness
	end
	fx.shell.Size = env.Vector3.new(1, 1, 1) * math.min(state.radius * 1.9, 2040)
	for _, emitter in ipairs(fx.figures) do
		emitter.Size, emitter.Color = env.NumberSequence.new(state.radius * 0.2), env.ColorSequence.new(cfg.color:Lerp(env.Color3.new(1, 1, 1), 0.4))
		emitter.Transparency = SkyFx.sequence(state, {{0, 1}, {0.25, 0.3}, {0.75, 0.3}, {1, 1}})
		emitter.Brightness, emitter.Rate, emitter.Enabled = 1.8 * brightness, 0.06, sky and cfg.figures
	end
	fx.linkClock = 1
end

function SkyFx.linkNet(state, fx)
	local env, cfg = state.context.environment, state.cfg.net
	local sky = cfg.place ~= "Around me"
	local maxDistance = sky and 2 * state.radius * 0.92 * math.sin(math.rad(5 + 20 * cfg.reach / 100) / 2) or 10 + 24 * cfg.reach / 100
	local used, degrees = 0, {}
	local function connect(firstNode, attachment)
		if used >= #fx.links then return end
		used += 1
		local link = fx.links[used]
		link.beam.Attachment0, link.beam.Attachment1 = firstNode.attachment, attachment
		link.pulse.Attachment0, link.pulse.Attachment1 = firstNode.attachment, attachment
		link.beam.Enabled, link.pulse.Enabled = true, cfg.pulses
		local color = cfg.rainbow and env.Color3.fromHSV((firstNode.hue + state.time * 0.05) % 1, 0.6, 1) or cfg.color
		link.beam.Color, link.pulse.Color = env.ColorSequence.new(color), env.ColorSequence.new(color)
	end
	for first = 1, #fx.nodes do
		for second = first + 1, #fx.nodes do
			if (degrees[first] or 0) >= 4 then break end
			if (degrees[second] or 0) >= 4 then continue end
			local firstNode, secondNode = fx.nodes[first], fx.nodes[second]
			if (firstNode.position - secondNode.position).Magnitude > maxDistance then continue end
			degrees[first], degrees[second] = (degrees[first] or 0) + 1, (degrees[second] or 0) + 1
			connect(firstNode, secondNode.attachment)
		end
	end
	if fx.cursorPosition then
		local nearest = {}
		for _, node in ipairs(fx.nodes) do
			local distance = (node.position - fx.cursorPosition).Magnitude
			if distance <= maxDistance * 1.3 then table.insert(nearest, {node = node, distance = distance}) end
		end
		table.sort(nearest, function(a, b) return a.distance < b.distance end)
		for index = 1, math.min(6, #nearest) do connect(nearest[index].node, fx.cursor) end
	end
	for index = used + 1, #fx.links do fx.links[index].beam.Enabled, fx.links[index].pulse.Enabled = false, false end
end

function SkyFx.cursor(state, fx, position)
	if not state.cfg.net.cursor then return nil end
	local camera, input = state.camera, state.context.inputService
	local viewport = camera.ViewportSize
	local x, y = viewport.X / 2, viewport.Y / 2
	if input and input.MouseEnabled then
		local mouse = input:GetMouseLocation()
		x, y = mouse.X, mouse.Y
	end
	local ray = camera:ViewportPointToRay(x, y)
	if state.cfg.net.place == "Around me" then return ray.Origin + ray.Direction.Unit * 26 end
	if ray.Direction.Y <= -0.05 then return nil end
	return position + ray.Direction.Unit * state.radius * 0.92
end

function SkyFx.stepNet(state, fx, position, playerPosition, delta)
	local env, cfg = state.context.environment, state.cfg.net
	local sky, speed = cfg.place ~= "Around me", cfg.speed / 100
	fx.shell.CFrame = env.CFrame.new(position)
	fx.cursorPosition = SkyFx.cursor(state, fx, position)
	if fx.cursorPosition then fx.cursor.Position = fx.cursorPosition end
	for _, node in ipairs(fx.nodes) do
		if sky then
			node.azimuth += node.drift * delta * speed
			node.elevation += node.vertical * delta * speed
			if node.elevation < math.rad(12) then node.vertical = math.abs(node.vertical) end
			if node.elevation > math.rad(74) then node.vertical = -math.abs(node.vertical) end
			node.position = position + SkyFx.direction(state, node.azimuth, node.elevation) * state.radius * 0.92
		else
			node.relative += node.velocity * delta * speed * 2.5
			local relative, velocity = node.relative, node.velocity
			if math.abs(relative.X) > 44 then velocity = env.Vector3.new(-math.sign(relative.X) * math.abs(velocity.X), velocity.Y, velocity.Z) end
			if relative.Y < -10 or relative.Y > 14 then velocity = env.Vector3.new(velocity.X, (relative.Y < 0 and 1 or -1) * math.abs(velocity.Y), velocity.Z) end
			if math.abs(relative.Z) > 44 then velocity = env.Vector3.new(velocity.X, velocity.Y, -math.sign(relative.Z) * math.abs(velocity.Z)) end
			node.velocity = velocity
			node.position = playerPosition + env.Vector3.new(0, 12, 0) + node.relative
		end
		node.part.CFrame = env.CFrame.new(node.position)
		if state.time >= node.nextEmit then node.emitter:Emit(1); node.nextEmit = state.time + 5 + math.random() * 3 end
	end
	fx.linkClock += delta
	if fx.linkClock >= 0.05 then fx.linkClock = 0; SkyFx.linkNet(state, fx) end
end

function SkyFx.drop(state, name)
	local effect = state.effects[name]
	state.effects[name] = nil
	if effect and effect.folder then pcall(function() effect.folder:Destroy() end) end
end

function SkyFx.clear(state)
	for _, name in ipairs(SKY_FX_ORDER) do SkyFx.drop(state, name) end
	if state.folder then pcall(function() state.folder:Destroy() end) end
	state.folder, state.camera = nil, nil
end

function SkyFx.dirty(state, name)
	if name == "general" then
		for _, effect in pairs(state.effects) do effect.dirty = true end
		return
	end
	if state.effects[name] then state.effects[name].dirty = true end
end

function SkyFx.set(state, name, key, value)
	local settings = state.cfg[name]
	if not settings then return end
	settings[key] = value
	SkyFx.dirty(state, name)
end

function SkyFx.setOn(state, name, enabled)
	local handle = state.controls[name]
	if handle and handle.Set then handle.Set(enabled); return end
	SkyFx.set(state, name, "on", enabled)
end

function SkyFx.scene(state, names)
	if not state.sceneSaved then
		state.sceneSaved = {}
		for _, name in ipairs(SKY_FX_ORDER) do state.sceneSaved[name] = state.cfg[name].on end
	end
	local selected = {}
	for _, name in ipairs(names or {}) do selected[name] = true end
	for _, name in ipairs(SKY_FX_ORDER) do SkyFx.setOn(state, name, selected[name] == true) end
	if state.paint then state.paint() end
end

function SkyFx.sceneEnd(state)
	local saved = state.sceneSaved
	state.sceneSaved = nil
	if not saved then return end
	for _, name in ipairs(SKY_FX_ORDER) do SkyFx.setOn(state, name, saved[name] == true) end
	if state.paint then state.paint() end
end

function SkyFx.build(state, name)
	local folder = SkyFx.create(state, "Folder", state.folder, {Name = name})
	local ok, effect = pcall(function()
		if name == "stars" or name == "runes" or name == "dust" then return SkyFx.buildParticles(state, name, folder) end
		if name == "net" then return SkyFx.buildNet(state, folder) end
		return SkyFx.buildTrails(state, name, folder)
	end)
	if ok then return effect end
	folder:Destroy()
	error(effect, 0)
end

function SkyFx.apply(state, name, effect)
	if name == "stars" then return SkyFx.applyStars(state, effect) end
	if name == "runes" then return SkyFx.applyRunes(state, effect) end
	if name == "dust" then return SkyFx.applyDust(state, effect) end
	if name == "net" then return SkyFx.applyNet(state, effect) end
	return SkyFx.applyTrails(state, name, effect)
end

function SkyFx.applySquash(state, name, effect)
	local env = state.context.environment
	local squash = env.NumberSequence.new(state.squash)
	for _, object in ipairs(effect.folder:GetDescendants()) do
		if object:IsA("ParticleEmitter") then pcall(function() object.Squash = squash end) end
	end
	local rotated = state.squash <= 0.05
	if name == "stars" then
		effect.big.Rotation = rotated and env.NumberRange.new(-20, 20) or env.NumberRange.new(0, 0)
		effect.big.RotSpeed = rotated and env.NumberRange.new(-12, 12) or env.NumberRange.new(0, 0)
	end
	if name == "runes" then effect.main.Rotation = rotated and env.NumberRange.new(-10, 10) or env.NumberRange.new(0, 0) end
	if name == "dust" then
		effect.main.Rotation = rotated and env.NumberRange.new(0, 45) or env.NumberRange.new(0, 0)
		effect.main.RotSpeed = rotated and env.NumberRange.new(-30, 30) or env.NumberRange.new(0, 0)
	end
end

function SkyFx.stepEffect(state, name, effect, position, look, playerPosition, delta)
	local env = state.context.environment
	if name == "stars" then effect.part.CFrame = env.CFrame.new(position); return end
	if name == "runes" then effect.part.CFrame = env.CFrame.new(playerPosition + env.Vector3.new(0, 9, 0)); return end
	if name == "dust" then effect.part.CFrame = env.CFrame.new(playerPosition + env.Vector3.new(0, 8, 0)); return end
	if name == "net" then return SkyFx.stepNet(state, effect, position, playerPosition, delta) end
	return SkyFx.stepTrails(state, name, effect, position, look)
end

function SkyFx.step(state, delta)
	local context = state.context
	if not context.isAlive() then SkyFx.clear(state); return end
	local active = false
	for _, name in ipairs(SKY_FX_ORDER) do if state.cfg[name].on then active = true; break end end
	local camera = context.workspace.CurrentCamera
	if not active or not camera then if state.folder then SkyFx.clear(state) end; return end
	if not state.folder or state.camera ~= camera or state.folder.Parent ~= camera then
		SkyFx.clear(state)
		state.folder = SkyFx.create(state, "Folder", camera, {Name = "PulseSkyFX"})
		state.camera = camera
	end
	delta = math.clamp(tonumber(delta) or 1 / 60, 0, 0.1)
	state.time += delta
	state.environmentClock += delta
	if state.environmentClock >= 0.5 then
		state.environmentClock = 0
		local atmosphere = context.lighting:FindFirstChildOfClass("Atmosphere")
		local radius = math.clamp(atmosphere and 72 / math.max(atmosphere.Density, 0.04) or context.lighting.FogEnd * 0.5, 110, 520)
		if math.abs(radius - state.radius) / state.radius > 0.08 then state.radius = radius; SkyFx.dirty(state, "general") end
		local stretch = context.configuration.ui and tonumber(context.configuration.ui.stretch) or 0
		local squash = stretch > 0 and math.floor(-math.log(math.max(0.1, 1 - stretch / 100 * 0.6), 2) * 100 + 0.5) / 100 or 0
		if math.abs(squash - state.squash) > 0.02 then state.squash = squash; SkyFx.dirty(state, "general") end
	end
	local frame, character = camera.CFrame, context.player.Character
	local root = character and character:FindFirstChild("HumanoidRootPart")
	local playerPosition = root and root.Position or frame.Position
	for _, name in ipairs(SKY_FX_ORDER) do
		local cfg, effect = state.cfg[name], state.effects[name]
		if not cfg.on then if effect then SkyFx.drop(state, name) end; continue end
		if name == "net" and effect and (effect.count ~= math.clamp(math.floor(cfg.nodes), 8, 140) or effect.place ~= cfg.place) then
			SkyFx.drop(state, name)
			effect = nil
		end
		if not effect and state.time >= (state.failures[name] or 0) then
			local ok, result = pcall(SkyFx.build, state, name)
			if ok then effect = result; state.effects[name] = effect
			else state.failures[name] = state.time + 5; context.environment.warn("[PulseHub] sky fx " .. name .. ": " .. tostring(result)) end
		end
		if not effect then continue end
		if effect.dirty then
			effect.dirty = false
			local ok, message = pcall(function()
				SkyFx.apply(state, name, effect)
				SkyFx.applySquash(state, name, effect)
			end)
			if not ok then context.environment.warn("[PulseHub] sky fx " .. name .. ": " .. tostring(message)) end
		end
		local ok, message = pcall(SkyFx.stepEffect, state, name, effect, frame.Position, frame.LookVector, playerPosition, delta)
		if not ok then
			state.failures[name] = state.time + 5
			SkyFx.drop(state, name)
			context.environment.warn("[PulseHub] sky fx " .. name .. ": " .. tostring(message))
		end
	end
end

function SkyFx.gallery(state)
	local context, env = state.context, state.context.environment
	local container = context.section:Container()
	if not container then return end
	local create = context.create
	local frame = create("Frame", {BackgroundTransparency = 1, Size = env.UDim2.new(1, 0, 0, 0), AutomaticSize = env.Enum.AutomaticSize.Y}, container)
	create("UIGridLayout", {CellSize = env.UDim2.new(0.5, -4, 0, 76), CellPadding = env.UDim2.fromOffset(8, 8),
		SortOrder = env.Enum.SortOrder.LayoutOrder}, frame)
	local labels = {"Stars", "Shooting Stars", "Comets", "Constellations", "Runes", "Stardust"}
	local colors = {{{70, 90, 150}, {12, 16, 40}}, {{150, 200, 255}, {14, 20, 46}}, {{110, 210, 255}, {16, 22, 50}},
		{{150, 205, 255}, {14, 18, 44}}, {{130, 220, 255}, {18, 30, 54}}, {{255, 214, 120}, {40, 28, 20}}}
	local ok, atlas = pcall(env.getcustomasset, "PulseHub/sky_fx_v6.jpg")
	if not ok then atlas = nil end
	local tiles = {}
	for index, key in ipairs(SKY_FX_ORDER) do
		local button = create("TextButton", {Text = "", AutoButtonColor = false, BorderSizePixel = 0, LayoutOrder = index,
			BackgroundColor3 = env.Color3.new(1, 1, 1)}, frame)
		context.corner(button, 12)
		create("UIGradient", {Color = env.ColorSequence.new(env.Color3.fromRGB(table.unpack(colors[index][1])),
			env.Color3.fromRGB(table.unpack(colors[index][2]))), Rotation = 35}, button)
		local picture = create("ImageLabel", {Name = "Photo", Size = env.UDim2.fromScale(1, 1), BackgroundTransparency = 1,
			ScaleType = env.Enum.ScaleType.Stretch, Visible = atlas ~= nil, Image = atlas or "", ZIndex = 2}, button)
		context.corner(picture, 12)
		picture.ImageRectOffset = env.Vector2.new((index - 1) % 4 * 256, math.floor((index - 1) / 4) * 128)
		picture.ImageRectSize = env.Vector2.new(256, 128)
		local shade = create("Frame", {AnchorPoint = env.Vector2.new(0, 1), Position = env.UDim2.new(0, 5, 1, -5),
			Size = env.UDim2.new(1, -10, 0, 20), BackgroundColor3 = env.Color3.new(0, 0, 0), BackgroundTransparency = 0.4,
			BorderSizePixel = 0, ZIndex = 3}, button)
		context.corner(shade, 7)
		local label = context.nova.label({Parent = shade, Text = context.translation.tr(labels[index]), Font = context.nova.Font.Semi(), Size = 12,
			Pos = env.UDim2.fromOffset(7, 0), Box = env.UDim2.new(1, -10, 1, 0), Truncate = true, Color = "Text", Z = 4})
		context.translation.bind(label, labels[index])
		local stroke = create("UIStroke", {Thickness = 1, Transparency = 0.8, ApplyStrokeMode = env.Enum.ApplyStrokeMode.Border}, button)
		context.nova.Theme.bind(stroke, "Color", "Glass")
		local tile = {key = key, stroke = stroke, hover = false}
		table.insert(tiles, tile)
		context.connect(button.MouseButton1Click, function() SkyFx.setOn(state, key, not state.cfg[key].on); state.paint() end)
		context.connect(button.MouseEnter, function() tile.hover = true; state.paint() end)
		context.connect(button.MouseLeave, function() tile.hover = false; state.paint() end)
	end
	state.paint = function()
		for _, tile in ipairs(tiles) do
			local selected = state.cfg[tile.key].on
			context.nova.paint(tile.stroke, "Color", (selected or tile.hover) and "Accent" or "Glass", "Quick")
			tile.stroke.Transparency, tile.stroke.Thickness = selected and 0 or (tile.hover and 0.35 or 0.8), selected and 2 or 1
		end
	end
	state.paint()
end

function SkyFx.install(context)
	local env, section = context.environment, context.section
	local state = {context = context, cfg = SkyFx.defaults(env), palettes = SkyFx.palettes(env), controls = {}, effects = {}, failures = {},
		time = 0, environmentClock = 1, radius = 160, squash = 0}
	local function slider(text, group, key, min, max, suffix)
		section:Slider({Text = text, Min = min, Max = max, Decimals = 0, Suffix = suffix, Default = state.cfg[group][key],
			Callback = function(value) SkyFx.set(state, group, key, value) end})
	end
	local function dropdown(text, group, key, values)
		local options = {}
		for _, value in ipairs(values) do table.insert(options, {code = value, label = value}) end
		section:Dropdown({Text = text, Default = state.cfg[group][key], Options = options, Callback = function(value)
			if value then SkyFx.set(state, group, key, value) end
		end})
	end
	local function color(text, group, key)
		section:Colorpicker({Text = text, Default = state.cfg[group][key], Callback = function(value)
			if env.typeof(value) == "Color3" then SkyFx.set(state, group, key, value) end
		end})
	end
	local function toggle(text, key, children)
		state.controls[key] = section:Toggle({Text = text, Default = false, Settings = children, Callback = function(value)
			SkyFx.set(state, key, "on", value == true)
			if state.paint then state.paint() end
		end})
	end
	section:Sub("SkyFX")
	section:Columns()
	section:Group({Title = "Sky Effects", Side = "Left", Pin = true})
	pcall(SkyFx.gallery, state)
	section:Group({Title = "Sky Settings", Side = "Left", Pin = true})
	slider("Effect brightness", "general", "bright", 30, 200, "%")
	section:Button({Text = "Turn all off", Callback = function()
		for _, name in ipairs(SKY_FX_ORDER) do SkyFx.setOn(state, name, false) end
		if state.paint then state.paint() end
	end})
	section:Group({Title = "Night Sky", Side = "Right", Pin = true})
	toggle("Stars", "stars", function()
		slider("Star density", "stars", "density", 10, 100, "%")
		slider("Star size", "stars", "size", 50, 200, "%")
		slider("Twinkle", "stars", "twinkle", 0, 100, "%")
		dropdown("Star color", "stars", "tint", {"Natural", "Cold", "Warm", "Pastel", "Rainbow"})
	end)
	toggle("Shooting Stars", "meteors", function()
		slider("Meteor frequency", "meteors", "rate", 5, 100, "%")
		slider("Tail length", "meteors", "length", 40, 200, "%")
		color("Meteor color", "meteors", "color")
	end)
	toggle("Comets", "comets", function()
		slider("Comet frequency", "comets", "rate", 5, 100, "%")
		slider("Comet size", "comets", "size", 50, 200, "%")
		color("Comet color", "comets", "color")
	end)
	section:Group({Title = "Magic", Side = "Right", Pin = true})
	toggle("Constellations", "net", function()
		dropdown("Placement", "net", "place", {"Sky", "Around me"})
		slider("Node count", "net", "nodes", 20, 140)
		slider("Link distance", "net", "reach", 0, 100, "%")
		slider("Drift speed", "net", "speed", 0, 100, "%")
		color("Line color", "net", "color")
		for _, entry in ipairs({{"Energy pulses", "pulses", true}, {"Follow cursor", "cursor", true},
			{"Rainbow lines", "rainbow", false}, {"Star figures", "figures", true}}) do
			section:Toggle({Text = entry[1], Default = entry[3], Callback = function(value) SkyFx.set(state, "net", entry[2], value == true) end})
		end
	end)
	toggle("Runes", "runes", function()
		slider("Rune amount", "runes", "amount", 10, 100, "%")
		slider("Rune size", "runes", "size", 50, 200, "%")
		dropdown("Rune set", "runes", "set", {"Runes", "Glyphs"})
		color("Rune color", "runes", "color")
	end)
	toggle("Stardust", "dust", function()
		slider("Dust amount", "dust", "amount", 10, 100, "%")
		dropdown("Dust color", "dust", "palette", {"Gold", "Silver", "Pink", "Aqua", "Rainbow"})
	end)
	local api = {cfg = state.cfg, scene = function(names) SkyFx.scene(state, names) end, sceneEnd = function() SkyFx.sceneEnd(state) end,
		set = function(group, key, value) SkyFx.set(state, group, key, value) end}
	env.getgenv().__pulseSkyFx = api
	if state.paint then state.paint() end
	if context.runService.RenderStepped then context.connect(context.runService.RenderStepped, function(delta)
		local ok, message = pcall(SkyFx.step, state, delta)
		if not ok then env.warn("[PulseHub] sky fx step: " .. tostring(message)) end
	end) end
	return state, function()
		SkyFx.clear(state)
		if env.getgenv().__pulseSkyFx == api then env.getgenv().__pulseSkyFx = nil end
	end
end

local AvatarSkins = {}
do -- Keep module-private locals out of the main chunk's register budget.

local AVATAR_PROPERTIES = {"BodyTypeScale", "DepthScale", "HeadScale", "HeightScale", "ProportionScale", "WidthScale",
	"Face", "Head", "LeftArm", "LeftLeg", "RightArm", "RightLeg", "Torso", "GraphicTShirt", "Pants", "Shirt"}
local AVATAR_COLORS = {"HeadColor", "LeftArmColor", "LeftLegColor", "RightArmColor", "RightLegColor", "TorsoColor"}
local AVATAR_PARTS = {Head = "Head", DynamicHead = "Head", Torso = "Torso", LeftArm = "LeftArm", RightArm = "RightArm",
	LeftLeg = "LeftLeg", RightLeg = "RightLeg"}
local AVATAR_ACCESSORIES = {HairAccessory = true, FaceAccessory = true, NeckAccessory = true, ShouldersAccessory = true,
	FrontAccessory = true, BackAccessory = true, WaistAccessory = true}

function AvatarSkins.serialize(description)
	local ok, result = pcall(function()
		local saved = {p = {}, c = {}, acc = {}}
		for _, key in AVATAR_PROPERTIES do saved.p[key] = description[key] end
		for _, key in AVATAR_COLORS do
			local color = description[key]
			saved.c[key] = {math.floor(color.R * 255 + 0.5), math.floor(color.G * 255 + 0.5), math.floor(color.B * 255 + 0.5)}
		end
		for _, accessory in description:GetAccessories(true) do
			table.insert(saved.acc, {t = accessory.AccessoryType.Name, id = accessory.AssetId, l = accessory.IsLayered == true,
				o = accessory.Order, pf = accessory.Puffiness})
		end
		return saved
	end)
	if ok then return result end
	return nil
end

function AvatarSkins.deserialize(environment, saved)
	if type(saved) ~= "table" then return nil end
	local ok, description = pcall(function()
		local result = environment.Instance.new("HumanoidDescription")
		for _, key in AVATAR_PROPERTIES do
			local value = type(saved.p) == "table" and saved.p[key]
			if type(value) == "number" then pcall(function() result[key] = value end) end
		end
		for _, key in AVATAR_COLORS do
			local color = type(saved.c) == "table" and saved.c[key]
			if type(color) ~= "table" then continue end
			pcall(function() result[key] = environment.Color3.fromRGB(tonumber(color[1]) or 0, tonumber(color[2]) or 0, tonumber(color[3]) or 0) end)
		end
		local accessories = {}
		for _, item in type(saved.acc) == "table" and saved.acc or {} do
			local valid, kind = pcall(function() return environment.Enum.AccessoryType[tostring(item.t)] end)
			if not valid or not kind or not tonumber(item.id) then continue end
			table.insert(accessories, {AccessoryType = kind, AssetId = tonumber(item.id), IsLayered = item.l == true,
				Order = tonumber(item.o), Puffiness = tonumber(item.pf)})
		end
		result:SetAccessories(accessories, true)
		return result
	end)
	if ok then return description end
	return nil
end

function AvatarSkins.bundle(context, id)
	local ok, description, name = pcall(function()
		local bundle = context.assetService:GetBundleDetailsAsync(id)
		for _, item in bundle.Items or {} do
			if item.Type == "UserOutfit" then return context.players:GetHumanoidDescriptionFromOutfitId(item.Id), bundle.Name end
		end
	end)
	if ok and description then return description, name end

	ok, description = pcall(context.avatar.GetItemDetails, context.avatar, id, context.environment.Enum.AvatarItemType.Bundle)
	if not ok or type(description) ~= "table" then return nil, "Bundle not found (rate limit?)" end
	local bundle = description
	local items = bundle.BundledItems or bundle.Items
	if type(items) ~= "table" or #items == 0 then return nil, "Bundle is empty" end
	description = context.environment.Instance.new("HumanoidDescription")
	local accessories, parts = {}, 0
	for _, item in items do
		local kind = tostring(item.AssetType)
		local part = AVATAR_PARTS[kind]
		if part then
			pcall(function() description[part] = item.Id end)
			parts += 1
			continue
		end
		if not AVATAR_ACCESSORIES[kind] then continue end
		accessories[kind] = accessories[kind] or {}
		table.insert(accessories[kind], tostring(item.Id))
	end
	for kind, values in accessories do pcall(function() description[kind] = table.concat(values, ",") end) end
	if parts == 0 and not next(accessories) then return nil, "This bundle has no body parts" end
	return description, bundle.Name or "ID " .. tostring(id)
end

function AvatarSkins.user(context, value)
	local id = tonumber(value) or context.players:GetUserIdFromNameAsync(value)
	local name = tostring(value)
	pcall(function() name = context.players:GetNameFromUserIdAsync(id) end)
	return context.players:GetHumanoidDescriptionFromUserId(id), name, id
end

function AvatarSkins.joints(model)
	local result = {}
	for _, joint in model:GetDescendants() do
		if joint:IsA("Motor6D") and joint.Part0 and joint.Part1 then
			result[joint.Part1.Name] = {joint = joint, parent = joint.Part0, part = joint.Part1, motor = true}
			continue
		end
		if not joint:IsA("AnimationConstraint") or not joint.Attachment0 or not joint.Attachment1 then continue end
		local first, second = joint.Attachment0, joint.Attachment1
		if first.Parent and second.Parent then result[second.Parent.Name] = {joint = joint, parent = first.Parent, part = second.Parent, a0 = first, a1 = second} end
	end
	return result
end

function AvatarSkins.frames(link)
	if link.motor then return link.joint.C0, link.joint.C1 end
	return link.a0.CFrame, link.a1.CFrame
end

function AvatarSkins.ground(environment, model, joints)
	local root, foot = model:FindFirstChild("HumanoidRootPart"), model:FindFirstChild("LeftFoot")
	if not root or not foot then return nil end
	local chain, part = {}, foot
	while part and part ~= root do
		local link = joints[part.Name]
		if not link or #chain >= 64 then return nil end
		table.insert(chain, 1, link)
		part = link.parent
	end
	local frame = environment.CFrame.new()
	for _, link in chain do
		local first, second = AvatarSkins.frames(link)
		frame = frame * first * second:Inverse()
	end
	return foot.Size.Y / 2 - frame.Position.Y
end

function AvatarSkins.ghost(part)
	part.CanCollide, part.CanTouch, part.CanQuery, part.Massless, part.CastShadow = false, false, false, true, true
	part:GetPropertyChangedSignal("CanCollide"):Connect(function() if part.CanCollide then part.CanCollide = false end end)
end

function AvatarSkins.prepare(state, model)
	local environment = state.context.environment
	local parts = {}
	for _, object in model:GetDescendants() do
		if object:IsA("BaseScript") then object:Destroy(); continue end
		if object:IsA("BasePart") then
			AvatarSkins.ghost(object)
			if object.Name ~= "HumanoidRootPart" then table.insert(parts, object) end
			continue
		end
		if object:IsA("AnimationConstraint") then object.IsKinematic = true end
		if object:IsA("BallSocketConstraint") then object.Enabled = false end
	end
	local humanoid = model:FindFirstChildOfClass("Humanoid")
	if humanoid then pcall(function()
		humanoid.DisplayDistanceType = environment.Enum.HumanoidDisplayDistanceType.None
		humanoid.HealthDisplayType = environment.Enum.HumanoidHealthDisplayType.AlwaysOff
		humanoid.EvaluateStateMachine, humanoid.BreakJointsOnDeath = false, false
	end) end
	local root = model:FindFirstChild("HumanoidRootPart")
	if root then root.Anchored, root.Transparency = true, 1 end
	model.Name = "PulseSkin"
	model.DescendantAdded:Connect(function(object) if object:IsA("BasePart") then AvatarSkins.ghost(object) end end)
	local joints = AvatarSkins.joints(model)
	return joints, AvatarSkins.ground(environment, model, joints), parts
end

function AvatarSkins.attach(state, character)
	state.character, state.links = character, nil
	local environment = state.context.environment
	local joints = AvatarSkins.joints(character)
	local ground = AvatarSkins.ground(environment, character, joints)
	if not ground or not state.ground or ground <= 0 then return false end
	local links, byPart = {}, {}
	for name, source in joints do
		local target = state.joints[name]
		if not target then continue end
		local source0, source1 = AvatarSkins.frames(source)
		local target0, target1 = AvatarSkins.frames(target)
		table.insert(links, {source = source, target = target, root = source.parent.Name == "HumanoidRootPart",
			restSource = source0 * source1:Inverse(), restTarget = target0 * target1:Inverse(), inverse = target0:Inverse(),
			target1 = target1, pivot0 = environment.CFrame.new(target0.Position), pivot1 = environment.CFrame.new(target1.Position):Inverse()})
		byPart[target.part.Name] = #links
	end
	if #links == 0 then return false end
	state.scale, state.lift = state.ground / ground, state.ground - ground
	state.chains, state.feet = {}, {}
	for name in byPart do
		local chain, part, depth = {}, name, 0
		while part and byPart[part] and depth < 32 do
			depth += 1
			local index = byPart[part]
			table.insert(chain, 1, index)
			local parent = links[index].target.parent
			part = parent.Name ~= "HumanoidRootPart" and parent.Name or nil
			if not part then state.chains[name] = chain end
		end
	end
	for _, name in {"LeftFoot", "RightFoot"} do
		local source, target = character:FindFirstChild(name), state.model:FindFirstChild(name)
		if state.chains[name] and source and target and source:IsA("BasePart") and target:IsA("BasePart") then
			table.insert(state.feet, {chain = state.chains[name], source = source.Size.Y / 2, target = target.Size.Y / 2})
		end
	end
	local hand = state.model:FindFirstChild("RightHand")
	local attachment = hand and hand:FindFirstChild("RightGripAttachment")
	state.modelGrip = hand and environment.CFrame.new(0, -hand.Size.Y / 2, 0) or nil
	if attachment and attachment:IsA("Attachment") then state.modelGrip = attachment.CFrame end
	state.links = links
	AvatarSkins.notify(state)
	return true
end

function AvatarSkins.drive(state, character)
	local sourceRoot = character:FindFirstChild("HumanoidRootPart")
	local targetRoot = state.model and state.model:FindFirstChild("HumanoidRootPart")
	if not state.links or not sourceRoot or not targetRoot then return false end
	local environment = state.context.environment
	for _, link in state.links do
		local first, second = AvatarSkins.frames(link.source)
		local relative = first * link.source.joint.Transform * second:Inverse()
		local target
		if link.root then
			target = environment.CFrame.new(link.restTarget.Position + (relative.Position - link.restSource.Position) * state.scale) * relative.Rotation
		else
			target = link.pivot0 * relative.Rotation * link.pivot1
		end
		link.relativeSource, link.relativeTarget = relative, target
		link.target.joint.Transform = link.inverse * target * link.target1
	end
	local lift = state.lift
	if #state.feet > 0 then
		local sourceLow, targetLow = math.huge, math.huge
		for _, foot in state.feet do
			local source, target = environment.CFrame.identity, environment.CFrame.identity
			for _, index in foot.chain do
				local link = state.links[index]
				source, target = source * link.relativeSource, target * link.relativeTarget
			end
			sourceLow, targetLow = math.min(sourceLow, source.Y - foot.source), math.min(targetLow, target.Y - foot.target)
		end
		if sourceLow < math.huge and targetLow < math.huge then lift = sourceLow - targetLow end
	end
	state.rootFrame, state.sourceFrame = sourceRoot.CFrame * environment.CFrame.new(0, lift, 0), sourceRoot.CFrame
	targetRoot.CFrame = state.rootFrame
	return true
end

function AvatarSkins.world(state, target, name)
	local chain = state.chains and state.chains[name]
	if not chain then return nil end
	local frame = target and state.rootFrame or state.sourceFrame
	for _, index in chain do
		local link = state.links[index]
		frame *= target and link.relativeTarget or link.relativeSource
	end
	return frame
end

function AvatarSkins.notify(state)
	local globals = state.context.environment.getgenv()
	local callback = rawget(globals, "__pulseSkinChanged")
	if type(callback) == "function" then state.context.environment.task.defer(function() pcall(callback, state.player) end) end
end

function AvatarSkins.restoreGrips(state, except)
	for joint, saved in state.grips do
		if joint == except then continue end
		pcall(function() if joint.Parent and saved.applied and joint.C0:FuzzyEq(saved.applied, 0.001) then joint.C0 = saved.original end end)
		state.grips[joint] = nil
	end
end

function AvatarSkins.grip(state, character)
	local hand = character:FindFirstChild("RightHand")
	local joint = hand and hand:FindFirstChild("RightGrip")
	AvatarSkins.restoreGrips(state, joint)
	if not joint or not joint:IsA("JointInstance") or not state.modelGrip then return end
	local saved = state.grips[joint]
	if not saved or not saved.applied or not joint.C0:FuzzyEq(saved.applied, 0.001) then
		saved = {original = joint.C0}
		state.grips[joint] = saved
	end
	local source, target = AvatarSkins.world(state, false, "RightHand"), AvatarSkins.world(state, true, "RightHand")
	if not source or not target then return end
	saved.applied = source:Inverse() * target * state.modelGrip
	joint.C0 = saved.applied
end

function AvatarSkins.restoreMounts(state)
	for object, saved in state.mounts do
		pcall(function()
			if object.Parent and saved.applied and object[saved.property]:FuzzyEq(saved.applied, 0.0001) then object[saved.property] = saved.original end
		end)
		state.mounts[object] = nil
	end
	state.mountList, state.mountCharacter = nil, nil
end

function AvatarSkins.scanMounts(state, character)
	local torso = {LowerTorso = character:FindFirstChild("LowerTorso"), UpperTorso = character:FindFirstChild("UpperTorso")}
	local function partName(part)
		for name, value in torso do if value == part then return name end end
	end
	local mounts, seen = {}, {}
	local displays = state.context.workspace:FindFirstChild("WeaponDisplays")
	for _, display in displays and displays:GetChildren() or {} do
		local constraint = display:FindFirstChildOfClass("RigidConstraint")
		local attachment = constraint and constraint.Attachment0
		local name = attachment and partName(attachment.Parent)
		if name and not seen[attachment] then
			seen[attachment] = true
			table.insert(mounts, {object = attachment, property = "CFrame", part = name})
		end
		local joint = display:FindFirstChild("PulseMount")
		name = joint and joint:IsA("JointInstance") and partName(joint.Part0)
		if name and not seen[joint] then
			seen[joint] = true
			table.insert(mounts, {object = joint, property = "C0", part = name, anchor = joint:GetAttribute("PulseAnchor")})
		end
	end
	state.mountList, state.mountCharacter, state.mountAt = mounts, character, state.context.environment.os.clock()
end

function AvatarSkins.mountOriginal(state, object)
	local saved = state.mounts[object]
	if saved and object.Parent and saved.applied and object[saved.property]:FuzzyEq(saved.applied, 0.0001) then return saved.original end
	return nil
end

function AvatarSkins.scaleOffset(value, original, replacement)
	local absolute = math.abs(value)
	local inside = math.min(absolute, original)
	local scaled = (original > 0.001 and inside * replacement / original or 0) + math.max(absolute - original, 0)
	return value < 0 and -scaled or scaled
end

function AvatarSkins.followMounts(state, character)
	local environment = state.context.environment
	if state.mountCharacter ~= character or environment.os.clock() - (state.mountAt or 0) > 0.5 then AvatarSkins.scanMounts(state, character) end
	for _, mount in state.mountList or {} do
		local object = mount.object
		local originalPart = character:FindFirstChild(mount.part)
		local modelPart = state.model:FindFirstChild(mount.part)
		local source, target = AvatarSkins.world(state, false, mount.part), AvatarSkins.world(state, true, mount.part)
		if not object.Parent or not originalPart or not modelPart or not source or not target then continue end
		local current, saved = object[mount.property], state.mounts[object]
		if not saved or not saved.applied or not current:FuzzyEq(saved.applied, 0.0001) then
			saved = {original = current, property = mount.property}
			state.mounts[object] = saved
		end
		local position = saved.original.Position
		local anchor = mount.anchor and originalPart:FindFirstChild(mount.anchor)
		if anchor and anchor:IsA("Attachment") then position = (AvatarSkins.mountOriginal(state, anchor) or anchor.CFrame).Position end
		local sourceSize, targetSize = originalPart.Size / 2, modelPart.Size / 2
		local scaled = environment.Vector3.new(AvatarSkins.scaleOffset(position.X, sourceSize.X, targetSize.X),
			AvatarSkins.scaleOffset(position.Y, sourceSize.Y, targetSize.Y), AvatarSkins.scaleOffset(position.Z, sourceSize.Z, targetSize.Z))
		saved.applied = source:Inverse() * target * environment.CFrame.new(scaled - position) * saved.original
		if not current:FuzzyEq(saved.applied, 0.0001) then object[mount.property] = saved.applied end
	end
end

function AvatarSkins.collectBody(state, character)
	local body = {}
	for _, child in character:GetChildren() do
		if child:IsA("Tool") or child:GetAttribute("PulseVFX") then continue end
		if child:IsA("BasePart") or child:IsA("Decal") then table.insert(body, child) end
		for _, object in child:GetDescendants() do
			if (object:IsA("BasePart") or object:IsA("Decal")) and not object:FindFirstAncestorOfClass("Tool") then table.insert(body, object) end
		end
	end
	state.body, state.bodyAt, state.bodyDirty = body, state.context.environment.os.clock(), false
	if state.bodyCharacter == character then return end
	if state.bodyConnection then pcall(function() state.bodyConnection:Disconnect() end) end
	state.bodyCharacter = character
	state.bodyConnection = character.DescendantAdded:Connect(function() state.bodyDirty = true end)
end

function AvatarSkins.hideBody(state, character)
	local age = state.context.environment.os.clock() - (state.bodyAt or 0)
	if state.bodyCharacter ~= character or not state.body or state.bodyDirty and age > 0.2 or age > 3 then AvatarSkins.collectBody(state, character) end
	for _, object in state.body do
		if not object.Parent or object.LocalTransparencyModifier == 1 then continue end
		object.LocalTransparencyModifier = 1
		state.hidden[object] = true
	end
end

function AvatarSkins.showBody(state)
	for object in state.hidden do pcall(function() if object.Parent then object.LocalTransparencyModifier = 0 end end) end
	table.clear(state.hidden)
	state.body = nil
end

function AvatarSkins.firstPerson(state, character)
	local camera = state.context.workspace.CurrentCamera
	local head = character:FindFirstChild("Head")
	local globals = state.context.environment.getgenv()
	local invis = rawget(globals, "__pulseInvis")
	local near = camera and head and (camera.CFrame.Position - head.Position).Magnitude < 1.4
	local transparency = near and 1 or type(invis) == "table" and invis.active == true and 0.5 or 0
	if transparency == state.near then return end
	state.near = transparency
	for _, part in state.modelParts do if part.Parent then part.LocalTransparencyModifier = transparency end end
end

function AvatarSkins.pose(state, map, targetJoints, root)
	if not state.links or not root then return false end
	local rootLink
	for _, link in state.links do
		local relative = link.restTarget
		if link.root then
			rootLink = link
		else
			local first, second = map(link.source.parent), map(link.source.part)
			if first and second and first.Parent and second.Parent then
				relative = link.pivot0 * (first.CFrame:Inverse() * second.CFrame).Rotation * link.pivot1
			end
		end
		local joint = link.target
		if targetJoints then joint = targetJoints[link.target.part.Name] end
		if joint then joint.joint.Transform = link.inverse * relative * link.target1 end
		if not targetJoints then link.relativeTarget = relative end
	end
	local source = rootLink and map(rootLink.source.part)
	if not source or not source.Parent then return false end
	root.CFrame = source.CFrame * rootLink.restTarget:Inverse()
	return true
end

function AvatarSkins.signature(character)
	local torso = character:FindFirstChild("UpperTorso")
	local shirt, pants = character:FindFirstChildOfClass("Shirt"), character:FindFirstChildOfClass("Pants")
	return table.concat({torso and torso:IsA("MeshPart") and torso.MeshId or "", shirt and shirt.ShirtTemplate or "",
		pants and pants.PantsTemplate or ""}, "|")
end

function AvatarSkins.freeCorpse(corpse)
	if corpse.watch then pcall(function() corpse.watch:Disconnect() end) end
	if corpse.model then pcall(function() corpse.model:Destroy() end) end
	for _, object in corpse.hidden do pcall(function() if object.Parent then object.LocalTransparencyModifier = 0 end end) end
end

function AvatarSkins.adoptCorpse(state, ragdoll)
	if state.corpses[ragdoll] or not state.model or not state.links then return end
	local model = state.model:Clone()
	model.Name = state.remote and "PulseRemoteSkinCorpse" or "PulseSkinCorpse"
	local corpse = {model = model, map = {}, hidden = {}, seen = {}, fade = -1, links = state.links,
		started = state.context.environment.os.clock(), parts = {}}
	for _, part in ragdoll:GetChildren() do if part:IsA("BasePart") then corpse.map[part.Name] = part end end
	corpse.joints = AvatarSkins.joints(model)
	for _, part in model:GetDescendants() do
		if not part:IsA("BasePart") then continue end
		AvatarSkins.ghost(part)
		if part.Name ~= "HumanoidRootPart" then table.insert(corpse.parts, part) end
	end
	corpse.root = model:FindFirstChild("HumanoidRootPart")
	model.Parent = state.context.workspace.CurrentCamera
	state.corpses[ragdoll] = corpse
end

function AvatarSkins.updateCorpses(state)
	local now = state.context.environment.os.clock()
	for ragdoll, corpse in state.corpses do
		if not ragdoll.Parent or not corpse.model.Parent then
			AvatarSkins.freeCorpse(corpse)
			state.corpses[ragdoll] = nil
			continue
		end
		if corpse.dirty ~= false or now - (corpse.scanAt or 0) > 1 then
			corpse.dirty, corpse.scanAt = false, now
			if not corpse.watch then corpse.watch = ragdoll.DescendantAdded:Connect(function() corpse.dirty = true end) end
			for _, object in ragdoll:GetDescendants() do
				if not object:IsA("BasePart") and not object:IsA("Decal") then continue end
				object.LocalTransparencyModifier = 1
				if not corpse.seen[object] then corpse.seen[object] = true; table.insert(corpse.hidden, object) end
			end
		end
		local torso = corpse.map.LowerTorso
		if not corpse.done then
			AvatarSkins.pose({links = corpse.links}, function(part) return corpse.map[part.Name] end, corpse.joints, corpse.root)
			if torso and torso.Anchored and now - corpse.started > 5 then corpse.done = true end
		end
		local fade = 0
		for _, object in corpse.hidden do
			if object.Parent and object:IsA("BasePart") and object.Name ~= "HumanoidRootPart" then fade = math.max(fade, object.Transparency) end
		end
		if fade == corpse.fade then continue end
		corpse.fade = fade
		for _, part in corpse.parts do if part.Parent then part.LocalTransparencyModifier = fade end end
	end
end

function AvatarSkins.watchRagdoll(state, object)
	if object.Name ~= "Raggy" or not object:IsA("Model") then return end
	local now, recent = state.context.environment.os.clock(), {}
	for _, entry in state.ragdolls do if now - entry.time < 6 then table.insert(recent, entry) end end
	table.insert(recent, {model = object, time = now})
	state.ragdolls = recent
end

function AvatarSkins.matchDeath(state)
	local death = state.death
	if not death or death.done then return end
	local now = state.context.environment.os.clock()
	if now - death.time > 4 then death.done = true; return end
	local recent = {}
	local candidates = state.registry and state.registry.ragdolls or state.ragdolls
	for _, entry in candidates do
		local ragdoll = entry.model
		if now - entry.time >= 6 or not ragdoll.Parent then continue end
		table.insert(recent, entry)
		if state.registry and entry.taken then continue end
		local root = ragdoll:FindFirstChild("LowerTorso") or ragdoll:FindFirstChild("HumanoidRootPart")
		local ok, signature = pcall(AvatarSkins.signature, ragdoll)
		if not root or (root.Position - death.position).Magnitude >= 12 then continue end
		if death.signature ~= "||" and (not ok or signature ~= death.signature) then continue end
		death.done, death.corpse = true, ragdoll
		if state.registry then entry.taken = true end
		AvatarSkins.adoptCorpse(state, ragdoll)
		if state.registry then return end
	end
	if not state.registry then state.ragdolls = recent end
end

function AvatarSkins.deadPose(state, character, camera)
	AvatarSkins.restoreGrips(state)
	AvatarSkins.restoreMounts(state)
	local root = state.model:FindFirstChild("HumanoidRootPart")
	local replaced = state.death and state.death.corpse and state.corpses[state.death.corpse]
	local posed = not replaced and AvatarSkins.pose(state, function(part) return part end, nil, root)
	state.model.Parent = posed and camera or nil
	AvatarSkins.hideBody(state, character)
	local transparency = 0
	for _, object in state.body do
		if object.Parent and object:IsA("BasePart") and object.Name ~= "HumanoidRootPart" then transparency = math.max(transparency, object.Transparency) end
	end
	if transparency == state.deadFade then return end
	state.deadFade, state.near = transparency, nil
	for _, part in state.modelParts do if part.Parent then part.LocalTransparencyModifier = transparency end end
end

function AvatarSkins.step(state)
	local model = state.model
	if not model then return end
	local character, camera = state.context.player.Character, state.context.workspace.CurrentCamera
	local humanoid = character and character:FindFirstChildOfClass("Humanoid")
	pcall(AvatarSkins.matchDeath, state)
	pcall(AvatarSkins.updateCorpses, state)
	if character and humanoid and character.Parent and humanoid.Health <= 0 and state.character == character and state.links then
		if not state.death or state.death.character ~= character then
			local root = character:FindFirstChild("LowerTorso") or character:FindFirstChild("HumanoidRootPart")
			local ok, signature = pcall(AvatarSkins.signature, character)
			state.death = {character = character, time = state.context.environment.os.clock(),
				position = root and root.Position or state.context.environment.Vector3.zero, signature = ok and signature or "||"}
			pcall(AvatarSkins.matchDeath, state)
		end
		AvatarSkins.deadPose(state, character, camera)
		return
	end
	local root = character and character:FindFirstChild("HumanoidRootPart")
	if not character or not humanoid or humanoid.Health <= 0 or not root then
		model.Parent = nil
		AvatarSkins.showBody(state)
		AvatarSkins.restoreGrips(state)
		AvatarSkins.restoreMounts(state)
		state.character, state.links = nil, nil
		return
	end
	if state.deadFade then
		state.deadFade, state.near = nil, nil
		if state.remote then for _, part in state.modelParts do if part.Parent then part.LocalTransparencyModifier = 0 end end end
	end
	local now = state.context.environment.os.clock()
	if state.character ~= character or not state.links and now - (state.attachAt or 0) > 0.5 then
		state.attachAt = now
		state.driven = false
		AvatarSkins.showBody(state)
		AvatarSkins.restoreGrips(state)
		AvatarSkins.restoreMounts(state)
		AvatarSkins.attach(state, character)
	end
	if not state.links then return end
	if model.Parent ~= camera then
		model.Parent = camera
		state.driven = false
		for _, part in model:GetDescendants() do
			if part:IsA("BasePart") and (part.CanCollide or part.CanTouch or part.CanQuery) then
				part.CanCollide, part.CanTouch, part.CanQuery = false, false, false
			end
		end
	end
	if state.remote and state.driven and camera then
		local distance = (root.Position - camera.CFrame.Position).Magnitude
		if distance > 12 then
			local point, size = camera:WorldToViewportPoint(root.Position), camera.ViewportSize
			if point.Z < -6 or point.X < -size.X * 0.35 or point.X > size.X * 1.35 or point.Y < -size.Y * 0.35 or point.Y > size.Y * 1.35 then return end
			if distance > 100 then
				state.tick = (state.tick or 0) + 1
				if state.tick % (distance > 250 and 3 or 2) ~= 0 then return end
			end
		end
	end
	if not AvatarSkins.drive(state, character) then return end
	state.driven = true
	AvatarSkins.hideBody(state, character)
	pcall(AvatarSkins.grip, state, character)
	pcall(AvatarSkins.followMounts, state, character)
	if not state.remote then AvatarSkins.firstPerson(state, character) end
end

function AvatarSkins.bind(state, enabled)
	if enabled == state.bound then return end
	state.bound = enabled
	local runService = state.context.runService
	if not enabled then
		pcall(runService.UnbindFromRenderStep, runService, "PulseSkinStep")
		if state.ragdollConnection then state.ragdollConnection:Disconnect(); state.ragdollConnection = nil end
		return
	end
	local priority = state.context.environment.Enum.RenderPriority.Camera.Value + 2
	runService:BindToRenderStep("PulseSkinStep", priority, function()
		if not state.alive then return end
		if not pcall(AvatarSkins.step, state) then state.links = nil end
	end)
	local added = state.context.workspace.DescendantAdded
	if added then state.ragdollConnection = added:Connect(function(object) AvatarSkins.watchRagdoll(state, object) end) end
end

function AvatarSkins.stop(state, suppressNotify)
	state.token += 1
	AvatarSkins.bind(state, false)
	AvatarSkins.showBody(state)
	AvatarSkins.restoreGrips(state)
	AvatarSkins.restoreMounts(state)
	for ragdoll, corpse in state.corpses do AvatarSkins.freeCorpse(corpse); state.corpses[ragdoll] = nil end
	state.death, state.ragdolls = nil, {}
	if state.bodyConnection then pcall(function() state.bodyConnection:Disconnect() end); state.bodyConnection = nil end
	state.bodyCharacter = nil
	local model = state.model
	state.model, state.character, state.links, state.joints, state.ground = nil, nil, nil, nil, nil
	state.baseDesc, state.public, state.near, state.legOn = nil, nil, nil, nil
	if model then pcall(function() model:Destroy() end); if not suppressNotify then AvatarSkins.notify(state) end end
end

function AvatarSkins.wear(state, description)
	if not state.alive then return false, "cancelled" end
	state.token += 1
	local token = state.token
	local context, environment = state.context, state.context.environment
	local ok, model = pcall(context.players.CreateHumanoidModelFromDescription, context.players, description, environment.Enum.HumanoidRigType.R15)
	if token ~= state.token or not state.alive then
		if ok and model then pcall(function() model:Destroy() end) end
		return false, "cancelled"
	end
	if not ok or not model then return false, "Couldn't build: " .. tostring(model) end
	local prepared, joints, ground, parts = pcall(AvatarSkins.prepare, state, model)
	if not prepared or not ground then
		pcall(function() model:Destroy() end)
		return false, "Couldn't rig: " .. tostring(joints)
	end
	local previous = state.model
	AvatarSkins.showBody(state)
	AvatarSkins.restoreGrips(state)
	AvatarSkins.restoreMounts(state)
	state.model, state.joints, state.ground, state.modelParts = model, joints, ground, parts
	state.character, state.links, state.near = nil, nil, nil
	if previous then pcall(function() previous:Destroy() end) end
	AvatarSkins.bind(state, true)
	return true
end

function AvatarSkins.headless(model, enabled)
	local head = model and model:FindFirstChild("Head")
	if not head then return end
	local objects = {head}
	for _, child in head:GetChildren() do if child:IsA("Decal") then table.insert(objects, child) end end
	for _, object in objects do pcall(function()
		local original = object:GetAttribute("PulseHL")
		if enabled then
			if original == nil then object:SetAttribute("PulseHL", object.Transparency) end
			object.Transparency = 1
			return
		end
		if original ~= nil then object.Transparency = original; object:SetAttribute("PulseHL", nil) end
	end) end
end

function AvatarSkins.cosmetics(state)
	local callback = rawget(state.context.environment.getgenv(), "__pulseCosMine")
	if type(callback) ~= "function" then return false, false end
	local ok, leg, head = pcall(callback)
	return ok and leg == true, ok and head == true
end

function AvatarSkins.dress(state, description)
	state.baseDesc = description
	local leg, head = AvatarSkins.cosmetics(state)
	local modelDescription = description
	if leg then
		local ok, cloned = pcall(function() return description:Clone() end)
		if ok and cloned then
			modelDescription = cloned
			pcall(function() cloned.RightLeg = 139607718 end)
		else
			leg = false
		end
	end
	local ok, reason = AvatarSkins.wear(state, modelDescription)
	if ok then state.legOn = leg; AvatarSkins.headless(state.model, head) end
	return ok, reason
end

function AvatarSkins.applyBundle(state, value)
	local id = tonumber(value)
	if not id then return false, "Bad bundle id" end
	if not state.context.player.Character then return false, "No character" end
	local description, name = AvatarSkins.bundle(state.context, id)
	if not description then return false, tostring(name) end
	local ok, reason = AvatarSkins.dress(state, description)
	if not ok then return false, tostring(reason) end
	state.public = {b = id}
	state.config.skin = {kind = "bundle", id = tostring(id), name = name, desc = AvatarSkins.serialize(description)}
	state.save()
	return true, tostring(name)
end

function AvatarSkins.applyUser(state, value)
	local query = tostring(value or ""):gsub("^%s+", ""):gsub("%s+$", "")
	if query == "" then return false, "Enter a username" end
	if not state.context.player.Character then return false, "No character" end
	local ok, description, name, id = pcall(AvatarSkins.user, state.context, query)
	if not ok or not description then return false, "Player not found" end
	local dressed, reason = AvatarSkins.dress(state, description)
	if not dressed then return false, tostring(reason) end
	state.public = tonumber(id) and {u = tonumber(id)} or nil
	state.config.skin = {kind = "user", id = query, name = name, uid = tonumber(id), desc = AvatarSkins.serialize(description)}
	state.save()
	return true, tostring(name)
end

function AvatarSkins.applySaved(state, saved)
	if type(saved) ~= "table" then return false end
	local description = AvatarSkins.deserialize(state.context.environment, saved.desc)
	if description then
		local ok = AvatarSkins.dress(state, description)
		if ok then
			local id = tonumber(saved.kind == "bundle" and saved.id or saved.uid or saved.id)
			state.public = id and (saved.kind == "bundle" and {b = id} or {u = id}) or nil
			state.config.skin = saved
			state.save()
			return true
		end
	end
	if saved.kind == "user" then return AvatarSkins.applyUser(state, saved.id) end
	if saved.id then return AvatarSkins.applyBundle(state, saved.id) end
	return false
end

function AvatarSkins.install(context, config, save)
	local state = {context = context, config = config, save = save, token = 0, alive = true, bound = false,
		hidden = {}, grips = {}, mounts = {}, corpses = {}, ragdolls = {}}
	local globals = context.environment.getgenv()
	local model = function() return state.model and state.links and state.model.Parent and state.model or nil end
	local mine = function() return state.model and state.public or nil end
	local mountOriginal = function(object)
		local original = AvatarSkins.mountOriginal(state, object)
		if original then return original end
		local remote = rawget(globals, "__pulseRemoteSkin")
		for _, entry in remote and remote.list or {} do
			original = AvatarSkins.mountOriginal(entry, object)
			if original then return original end
		end
	end
	local cosmetics = function()
		context.environment.task.spawn(function()
			if not state.alive or not state.model or not state.baseDesc then return end
			local leg, head = AvatarSkins.cosmetics(state)
			if leg ~= (state.legOn == true) then AvatarSkins.dress(state, state.baseDesc); return end
			AvatarSkins.headless(state.model, head)
		end)
	end
	globals.__pulseSkinModel, globals.__pulseSkinMine, globals.__pulseMountOrig, globals.__pulseSkinCos = model, mine, mountOriginal, cosmetics
	return state, function()
		state.alive = false
		AvatarSkins.stop(state)
		if globals.__pulseSkinModel == model then globals.__pulseSkinModel = nil end
		if globals.__pulseSkinMine == mine then globals.__pulseSkinMine = nil end
		if globals.__pulseMountOrig == mountOriginal then globals.__pulseMountOrig = nil end
		if globals.__pulseSkinCos == cosmetics then globals.__pulseSkinCos = nil end
	end
end

end -- AvatarSkins private scope

local RemoteAvatarSkins = {}

function RemoteAvatarSkins.bind(state)
	local enabled = next(state.list) ~= nil
	if enabled == state.bound then return end
	state.bound = enabled
	local context, environment = state.context, state.context.environment
	if not enabled then
		pcall(context.runService.UnbindFromRenderStep, context.runService, "PulseRSkinStep")
		if state.ragdollConnection then state.ragdollConnection:Disconnect(); state.ragdollConnection = nil end
		state.ragdolls = {}
		return
	end
	local priority = environment.Enum.RenderPriority.Camera.Value + 3
	context.runService:BindToRenderStep("PulseRSkinStep", priority, function()
		for _, entry in state.list do if not pcall(AvatarSkins.step, entry) then entry.links = nil end end
	end)
	state.ragdollConnection = context.workspace.DescendantAdded:Connect(function(object) AvatarSkins.watchRagdoll(state, object) end)
end

function RemoteAvatarSkins.clear(state, player)
	local entry = state.list[player]
	if not entry then return end
	state.list[player] = nil
	entry.alive = false
	entry.generation += 1
	AvatarSkins.stop(entry, true)
	RemoteAvatarSkins.bind(state)
	AvatarSkins.notify(entry)
end

function RemoteAvatarSkins.description(state, selection)
	local key = selection.u and "u" .. selection.u or "b" .. selection.b
	if state.descriptions[key] then return state.descriptions[key] end
	local description
	if selection.u then
		local ok, value = pcall(state.context.players.GetHumanoidDescriptionFromUserId, state.context.players, selection.u)
		if ok then description = value end
	else
		local ok, value = pcall(AvatarSkins.bundle, state.context, selection.b)
		if ok then description = value end
	end
	if description then state.descriptions[key] = description end
	return description
end

function RemoteAvatarSkins.build(state, player, entry, selection, leg)
	entry.token += 1
	local token = entry.token
	local description = RemoteAvatarSkins.description(state, selection)
	if token ~= entry.token or state.list[player] ~= entry then return end
	if not description then entry.failAt = state.context.environment.os.clock(); return end
	if leg then
		local ok, cloned = pcall(function() return description:Clone() end)
		if ok and cloned then
			description = cloned
			pcall(function() cloned.RightLeg = 139607718 end)
		end
	end
	local context, environment = state.context, state.context.environment
	local ok, model = pcall(context.players.CreateHumanoidModelFromDescription, context.players, description, environment.Enum.HumanoidRigType.R15)
	if token ~= entry.token or state.list[player] ~= entry then
		if ok and model then pcall(function() model:Destroy() end) end
		return
	end
	if not ok or not model then entry.failAt = environment.os.clock(); return end
	local prepared, joints, ground, parts = pcall(AvatarSkins.prepare, entry, model)
	if not prepared or not ground then
		pcall(function() model:Destroy() end)
		entry.failAt = environment.os.clock()
		return
	end
	model.Name = "PulseRemoteSkin"
	AvatarSkins.showBody(entry)
	AvatarSkins.restoreGrips(entry)
	AvatarSkins.restoreMounts(entry)
	if entry.model then pcall(function() entry.model:Destroy() end) end
	entry.model, entry.joints, entry.ground, entry.modelParts = model, joints, ground, parts
	entry.character, entry.links = nil, nil
	AvatarSkins.headless(model, entry.headless)
	entry.headlessApplied = entry.headless
end

function RemoteAvatarSkins.set(state, player, payload, leg, headless)
	local context, environment = state.context, state.context.environment
	if environment.typeof(player) ~= "Instance" or player == context.player then return end
	local user = type(payload) == "table" and tonumber(payload.u) or nil
	local bundle = type(payload) == "table" and tonumber(payload.b) or nil
	if user and (user < 1 or user >= 10000000000000) then user = nil end
	if bundle and (bundle < 1 or bundle >= 10000000000000) then bundle = nil end
	if not user and not bundle then RemoteAvatarSkins.clear(state, player); return end
	local selection = user and {u = math.floor(user)} or {b = math.floor(bundle)}
	local key = (user and "u" .. selection.u or "b" .. selection.b) .. (leg and "|k" or "")
	local entry = state.list[player]
	if entry and entry.key == key then
		entry.headless = headless == true
		if entry.model and entry.headlessApplied ~= entry.headless then
			AvatarSkins.headless(entry.model, entry.headless)
			entry.headlessApplied = entry.headless
		end
		if entry.model or entry.busy or entry.failAt and environment.os.clock() - entry.failAt < 30 then return end
	end
	if entry then
		AvatarSkins.stop(entry, true)
	else
		local entryContext = table.clone(context)
		entryContext.player = player
		entry = {context = entryContext, player = player, remote = true, registry = state, alive = true, bound = false, token = 0,
			generation = 0, hidden = {}, grips = {}, mounts = {}, corpses = {}, ragdolls = {}}
		state.list[player] = entry
	end
	entry.key, entry.headless, entry.failAt = key, headless == true, nil
	entry.generation += 1
	local generation = entry.generation
	entry.busy = true
	RemoteAvatarSkins.bind(state)
	environment.task.spawn(function()
		if entry.generation ~= generation or state.list[player] ~= entry then return end
		pcall(RemoteAvatarSkins.build, state, player, entry, selection, leg)
		if entry.generation == generation then entry.busy = false end
	end)
end

function RemoteAvatarSkins.install(context)
	local state = {context = context, list = {}, descriptions = {}, ragdolls = {}, bound = false}
	state.set = function(player, payload, leg, headless) RemoteAvatarSkins.set(state, player, payload, leg, headless) end
	state.clear = function(player) RemoteAvatarSkins.clear(state, player) end
	state.clearAll = function() for player in state.list do RemoteAvatarSkins.clear(state, player) end end
	state.modelOf = function(player) local entry = state.list[player]; return entry and entry.model or nil end
	state.liveModel = function(player)
		local entry = state.list[player]
		if not entry or not entry.model or not entry.links or not entry.model.Parent or entry.character ~= player.Character then return nil end
		return entry.model
	end
	local globals = context.environment.getgenv()
	globals.__pulseRemoteSkin = state
	local removing
	if context.players.PlayerRemoving then removing = context.connect(context.players.PlayerRemoving, state.clear) end
	return state, function()
		if removing then pcall(function() removing:Disconnect() end) end
		state.clearAll()
		if globals.__pulseRemoteSkin == state then globals.__pulseRemoteSkin = nil end
	end
end

local AnimationFeature = {}
do -- Keep module-private locals out of the main chunk's register budget.

local ANIMATION_SLOTS = {
	idle = "IdleAnimation", walk = "WalkAnimation", run = "RunAnimation", jump = "JumpAnimation",
	fall = "FallAnimation", climb = "ClimbAnimation", swim = "SwimAnimation", swimidle = "SwimAnimation",
}
local ANIMATION_TYPES = {IdleAnimation = true, WalkAnimation = true, RunAnimation = true, JumpAnimation = true,
	FallAnimation = true, ClimbAnimation = true, SwimAnimation = true}
local ANIMATION_ORDER = {"IdleAnimation", "WalkAnimation", "RunAnimation", "JumpAnimation", "FallAnimation", "ClimbAnimation", "SwimAnimation"}

function AnimationFeature.defaults(saved)
	saved = type(saved) == "table" and saved or {}
	return {
		favorites = type(saved.favorites) == "table" and saved.favorites or {}, lastBundle = saved.lastBundle,
		speed = tonumber(saved.speed) or 1, emoteSpeed = tonumber(saved.emoteSpeed) or 1,
		mix = type(saved.mix) == "table" and saved.mix or {}, mixSaves = type(saved.mixSaves) == "table" and saved.mixSaves or {},
		skinMix = type(saved.skinMix) == "table" and saved.skinMix or {}, skin = type(saved.skin) == "table" and saved.skin or nil,
		lastMode = saved.lastMode or "bundle", toggleKey = type(saved.toggleKey) == "string" and saved.toggleKey or "RightShift",
		autoLoad = saved.autoLoad ~= false, emoteHold = saved.emoteHold == true, animPreview = saved.animPreview ~= false,
	}
end

function AnimationFeature.load(context, path)
	local ok, value = pcall(function()
		if not context.environment.isfile(path) then return nil end
		return context.http:JSONDecode(context.environment.readfile(path))
	end)
	if ok and type(value) == "table" then return value end
	return {}
end

function AnimationFeature.write(state, path, value)
	pcall(function()
		local environment = state.context.environment
		if not environment.isfolder("BundleAnimations") then environment.makefolder("BundleAnimations") end
		environment.writefile(path, state.context.http:JSONEncode(value))
	end)
end

function AnimationFeature.parseId(value)
	if not value then return nil end
	value = tostring(value)
	return tonumber(value:match("bundles/(%d+)") or value:match("(%d%d%d%d+)") or value:match("(%d+)"))
end

function AnimationFeature.assetAnimations(model, wanted)
	local result = {}
	local animate = model:FindFirstChild("Animate")
	if not animate then return result end
	for _, folder in animate:GetChildren() do
		local kind = ANIMATION_SLOTS[folder.Name:lower()]
		if not kind or wanted and not wanted[kind] then continue end
		for _, animation in folder:GetChildren() do
			if not animation:IsA("Animation") or animation.AnimationId == "" then continue end
			result[kind] = result[kind] or {}
			result[kind][animation.Name] = animation.AnimationId
		end
	end
	return result
end

function AnimationFeature.bundle(state, id, progress)
	local context, environment = state.context, state.context.environment
	id = tonumber(id)
	if not id then return nil end
	local cached = state.cache[tostring(id)]
	if type(cached) == "table" then return cached, state.details[id] end

	local ok, details = pcall(context.avatar.GetItemDetails, context.avatar, id, environment.Enum.AvatarItemType.Bundle)
	if not ok or type(details) ~= "table" or type(details.BundledItems) ~= "table" then return nil end
	state.details[id] = details
	local assets, wanted = {}, {}
	for _, item in details.BundledItems do
		local kind = tostring(item.AssetType)
		if not item.Id or not ANIMATION_TYPES[kind] then continue end
		table.insert(assets, {kind = kind, id = item.Id})
		wanted[kind] = true
	end

	local result
	local description = environment.Instance.new("HumanoidDescription")
	for _, asset in assets do pcall(function() description[asset.kind] = tonumber(asset.id) end) end
	local created, model = pcall(context.players.CreateHumanoidModelFromDescription, context.players, description, environment.Enum.HumanoidRigType.R15)
	description:Destroy()
	if created and model then
		pcall(function() result = AnimationFeature.assetAnimations(model, wanted) end)
		pcall(function() model:Destroy() end)
	end
	if result and next(result) and progress then pcall(progress, #assets, #assets) end
	if not result or not next(result) then
		result = {}
		for index, asset in assets do
			pcall(function()
				for _, model in environment.game:GetObjects("rbxassetid://" .. asset.id) do
					for _, animation in model:GetDescendants() do
						if not animation:IsA("Animation") then continue end
						result[asset.kind] = result[asset.kind] or {}
						result[asset.kind][animation.Name] = animation.AnimationId
					end
				end
			end)
			if progress then pcall(progress, index, #assets) end
			environment.task.wait()
		end
	end
	if not next(result) then return nil, details end
	state.cache[tostring(id)] = result
	AnimationFeature.write(state, "BundleAnimations/anims_cache.json", state.cache)
	return result, details
end

function AnimationFeature.stop(state)
	state.token += 1
	local emote = state.gameEmote
	state.gameEmote = nil
	if emote then pcall(function() emote:Stop(0) end) end
	for _, connection in state.connections do pcall(function() connection:Disconnect() end) end
	table.clear(state.connections)
	state.toolSync, state.resume = nil, nil
	for _, track in state.tracks do pcall(function() track:Stop(0) end) end
	table.clear(state.tracks)
	state.current = nil
	local backup = state.backup
	if not backup then return end
	for animation, id in backup.ids do pcall(function() if animation.Parent then animation.AnimationId = id end end) end
	pcall(function() if backup.animate.Parent then backup.animate.Disabled = backup.disabled end end)
	state.backup = nil
end

function AnimationFeature.backup(state, animate)
	if not animate then return end
	local backup = {animate = animate, disabled = animate.Disabled, ids = {}}
	state.backup = backup
	animate.Disabled = true
	for _, folder in animate:GetChildren() do
		if not ANIMATION_SLOTS[folder.Name:lower()] then continue end
		for _, animation in folder:GetChildren() do
			if not animation:IsA("Animation") then continue end
			local id = animation.AnimationId
			if id == "" then id = animation:GetAttribute("PulseOrigAnim") or "" else animation:SetAttribute("PulseOrigAnim", id) end
			backup.ids[animation] = id
			animation.AnimationId = ""
		end
	end
end

function AnimationFeature.track(state, animator, id, priority, looped)
	local digits = tostring(id or ""):match("%d+")
	if not digits or digits == "0" then return nil end
	local animation = state.context.environment.Instance.new("Animation")
	animation.AnimationId = "rbxassetid://" .. digits
	local ok, track = pcall(animator.LoadAnimation, animator, animation)
	if not ok or not track then return nil end
	track.Looped, track.Priority = looped ~= false, priority
	return track
end

function AnimationFeature.choose(animations, kind, preferred)
	local choices = animations[kind]
	if type(choices) ~= "table" then return nil end
	if preferred and choices[preferred] then return choices[preferred] end
	for _, id in choices do return id end
end

function AnimationFeature.play(state, track, fade, speed)
	if not track then return end
	if state.current ~= track then
		if state.current then pcall(function() state.current:Stop(fade or 0.15) end) end
		state.current = track
		pcall(function() track:Play(fade or 0.15) end)
	end
	if not speed then return end
	state.baseSpeed = speed
	pcall(function() track:AdjustSpeed(speed * (state.speedMultiplier or state.config.speed)) end)
end

function AnimationFeature.refreshSpeed(state)
	if state.current then pcall(function() state.current:AdjustSpeed(state.baseSpeed * state.speedMultiplier) end) end
end

function AnimationFeature.setSpeed(state, value)
	state.speedMultiplier = tonumber(value) or 1
	AnimationFeature.refreshSpeed(state)
end

function AnimationFeature.stopGameEmote(state, fade)
	local track = state.gameEmote
	state.gameEmote = nil
	if track then pcall(function() track:Stop(fade or 0.2) end) end
end

function AnimationFeature.gameEmoteId(state, animate, animator, input)
	local environment = state.context.environment
	local id
	if environment.typeof(input) == "Instance" and input:IsA("Animation") then id = input.AnimationId:match("%d+") end
	if type(input) == "string" and not tonumber(input) then
		local folder = animate and animate:FindFirstChild(input)
		local animation = folder and folder:FindFirstChildOfClass("Animation")
		return animation and animation.AnimationId:match("%d+") or nil
	end
	if not id and tonumber(input) then id = tostring(tonumber(input)) end
	if not id then return nil end
	if state.cache["e" .. id] then return state.cache["e" .. id] end

	local preview = AnimationFeature.track(state, animator, id, environment.Enum.AnimationPriority.Action4, false)
	if preview then
		for _ = 1, 8 do
			if preview.Length > 0 then
				state.cache["e" .. id] = id
				pcall(function() preview:Destroy() end)
				return id
			end
			environment.task.wait(0.05)
		end
		pcall(function() preview:Destroy() end)
	end
	return AnimationFeature.emoteId(state, id)
end

function AnimationFeature.playGameEmote(state, animate, animator, token, input)
	if token ~= state.token then return false end
	local id = AnimationFeature.gameEmoteId(state, animate, animator, input)
	if not id or token ~= state.token then return false end
	AnimationFeature.stopGameEmote(state, 0)
	local environment = state.context.environment
	local animation = environment.Instance.new("Animation")
	animation.AnimationId = "rbxassetid://" .. id
	local ok, track = pcall(animator.LoadAnimation, animator, animation)
	if not ok or not track then return false end
	track.Priority = environment.Enum.AnimationPriority.Action4
	state.gameEmote = track
	if state.current then pcall(function() state.current:Stop(0.15) end) end
	state.current, state.pose = nil, "Emote"
	pcall(function() track:Play(0.1) end)
	track.Stopped:Once(function()
		if state.gameEmote ~= track then return end
		state.gameEmote = nil
		if token == state.token and state.resume then state.resume() end
	end)
	return true
end

function AnimationFeature.gameData(state)
	if state.gameSync ~= nil then return state.gameSync or nil end
	local context = state.context
	local ok, result = pcall(function()
		local database = context.storage:WaitForChild("Database", 5)
		return context.environment.require(database:WaitForChild("Sync", 5))
	end)
	state.gameSync = ok and type(result) == "table" and result or false
	return state.gameSync or nil
end

function AnimationFeature.gameCommand(state, character, humanoid, animate, play, token, command)
	if token ~= state.token or type(command) ~= "string" then return end
	if animate and animate.Parent and not animate.Disabled then return end
	local context, environment = state.context, state.context.environment
	local sync = AnimationFeature.gameData(state)
	local backpack = context.player:FindFirstChildOfClass("Backpack")
	local toys = backpack and backpack:FindFirstChild("Toys")
	local owned = toys and toys:FindFirstChild(command)
	if owned or sync and type(sync.Toys) == "table" and sync.Toys[command] ~= nil then
		local tool
		if owned then
			local remotes = context.storage:FindFirstChild("Remotes")
			local extras = remotes and remotes:FindFirstChild("Extras")
			local replicate = extras and extras:FindFirstChild("ReplicateToy")
			if replicate then pcall(function() tool = replicate:InvokeServer(command) end) end
			environment.task.wait()
		else
			tool = backpack and backpack:FindFirstChild(command) or character:FindFirstChild(command)
		end
		if environment.typeof(tool) ~= "Instance" or not tool:IsA("Tool") or token ~= state.token then return end
		if tool.Parent ~= character then pcall(function() tool.Parent = backpack end); environment.task.wait() end
		pcall(humanoid.EquipTool, humanoid, tool)
		return
	end
	local emote = sync and type(sync.Emotes) == "table" and sync.Emotes[command]
	if type(emote) ~= "table" then return end
	if type(emote.Command) == "string" and animate and animate:FindFirstChild(emote.Command) then play(emote.Command); return end
	if emote.AnimationID then play(tostring(emote.AnimationID)) end
end

function AnimationFeature.bindGameEmotes(state, character, humanoid, animate, animator, token)
	local context, environment = state.context, state.context.environment
	local function play(value) return AnimationFeature.playGameEmote(state, animate, animator, token, value) end
	local bindable = animate and animate:FindFirstChild("PlayEmote")
	if bindable and bindable:IsA("BindableFunction") then
		local previous
		pcall(function() previous = bindable.OnInvoke end)
		local assigned = pcall(function() bindable.OnInvoke = play end)
		if assigned then table.insert(state.connections, {Disconnect = function()
			pcall(function() if bindable.OnInvoke == play then bindable.OnInvoke = previous end end)
		end}) end
	end
	local remotes = context.storage and context.storage:FindFirstChild("Remotes")
	local misc = remotes and remotes:FindFirstChild("Misc")
	local event = misc and misc:FindFirstChild("PlayEmote")
	if event and event:IsA("BindableEvent") then
		table.insert(state.connections, event.Event:Connect(function(command)
			environment.task.spawn(AnimationFeature.gameCommand, state, character, humanoid, animate, play, token, command)
		end))
	end
	if context.player and context.player.Chatted then table.insert(state.connections, context.player.Chatted:Connect(function(message)
		if type(message) ~= "string" or token ~= state.token then return end
		local command = message:match("^/e%s+(%S+)") or message:match("^/emote%s+(%S+)")
		if not command then return end
		local sync = AnimationFeature.gameData(state)
		local emote = sync and type(sync.Emotes) == "table" and sync.Emotes[command]
		if type(emote) == "table" and emote.AnimationID then environment.task.spawn(play, tostring(emote.AnimationID)); return end
		if animate and animate:FindFirstChild(command) then environment.task.spawn(play, command) end
	end)) end
end

function AnimationFeature.bindTools(state, character, humanoid, animate, animator, token)
	local environment = state.context.environment
	local priority = environment.Enum.AnimationPriority
	local fallback = humanoid.RigType == environment.Enum.HumanoidRigType.R6
		and {toolnone = "182393478", toolslash = "129967390", toollunge = "129967478"}
		or {toolnone = "507768375", toolslash = "522635514", toollunge = "522638767"}
	local function animationId(name)
		local folder = animate and animate:FindFirstChild(name)
		local animation = folder and folder:FindFirstChildOfClass("Animation")
		return animation and animation.AnimationId:match("%d+") or fallback[name]
	end
	local hold = AnimationFeature.track(state, animator, animationId("toolnone"), priority.Action, true)
	state.tracks.toolnone = hold
	local own = {}
	for _, track in state.tracks do own[track] = true end
	local tool, action, toolConnections = nil, nil, {}
	local function updateWeight()
		if not hold or token ~= state.token then return end
		local other = false
		for _, track in animator:GetPlayingAnimationTracks() do
			if own[track] or track == state.gameEmote or not track.IsPlaying or track.WeightTarget <= 0.05 then continue end
			if track.Priority ~= priority.Core and track.Priority.Value >= priority.Action.Value then other = true; break end
		end
		pcall(function() hold:AdjustWeight(other and 0.001 or 1, 0.12) end)
	end
	local function actionRequested(target)
		if token ~= state.token then return end
		local request = target:FindFirstChild("toolanim")
		if not request or not request:IsA("StringValue") then return end
		local value = request.Value
		pcall(function() request:Destroy() end)
		local name = value == "Slash" and "toolslash" or value == "Lunge" and "toollunge"
		if not name then return end
		if action then own[action] = nil; pcall(function() action:Stop(0) end) end
		action = AnimationFeature.track(state, animator, animationId(name), priority.Action2, false)
		if not action then return end
		own[action], state.tracks.toolAct = true, action
		pcall(function() action:Play(0.05) end)
	end
	local function disconnectTool()
		for _, connection in toolConnections do pcall(function() connection:Disconnect() end) end
		table.clear(toolConnections)
	end
	local function synchronize()
		if token ~= state.token then return end
		local current = character:FindFirstChildOfClass("Tool")
		if current ~= tool then
			disconnectTool()
			tool = current
			if tool then
				actionRequested(tool)
				table.insert(toolConnections, tool.ChildAdded:Connect(function(child)
					if child.Name == "toolanim" then environment.task.defer(actionRequested, tool) end
				end))
			end
		end
		if not hold then return end
		if tool and not hold.IsPlaying then pcall(function() hold:Play(0.1) end); updateWeight(); return end
		if not tool and hold.IsPlaying then pcall(function() hold:Stop(0.1) end) end
	end
	state.toolSync = synchronize
	table.insert(state.connections, {Disconnect = disconnectTool})
	for _, signal in {character.ChildAdded, character.ChildRemoved} do
		if not signal then continue end
		table.insert(state.connections, signal:Connect(function(child)
			if child:IsA("Tool") then environment.task.defer(synchronize) end
		end))
	end
	if animator.AnimationPlayed then table.insert(state.connections, animator.AnimationPlayed:Connect(function(track)
		if token ~= state.token or own[track] or not tool then return end
		if track.Priority == priority.Core or track.Priority.Value < priority.Action.Value then return end
		updateWeight()
		track.Stopped:Once(function()
			environment.task.delay(0.05, updateWeight)
			environment.task.delay(0.3, updateWeight)
		end)
	end)) end
	synchronize()
end

function AnimationFeature.applyTracks(state, character, animations)
	AnimationFeature.stop(state)
	local humanoid = character and character:FindFirstChildOfClass("Humanoid")
	local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
	if not animator then return false end
	local environment = state.context.environment
	local priority = environment.Enum.AnimationPriority
	local definitions = {
		{"idle", "IdleAnimation", "Animation1", priority.Idle}, {"walk", "WalkAnimation", nil, priority.Movement},
		{"run", "RunAnimation", nil, priority.Movement}, {"jump", "JumpAnimation", nil, priority.Movement, false},
		{"fall", "FallAnimation", nil, priority.Movement}, {"climb", "ClimbAnimation", nil, priority.Movement},
		{"swim", "SwimAnimation", "Swim", priority.Movement}, {"swimidle", "SwimAnimation", "SwimIdle", priority.Idle},
	}
	for _, definition in definitions do
		local id = AnimationFeature.choose(animations, definition[2], definition[3])
		state.tracks[definition[1]] = AnimationFeature.track(state, animator, id, definition[4], definition[5])
	end
	local tracks = state.tracks
	if not tracks.idle and not tracks.walk and not tracks.run then return false end
	local animate = character:FindFirstChild("Animate")
	if animate then pcall(AnimationFeature.backup, state, animate) end
	for _, track in animator:GetPlayingAnimationTracks() do pcall(function() track:Stop(0) end) end
	state.pose = "Standing"
	local token = state.token
	local function movementSpeed()
		local root = humanoid.RootPart
		if not root then return 0 end
		local velocity = root.AssemblyLinearVelocity
		return math.sqrt(velocity.X * velocity.X + velocity.Z * velocity.Z)
	end
	local function running(speed)
		if token ~= state.token then return end
		if speed > 0.5 then
			AnimationFeature.stopGameEmote(state, 0.1)
			state.pose = "Running"
			AnimationFeature.play(state, speed > 9 and tracks.run or tracks.walk or tracks.run, 0.15, speed / 16)
			return
		end
		if state.gameEmote or state.pose == "Jumping" or state.pose == "FreeFall" then return end
		state.pose = "Standing"
		AnimationFeature.play(state, tracks.idle, 0.2, 1)
	end
	local function connect(signal, callback)
		if signal then table.insert(state.connections, signal:Connect(callback)) end
	end
	state.resume = function() running(movementSpeed()) end
	AnimationFeature.bindGameEmotes(state, character, humanoid, animate, animator, token)
	AnimationFeature.bindTools(state, character, humanoid, animate, animator, token)
	connect(humanoid.Running, running)
	connect(humanoid.Jumping, function()
		if token ~= state.token then return end
		AnimationFeature.stopGameEmote(state, 0.1)
		state.pose = "Jumping"
		AnimationFeature.play(state, tracks.jump or tracks.fall, 0.1, 1)
	end)
	connect(humanoid.FreeFalling, function(active)
		if token ~= state.token then return end
		if active then
			AnimationFeature.stopGameEmote(state, 0.1)
			state.pose = "FreeFall"
			AnimationFeature.play(state, tracks.fall or tracks.jump, 0.25, 1)
			return
		end
		state.pose = "Landed"
		running(movementSpeed())
	end)
	connect(humanoid.Climbing, function(speed)
		if token ~= state.token then return end
		AnimationFeature.stopGameEmote(state, 0.1)
		state.pose = "Climbing"
		AnimationFeature.play(state, tracks.climb, 0.15, speed / 5)
	end)
	connect(humanoid.Swimming, function(speed)
		if token ~= state.token then return end
		state.pose = "Swimming"
		AnimationFeature.play(state, math.abs(speed or 0) > 1 and tracks.swim or tracks.swimidle or tracks.swim, 0.2, 1)
	end)
	connect(humanoid.Seated, function(active) if not active then running(0) end end)
	connect(humanoid.StateChanged, function(_, nextState)
		if token ~= state.token or state.pose ~= "Jumping" and state.pose ~= "FreeFall" then return end
		local states = environment.Enum.HumanoidStateType
		if nextState ~= states.Landed and nextState ~= states.Running and nextState ~= states.RunningNoPhysics then return end
		state.pose = "Landed"
		running(movementSpeed())
	end)
	AnimationFeature.play(state, tracks.idle, 0.2, 1)
	environment.task.spawn(function()
		while state.alive and token == state.token do
			environment.task.wait(0.4)
			if token ~= state.token or not state.alive then return end
			if animate and animate.Parent then animate.Disabled = true end
			if state.current and state.current.Looped and not state.current.IsPlaying then pcall(function() state.current:Play(0.1) end) end
			if state.toolSync then pcall(state.toolSync) end
		end
	end)
	environment.task.spawn(function()
		while state.alive and token == state.token do
			environment.task.wait(0.1)
			if token ~= state.token or not state.alive then return end
			if not state.gameEmote and state.pose ~= "Jumping" and state.pose ~= "FreeFall" then pcall(running, movementSpeed()) end
		end
	end)
	return true
end

function AnimationFeature.save(state)
	AnimationFeature.write(state, "BundleAnimations/config.json", state.config)
end

function AnimationFeature.enableAutoLoad(state)
	if state.config.autoLoad then return end
	state.config.autoLoad = true
	local setter = state.context.setters and state.context.setters["Free anims/bundles/Auto-load on respawn"]
	if setter then pcall(setter, true) end
end

function AnimationFeature.resetTracks(state)
	AnimationFeature.stop(state)
	local character = state.context.player.Character
	local animate = character and character:FindFirstChild("Animate")
	if not animate then return end
	pcall(function()
		animate.Disabled = true
		state.context.environment.task.wait(0.1)
		animate.Disabled = false
	end)
end

function AnimationFeature.applyBundle(state, value, progress)
	local id = AnimationFeature.parseId(value)
	local character = state.context.player.Character
	if not character or not character:FindFirstChildOfClass("Humanoid") then return false, "No character" end
	local animations, details = AnimationFeature.bundle(state, id, progress)
	if not animations then return false, "Failed to load bundle animations (ID: " .. tostring(id) .. ")" end
	if not AnimationFeature.applyTracks(state, character, animations) then return false, "Couldn't apply (no Animator)" end
	state.config.lastBundle, state.config.lastMode = tostring(id), "bundle"
	AnimationFeature.enableAutoLoad(state)
	AnimationFeature.save(state)
	return true, "Applied (visible to all): " .. (details and details.Name or "ID " .. id)
end

function AnimationFeature.applyMix(state)
	local character = state.context.player.Character
	if not character or not character:FindFirstChildOfClass("Humanoid") then return false, "No character" end
	local assigned = false
	for _, kind in ANIMATION_ORDER do if state.config.mix[kind] then assigned = true; break end end
	if not assigned then return false, "Assign at least one slot first (tap SET)" end
	local animations = AnimationFeature.assetAnimations(character)
	local cache = {}
	for _, kind in ANIMATION_ORDER do
		local slot = state.config.mix[kind]
		local id = slot and tonumber(slot.id)
		if not id then continue end
		if cache[id] == nil then cache[id] = AnimationFeature.bundle(state, id) or false end
		if cache[id] and cache[id][kind] then animations[kind] = cache[id][kind] end
	end
	if not AnimationFeature.applyTracks(state, character, animations) then return false, "Couldn't apply mix (no Animator)" end
	state.config.lastMode = "mix"
	AnimationFeature.enableAutoLoad(state)
	AnimationFeature.save(state)
	return true, "Applied mix (visible to all)"
end

function AnimationFeature.setMixSlot(state, kind, id, name)
	state.config.mix[kind] = {id = tostring(id), name = name}
	AnimationFeature.save(state)
end

function AnimationFeature.clearMixSlot(state, kind)
	state.config.mix[kind] = nil
	AnimationFeature.save(state)
end

function AnimationFeature.clearMix(state)
	state.config.mix = {}
	AnimationFeature.save(state)
	if state.config.lastMode == "mix" then state.reset() end
end

function AnimationFeature.copyMix(mix)
	local copy = {}
	for key, value in type(mix) == "table" and mix or {} do
		if type(value) == "table" then copy[key] = {id = value.id, name = value.name} end
	end
	return copy
end

function AnimationFeature.queueMix(state)
	state.mixGeneration = (state.mixGeneration or 0) + 1
	local generation = state.mixGeneration
	state.context.environment.task.delay(0.05, function()
		if not state.alive or state.mixGeneration ~= generation then return end
		if next(state.config.mix) then pcall(AnimationFeature.applyMix, state); return end
		if state.config.lastMode == "mix" then state.reset() end
	end)
end

function AnimationFeature.stopEmote(state)
	for _, connection in state.emoteConnections do pcall(function() connection:Disconnect() end) end
	table.clear(state.emoteConnections)
	if state.emote then pcall(function() state.emote:Stop(0.2) end) end
	state.emote = nil
end

function AnimationFeature.emoteId(state, value)
	local id = tostring(value or ""):match("%d+")
	if not id then return nil end
	local key = "e" .. id
	if state.cache[key] then return state.cache[key] end

	local context, environment = state.context, state.context.environment
	local character = context.player.Character
	local humanoid = character and character:FindFirstChildOfClass("Humanoid")
	local animate = character and character:FindFirstChild("Animate")
	local resolved
	if humanoid and animate then
		local previous = animate:FindFirstChild("PlayEmote")
		local proxy = environment.Instance.new("BindableFunction")
		proxy.OnInvoke = function(animation)
			if environment.typeof(animation) == "Instance" and animation:IsA("Animation") then resolved = animation.AnimationId:match("%d+") end
			return false
		end
		if previous then previous.Name = "PlayEmote_PulseHold" end
		proxy.Name, proxy.Parent = "PlayEmote", animate
		pcall(humanoid.PlayEmoteAndGetAnimTrackById, humanoid, tonumber(id))
		proxy:Destroy()
		if previous and previous.Parent then previous.Name = "PlayEmote" end
	end
	if not resolved then
		pcall(function()
			for _, model in environment.game:GetObjects("rbxassetid://" .. id) do
				local objects = model:GetDescendants()
				table.insert(objects, model)
				for _, animation in objects do
					if not animation:IsA("Animation") then continue end
					resolved = animation.AnimationId:match("%d+")
					if resolved then return end
				end
			end
		end)
	end
	if resolved then
		state.cache[key] = resolved
		AnimationFeature.write(state, "BundleAnimations/anims_cache.json", state.cache)
	end
	return resolved or id
end

function AnimationFeature.applyEmote(state, value, name)
	local character = state.context.player.Character
	local humanoid = character and character:FindFirstChildOfClass("Humanoid")
	local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
	if not animator then return false, "No character" end
	local id = AnimationFeature.emoteId(state, value)
	if not id then return false, "Couldn't load emote" end
	AnimationFeature.stopEmote(state)
	local track = AnimationFeature.track(state, animator, id, state.context.environment.Enum.AnimationPriority.Action4, true)
	if not track then return false, "Couldn't load emote" end
	state.emote = track
	pcall(function() track:Play(0.15); track:AdjustSpeed(state.config.emoteSpeed) end)
	for _, signal in {humanoid.Running, humanoid.Jumping} do
		if not signal then continue end
		table.insert(state.emoteConnections, signal:Connect(function(value)
			if state.config.emoteHold then return end
			if value == true or type(value) == "number" and value > 0.5 then AnimationFeature.stopEmote(state) end
		end))
	end
	return true, "Playing emote: " .. (name or "ID " .. id)
end

function AnimationFeature.applyConfig(state, saved)
	local restored = AnimationFeature.defaults(saved)
	for key in state.config do state.config[key] = nil end
	for key, value in restored do state.config[key] = value end
	AnimationFeature.save(state)
	AnimationFeature.setSpeed(state, state.config.speed)
	AnimationFeature.stopEmote(state)
	state.generation += 1
	local generation = state.generation
	local lastMode, lastBundle = state.config.lastMode, state.config.lastBundle
	local skin = state.config.skin
	state.context.environment.task.spawn(function()
		if not state.alive or state.generation ~= generation then return end
		if state.skin then
			AvatarSkins.stop(state.skin)
			if type(skin) == "table" then pcall(AvatarSkins.applySaved, state.skin, skin) end
		end
		if not state.alive or state.generation ~= generation then return end
		if lastMode == "mix" and next(state.config.mix) then
			pcall(AnimationFeature.applyMix, state)
		else
			if lastBundle then pcall(AnimationFeature.applyBundle, state, lastBundle)
			else AnimationFeature.resetTracks(state) end
		end
		if not state.alive or state.generation ~= generation then return end
		state.config.lastMode, state.config.lastBundle, state.config.skin = lastMode, lastBundle, skin
		AnimationFeature.save(state)
		if state.uiRefresh then pcall(state.uiRefresh) end
		if state.favRefresh then pcall(state.favRefresh) end
	end)
end

function AnimationFeature.controls(state)
	local section, context, config = state.context.section, state.context, state.config
	section:Sub("bundles")
	section:Header("Animation options")
	local speed = section:Slider({Text = "Animation Speed", Min = 0.1, Max = 3, Default = config.speed, Decimals = 2, Callback = function(value)
		config.speed = value
		AnimationFeature.setSpeed(state, value)
		AnimationFeature.save(state)
	end})
	local autoLoad = section:Toggle({Text = "Auto-load on respawn", Default = config.autoLoad, Callback = function(value)
		config.autoLoad = not not value
		AnimationFeature.save(state)
	end})
	section:Button({Text = "Reset to default animations", Callback = state.reset})
	AnimationFeature.catalog(state, "bundle")

	section:Header("Animation combo")
	local slots = {}
	for _, kind in ANIMATION_ORDER do table.insert(slots, {code = kind, label = kind:gsub("Animation$", "")}) end
	local selected, bundleId = ANIMATION_ORDER[1], ""
	section:Dropdown({Text = "Slot", Options = slots, Default = selected, NoSave = true, Callback = function(value) selected = value end})
	local native = section:LastSection()
	if native and native.Input then native:Input({Text = "Bundle ID", Live = true, Callback = function(value) bundleId = tostring(value or "") end}) end
	section:Button({Text = "Set slot", Callback = function()
		local id = AnimationFeature.parseId(bundleId)
		if not id then return end
		AnimationFeature.setMixSlot(state, selected, id, "ID " .. id)
		AnimationFeature.queueMix(state)
	end})
	section:Button({Text = "Clear slot", Callback = function()
		AnimationFeature.clearMixSlot(state, selected)
		AnimationFeature.queueMix(state)
	end})
	section:Button({Text = "Clear combo", Callback = function() AnimationFeature.clearMix(state) end})

	section:Sub("emotes")
	section:Header("Emote options")
	local emoteSpeed = section:Slider({Text = "Emote Speed", Min = 0.1, Max = 3, Default = config.emoteSpeed, Decimals = 2, Callback = function(value)
		config.emoteSpeed = value
		if state.emote then pcall(function() state.emote:AdjustSpeed(value) end) end
		AnimationFeature.save(state)
	end})
	local hold = section:Toggle({Text = "Hold (don't stop when moving)", Default = config.emoteHold, Callback = function(value)
		config.emoteHold = not not value
		AnimationFeature.save(state)
	end})
	section:Button({Text = "Stop emote", Callback = state.stopEmote})
	AnimationFeature.catalog(state, "emote")

	section:Sub("skins")
	section:Header("Skin")
	local username = ""
	native = section:LastSection()
	if native and native.Input then native:Input({Text = "Username or user ID", Live = true,
		Callback = function(value) username = tostring(value or "") end}) end
	section:Button({Text = "Wear", Callback = function()
		context.environment.task.spawn(function()
			local ok, message = AvatarSkins.applyUser(state.skin, username)
			context.window:Notify({Title = context.translation.tr("Skin"), Text = message, Kind = ok and "success" or "danger"})
		end)
	end})
	section:Button({Text = "Remove skin", Callback = state.resetSkin})
	AnimationFeature.presetControls(state)
	AnimationFeature.catalog(state, "skin")
	AnimationFeature.favoriteControls(state)
	state.uiRefresh = function()
		speed.SetSilent(config.speed)
		autoLoad.SetSilent(config.autoLoad)
		emoteSpeed.SetSilent(config.emoteSpeed)
		hold.SetSilent(config.emoteHold)
	end
end

function AnimationFeature.presetControls(state)
	local context, section = state.context, state.context.section
	local presets = {{code = "163620952", label = "Iysglimt"}, {code = "8990346215", label = "runeaid"},
		{code = "89003145", label = "7788s"}, {code = "1219722", label = "coldness"},
		{code = "1195061435", label = "reaizsym"}, {code = "887330563", label = "aurqzv"}}
	section:Header("Presets")
	local selected = presets[1].code
	section:Dropdown({Text = "Preset", Options = presets, Default = selected, NoSave = true, Callback = function(value) selected = value end})
	section:Button({Text = "Wear preset", Callback = function()
		local choice = selected
		local label
		for _, preset in presets do if preset.code == choice then label = preset.label:lower(); break end end
		local skin = state.config.skin
		local current = type(skin) == "table" and skin.kind == "user" and tostring(skin.id):lower() or nil
		if current and (current == choice or current == label) then state.resetSkin(); return end
		context.environment.task.spawn(function()
			local ok, message = AvatarSkins.applyUser(state.skin, choice)
			context.window:Notify({Title = context.translation.tr("Skin"), Text = message, Kind = ok and "success" or "danger"})
		end)
	end})
end

function AnimationFeature.favoriteControls(state)
	local context, section = state.context, state.context.section
	section:Sub("favorites")
	section:Header("Favorites")
	local selected
	local dropdown = section:Dropdown({Text = "Favorites", Options = {}, Default = "", NoSave = true,
		Callback = function(value) selected = value end})
	state.favRefresh = function()
		local options = {}
		for id, entry in state.config.favorites do
			local kind = type(entry) == "table" and entry.kind or "bundle"
			local name = type(entry) == "table" and entry.name or kind .. " " .. tostring(id)
			table.insert(options, {code = tostring(id), label = tostring(name) .. " (" .. tostring(kind) .. ")"})
		end
		table.sort(options, function(first, second) return first.label < second.label end)
		dropdown.SetOptions(options)
		selected = options[1] and options[1].code or nil
		if selected then dropdown.SetSilent(selected) end
	end
	section:Button({Text = "Apply", Callback = function()
		local entry = selected and state.config.favorites[selected]
		if not entry then return end
		local id = selected
		local kind = type(entry) == "table" and entry.kind or "bundle"
		local name = type(entry) == "table" and entry.name or nil
		context.environment.task.spawn(function()
			if kind == "emote" then AnimationFeature.applyEmote(state, id, name); return end
			if kind == "skin" then AvatarSkins.applyBundle(state.skin, id); return end
			AnimationFeature.applyBundle(state, id)
		end)
	end})
	section:Button({Text = "Remove favorite", Callback = function()
		if not selected then return end
		state.config.favorites[selected] = nil
		AnimationFeature.save(state)
		state.favRefresh()
	end})
	state.favRefresh()
end

function AnimationFeature.search(state, kind, query)
	local environment = state.context.environment
	local params = environment.CatalogSearchParams.new()
	if query ~= "" then params.SearchKeyword = query end
	if kind == "emote" then params.AssetTypes = {environment.Enum.AvatarAssetType.EmoteAnimation}
	else params.BundleTypes = {kind == "skin" and environment.Enum.BundleType.BodyParts or environment.Enum.BundleType.Animations} end
	pcall(function() params.SortType = environment.Enum.CatalogSortType.MostFavorited end)
	local pages = state.context.avatar:SearchCatalog(params)
	local result = {}
	for _ = 1, 4 do
		for _, item in pages:GetCurrentPage() do table.insert(result, {code = tostring(item.Id), label = item.Name or tostring(item.Id)}) end
		if pages.IsFinished then break end
		pages:AdvanceToNextPageAsync()
	end
	return result
end

function AnimationFeature.catalog(state, kind)
	local context, section = state.context, state.context.section
	local text, selected, serial, names = "", nil, 0, {}
	section:Header(kind == "emote" and "Emote catalog" or kind == "skin" and "Skin catalog" or "Animation packs")
	local native = section:LastSection()
	if native and native.Input then native:Input({Text = "Search", Live = true, Callback = function(value) text = tostring(value or "") end}) end
	local dropdown = section:Dropdown({Text = kind == "emote" and "Emotes" or kind == "skin" and "Skins" or "Bundles", Options = {}, Default = "", NoSave = true,
		Callback = function(value) selected = value end})
	local function apply(value)
		if kind == "emote" then return AnimationFeature.applyEmote(state, value, names[tostring(value)]) end
		if kind == "skin" then return AvatarSkins.applyBundle(state.skin, AnimationFeature.parseId(value)) end
		return AnimationFeature.applyBundle(state, value)
	end
	local function notify(ok, message)
		context.window:Notify({Title = context.translation.tr(kind == "emote" and "Emote" or kind == "skin" and "Skin" or "Animation"), Text = message, Kind = ok and "success" or "danger"})
	end
	local function search()
		serial += 1
		local current = serial
		local query = text:gsub("^%s+", ""):gsub("%s+$", "")
		context.environment.task.spawn(function()
			local ok, results = pcall(AnimationFeature.search, state, kind, query)
			if not state.alive or current ~= serial then return end
			if not ok then notify(false, "Catalog error (rate limit?). Try again."); return end
			names = {}
			for _, result in results do names[result.code] = result.label end
			dropdown.SetOptions(results)
			selected = results[1] and results[1].code or nil
			if selected then dropdown.SetSilent(selected) end
		end)
	end
	section:Button({Text = "Search", Callback = function()
		local value = text:gsub("^%s+", ""):gsub("%s+$", "")
		if value:match("^%d+$") or value:find("bundles/", 1, true) or value:find("catalog/", 1, true) then
			context.environment.task.spawn(function() local ok, message = apply(value); notify(ok, message) end)
			return
		end
		search()
	end})
	section:Button({Text = "Apply", Callback = function()
		if not selected then return end
		local id = selected
		context.environment.task.spawn(function() local ok, message = apply(id); notify(ok, message) end)
	end})
	section:Button({Text = "Copy ID", Callback = function()
		if not selected then return end
		local copy = context.environment.setclipboard or context.environment.toclipboard
		if copy then pcall(copy, tostring(selected)) end
	end})
	section:Button({Text = "Favorite", Callback = function()
		if not selected then return end
		local favorites = state.config.favorites
		if favorites[selected] then favorites[selected] = nil else favorites[selected] = {name = names[selected] or kind .. " " .. selected, kind = kind} end
		AnimationFeature.save(state)
		if state.favRefresh then state.favRefresh() end
	end})
	search()
end

function AnimationFeature.install(context)
	local environment, globals = context.environment, context.environment.getgenv()
	if globals.__pulseFA_cleanup then pcall(globals.__pulseFA_cleanup) end
	local state = {context = context, alive = true, token = 0, generation = 0, connections = {}, tracks = {}, emoteConnections = {}, details = {},
		config = AnimationFeature.defaults(AnimationFeature.load(context, "BundleAnimations/config.json")),
		cache = AnimationFeature.load(context, "BundleAnimations/anims_cache.json"), baseSpeed = 1}
	state.speedMultiplier = state.config.speed
	state.save = function() AnimationFeature.save(state) end
	local skin, stopSkin = AvatarSkins.install(context, state.config, state.save)
	state.skin = skin
	local remoteSkins, stopRemoteSkins = RemoteAvatarSkins.install(context)
	state.remoteSkins = remoteSkins
	state.applyBundle = function(id, progress) return AnimationFeature.applyBundle(state, id, progress) end
	state.applySkin = function(id) return AvatarSkins.applyBundle(skin, id) end
	state.applySkinUser = function(value) return AvatarSkins.applyUser(skin, value) end
	state.resetSkin = function()
		AvatarSkins.stop(skin)
		state.config.skin = nil
		AnimationFeature.save(state)
		return true, "Skin removed"
	end
	state.applyMix = function() return AnimationFeature.applyMix(state) end
	state.setMixSlot = function(kind, id, name) AnimationFeature.setMixSlot(state, kind, id, name) end
	state.clearMixSlot = function(kind) AnimationFeature.clearMixSlot(state, kind) end
	state.clearMix = function() AnimationFeature.clearMix(state) end
	state.copyMix = AnimationFeature.copyMix
	state.MIX_SLOTS = {}
	for _, kind in ANIMATION_ORDER do table.insert(state.MIX_SLOTS, {key = kind, label = kind:gsub("Animation$", "")}) end
	state.setSpeed = function(value) AnimationFeature.setSpeed(state, value) end
	state.refreshSpeed = function() AnimationFeature.refreshSpeed(state) end
	state.refreshEmoteSpeed = function() if state.emote then pcall(function() state.emote:AdjustSpeed(state.config.emoteSpeed) end) end end
	state.applyEmote = function(id, name) return AnimationFeature.applyEmote(state, id, name) end
	state.stopEmote = function() AnimationFeature.stopEmote(state) end
	state.applyConfig = function(saved) AnimationFeature.applyConfig(state, saved) end
	state.parseBundleId = AnimationFeature.parseId
	state.reset = function()
		AnimationFeature.resetTracks(state)
		state.config.lastBundle = nil
		AnimationFeature.save(state)
		return true, "Default animations restored"
	end
	local function restore()
		if not state.alive or not state.config.autoLoad then return end
		if state.config.lastMode == "mix" and next(state.config.mix) then AnimationFeature.applyMix(state); return end
		if state.config.lastBundle then AnimationFeature.applyBundle(state, state.config.lastBundle) end
	end
	local respawn = context.connect(context.player.CharacterAdded, function(character)
		character:WaitForChild("Humanoid")
		environment.task.wait(1)
		if state.alive and context.player.Character == character then pcall(restore) end
	end)
	environment.task.spawn(function() environment.task.wait(0.5); pcall(restore) end)
	if state.config.skin then environment.task.spawn(function()
		local saved = state.config.skin
		for _ = 1, 60 do
			if not state.alive or state.config.skin ~= saved then return end
			local character = context.player.Character
			if character and character:FindFirstChild("HumanoidRootPart") then break end
			environment.task.wait(0.25)
		end
		if state.alive and state.config.skin == saved then pcall(AvatarSkins.applySaved, skin, saved) end
	end) end
	local stop = function()
		state.alive = false
		state.generation += 1
		pcall(function() respawn:Disconnect() end)
		stopRemoteSkins()
		stopSkin()
		AnimationFeature.stopEmote(state)
		AnimationFeature.stop(state)
		if globals.__pulseFA == state then globals.__pulseFA = nil end
	end
	globals.__pulseFA, globals.__pulseFA_cleanup = state, stop
	return state, stop
end

end -- AnimationFeature private scope

local PulseApplication = {}

PulseApplication.Mobile = {}

function PulseApplication.Mobile.action(state, key)
	local context, settings = state.context, state.context.configuration
	local globals = context.environment.getgenv()
	if key == "fly" then settings.fly.on = not settings.fly.on; return end
	if key == "bhop" then settings.bhop = not settings.bhop; return end
	local toggles = {killall = "KillAll", invis = "Invis", noclip = "Noclip", speed = "Speed", sglitch = "SGlitch"}
	local name = toggles[key]
	if name then
		local get, set = globals["__pulseGet" .. name], globals["__pulseSet" .. name]
		if type(set) == "function" then pcall(set, not (type(get) == "function" and get())) end
		return
	end
	local actions = {shot = "__pulseShotMurder", knife = "__pulseThrowKnife", bombjump = "__pulseAutoBombJump"}
	if actions[key] then
		local action = globals[actions[key]]
		if type(action) == "function" then pcall(action) end
		return
	end
	if key ~= "flingM" and key ~= "flingS" then return end
	if state.flinging then
		state.cancelFling = true
		if type(globals.__pulseFlingCancel) == "function" then pcall(globals.__pulseFlingCancel) end
		return
	end
	state.flinging, state.cancelFling = key, false
	context.environment.task.spawn(function()
		pcall(function()
			local roles = context.roles()
			for _, player in context.players:GetPlayers() do
				if state.cancelFling then break end
				if player == context.player then continue end
				local data = roles[player.Name]
				local role = data and data.Role
				local backpack = player:FindFirstChildOfClass("Backpack")
				local character = player.Character
				if role == "Innocent" and (character and character:FindFirstChild("Gun") or backpack and backpack:FindFirstChild("Gun")) then role = "Hero" end
				if not data or data.Dead == true or data.Killed == true then continue end
				if key == "flingM" and role ~= "Murderer" then continue end
				if key == "flingS" and role ~= "Sheriff" and role ~= "Hero" then continue end
				local humanoid = character and character:FindFirstChildOfClass("Humanoid")
				if not humanoid or humanoid.Health <= 0 then continue end
				if type(globals.__pulseFlingPersist) == "function" then
					globals.__pulseFlingPersist(player, {time = 10})
					continue
				end
				if type(globals.__pulseFlingPlayer) == "function" then
					pcall(globals.__pulseFlingPlayer, player)
					while globals.__pulseManualFling and not state.cancelFling do context.environment.task.wait(0.1) end
					continue
				end
				if type(globals.__pulseFlingChar) == "function" then pcall(globals.__pulseFlingChar, character, 1); context.environment.task.wait(0.12) end
			end
		end)
		state.flinging = nil
	end)
end

PulseApplication.Mobile.buttons = {
	{key = "fly", text = "Fly Button", label = "FLY", x = -1, y = 0},
	{key = "bhop", text = "Bhop Button", label = "BHOP", x = 0, y = 0},
	{key = "flingS", text = "Fling Sheriff Button", label = "FLING S", x = 0, y = 1},
	{key = "flingM", text = "Fling Murderer Button", label = "FLING M", x = 1, y = 0},
	{key = "shot", text = "Shot Murder Button", label = "SHOT", x = 0, y = -1},
	{key = "killall", text = "Kill All Murder Button", label = "KILL ALL", x = 2, y = -1},
	{key = "invis", text = "Invisible Button", label = "INVIS", x = -1, y = 1},
	{key = "knife", text = "Knife Throw Button", label = "KNIFE", x = 1, y = -1},
	{key = "bombjump", text = "Auto Bomb Jump Button", label = "BOMB", x = -1, y = 2},
	{key = "noclip", text = "No Clip Button", label = "NOCLIP", x = 1, y = 1},
	{key = "speed", text = "Speed Button", label = "SPEED", x = 2, y = 0},
	{key = "sglitch", text = "Speed Glitch Button", label = "GLITCH", x = 2, y = 1},
}

function PulseApplication.Mobile.refresh(state)
	if state.painted then table.clear(state.painted) end
	local context, environment = state.context, state.context.environment
	local mobile, style = context.configuration.mobile, context.configuration.uis
	local camera = context.workspace.CurrentCamera
	local viewport = camera and camera.ViewportSize or environment.Vector2.new(800, 600)
	local small = math.min(viewport.X, viewport.Y) <= 500
	local jumpX = viewport.X - (small and 60 or 110)
	local jumpY = viewport.Y - (small and 55 or 150)
	local radius = small and 35 or 60
	for index, item in PulseApplication.Mobile.buttons do
		local button = state.buttons[item.key]
		local size = math.floor(64 * math.clamp((tonumber(style.size[item.key]) or 100) / 100, 0.5, 2) + 0.5)
		local position = mobile.pos[item.key]
		local x = item.x >= 0 and jumpX - radius - 46 - item.x * 76 or jumpX
		local y = item.y >= 0 and jumpY - radius - 46 - item.y * 76 or jumpY
		x, y = math.floor(x - size / 2), math.floor(y - size / 2)
		if style.style == "Compact" then x, y = viewport.X - 20 - size, jumpY - radius - 14 - size - (index - 1) * (size + 8) end
		if type(position) == "table" and type(position.x) == "number" and type(position.y) == "number" then x, y = position.x, position.y end
		button.Position = environment.UDim2.fromOffset(math.clamp(x, 0, math.max(0, viewport.X - size)), math.clamp(y, 0, math.max(0, viewport.Y - size)))
		button.Size = environment.UDim2.fromOffset(size, size)
		button.Visible = mobile[item.key] == true
		button.BackgroundColor3 = style.style == "Glass" and environment.Color3.fromRGB(200, 205, 220) or environment.Color3.fromRGB(28, 28, 32)
		button.BackgroundTransparency = style.style == "Glass" and 0.65 or 0.15
		button.TextColor3 = environment.Color3.fromRGB(255, 255, 255)
		button.Text = item.label .. (style.lock[item.key] and " ðŸ”’" or "")
	end
end

function PulseApplication.Mobile.button(state, item)
	local context, environment = state.context, state.context.environment
	local inputService = context.inputService
	local button = context.create("TextButton", {Name = item.key, Text = item.label, AutoButtonColor = false,
		Font = environment.Enum.Font.GothamBold, TextSize = 10, BorderSizePixel = 0, Active = true}, state.gui)
	context.corner(button, 32)
	local current, origin, start, moved, doubleTap, lastTime, lastPosition
	context.connect(button.InputBegan, function(input)
		local kind = input.UserInputType
		if kind ~= environment.Enum.UserInputType.Touch and kind ~= environment.Enum.UserInputType.MouseButton1 then return end
		if current then return end
		current, origin, start, moved = input, input.Position, button.Position, false
		local point = environment.Vector2.new(input.Position.X, input.Position.Y)
		doubleTap = context.configuration.uis.dtap == true and lastTime ~= nil and environment.os.clock() - lastTime < 0.33
			and (point - lastPosition).Magnitude < 48
		if item.key == "shot" and not doubleTap then PulseApplication.Mobile.action(state, item.key) end
	end)
	context.connect(inputService.InputChanged, function(input)
		if not current or context.configuration.uis.lock[item.key] then return end
		if current.UserInputType == environment.Enum.UserInputType.Touch and input ~= current then return end
		if current.UserInputType ~= environment.Enum.UserInputType.Touch and input.UserInputType ~= environment.Enum.UserInputType.MouseMovement then return end
		local delta = input.Position - origin
		if math.abs(delta.X) > 10 or math.abs(delta.Y) > 10 then moved = true end
		if not moved then return end
		local camera = context.workspace.CurrentCamera
		local viewport = camera and camera.ViewportSize or environment.Vector2.new(800, 600)
		local x = math.clamp(start.X.Offset + delta.X, 0, math.max(0, viewport.X - button.AbsoluteSize.X))
		local y = math.clamp(start.Y.Offset + delta.Y, 0, math.max(0, viewport.Y - button.AbsoluteSize.Y))
		button.Position = environment.UDim2.fromOffset(x, y)
		context.configuration.mobile.pos[item.key] = {x = x, y = y}
	end)
	context.connect(inputService.InputEnded, function(input)
		if not current then return end
		if current.UserInputType == environment.Enum.UserInputType.Touch and input ~= current then return end
		if current.UserInputType ~= environment.Enum.UserInputType.Touch and input.UserInputType ~= environment.Enum.UserInputType.MouseButton1 then return end
		current = nil
		if moved then lastTime, lastPosition = nil, nil; return end
		if doubleTap then
			local locks = context.configuration.uis.lock
			locks[item.key] = not locks[item.key]
			lastTime, lastPosition = nil, nil
			PulseApplication.Mobile.refresh(state)
			return
		end
		lastTime, lastPosition = environment.os.clock(), environment.Vector2.new(input.Position.X, input.Position.Y)
		if item.key ~= "shot" then PulseApplication.Mobile.action(state, item.key) end
	end)
	return button
end

function PulseApplication.Mobile.paint(state)
	local context, environment = state.context, state.context.environment
	local globals, settings = environment.getgenv(), context.configuration
	local active = {fly = settings.fly.on == true, bhop = settings.bhop == true}
	for key, name in {killall = "KillAll", invis = "Invis", noclip = "Noclip", speed = "Speed", sglitch = "SGlitch"} do
		local get = globals["__pulseGet" .. name]
		if type(get) ~= "function" then continue end
		local ok, value = pcall(get)
		active[key] = ok and value == true
	end
	local character = context.player.Character
	local backpack = context.player:FindFirstChildOfClass("Backpack")
	for _, item in PulseApplication.Mobile.buttons do
		local button = state.buttons[item.key]
		local unavailable = (item.key == "shot" or item.key == "knife") and not (
			character and character:FindFirstChild(item.key == "shot" and "Gun" or "Knife")
			or backpack and backpack:FindFirstChild(item.key == "shot" and "Gun" or "Knife"))
		local selected = active[item.key] or state.flinging == item.key
		local signature = tostring(selected) .. tostring(unavailable) .. tostring(settings.uis.style)
		if state.painted[item.key] == signature then continue end
		state.painted[item.key] = signature
		button.BackgroundColor3 = selected and environment.Color3.fromRGB(66, 135, 245)
			or settings.uis.style == "Glass" and environment.Color3.fromRGB(200, 205, 220) or environment.Color3.fromRGB(28, 28, 32)
		button.TextTransparency = unavailable and 0.55 or 0
	end
end

function PulseApplication.Mobile.hud(state)
	local context, environment = state.context, state.context.environment
	local settings, section = context.configuration.mobile, context.section
	local globals = environment.getgenv()
	local function refresh()
		pcall(function()
			local window = globals.__pulseMM2Nova
			if not window then return end
			window:SetWatermark(settings.pingfps == true or settings.roundtimer == true)
			if not settings.roundtimer then window:SetWatermarkTitle(nil) end
		end)
	end
	local function setPing(value)
		settings.pingfps = value == true
		refresh()
		local control = globals.__pulsePfSettings
		if control and control.Get and control.SetSilent and control.Get() ~= settings.pingfps then pcall(control.SetSilent, settings.pingfps) end
	end

	section:Header("HUD")
	local control = section:Toggle({Text = "Show Ping/Fps UI", Default = false, Callback = setPing})
	globals.__pulsePingFps = {get = function() return settings.pingfps == true end, set = function(value)
		if control and control.Set then control.Set(value); return end
		setPing(value)
	end}
	section:Toggle({Text = "Show Round Timer", Default = false, Callback = function(value)
		settings.roundtimer = value == true
		refresh()
	end})
	setPing(settings.pingfps == true)

	local elapsed = 0
	context.connect(context.runService.Heartbeat, function(delta)
		if not settings.roundtimer then return end
		elapsed += delta
		if elapsed < 0.25 then return end
		elapsed = 0
		local title
		pcall(function()
			local part = context.workspace:FindFirstChild("RoundTimerPart")
			local time = part and part:GetAttribute("Time")
			if type(time) == "number" and time > 0 then title = string.format("%d:%02d", math.floor(time / 60), math.floor(time % 60)) end
		end)
		local window = globals.__pulseMM2Nova
		if window and window.SetWatermarkTitle then pcall(window.SetWatermarkTitle, window, title) end
	end)
end

function PulseApplication.Mobile.install(context)
	local settings = context.configuration
	settings.mobile = type(settings.mobile) == "table" and settings.mobile or {}
	settings.mobile.pos = type(settings.mobile.pos) == "table" and settings.mobile.pos or {}
	settings.uis = type(settings.uis) == "table" and settings.uis or {}
	settings.uis.size = type(settings.uis.size) == "table" and settings.uis.size or {}
	settings.uis.lock = type(settings.uis.lock) == "table" and settings.uis.lock or {}
	if settings.uis.style ~= "Pulse" and settings.uis.style ~= "Glass" and settings.uis.style ~= "Compact" then settings.uis.style = "Pulse" end
	local state = {context = context, buttons = {}, painted = {}}
	local environment, section = context.environment, context.section
	state.gui = context.create("ScreenGui", {Name = "PulseMobileBtns", ResetOnSpawn = false, IgnoreGuiInset = true,
		ZIndexBehavior = environment.Enum.ZIndexBehavior.Sibling, DisplayOrder = 9999}, context.parent)
	section:Sub("UIS")
	section:Note({Text = "On-screen buttons (mobile). Hold & drag a button to move it, tap to use."})
	section:Header("Buttons Style")
	for _, item in PulseApplication.Mobile.buttons do state.buttons[item.key] = PulseApplication.Mobile.button(state, item) end
	section:Dropdown({Text = "Button Design", Default = settings.uis.style,
		Options = {{code = "Pulse", label = "Pulse"}, {code = "Glass", label = "Glass"}, {code = "Compact", label = "Compact"}}, Callback = function(value)
		settings.uis.style = value
		PulseApplication.Mobile.refresh(state)
	end})
	for _, item in PulseApplication.Mobile.buttons do
		section:Toggle({Text = item.text, Default = settings.mobile[item.key] == true, Callback = function(value)
			settings.mobile[item.key] = value
			PulseApplication.Mobile.refresh(state)
		end, Settings = function()
			section:Slider({Text = item.text .. " Size", Min = 50, Max = 200, Default = tonumber(settings.uis.size[item.key]) or 100,
				Decimals = 0, Suffix = "%", Callback = function(value)
					settings.uis.size[item.key] = value
					PulseApplication.Mobile.refresh(state)
				end})
		end})
	end
	section:Button({Text = "Reset UIS Position", Callback = function() table.clear(settings.mobile.pos); PulseApplication.Mobile.refresh(state) end})
	section:Header("Lock")
	section:Toggle({Text = "Double Tap Lock", Default = settings.uis.dtap == true, Callback = function(value) settings.uis.dtap = value end})
	section:Button({Text = "Unlock All Buttons", Callback = function() table.clear(settings.uis.lock); PulseApplication.Mobile.refresh(state) end})
	PulseApplication.Mobile.hud(state)
	local globals = environment.getgenv()
	globals.__pulseSyncUIS = function() PulseApplication.Mobile.refresh(state) end
	globals.__pulseRefreshBtnStyles = globals.__pulseSyncUIS
	table.insert(context.applyHooks, globals.__pulseSyncUIS)
	PulseApplication.Mobile.refresh(state)
	environment.task.spawn(function()
		while context.isAlive() do
			pcall(PulseApplication.Mobile.paint, state)
			environment.task.wait(0.25)
		end
	end)
	return state, function()
		state.cancelFling = true
		globals.__pulseSyncUIS, globals.__pulseRefreshBtnStyles, globals.__pulsePingFps = nil, nil, nil
		state.gui:Destroy()
	end
end

PulseApplication.Trolly = {}

function PulseApplication.Trolly.raycastParams(state, extra)
	local environment = state.context.environment
	local params = environment.RaycastParams.new()
	local excluded = {}

	for _, player in ipairs(state.context.players:GetPlayers()) do
		if player.Character then table.insert(excluded, player.Character) end
	end
	if state.model then table.insert(excluded, state.model) end
	if state.dance and state.dance.pig then table.insert(excluded, state.dance.pig.model) end
	local television = state.dance and state.dance.television
	if television then
		if television.model then table.insert(excluded, television.model) end
		if television.statue and television.statue.model then table.insert(excluded, television.statue.model) end
		if television.effectFolder then table.insert(excluded, television.effectFolder) end
	end
	local fight = state.dance and state.dance.fight
	if fight then
		if fight.statue and fight.statue.model then table.insert(excluded, fight.statue.model) end
		if fight.pig and fight.pig.model then table.insert(excluded, fight.pig.model) end
		if fight.effectFolder then table.insert(excluded, fight.effectFolder) end
	end
	if state.cut and state.cut.actor then table.insert(excluded, state.cut.actor) end
	if extra then table.insert(excluded, extra) end

	params.FilterType = environment.Enum.RaycastFilterType.Exclude
	params.FilterDescendantsInstances = excluded
	return params
end

function PulseApplication.Trolly.horizontal(environment, vector)
	local horizontal = environment.Vector3.new(vector.X, 0, vector.Z)
	if horizontal.Magnitude < 0.001 then return nil end
	return horizontal.Unit
end

function PulseApplication.Trolly.position(state)
	local context = state.context
	local environment, workspace = context.environment, context.workspace
	local regular = workspace:FindFirstChild("RegularLobby")

	if regular then
		local board = regular:FindFirstChild("RadioBoard")
		local screen = board and board:FindFirstChild("Screen")
		if not screen or not screen:IsA("BasePart") then return nil end

		local forward = PulseApplication.Trolly.horizontal(environment, screen.CFrame.LookVector)
		local right = PulseApplication.Trolly.horizontal(environment, screen.CFrame.RightVector)
		if not forward or not right then return nil end
		return screen.Position - right * 18.2 - forward * 0.7, forward
	end

	local lobby = workspace:FindFirstChild("Lobby")
	local spawns = lobby and lobby:FindFirstChild("Spawns")
	if not spawns or not lobby:FindFirstChild("VotePads") then return nil end

	local ok, box = pcall(function() return spawns:GetBoundingBox() end)
	if not ok then return nil end

	local origin = box.Position
	local params = PulseApplication.Trolly.raycastParams(state, lobby:FindFirstChild("InvisibleWalls"))
	local wall = workspace:Raycast(origin + environment.Vector3.new(0, 18, 0), environment.Vector3.new(-120, 0, 0), params)
	if not wall or math.abs(wall.Normal.Y) > 0.2 then return nil end

	local normal = PulseApplication.Trolly.horizontal(environment, wall.Normal)
	if not normal then return nil end

	local floorOrigin = environment.Vector3.new(wall.Position.X, origin.Y + 4, wall.Position.Z) + normal * 4
	local floor = workspace:Raycast(floorOrigin, environment.Vector3.new(0, -20, 0), params)
	local base = environment.Vector3.new(wall.Position.X, floor and floor.Position.Y or origin.Y, wall.Position.Z)
	local tangent = environment.Vector3.yAxis:Cross(normal)
	return base + tangent * 7 + normal * 3.6, normal
end

function PulseApplication.Trolly.create(state, className, properties, parent)
	local object = state.context.environment.Instance.new(className)
	for key, value in pairs(properties) do object[key] = value end
	object.Parent = parent
	return object
end

function PulseApplication.Trolly.settings(state)
	local configuration = state.context.configuration
	if type(configuration.npc) ~= "table" then configuration.npc = {} end
	local settings = configuration.npc
	if settings.on == nil then settings.on = true end
	if settings.dances == nil then settings.dances = true end
	if tonumber(settings.volume) == nil then settings.volume = 100 end
	return settings
end

function PulseApplication.Trolly.setOn(state, enabled)
	local settings = PulseApplication.Trolly.settings(state)
	settings.on = enabled and true or false
	if settings.on then
		pcall(PulseApplication.Trolly.ensure, state)
		return
	end
	pcall(PulseApplication.Trolly.remove, state)
end

function PulseApplication.Trolly.setVolume(state, value)
	local volume = math.clamp(tonumber(value) or 100, 0, 100)
	PulseApplication.Trolly.settings(state).volume = volume
	pcall(function() PulseApplication.Trolly.soundGroup(state).Volume = volume / 100 end)
end

function PulseApplication.Trolly.soundGroup(state)
	if state.soundGroup and state.soundGroup.Parent then return state.soundGroup end

	local volume = tonumber(PulseApplication.Trolly.settings(state).volume) or 100
	state.soundGroup = PulseApplication.Trolly.create(state, "SoundGroup", {
		Name = "PulseNpcSounds", Volume = math.clamp(volume / 100, 0, 1),
	}, state.context.soundService)
	return state.soundGroup
end

function PulseApplication.Trolly.initVoices(state)
	if state.voices[1] and state.voices[1].Parent then return end

	state.voices = {}
	local group = PulseApplication.Trolly.soundGroup(state)
	for _, id in ipairs({9118480732, 9118480950, 9125850674}) do
		for _ = 1, 2 do
			local voice = PulseApplication.Trolly.create(state, "Sound", {
				Name = "PulseNpcVoice", SoundId = "rbxassetid://" .. id, Volume = 0, SoundGroup = group,
			}, state.context.soundService)
			table.insert(state.voices, voice)
		end
	end
	state.voiceIndex = 0
end

function PulseApplication.Trolly.syllable(state)
	PulseApplication.Trolly.initVoices(state)
	state.voiceIndex = state.voiceIndex % #state.voices + 1
	local voice = state.voices[state.voiceIndex]
	if voice.TimeLength <= 0.3 then return end

	local context, environment = state.context, state.context.environment
	voice:Stop()
	voice.PlaybackSpeed = 1.08 + math.random() * 0.28
	voice.TimePosition = math.random() * math.max(0, voice.TimeLength - 0.3)
	voice.Volume = 0.55
	voice:Play()
	environment.task.delay(0.085 + math.random() * 0.06, function()
		if not voice.Parent then return end
		context.tweenService:Create(voice, environment.TweenInfo.new(0.05), {Volume = 0}):Play()
		environment.task.delay(0.06, function()
			if voice.Parent and voice.Volume <= 0.01 then voice:Stop() end
		end)
	end)
end

function PulseApplication.Trolly.spooky(state, root)
	local environment = state.context.environment
	PulseApplication.Trolly.create(state, "PointLight", {Name = "PulseGlow", Color = environment.Color3.fromRGB(255, 140, 50),
		Brightness = 1.3, Range = 11, Shadows = false}, root)
	local mist = PulseApplication.Trolly.create(state, "Attachment", {Name = "PulseMist",
		Position = environment.Vector3.new(0, -2.6, 0)}, root)
	PulseApplication.Trolly.create(state, "ParticleEmitter", {Name = "Mist", Texture = "rbxassetid://101959242173269",
		Rate = 3, Lifetime = environment.NumberRange.new(3, 4.5), Speed = environment.NumberRange.new(0.4, 1),
		SpreadAngle = environment.Vector2.new(180, 10), Rotation = environment.NumberRange.new(0, 360),
		RotSpeed = environment.NumberRange.new(-15, 15), Size = environment.NumberSequence.new({
			environment.NumberSequenceKeypoint.new(0, 2.5), environment.NumberSequenceKeypoint.new(1, 5)}),
		Transparency = environment.NumberSequence.new({environment.NumberSequenceKeypoint.new(0, 1),
			environment.NumberSequenceKeypoint.new(0.3, 0.75), environment.NumberSequenceKeypoint.new(1, 1)}),
		Color = environment.ColorSequence.new(environment.Color3.fromRGB(150, 90, 220), environment.Color3.fromRGB(255, 130, 40)),
		LightEmission = 0.4, Acceleration = environment.Vector3.new(0, 0.2, 0), ZOffset = -1}, mist)
	local embers = PulseApplication.Trolly.create(state, "Attachment", {Name = "PulseEmbers",
		Position = environment.Vector3.new(0, 0.5, 0)}, root)
	PulseApplication.Trolly.create(state, "ParticleEmitter", {Name = "Embers", Texture = "rbxassetid://16512006463",
		Rate = 4, Lifetime = environment.NumberRange.new(1.6, 2.6), Speed = environment.NumberRange.new(1, 2.2),
		SpreadAngle = environment.Vector2.new(60, 60), Drag = 1, Size = environment.NumberSequence.new({
			environment.NumberSequenceKeypoint.new(0, 0.18), environment.NumberSequenceKeypoint.new(1, 0)}),
		Transparency = environment.NumberSequence.new(0.1, 1), Color = environment.ColorSequence.new(
			environment.Color3.fromRGB(255, 170, 60), environment.Color3.fromRGB(255, 90, 20)),
		LightEmission = 1, Acceleration = environment.Vector3.new(0, 1.5, 0)}, embers)
end

function PulseApplication.Trolly.loadAnimations(state, humanoid)
	local environment = state.context.environment
	local animator = humanoid:FindFirstChildOfClass("Animator") or environment.Instance.new("Animator", humanoid)
	local ids = {idle = 507766388, look = 507766666, wave = 507770239, point = 507770453,
		cheer = 507770677, laugh = 507770818}

	for name, id in pairs(ids) do
		local animation = environment.Instance.new("Animation")
		animation.AnimationId = "rbxassetid://" .. id
		local ok, track = pcall(function() return animator:LoadAnimation(animation) end)
		animation:Destroy()
		if not ok then continue end

		track.Priority = (name == "idle" or name == "look") and environment.Enum.AnimationPriority.Idle
			or environment.Enum.AnimationPriority.Action
		if name == "idle" then
			track.Priority = environment.Enum.AnimationPriority.Idle
			track.Looped = true
			track:Play(0.3)
		end
		state.animations[name] = track
	end
end

function PulseApplication.Trolly.gesture(state, name)
	local selected = state.animations[name]
	if not selected then return end

	for key, track in pairs(state.animations) do
		if key ~= "idle" and track.IsPlaying then track:Stop(0.25) end
	end
	selected.Looped = false
	selected:Play(0.2)
	state.context.environment.task.delay(name == "laugh" and 2.2 or 2.4, function()
		if selected.IsPlaying then selected:Stop(0.4) end
	end)
end

function PulseApplication.Trolly.build(state)
	local context = state.context
	local environment = context.environment
	local position, forward = PulseApplication.Trolly.position(state)
	if not position then return end

	local params = PulseApplication.Trolly.raycastParams(state)
	local ground = context.workspace:Raycast(position + environment.Vector3.new(0, 2, 0), environment.Vector3.new(0, -30, 0), params)
	if not ground then return end

	local description = environment.Instance.new("HumanoidDescription")
	local color = environment.Color3.fromRGB(236, 236, 236)
	for _, property in ipairs({"HeadColor", "TorsoColor", "LeftArmColor", "RightArmColor", "LeftLegColor", "RightLegColor"}) do
		description[property] = color
	end
	description.HatAccessory = "78557106937297,14926431610"
	description.BackAccessory, description.ShouldersAccessory, description.WaistAccessory = "110464967322599", "96098589382408", "82801950828150"
	description.Shirt, description.Pants = 5764463125, 18429601675

	local function createModel()
		return context.players:CreateHumanoidModelFromDescription(description, environment.Enum.HumanoidRigType.R15)
	end
	local ok, model = pcall(createModel)
	if not ok or not model then
		description.HatAccessory, description.BackAccessory = "", ""
		description.ShouldersAccessory, description.WaistAccessory = "", ""
		description.Shirt, description.Pants = 0, 0
		ok, model = pcall(createModel)
	end
	description:Destroy()
	if not ok or not model then return end

	local humanoid = model:FindFirstChildOfClass("Humanoid")
	local root = model:FindFirstChild("HumanoidRootPart")
	local head = model:FindFirstChild("Head")
	if not humanoid or not root or not head then model:Destroy(); return end

	model.Name = "PulseNpc"
	humanoid.DisplayDistanceType = environment.Enum.HumanoidDisplayDistanceType.None
	humanoid.HealthDisplayType = environment.Enum.HumanoidHealthDisplayType.AlwaysOff
	for _, descendant in ipairs(model:GetDescendants()) do
		if descendant:IsA("BasePart") then
			descendant.CanCollide, descendant.CanQuery, descendant.CanTouch = false, false, false
		end
	end
	root.Anchored = true

	local face, hats = nil, {}
	for _, accessory in ipairs(model:GetChildren()) do
		if not accessory:IsA("Accessory") or accessory.AccessoryType ~= environment.Enum.AccessoryType.Hat then continue end
		local handle = accessory:FindFirstChild("Handle")
		if not handle then continue end
		local size = handle.Size.X * handle.Size.Y * handle.Size.Z
		if not face or size > face.Size.X * face.Size.Y * face.Size.Z then
			if face then table.insert(hats, face) end
			face = handle
			continue
		end
		table.insert(hats, handle)
	end
	for _, child in ipairs(head:GetChildren()) do
		if child:IsA("Decal") then child:Destroy() end
	end
	head.Transparency = 1

	if not face then
		face = PulseApplication.Trolly.create(state, "Part", {Name = "TrollHead", Size = environment.Vector3.new(2, 1, 1),
			Color = environment.Color3.new(1, 1, 1), Material = environment.Enum.Material.SmoothPlastic,
			CanCollide = false, CanQuery = false, CanTouch = false, Massless = true}, model)
		PulseApplication.Trolly.create(state, "SpecialMesh", {MeshType = environment.Enum.MeshType.Head,
			Scale = environment.Vector3.new(1.5, 1.5, 1.5)}, face)
		PulseApplication.Trolly.create(state, "Decal", {Name = "face", Face = environment.Enum.NormalId.Front,
			Texture = "rbxthumb://type=Asset&id=9631028060&w=420&h=420"}, face)
		face.CFrame = head.CFrame * environment.CFrame.new(0, 0.22, 0)
		PulseApplication.Trolly.create(state, "WeldConstraint", {Part0 = face, Part1 = head}, face)
	end

	local headAttachment, faceAttachment = head:FindFirstChild("HatAttachment"), face:FindFirstChild("HatAttachment")
	for _, hat in ipairs(hats) do
		local attachment = hat:FindFirstChild("HatAttachment")
		if not headAttachment or not faceAttachment or not attachment then continue end
		local offset = headAttachment.CFrame * faceAttachment.CFrame:Inverse()
			* environment.CFrame.new(0, face.Size.Y / 2 + hat.Size.Y * 0.32, 0.18)
			* environment.CFrame.Angles(0, 0, math.rad(-8))
		attachment.CFrame = offset:Inverse() * headAttachment.CFrame
	end

	local height = ground.Position.Y + humanoid.HipHeight + root.Size.Y / 2
	local location = environment.Vector3.new(position.X, height, position.Z)
	state.home = environment.CFrame.lookAt(location, location + forward)
	model:PivotTo(state.home)
	model.Parent = context.workspace
	state.model, state.root, state.humanoid, state.neck, state.animations = model, root, humanoid, head:FindFirstChild("Neck"), {}
	pcall(PulseApplication.Trolly.spooky, state, root)
	PulseApplication.Trolly.loadAnimations(state, humanoid)
	state.lift = math.clamp(face.Position.Y + face.Size.Y / 2 - root.Position.Y, 1.6, 4) + 0.35
	PulseApplication.Trolly.createHud(state)
	PulseApplication.Trolly.createPrompt(state)
end

