	state.pigTag, state.pigScale, state.pigLabel, state.pigGradient = pigTag, pigScale, pigLabel, pigGradient
end

function PulseApplication.Trolly.hudStep(state)
	if not state.hud or not state.root or not state.root.Parent then return end
	local context, environment = state.context, state.context.environment
	local camera = context.workspace.CurrentCamera
	if not camera then return end

	local target = state.root.Position + environment.Vector3.new(0, state.lift or 3, 0)
	local cameraPosition = camera.CFrame.Position
	local distance = (cameraPosition - target).Magnitude
	local now = os.clock()
	if now - (state.occlusionChecked or 0) > 0.15 then
		state.occlusionChecked = now
		local direction = target - cameraPosition
		local wall = distance < 90 and context.workspace:Raycast(cameraPosition, direction, PulseApplication.Trolly.raycastParams(state))
		state.occluded = wall and wall.Instance.Transparency < 0.9 and (wall.Position - cameraPosition).Magnitude < distance - 0.5 or false
	end

	local point, onScreen = camera:WorldToViewportPoint(target)
	state.tag.Visible = onScreen and point.Z > 0 and distance < 80 and not state.occluded and not state.open
	local hudScale = math.clamp(camera.ViewportSize.Y / 1000, 0.6, 1.35)
	if state.tag.Visible then
		state.tag.Position = environment.UDim2.fromOffset(math.floor(point.X + 0.5), math.floor(point.Y + 0.5))
		state.tagScale.Scale = math.clamp(16 / math.max(distance, 1), 0.7, 1.15) * hudScale
		state.tagSubtitle.Text = "ðŸŽƒ " .. context.translation.tr("GUIDE") .. "  Â·  PULSE HUB"
		local playerRoot = PulseApplication.Trolly.playerRoot(state)
		state.bubble.Visible = not state.dance and playerRoot ~= nil and (playerRoot.Position - state.root.Position).Magnitude < 20
		state.bubble.Position = environment.UDim2.new(0.5, 0, 1, math.floor(-48 + math.sin(now * 2.6) * 3 + 0.5))
		PulseApplication.Trolly.lyricStep(state, state.dance and state.dance.time or 0)
	end

	local dance = state.dance
	local television = dance and dance.television
	local statueHead = television and television.statue and television.statue.parts.Head
	state.statueLyricFrame.Visible = false
	if statueHead and statueHead.Parent and dance.running and not dance.ending and not state.open then
		local position = statueHead.Position + environment.Vector3.new(0, 1.7, 0)
		local screen, visible = camera:WorldToViewportPoint(position)
		local statueDistance = (cameraPosition - position).Magnitude
		if visible and screen.Z > 0 and statueDistance < 80 then
			state.statueLyricFrame.Position = environment.UDim2.fromOffset(math.floor(screen.X + 0.5), math.floor(screen.Y + 0.5))
			state.statueBaseScale.Scale = math.clamp(16 / math.max(statueDistance, 1), 0.7, 1.15) * hudScale
			state.statueLyricFrame.Visible = PulseApplication.Trolly.statueLyricStep(state, dance.time or 0)
		end
	end

	local pig = state.dance and state.dance.pig
	state.pigTag.Visible = false
	if pig and pig.headPosition and pig.body.Parent and pig.alpha > 0.02 and not state.open then
		local position = pig.headPosition + environment.Vector3.new(0, 1.05 + 0.08 * math.sin(now * 3), 0)
		local screen, visible = camera:WorldToViewportPoint(position)
		local pigDistance = (cameraPosition - position).Magnitude
		if visible and screen.Z > 0 and pigDistance < 80 then
			local age = math.clamp((now - pig.born) / 0.35, 0, 1)
			local pop = 1 + 2.70158 * (age - 1) ^ 3 + 1.70158 * (age - 1) ^ 2
			state.pigTag.Position = environment.UDim2.fromOffset(math.floor(screen.X + 0.5), math.floor(screen.Y + 0.5))
			state.pigScale.Scale = math.max(0.01, math.clamp(14 / math.max(pigDistance, 1), 0.55, 1.1) * hudScale * pop)
			state.pigLabel.TextTransparency = 1 - pig.alpha
			state.pigLabel.Rotation = 3 * math.sin(now * 2.2)
			state.pigGradient.Offset = environment.Vector2.new(math.sin(now * 1.7) * 0.4, 0)
			state.pigGradient.Rotation = 8 * math.sin(now * 1.1)
			state.pigTag.Visible = true
		end
	end

	state.promptButton.Visible = state.promptVisible and not state.open
	if not state.promptButton.Visible then return end
	local promptPosition = state.root.Position + environment.Vector3.new(0, 0.2, 0) + camera.CFrame.RightVector * 1.4
	local screen, visible = camera:WorldToViewportPoint(promptPosition)
	state.promptButton.Position = visible and screen.Z > 0 and environment.UDim2.fromOffset(math.floor(screen.X + 0.5), math.floor(screen.Y + 0.5))
		or environment.UDim2.fromOffset(-1000, -1000)
	state.promptButton.Text = "G   " .. context.translation.tr("Talk")
end

function PulseApplication.Trolly.createPrompt(state)
	local environment = state.context.environment
	state.prompt = PulseApplication.Trolly.create(state, "ProximityPrompt", {
		Name = "Talk", ActionText = state.context.translation.tr("Talk"), ObjectText = "Trolly",
		KeyboardKeyCode = environment.Enum.KeyCode.G, HoldDuration = 0, MaxActivationDistance = 10,
		RequiresLineOfSight = false, Style = environment.Enum.ProximityPromptStyle.Custom,
	}, state.root)
	state.prompt.Triggered:Connect(function() PulseApplication.Trolly.open(state) end)
	state.prompt.PromptShown:Connect(function() state.promptVisible = true end)
	state.prompt.PromptHidden:Connect(function() state.promptVisible = false end)
end

function PulseApplication.Trolly.remove(state)
	PulseApplication.Trolly.close(state)
	state.preparingDance = nil
	pcall(PulseApplication.Trolly.danceEnd, state)
	if state.model then state.model:Destroy() end
	if state.tag then state.tag.Visible = false end
	if state.promptButton then state.promptButton.Visible = false end
	state.promptVisible = false
	state.occlusionChecked, state.occluded = nil, nil
	state.model, state.root, state.humanoid, state.neck, state.prompt, state.animations = nil, nil, nil, nil, nil, {}
	state.joints, state.jointsModel = nil, nil
end

function PulseApplication.Trolly.ensure(state)
	if not state.context.isAlive() then return end
	if PulseApplication.Trolly.settings(state).on == false then
		PulseApplication.Trolly.remove(state)
		return
	end
	if state.model and state.model.Parent then
		if state.prompt then state.prompt.ActionText = state.context.translation.tr("Talk") end
		return
	end
	if state.building then return end

	PulseApplication.Trolly.remove(state)
	state.building = true
	local ok = pcall(PulseApplication.Trolly.build, state)
	state.building = false
	if not ok or not state.context.isAlive() or PulseApplication.Trolly.settings(state).on == false then
		PulseApplication.Trolly.remove(state)
	end
end

function PulseApplication.Trolly.install(context)
	local state = {context = context, animations = {}, voices = {}, sequence = 0, elapsed = 0}
	PulseApplication.Trolly.settings(state)
	local api = {
		danceStart = function(key) PulseApplication.Trolly.danceStart(state, key) end,
		danceStop = function() PulseApplication.Trolly.danceStop(state) end,
		setOn = function(enabled) PulseApplication.Trolly.setOn(state, enabled) end,
		setVolume = function(value) PulseApplication.Trolly.setVolume(state, value) end,
	}
	context.environment.getgenv().__pulseNpc = api
	local keyCodes = {context.environment.Enum.KeyCode.One, context.environment.Enum.KeyCode.Two,
		context.environment.Enum.KeyCode.Three, context.environment.Enum.KeyCode.Four,
		context.environment.Enum.KeyCode.Five, context.environment.Enum.KeyCode.Six,
		context.environment.Enum.KeyCode.Seven, context.environment.Enum.KeyCode.Eight, context.environment.Enum.KeyCode.Nine}
	context.connect(context.inputService.InputBegan, function(input, processed)
		if processed or not state.open then return end
		for index, code in ipairs(keyCodes) do
			if input.KeyCode == code and state.hotkeys[index] then state.hotkeys[index](); return end
		end
	end)
	context.connect(context.runService.RenderStepped, function() pcall(PulseApplication.Trolly.hudStep, state) end)
	context.connect(context.runService.Stepped, function(_, delta)
		if not state.model or not state.model.Parent then return end
		pcall(PulseApplication.Trolly.neckStep, state)
		pcall(PulseApplication.Trolly.danceStep, state, delta)
	end)
	context.connect(context.runService.Heartbeat, function(delta)
		pcall(PulseApplication.Trolly.moveStep, state, delta)
		pcall(PulseApplication.Trolly.danceTick, state)
		if state.open then
			PulseApplication.Trolly.fitDialog(state)
			local character = context.player.Character
			local playerRoot = character and character:FindFirstChild("HumanoidRootPart")
			if not playerRoot or not state.root or not state.root.Parent or (playerRoot.Position - state.root.Position).Magnitude > 14 then
				state.farFrames += 1
			else
				state.farFrames = 0
			end
			if state.farFrames >= 6 then PulseApplication.Trolly.close(state) end
		end
		state.elapsed += delta
		if state.elapsed < 5 then return end
		state.elapsed = 0
		PulseApplication.Trolly.ensure(state)
	end)
	context.environment.task.defer(function() PulseApplication.Trolly.ensure(state) end)

	return function()
		PulseApplication.Trolly.remove(state)
		pcall(PulseApplication.Trolly.cameraEnd, state)
		pcall(PulseApplication.Trolly.hideEnd, state)
		if state.gui then state.gui:Destroy() end
		if state.hud then state.hud:Destroy() end
		for _, voice in ipairs(state.voices) do voice:Destroy() end
		if state.soundGroup then state.soundGroup:Destroy() end
		if context.environment.getgenv().__pulseNpc == api then context.environment.getgenv().__pulseNpc = nil end
	end
end


function PulseApplication.installAppearance(context)
	local window, nova, translation = context.window, context.nova, context.translation
	local tab = context.hub.NovaTabs.Settings
	local refs = {}
	window.AppearanceRefs = refs
	local function section(title, icon)
		local value = tab:Section({Title = title, Icon = icon, Sub = "UI"})
		if value.TitleLabel then translation.bind(value.TitleLabel, title) end
		return value
	end
	local function add(parent, kind, options)
		local control = parent[kind](parent, options)
		if control and control.Title then translation.bind(control.Title, options.Text) end
		return control
	end
	local interface = section("Interface", "layout-panel-left")
	refs.scale = add(interface, "Slider", {Text = "UI scale", Min = 0.6, Max = 1.4, Decimals = 2,
		Default = window.UserScale, Suffix = "x", Callback = function() end, Released = function(value) window:SetScale(value) end})
	refs.autofit = add(interface, "Toggle", {Text = "Fit to screen", Default = window.AutoFit,
		Callback = function(value) window:SetAutoFit(value) end})
	refs.radius = add(interface, "Slider", {Text = "Corner radius", Min = 0, Max = 2, Decimals = 2,
		Default = tonumber(window.State.get("radius", 1)) or 1, Suffix = "x", Callback = function(value) window:SetCornerRadius(value) end})
	refs.textScale = add(interface, "Slider", {Text = "Text size", Min = 0.85, Max = 1.25, Decimals = 2,
		Default = tonumber(window.State.get("textScale", 1)) or 1, Suffix = "x", Callback = function(value) window:SetTextScale(value) end})
	local fonts = {}
	for _, family in ipairs(nova.Font.Families) do table.insert(fonts, family[1]) end
	refs.font = add(interface, "Dropdown", {Text = "Font", Options = fonts, Default = nova.Font.name, Callback = function(value) window:SetFont(value) end})
	refs.opacity = add(interface, "Slider", {Text = "Window opacity", Min = 0.5, Max = 1, Decimals = 2,
		Default = window.Opacity, Callback = function(value) window:SetOpacity(value) end})
	refs.sidebarWidth = add(interface, "Slider", {Text = "Sidebar width", Min = 188, Max = 340, Decimals = 0,
		Default = window.ExpandedWidth, Suffix = " px", Callback = function() end, Released = function(value) window:SetSidebarWidth(value) end})
	window.OnSidebarWidth = function(value) if refs.sidebarWidth then refs.sidebarWidth:SetSilent(value) end end
	refs.density = add(interface, "Dropdown", {Text = "Sidebar density", Options = nova.WindowClass.Densities,
		Default = window.Density, Callback = function(value) window:SetDensity(value) end})
	refs.compact = add(interface, "Toggle", {Text = "Compact sidebar", Default = window.SidebarCollapsed == true,
		Callback = function(value) window:SetSidebarCollapsed(value) end})
	window.OnSidebarChanged = function(value) if refs.compact then refs.compact:SetSilent(value) end end
	refs.groupLabels = add(interface, "Toggle", {Text = "Group labels", Default = window.GroupLabels ~= false,
		Callback = function(value) window:SetGroupLabels(value) end})
	window.OnGroupLabels = function(value) if refs.groupLabels then refs.groupLabels:SetSilent(value) end end

	local theme = section("Theme", "palette")
	refs.halloween = add(theme, "Toggle", {Text = "Halloween theme", Default = window:IsHalloween(), Callback = function(value)
		if value ~= window:IsHalloween() then window:SetHalloween(value) end
	end})
	local presets = {"Crimson", "Ember", "Gold", "Mint", "Ocean", "Violet", "Rose", "Ice"}
	for name in pairs(nova.Theme.Presets or {}) do if not table.find(presets, name) then table.insert(presets, name) end end
	local function selectedPreset()
		local selected
		pcall(function()
			for _, name in ipairs(presets) do
				local color = nova.Theme.Presets[name]
				if color and color:ToHex() == nova.Theme.tokens.Accent:ToHex() then
					selected = name
					break
				end
			end
		end)
		return selected
	end
	refs.palette = add(theme, "Dropdown", {Text = "Accent", Options = presets, Default = selectedPreset(), Callback = function(name)
		local color = nova.Theme.Presets[name]
		if not color then return end
		window:SetAccent(color)
		if refs.accent then refs.accent:SetSilent(color) end
	end})
	refs.accent = add(theme, "Colorpicker", {Text = "Custom accent", Alpha = false, Default = nova.Theme.tokens.Accent,
		Callback = function(value)
			window:SetAccent(value)
			if refs.palette then refs.palette:SetSilent(nil) end
		end})
	local bases = {}
	for _, base in ipairs(nova.Theme.Bases) do table.insert(bases, base[1]) end
	refs.base = add(theme, "Dropdown", {Text = "Base theme", Options = bases, Default = nova.Theme.base, Callback = function(value)
		window:SetBase(value)
		if refs.panel then refs.panel:SetSilent(nova.Theme.tokens.Background) end
		if refs.halloween then refs.halloween:SetSilent(window:IsHalloween()) end
	end})
	refs.panel = add(theme, "Colorpicker", {Text = "Panel color", Alpha = false, Default = nova.Theme.tokens.Background, Callback = function(value)
		window:SetPanelColor(value)
		if refs.base then refs.base:SetSilent("Custom") end
	end})
	refs.cards = add(theme, "Dropdown", {Text = "Card style", Options = nova.WindowClass.CardStyles, Default = window.CardStyle,
		Callback = function(value) window:SetCardStyle(value) end})
	refs.background = add(theme, "Dropdown", {Text = "Background", Options = nova.WindowClass.BackgroundStyles, Default = window.BgStyle,
		Callback = function(value)
			window:SetBackground(value)
			if refs.halloween then refs.halloween:SetSilent(window:IsHalloween()) end
		end})
	refs.backgroundIntensity = add(theme, "Slider", {Text = "Background intensity", Min = 0, Max = 1.5, Decimals = 2,
		Default = window.BgIntensity, Callback = function(value) window:SetBackgroundIntensity(value) end})
	refs.blur = add(theme, "Toggle", {Text = "Blur behind menu", Default = window.BlurEnabled, Callback = function(value) window:SetBlur(value) end})

	local behavior = section("Behavior", "sliders-horizontal")
	refs.motion = add(behavior, "Toggle", {Text = "Animations", Default = nova.Motion.enabled, Callback = function(value) window:SetMotion(value) end})
	refs.sounds = add(behavior, "Toggle", {Text = "Interface sounds", Default = nova.Sound.enabled, Callback = function(value) window:SetSounds(value) end})
	refs.volume = add(behavior, "Slider", {Text = "Sound volume", Min = 0, Max = 1, Decimals = 2,
		Default = nova.Sound.volume, Callback = function(value) window:SetVolume(value) end})
	refs.tips = add(behavior, "Toggle", {Text = "Tooltips", Default = window.TooltipsOn, Callback = function(value) window:SetTooltips(value) end})
	refs.launcher = add(behavior, "Toggle", {Text = "Launcher button", Default = window.LauncherOn, Callback = function(value) window:SetLauncher(value) end})
	window.SyncAppearance = function()
		local values = {scale = window.UserScale, autofit = window.AutoFit, radius = tonumber(window.State.get("radius", 1)) or 1,
			textScale = tonumber(window.State.get("textScale", 1)) or 1, font = nova.Font.name, opacity = window.Opacity,
			sidebarWidth = window.ExpandedWidth, density = window.Density, compact = window.SidebarCollapsed == true,
			groupLabels = window.GroupLabels ~= false, halloween = window:IsHalloween(), accent = nova.Theme.tokens.Accent,
			base = nova.Theme.base, panel = nova.Theme.tokens.Background, cards = window.CardStyle, background = window.BgStyle,
			backgroundIntensity = window.BgIntensity, blur = window.BlurEnabled, motion = nova.Motion.enabled,
			sounds = nova.Sound.enabled, volume = nova.Sound.volume, tips = window.TooltipsOn, launcher = window.LauncherOn}
		for name, value in pairs(values) do
			local control = refs[name]
			if control and control.SetSilent then pcall(control.SetSilent, control, value) end
		end
		if refs.palette then pcall(refs.palette.SetSilent, refs.palette, selectedPreset()) end
	end
	add(behavior, "Button", {Text = "Reset appearance", Icon = "rotate-ccw", DoubleClick = true, Callback = function()
		window:ResetAppearance()
		window:SyncAppearance()
		window:Notify({Title = translation.tr("Appearance reset"), Kind = "success"})
	end})
end

function PulseApplication.installMenu(context)
	local environment = context.environment
	local globals = environment.getgenv()
	local settings, window = context.configuration, context.window
	local section, translation = context.section, context.translation
	local key = globals.__pulseBindFromName(settings.ui.menuKey)

	section:Header("Menu", "Left")
	if key and key.EnumType == environment.Enum.KeyCode then
		context.hub.MenuKey = key
		window:SetKey(key)
	end
	local keybind
	window:OnKeyChanged(function(value)
		context.hub.MenuKey = value
		settings.ui.menuKey = value.Name
		if keybind and keybind.Get and keybind.Get() ~= value then pcall(keybind.Set, value) end
	end)
	keybind = section:Keybind({Text = "Menu key", Default = window.Key, NoSave = true, Callback = function(value)
		if environment.typeof(value) ~= "EnumItem" or value.EnumType ~= environment.Enum.KeyCode then return end
		window:SetKey(value)
		context.hub.MenuKey = value
		settings.ui.menuKey = value.Name
	end})
	local pingFps = globals.__pulsePingFps
	globals.__pulsePfSettings = section:Toggle({Text = "Show FPS / Ping", NoSave = true, Default = pingFps and pingFps.get() or false, Callback = function(value)
		local current = globals.__pulsePingFps
		if current and current.get() ~= value then current.set(value) end
	end})
	globals.__pulseKbSettings = section:Toggle({Text = "Show Keybinds", NoSave = true,
		Default = window.State.get("keybindList", window.IsTouch == true) == true,
		Callback = function(value) pcall(window.SetKeybindList, window, value) end})
	section:Dropdown({Text = "Language", NoSave = true, Default = settings.ui.lang or "en",
		Options = {{code = "en", label = "English"}, {code = "ru", label = "Ð ÑƒÑÑÐºÐ¸Ð¹"}}, Callback = function(language)
			settings.ui.lang = language
			translation.setLang(language)
			for _, callback in ipairs(globals.__pulseNovaLangHooks or {}) do pcall(callback) end
		end})
end

function PulseApplication.installGeneral(context)
	local environment = context.environment
	local settings = context.configuration
	local virtualUser = environment.game:GetService("VirtualUser")
	local lastFrame, baseFrame

	context.connect(context.player.Idled, function()
		if not settings.afk or not settings.afk.on then return end
		pcall(function()
			virtualUser:CaptureController()
			virtualUser:ClickButton2(environment.Vector2.new())
		end)
	end)
	context.section:Header("General", "Left")
	context.section:Toggle({Text = "Anti AFK", Default = context.defaults.afk.on,
		Callback = function(enabled) settings.afk.on = enabled end})
	context.section:Slider({Text = "Screen Stretch", Min = 0, Max = 100,
		Default = math.floor((context.defaults.ui.stretch or 0) + 0.5), Decimals = 0, Suffix = "%",
		Callback = function(value) settings.ui.stretch = value end})
	context.section:Toggle({Text = "Trolly NPC", Default = type(context.defaults.npc) ~= "table" or context.defaults.npc.on ~= false,
		Callback = function(enabled)
			if type(settings.npc) ~= "table" then settings.npc = {} end
			settings.npc.on = enabled
			local npc = environment.getgenv().__pulseNpc
			if npc then npc.setOn(enabled) end
		end})
	context.section:Toggle({Text = "Trolly Dances", Default = type(context.defaults.npc) ~= "table" or context.defaults.npc.dances ~= false,
		Callback = function(enabled)
			if type(settings.npc) ~= "table" then settings.npc = {} end
			settings.npc.dances = enabled
		end})
	context.section:Slider({Text = "Trolly Volume", Min = 0, Max = 100,
		Default = type(context.defaults.npc) == "table" and tonumber(context.defaults.npc.volume) or 100,
		Decimals = 0, Suffix = "%", Callback = function(value)
			if type(settings.npc) ~= "table" then settings.npc = {} end
			settings.npc.volume = value
			local npc = environment.getgenv().__pulseNpc
			if npc then npc.setVolume(value) end
		end})
	if context.window then
		context.section:Button({Text = "Unload hub", DoubleClick = true, Callback = function()
			environment.task.defer(function() context.window:Destroy() end)
		end})
	end
	context.connect(context.runService.RenderStepped, function()
		local stretch = settings.ui and settings.ui.stretch or 0
		if stretch <= 0 then
			lastFrame = nil
			return
		end

		local camera = context.workspace.CurrentCamera
		if not camera then return end
		local scale, current = 1 - stretch / 100 * 0.6, camera.CFrame
		local base = lastFrame and current == lastFrame and baseFrame or current
		camera.CFrame = base * environment.CFrame.new(0, 0, 0, 1, 0, 0, 0, scale, 0, 0, 0, 1)
		lastFrame, baseFrame = camera.CFrame, base
	end)
end

function PulseApplication.start(host, game, parent)
	local environment, diagnostics = OfflineEnvironment.create(host, game)
	local hostGlobal = type(host.getgenv) == "function" and host.getgenv() or host
	hostGlobal.PulseOfflineDiagnostics = diagnostics
	hostGlobal.PulseOfflineEnvironment = environment
	local ok, application = xpcall(function()
		return PulseApplication.create(environment, parent, {["3.4"] = "offline"})
	end, function(message)
		return host.debug.traceback(tostring(message), 2)
	end)
	if not ok then
		table.insert(diagnostics.errors, application)
		host.warn("[Pulse offline] Startup error: " .. application)
		return nil, diagnostics
	end
	application.diagnostics = diagnostics
	return application, diagnostics
end

function PulseApplication.create(environment, parent, versions)
	local game = environment.game
	local players = game:GetService("Players")
	local inputService = game:GetService("UserInputService")
	local runService = game:GetService("RunService")
	local workspace = game:GetService("Workspace")
	local http = game:GetService("HttpService")
	local settings = Configuration.load(environment, http, versions)
	if type(settings.ctrl) ~= "table" then settings.ctrl = {} end
	local defaults = Configuration.defaultView(settings, versions)
	local translation = Translation.create()
	translation.setLang(settings.ui.lang)
	InputBindings.install(environment, inputService)

	local nova = NovaFoundation.create(environment)
	local layout = Layout.create()
	local window, tabs = PulseWindow.create(environment, nova, layout, parent)
	environment.getgenv().__pulseMM2Nova = window
	for _, group in ipairs(window.Groups) do translation.bind(group.Label, group.Key) end
	for name, tab in pairs(tabs) do translation.bind(tab.Label, name) end
	local globals = environment.getgenv()
	globals.__pulseBinds = globals.__pulseBinds or {}
	globals.__pulseBakedCfg = Configuration.baked(http)
	local hub = {W = window, Nova = nova, NovaTabs = tabs, tabs = {}, _tabList = {}, _ckeys = {}}
	local connections = {}
	local context = {translator = translation, layout = layout, icons = {}, config = settings.ctrl,
		defaults = {}, setters = {}, applyHooks = {}, applyState = {}}
	local roles = RoleData.create({environment = environment, storage = game:GetService("ReplicatedStorage"), players = players})
	local function connect(signal, callback)
		local connection = signal:Connect(callback)
		table.insert(connections, connection)
		return connection
	end
	local function create(className, properties, owner)
		local object = environment.Instance.new(className)
		for key, value in pairs(properties) do object[key] = value end
		object.Parent = owner
		return object
	end

	context.alive = function() return not hub.dead and not window.Destroyed end
	context.localPlayer = players.LocalPlayer
	context.connect = connect

